function localizedDisplayName(value) {
  const source = String(value || "").trim();
  if (!source) {
    return source;
  }
  const direct = dynamicDisplayLabels[source];
  if (direct || currentLanguage() !== "en" || !/[一-鿿]/.test(source)) {
    return direct || source;
  }
  return Object.entries(dynamicDisplayLabels.en)
    .sort((left, right) => right[0].length - left[0].length)
    .reduce((result, [zh, en]) => result.replaceAll(zh, en), source);
}

function localizeMixedText(value) {
  const source = String(value || "");
  if (!source || currentLanguage() !== "en") {
    return source;
  }
  let result = localizedDisplayName(source);
  result = result
    .replace(/文件\s+(.+?)\s+已进入待发起状态/g, "File $1 is ready to start.")
    .replace(/(.+?)\s+(V\d+)\s+已完成模型转换并自动回填 URN/g, "$1 $2 completed model translation and URN was backfilled.")
    .replace(/流程\s+(.+?)\s+审批完成后自动导出了审阅版本\s+(.+)/g, (_match, workflowName, fileName) => `Workflow ${localizeMixedText(workflowName.trim())} auto-exported reviewed version ${fileName.trim()} after approval.`)
    .replace(/流程\s+(.+?)\s+已生成审批记录单/g, (_match, workflowName) => `Workflow ${localizeMixedText(workflowName.trim())} generated an approval record.`)
    .replace(/流程\s+(.+?)\s+已生成审阅归档文件\s*·\s*(.+)/g, (_match, workflowName, fileName) => `Workflow ${localizeMixedText(workflowName.trim())} generated a reviewed archive file · ${fileName.trim()}`)
    .replace(/流程\s+(.+?)\s+已提交给\s+(.+)/g, (_match, workflowName, owners) => `Workflow ${localizeMixedText(workflowName.trim())} was submitted to ${localizeMixedText(owners.trim())}`)
    .replace(/已转交\s+(.+?)\s+进行最终审阅。?/g, (_match, owners) => `Submitted to ${localizeMixedText(owners.trim())} for final review.`)
    .replace(/流程已全部通过，文件进入归档状态。?/g, "Workflow approved. Files are archived.")
    .replace(/文档已完成审阅并进入归档状态/g, "Document review completed and archived.")
    .replace(/更新了整份文件的备注信息/g, "Updated document remarks.")
    .replace(/清空了备注信息/g, "Cleared document remarks.")
    .replace(/(定点|Point)批注\s*·\s*第\s*(\d+)\s*页/g, "Point Annotation · Page $2")
    .replace(/(矩形|Rectangle)批注\s*·\s*第\s*(\d+)\s*页/g, "Rectangle Annotation · Page $2")
    .replace(/(文本|Text)批注\s*·\s*第\s*(\d+)\s*页/g, "Text Annotation · Page $2")
    .replace(/(箭头|Arrow)批注\s*·\s*第\s*(\d+)\s*页/g, "Arrow Annotation · Page $2")
    .replace(/(手绘|Freehand)批注\s*·\s*第\s*(\d+)\s*页/g, "Freehand Annotation · Page $2")
    .replace(/(定点|Point)批注/g, "Point Annotation")
    .replace(/(矩形|Rectangle)批注/g, "Rectangle Annotation")
    .replace(/(文本|Text)批注/g, "Text Annotation")
    .replace(/(箭头|Arrow)批注/g, "Arrow Annotation")
    .replace(/(手绘|Freehand)批注/g, "Freehand Annotation")
    .replace(/当前节点待处理/g, "Current step pending")
    .replace(/待\s*([^·]+?)\s*处理/g, (_match, owner) => `Pending ${localizeMixedText(owner.trim())}`)
    .replace(/(\d+)\s*个文件/g, "$1 files")
    .replace(/第\s*(\d+)\s*页/g, "Page $1");
  if (typeof STATIC_EN_TEXT === "object") {
    result = Object.entries(STATIC_EN_TEXT)
      .sort((left, right) => right[0].length - left[0].length)
      .reduce((next, [zh, en]) => next.replaceAll(zh, en), result);
  }
  return result
    .replace(/Page\s*(\d+)\s*pages/g, "Page $1")
    .replace(/确认删除“([^”]+)”吗？该批注下的回复和附件也会一起移除。/g, (_match, title) => `Delete “${localizeMixedText(title)}”? Replies and attachments under this annotation will also be removed.`)
    .replace(/确认删除这条回复吗？其附件也会一起移除。/g, "Delete this reply? Its attachments will also be removed.")
    .replace(/确认重置成员“([^”]+)”的登录密码吗？/g, (_match, name) => `Reset the login password for “${localizeMixedText(name)}”?`)
    .replace(/确认移除成员“([^”]+)”吗？/g, (_match, name) => `Remove member “${localizeMixedText(name)}”?`)
    .replace(/确认删除这条文件夹覆盖权限吗？/g, "Delete this folder override permission?")
    .replace(/确认撤回当前流程吗？撤回后文件会恢复为待发起状态，并解除审批锁定。/g, "Withdraw the current workflow? The file will return to Ready to Start and the approval lock will be released.")
    .replace(/确认删除文件“([^”]+)”吗？该操作会同时移除版本记录和导出文件。/g, (_match, name) => `Delete file “${localizeMixedText(name)}”? Version history and exported files will also be removed.`)
    .replace(/确认删除文件夹“([^”]+)”吗？为空目录时才允许删除。/g, (_match, name) => `Delete folder “${localizeMixedText(name)}”? Only empty folders can be deleted.`)
    .replace(/确认删除选中的\s*(\d+)\s*份文件吗？该操作会同时移除版本记录和导出文件。/g, (_match, count) => `Delete ${count} selected files? Version history and exported files will also be removed.`)
    .replace(/确认放弃？已填写内容不会保存。/g, "Discard this draft? Entered content will not be saved.")
    .replace(/确认删除当前流程模板吗？已运行中的流程不会受影响。/g, "Delete the current workflow template? Running workflows will not be affected.")
    .replace(/确认将\s*(.*?)\s*还原为\s*(.*?)\s*吗？系统会生成一个新的当前版本。/g, (_match, name, version) => `Restore ${localizeMixedText(name)} to ${localizeMixedText(version)}? The system will create a new current version.`)
    .replace(/确认将\s*(.*?)\s*设为当前生效版本吗？原当前版本会保留为历史版本。/g, (_match, version) => `Set ${localizeMixedText(version)} as the current version? The previous current version will remain in history.`)
    .replace(/此操作不可撤销，确认删除\s*(.*?)\s*吗？/g, (_match, version) => `This action cannot be undone. Delete ${localizeMixedText(version)}?`)
    .replace(/当前文件扩展名为 \.(.*?)，你选择的是 \.(.*?)。系统会给出警告但仍允许继续创建新版本，是否继续？/g, (_match, currentExt, nextExt) => `The current file extension is .${currentExt}, but you selected .${nextExt}. The system will show a warning but still allow creating the new version. Continue?`)
    .replace(/确认退出当前 PDF 页面吗？未保存的批注草稿会丢失。/g, "Exit the current PDF page? Unsaved annotation drafts will be lost.");
}

function hasCjkText(value) {
  return /[\u4e00-\u9fff]/.test(String(value || ""));
}

function localizeUserMessage(value, fallback = text("操作失败，请稍后重试。", "Operation failed. Please try again.")) {
  const fallbackValue = String(fallback || "").trim() || text("操作失败，请稍后重试。", "Operation failed. Please try again.");
  const source = String(value || "").trim() || fallbackValue;
  const localized = localizeMixedText(source);
  if (currentLanguage() === "en" && hasCjkText(localized)) {
    const fallbackLocalized = localizeMixedText(fallbackValue);
    return hasCjkText(fallbackLocalized) ? "Operation failed. Please try again." : fallbackLocalized;
  }
  return localized || fallbackValue;
}


