const ANNOTATION_STATUS_VALUES = new Set(["open", "in_progress", "resolved"]);

function normalizeAnnotationStatusValue(status, fallback = "open") {
  const value = String(status || "").trim();
  if (ANNOTATION_STATUS_VALUES.has(value)) {
    return value;
  }
  const fallbackValue = String(fallback || "").trim();
  return ANNOTATION_STATUS_VALUES.has(fallbackValue) ? fallbackValue : "open";
}

function annotationStatusDisplayLabel(status) {
  const normalizedStatus = normalizeAnnotationStatusValue(status);
  return {
    open: text("未解决", "Open"),
    in_progress: text("进行中", "In Progress"),
    resolved: text("已解决", "Resolved"),
  }[normalizedStatus];
}

function annotationStatusSignalTone(status) {
  return {
    open: "open",
    in_progress: "alert",
    resolved: "success",
  }[normalizeAnnotationStatusValue(status)];
}

function inferredAnnotationStatus(annotation = {}, doc = currentDocument(), editor = state?.annotationEditor || {}) {
  return normalizeAnnotationStatusValue(editor.status || annotation.status, "open");
}

