function normalizeWorkflowTemplateAssigneeMode(value) {
  return value === "role" ? "role" : "user";
}

const WORKFLOW_STARTER_ROLE_VALUES = ["super_admin", "project_admin", "reviewer"];
const WORKFLOW_APPROVER_ROLE_VALUES = ["super_admin", "project_admin", "reviewer"];

function workflowRoleMemberCount(role) {
  return (currentAccess().projectMembers || []).filter((member) => member.user?.id && member.role === role).length;
}

function workflowRoleOptionWithMemberCounts(option) {
  const count = workflowRoleMemberCount(option.value);
  return {
    ...option,
    memberCount: count,
    label: text(`${option.label} · ${count} 人`, `${option.label} · ${count} member${count === 1 ? "" : "s"}`),
  };
}

function workflowRoleOptionsFor(roleValues = []) {
  const allowed = new Set(roleValues);
  return accessRoleOptions()
    .filter((option) => allowed.has(option.value))
    .map(workflowRoleOptionWithMemberCounts);
}

function workflowStarterRoleOptions() {
  return workflowRoleOptionsFor(WORKFLOW_STARTER_ROLE_VALUES);
}

function workflowApproverRoleOptions() {
  return workflowRoleOptionsFor(WORKFLOW_APPROVER_ROLE_VALUES);
}

function workflowTemplateSelectorLabel(selector) {
  if (!selector || typeof selector !== "object") {
    return "";
  }
  if (selector.type === "role") {
    return projectRoleLabels[selector.role] || selector.label || selector.role || "";
  }
  const projectMember = (currentAccess().projectMembers || []).find((member) => member.user?.id === selector.userId);
  return projectMember?.user?.name || selector.label || selector.name || "";
}

function workflowTemplateStepResolvedReviewers(step) {
  const resolved = [];
  const seen = new Set();

  (step?.reviewers || []).forEach((selector) => {
    if (!selector || typeof selector !== "object") {
      return;
    }
    if (selector.type === "role") {
      const members = (currentAccess().projectMembers || []).filter((member) => member.role === selector.role);
      if (!members.length) {
        return;
      }
      members.forEach((member) => {
        const key = member.user?.id || member.user?.name || member.role;
        const label = member.user?.name || member.roleLabel || projectRoleLabels[member.role] || selector.role;
        if (!label || !key || seen.has(key)) {
          return;
        }
        seen.add(key);
        resolved.push(label);
      });
      return;
    }
    const member = (currentAccess().projectMembers || []).find((item) => item.user?.id === selector.userId);
    const key = member?.user?.id || selector.userId || selector.label || selector.name || "";
    const label = member?.user?.name || selector.label || selector.name || "";
    if (!label || !key || seen.has(key)) {
      return;
    }
    seen.add(key);
    resolved.push(label);
  });

  return resolved;
}

function createWorkflowTemplateStepDraft(step = {}, options = {}) {
  const selectors = Array.isArray(step.reviewers)
    ? step.reviewers
        .map((item) => {
          if (!item) {
            return null;
          }
          if (typeof item === "string") {
            return {
              id: `selector-${crypto.randomUUID()}`,
              type: "user",
              userId: "",
              role: "",
              label: item,
            };
          }
          return {
            id: item.id || `selector-${crypto.randomUUID()}`,
            type: item.type === "role" ? "role" : "user",
            userId: item.userId || "",
            role: item.role || "",
            label: item.label || item.name || "",
          };
        })
        .filter(Boolean)
    : [];
  const inferredAssigneeMode = selectors.some((selector) => selector.type === "role") ? "role" : "user";
  return {
    id: step.id || `draft-step-${crypto.randomUUID()}`,
    name: step.name || "",
    mode: step.mode || "single",
    assigneeMode: normalizeWorkflowTemplateAssigneeMode(step.assigneeMode || inferredAssigneeMode),
    selectedUserIds: selectors
      .filter((selector) => selector.type !== "role")
      .map((selector) => selector.userId)
      .filter((userId) => {
        const member = (currentAccess().projectMembers || []).find((item) => item.user?.id === userId);
        return member && WORKFLOW_APPROVER_ROLE_VALUES.includes(member.role);
      }),
    selectedRoles: selectors
      .filter((selector) => selector.type === "role")
      .map((selector) => selector.role)
      .filter((role) => WORKFLOW_APPROVER_ROLE_VALUES.includes(role)),
    dueDays: Number(step.dueDays || 1) || 1,
    description: step.description || "",
    confirmed: step.confirmed !== undefined ? Boolean(step.confirmed) : Boolean(options.defaultConfirmed),
    collapsed: step.collapsed !== undefined ? Boolean(step.collapsed) : Boolean(options.defaultCollapsed),
  };
}

function createEmptyWorkflowTemplateDraft() {
  return {
    id: "",
    name: "",
    category: "项目级流程",
    projectName: "CDE文件管理系统",
    description: "",
    allowedRoles: [...WORKFLOW_STARTER_ROLE_VALUES],
    autoExport: {
      enabled: false,
      targetFolderId: "",
      targetPath: "",
      namingRule: text("流程发起时间 + 审核流程名称 + 发起人", "Workflow start time + review name + initiator"),
      exportReviewedFile: true,
      exportApprovalReport: true,
    },
    steps: [
      createWorkflowTemplateStepDraft({
        name: "1st review",
        mode: "single",
        dueDays: 2,
      }, { defaultConfirmed: false, defaultCollapsed: false }),
    ],
  };
}

function templateDraftFromTemplate(template) {
  if (!template) {
    return createEmptyWorkflowTemplateDraft();
  }
  const resolvedExportFolderId = workflowTemplateResolveExportFolderId(
    template.autoExport?.targetFolderId || "",
    template.autoExport?.targetPath || "",
  );
  return {
    id: template.id || "",
    name: template.name || "",
    category: template.category || "项目级流程",
    projectName: template.projectName || state.access.project?.name || "CDE文件管理系统",
    description: template.description || "",
    allowedRoles: Array.isArray(template.allowedRoles)
      ? template.allowedRoles.filter((role) => WORKFLOW_STARTER_ROLE_VALUES.includes(role))
      : [...WORKFLOW_STARTER_ROLE_VALUES],
    autoExport: {
      enabled: Boolean(template.autoExport?.enabled),
      targetFolderId: resolvedExportFolderId,
      targetPath:
        resolvedExportFolderId
          ? workflowTemplateExportPathForFolder(resolvedExportFolderId)
          : template.autoExport?.targetPath || "",
      namingRule: template.autoExport?.namingRule || text("流程发起时间 + 审核流程名称 + 发起人", "Workflow start time + review name + initiator"),
      exportReviewedFile: template.autoExport?.exportReviewedFile !== undefined ? Boolean(template.autoExport.exportReviewedFile) : true,
      exportApprovalReport: template.autoExport?.exportApprovalReport !== undefined ? Boolean(template.autoExport.exportApprovalReport) : true,
    },
    steps: Array.isArray(template.steps) && template.steps.length
      ? template.steps.map((step) => createWorkflowTemplateStepDraft(step, { defaultConfirmed: true, defaultCollapsed: false }))
      : [createWorkflowTemplateStepDraft({}, { defaultConfirmed: false, defaultCollapsed: false })],
  };
}

function workflowTemplateCategoryOptions() {
  const optionMap = new Map();
  const appendOption = (value, label = value) => {
    const normalizedValue = String(value || "").trim();
    if (!normalizedValue || optionMap.has(normalizedValue)) {
      return;
    }
    optionMap.set(normalizedValue, {
      value: normalizedValue,
      label: label || normalizedValue,
    });
  };

  [
    { value: "项目级流程", label: text("项目级流程", "Project-level Flow") },
    { value: "文档审阅", label: text("文档审阅", "Document Review") },
    { value: "专业会签", label: text("专业会签", "Discipline Sign-off") },
    { value: "发布审批", label: text("发布审批", "Publish Approval") },
    { value: "归档流程", label: text("归档流程", "Archive Flow") },
    { value: "系统级流程", label: text("系统级流程", "System Flow") },
  ].forEach((option) => appendOption(option.value, option.label));

  state.workflowTemplates.forEach((template) => appendOption(template.category, template.category));
  appendOption(state.workflowTemplateDraft?.category, state.workflowTemplateDraft?.category);

  return [...optionMap.values()];
}

function workflowTemplateProjectRootPath() {
  return `/${state.access.project?.name || "CDE文件管理系统"}`;
}

function workflowTemplateNormalizeExportFolderId(folderId) {
  return folderId === WORKFLOW_TEMPLATE_EXPORT_ROOT ? WORKFLOW_TEMPLATE_EXPORT_ROOT : String(folderId || "");
}

function workflowTemplatePayloadExportFolderId(folderId) {
  return workflowTemplateNormalizeExportFolderId(folderId) === WORKFLOW_TEMPLATE_EXPORT_ROOT ? "" : workflowTemplateNormalizeExportFolderId(folderId);
}

function workflowTemplateResolveExportFolderId(folderId, targetPath = "") {
  const normalizedFolderId = workflowTemplateNormalizeExportFolderId(folderId);
  if (normalizedFolderId) {
    return normalizedFolderId;
  }
  const normalizedPath = String(targetPath || "").trim();
  if (!normalizedPath) {
    return "";
  }
  if (normalizedPath === workflowTemplateProjectRootPath()) {
    return WORKFLOW_TEMPLATE_EXPORT_ROOT;
  }
  const matchedFolder = state.folders.find((folder) => workflowTemplateExportPathForFolder(folder.id) === normalizedPath);
  return matchedFolder?.id || "";
}

function workflowResolvedDocuments(workflow) {
  return (workflow?.fileRefs || [])
    .map((fileRef) => documentById(fileRef.docId))
    .filter(Boolean);
}

function workflowPrimaryDocument(workflow) {
  return workflowResolvedDocuments(workflow)[0] || null;
}

function workflowReviewableDocument(workflow) {
  return workflowResolvedDocuments(workflow).find((doc) => canPreviewDocument(doc) && canOpenDocumentWorkspace(doc)) || workflowPrimaryDocument(workflow);
}

function canExportWorkflowCommentReport(workflow) {
  const docs = workflowResolvedDocuments(workflow);
  return Boolean(docs.length) && docs.every((doc) => canExportReview(doc));
}

function workflowCurrentOwners(workflow) {
  const step = workflow?.currentStep;
  if (!step) {
    return [];
  }
  return (step.reviewers || [])
    .filter((reviewer) => reviewer.status === "pending")
    .map((reviewer) => reviewer.name)
    .filter(Boolean);
}

function workflowStatusMeta(workflow) {
  if (!workflow) {
    return {
      label: text("未开始", "Not Started"),
      tone: "neutral",
    };
  }

  if (workflow.status === "approved") {
    return {
      label: text("已完成", "Completed"),
      tone: "success",
    };
  }
  if (workflow.status === "rejected") {
    return {
      label: text("已退回", "Returned"),
      tone: "alert",
    };
  }
  if (workflow.status === "withdrawn") {
    return {
      label: text("已撤回", "Withdrawn"),
      tone: "neutral",
    };
  }
  return {
    label: text("审批中", "In Approval"),
    tone: workflowDueBucket(workflow) === "overdue" ? "alert" : "info",
  };
}

function workflowStageMeta(workflow) {
  const step = workflow?.currentStep;
  const status = workflowStatusMeta(workflow);
  if (!step) {
    return {
      label: status.label,
      note: workflow?.templateName || text("无审批节点", "No approval step"),
      owners: workflow?.initiator ? [workflow.initiator] : [],
    };
  }
  const owners = workflowCurrentOwners(workflow).map(localizedDisplayName);
  return {
    label: text(step.name || "当前节点", step.name === "approval" ? "Review Step" : step.name || "Current Step"),
    note: owners.length ? text(`当前责任人 ${owners.join(" / ")}`, `Current owner ${owners.join(" / ")}`) : text("等待系统推进", "Waiting for system progress"),
    owners,
  };
}

function workflowDueBucket(workflow) {
  if (!workflow?.dueDate) {
    return "none";
  }
  if (workflow.status === "approved") {
    return "safe";
  }
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const due = new Date(`${workflow.dueDate}T00:00:00`);
  const diffDays = Math.round((due.getTime() - today.getTime()) / (24 * 60 * 60 * 1000));
  if (diffDays <= 0) {
    return "overdue";
  }
  if (diffDays <= 2) {
    return "soon";
  }
  return "safe";
}

function workflowInstanceIssueStats(workflow) {
  const summary = {
    total: 0,
    open: 0,
    inProgress: 0,
    resolved: 0,
    replies: 0,
    attachments: 0,
  };
  workflowResolvedDocuments(workflow).forEach((doc) => {
    const docStats = issueStats(doc);
    summary.total += docStats.total;
    summary.open += docStats.open;
    summary.inProgress += docStats.inProgress;
    summary.resolved += docStats.resolved;
    summary.replies += docStats.replies;
    summary.attachments += docStats.attachments;
  });
  return summary;
}

function workflowInstanceFileSummary(workflow) {
  const docs = workflowResolvedDocuments(workflow);
  if (!docs.length) {
    return text("当前流程还没有关联文件", "No files linked to this workflow yet");
  }
  const names = docs.slice(0, 2).map((doc) => doc.name);
  return docs.length > 2
    ? text(`${names.join(" / ")} 等 ${docs.length} 个文件`, `${names.join(" / ")} and ${docs.length} files`)
    : names.join(" / ");
}

function workflowInstanceLatestActor(workflow) {
  return workflow?.activity?.[0]?.actor || workflow?.initiator || text("系统", "System");
}

function launchableWorkflowTemplates() {
  return state.workflowTemplates.filter((template) => template.permissions?.launch !== false);
}

function selectedLaunchTemplate() {
  const requestedId = state.launchFlowDraft.templateId;
  return launchableWorkflowTemplates().find((template) => template.id === requestedId) || launchableWorkflowTemplates()[0] || null;
}

function launchFlowSelectedDocuments() {
  return state.launchFlowSelectedIds.map((id) => documentById(id)).filter(Boolean);
}

function currentLaunchFlowSnapshot() {
  return {
    workflowName: state.launchFlowDraft.workflowName.trim(),
    templateId: state.launchFlowDraft.templateId,
    description: state.launchFlowDraft.description.trim(),
    selectedIds: [...state.launchFlowSelectedIds].sort(),
  };
}

function launchFlowIsDirty() {
  const current = currentLaunchFlowSnapshot();
  const initial = state.launchFlowInitialSnapshot || createEmptyLaunchFlowSnapshot();
  return (
    current.workflowName !== initial.workflowName ||
    current.templateId !== initial.templateId ||
    current.description !== initial.description ||
    current.selectedIds.join("|") !== (initial.selectedIds || []).join("|")
  );
}

function launchTemplateGroupKey(template) {
  return `${template.category || "项目级流程"}::${template.projectName || state.access.project?.name || "当前项目"}`;
}

function groupedLaunchTemplates() {
  const groups = [];
  launchableWorkflowTemplates().forEach((template) => {
    const key = launchTemplateGroupKey(template);
    let group = groups.find((item) => item.key === key);
    if (!group) {
      group = {
        key,
        category: template.category || "项目级流程",
        projectName: template.projectName || state.access.project?.name || "当前项目",
        templates: [],
      };
      groups.push(group);
    }
    group.templates.push(template);
  });
  return groups;
}

function isLaunchTemplateGroupOpen(groupKey) {
  if (!Object.prototype.hasOwnProperty.call(state.launchFlowTemplateOpenGroups, groupKey)) {
    return true;
  }
  return Boolean(state.launchFlowTemplateOpenGroups[groupKey]);
}

function defaultWorkflowFilePickerExpandedFolders() {
  const expanded = new Set();
  state.folders.forEach((folder) => {
    if (!folder.parentId) {
      expanded.add(folder.id);
    }
  });
  state.launchFlowSelectedIds.forEach((docId) => {
    let cursor = documentById(docId)?.parentId || null;
    while (cursor) {
      expanded.add(cursor);
      cursor = folderById(cursor)?.parentId || null;
    }
  });
  return [...expanded];
}

function workflowFileIdsForFolder(folderId) {
  const descendantIds = new Set([folderId]);
  let added = true;
  while (added) {
    added = false;
    state.folders.forEach((folder) => {
      if (folder.parentId && descendantIds.has(folder.parentId) && !descendantIds.has(folder.id)) {
        descendantIds.add(folder.id);
        added = true;
      }
    });
  }
  return state.documents.filter((doc) => descendantIds.has(doc.parentId)).map((doc) => doc.id);
}

function workflowFilesCountLabel(ids = state.launchFlowSelectedIds) {
  return text(`已选择 ${ids.length} 个文件`, `${ids.length} file${ids.length === 1 ? "" : "s"} selected`);
}

