function createMissingElementStub(name) {
  const element = document.createElement("div");
  element.dataset.stubElement = name;
  element.hidden = true;
  element.setAttribute("aria-hidden", "true");
  element.value = "";
  element.checked = false;
  element.disabled = false;
  element.open = false;
  element.showModal = () => {
    element.open = true;
  };
  element.close = () => {
    element.open = false;
  };
  element.select = () => {};
  element.focus = () => {};
  element.blur = () => {};
  element.click = () => {};
  element.scrollTo = () => {};
  element.scrollIntoView = () => {};
  element.reportValidity = () => true;
  element.querySelector = () => null;
  element.querySelectorAll = () => [];
  element.options = [];
  element.selectedOptions = [];
  element.getBoundingClientRect = () => ({
    left: 0,
    top: 0,
    width: 0,
    height: 0,
    right: 0,
    bottom: 0,
  });
  if (name === "pdfCanvas") {
    element.getContext = () => ({
      setTransform() {},
      clearRect() {},
      save() {},
      restore() {},
      scale() {},
      translate() {},
      beginPath() {},
      moveTo() {},
      lineTo() {},
      stroke() {},
      fillRect() {},
      fillText() {},
      measureText() {
        return { width: 0 };
      },
      canvas: element,
    });
  }
  return element;
}

Object.keys(elements).forEach((key) => {
  if (elements[key] === null) {
    elements[key] = createMissingElementStub(key);
  }
});

let startupLarkRedirectResult = null;

function setElementText(element, value) {
  if (element) {
    element.textContent = value;
  }
}

function setElementPlaceholder(element, value) {
  if (element) {
    element.placeholder = value;
  }
}

function setElementAttribute(element, attribute, value) {
  if (element) {
    element.setAttribute(attribute, value);
  }
}

function setSelectorText(selector, value) {
  const element = document.querySelector(selector);
  if (element) {
    element.textContent = value;
  }
}

function setSelectorsText(selector, value) {
  document.querySelectorAll(selector).forEach((element) => {
    element.textContent = value;
  });
}

function setSelectorAttribute(selector, attribute, value) {
  const element = document.querySelector(selector);
  if (element) {
    element.setAttribute(attribute, value);
  }
}


