  elements.modelClashModelList?.addEventListener("change", (event) => {
    const input = event.target;
    if (!(input instanceof HTMLInputElement) || input.type !== "checkbox") {
      return;
    }
    const docId = input.dataset.modelClashDoc || "";
    const doc = documentById(docId);
    if (!modelClashDocumentReady(doc)) {
      renderModelAppsPanel();
      return;
    }
    const selected = new Set(state.modelClashSelectedIds);
    if (input.checked) {
      selected.add(docId);
    } else {
      selected.delete(docId);
    }
    state.modelClashSelectedIds = Array.from(selected).filter((id) => modelClashDocumentReady(documentById(id)));
    renderModelAppsPanel();
  });
