  elements.modelAppsPanel?.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    const scheduleStepButton = target?.closest("[data-schedule-step]");
    if (scheduleStepButton instanceof HTMLElement) {
      setConstructionScheduleGuidePage(scheduleStepButton.dataset.scheduleStep || "model");
      return;
    }
    const quantityModelButton = target?.closest("[data-quantity-model]");
    if (quantityModelButton instanceof HTMLButtonElement) {
      selectQuantityModelDocument(quantityModelButton.dataset.quantityModel || "");
      return;
    }
    const healthModelButton = target?.closest("[data-model-health-model]");
    if (healthModelButton instanceof HTMLButtonElement) {
      selectModelHealthDocument(healthModelButton.dataset.modelHealthModel || "");
      return;
    }
    const diffModelButton = target?.closest("[data-model-diff-model]");
    if (diffModelButton instanceof HTMLButtonElement) {
      selectModelDiffDocument(diffModelButton.dataset.modelDiffModel || "");
      return;
    }
    const scheduleModelButton = target?.closest("[data-schedule-model]");
    if (scheduleModelButton instanceof HTMLButtonElement) {
      selectConstructionScheduleDocument(scheduleModelButton.dataset.scheduleModel || "");
      return;
    }
    const scheduleVersionButton = target?.closest("[data-schedule-version]");
    if (scheduleVersionButton instanceof HTMLButtonElement) {
      selectConstructionScheduleVersion(scheduleVersionButton.dataset.scheduleVersion || "");
      return;
    }
    const scheduleActionButton = target?.closest("[data-schedule-action]");
    if (scheduleActionButton instanceof HTMLButtonElement && !scheduleActionButton.disabled) {
      handleConstructionScheduleAction(scheduleActionButton.dataset.scheduleAction || "", scheduleActionButton);
      return;
    }
    const diffTaskButton = target?.closest("[data-model-diff-task]");
    if (diffTaskButton instanceof HTMLButtonElement) {
      state.modelDiffTaskId = diffTaskButton.dataset.modelDiffTask || "";
      void refreshModelDiffTaskDetail(state.modelDiffTaskId, { renderAfter: true });
      return;
    }
    const diffRecordRow = target?.closest("[data-model-diff-record]");
    if (diffRecordRow instanceof HTMLTableRowElement && !target?.closest("[data-model-diff-action]")) {
      state.modelDiffSelectedRecordId = diffRecordRow.dataset.modelDiffRecord || "";
      renderModelAppsPanel();
      return;
    }
    const diffActionButton = target?.closest("[data-model-diff-action]");
    if (diffActionButton instanceof HTMLButtonElement && !diffActionButton.disabled) {
      const action = diffActionButton.dataset.modelDiffAction || "";
      const recordId = diffActionButton.dataset.recordId || "";
      if (action === "detail") {
        state.modelDiffSelectedRecordId = recordId;
        renderModelAppsPanel();
      } else if (action === "viewer") {
        state.modelDiffSelectedRecordId = recordId || state.modelDiffSelectedRecordId;
        openModelDiffViewer(recordId);
      } else if (action === "issue") {
        void createIssueFromModelDiff(recordId);
      }
      return;
    }
    const healthActionButton = target?.closest("[data-model-health-action]");
    if (healthActionButton instanceof HTMLButtonElement && !healthActionButton.disabled) {
      handleModelHealthAction(healthActionButton.dataset.modelHealthAction || "", healthActionButton);
      return;
    }
    const actionButton = target?.closest("[data-model-app-action]");
    if (!(actionButton instanceof HTMLButtonElement)) {
      return;
    }
    if (actionButton.dataset.modelAppAction === "open-files") {
      void openFilesView({ confirm: false });
    }
    if (actionButton.dataset.modelAppAction === "open-aps-settings") {
      state.accessMenu = "aps_configuration";
      openAccessView();
    }
  });
