    const editButton = target.closest("[data-project-edit]");
    if (editButton instanceof HTMLButtonElement) {
      startProjectManagementEdit(editButton.dataset.projectEdit || "");
      return;
    }
    const memberSourceButton = target.closest("[data-project-use-member-source]");
    if (memberSourceButton instanceof HTMLButtonElement) {
      useProjectAsMemberSource(memberSourceButton.dataset.projectUseMemberSource || "");
      return;
    }
    const templateSourceButton = target.closest("[data-project-use-template-source]");
    if (templateSourceButton instanceof HTMLButtonElement) {
      useProjectAsTemplateSource(templateSourceButton.dataset.projectUseTemplateSource || "");
    }
