  document.addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof Element)) {
      return;
    }
    if (state.sidebarUserMenuOpen && !target.closest(".sidebar-user")) {
      closeSidebarUserMenu();
      return;
    }
    if (state.projectSwitcherOpen && !target.closest(".project-switcher")) {
      closeProjectSwitcher();
      return;
    }
    if (state.notificationPanelOpen && !target.closest(".header-notification-shell")) {
      closeNotificationPanel();
      return;
    }
    if ((state.libraryFilterPopoverOpen || state.libraryColumnSettingsPopoverOpen) && !target.closest(".folder-browser-tools")) {
      closeLibraryToolbarPopovers();
      return;
    }
    if (routeRowActionPortalClick(event, target)) {
      return;
    }
    if (state.openRowActionMenuKey && !target.closest(".row-menu-shell") && !target.closest(".row-action-menu-portal")) {
      closeRowActionMenu();
    }
    if (state.inlineRenameId && !target.closest(".inline-rename-shell")) {
      cancelInlineRename();
    }
    if (state.launchFlowTemplateMenuOpen && !target.closest(".workflow-template-picker-shell")) {
      state.launchFlowTemplateMenuOpen = false;
      renderLaunchFlowModal();
    }
  });
