function accessText(value) {
  if (currentLanguage() === "zh") {
    return value;
  }
  return ACCESS_EN_TEXT[value] || value;
}

function normalizeAccessMenu(value) {
  const aliasMap = {
    email_notifications: "email_channel",
  };
  const normalizedValue = aliasMap[value] || value;
  return [
    "overview",
    "project_management",
    "acc_integration",
    "acc_custom_integration",
    "hierarchy",
    "roles",
    "matrix",
    "guest_policy",
    "email_channel",
    "project_notifications",
    "aps_configuration",
    "ai_configuration",
    "members",
    "folder_permissions",
    "audit",
  ].includes(normalizedValue)
    ? normalizedValue
    : "overview";
}

function systemAccessMenus() {
  return new Set(["project_management", "aps_configuration", "ai_configuration", "email_channel", "hierarchy", "roles", "matrix"]);
}

function projectAccessMenus() {
  return new Set(["overview", "acc_integration", "acc_custom_integration", "ai_configuration", "guest_policy", "project_notifications", "members", "folder_permissions", "audit"]);
}

function normalizeAccessMenuForView(menu, view = state.currentView) {
  const normalizedMenu = normalizeAccessMenu(menu);
  if (view === "access") {
    return systemAccessMenus().has(normalizedMenu) ? normalizedMenu : "project_management";
  }
  if (view === "project-settings") {
    return projectAccessMenus().has(normalizedMenu) ? normalizedMenu : "overview";
  }
  return normalizedMenu;
}

function accessMenuSectionId(menu) {
  return {
    overview: "accessOverviewView",
    project_management: "accessProjectManagementView",
    acc_integration: "accessAccIntegrationView",
    acc_custom_integration: "accessAccCustomIntegrationView",
    hierarchy: "accessHierarchyView",
    roles: "accessRolesView",
    matrix: "accessMatrixView",
    guest_policy: "accessGuestPolicyView",
    email_channel: "accessEmailNotificationsView",
    project_notifications: "accessEmailNotificationsView",
    aps_configuration: "accessApsConfigurationView",
    ai_configuration: "accessAiConfigurationView",
    members: "accessMembersView",
    folder_permissions: "accessFolderPermissionView",
    audit: "accessAuditView",
  }[normalizeAccessMenu(menu)] || "accessOverviewView";
}

function normalizeProfileCenterTab(value) {
  return value === "security" ? "security" : "overview";
}

function closeSidebarUserMenu(options = {}) {
  state.sidebarUserMenuOpen = false;
  if (options.render !== false) {
    render();
  } else {
    if (state.pdfDoc && !elements.canvasWrap.classList.contains("hidden")) {
      syncAnnotationLayerBounds();
    }
    elements.annotationLayer.classList.toggle("interactive", isReviewDrawModeActive());
    syncReviewCursorState();
  }
}

function openProfileCenterModal(tab = "overview") {
  if (!currentUser()) {
    return;
  }
  prepareExclusiveOverlay("profileCenter");
  state.profileCenterModalOpen = true;
  state.profileCenterTab = normalizeProfileCenterTab(tab);
  render();
}

function closeProfileCenterModal(options = {}) {
  state.profileCenterModalOpen = false;
  state.overlayFocusedKey = "";
  if (options.render !== false) {
    render();
  } else {
    if (state.pdfDoc && !elements.canvasWrap.classList.contains("hidden")) {
      syncAnnotationLayerBounds();
    }
    elements.annotationLayer.classList.toggle("interactive", isReviewDrawModeActive());
    syncReviewCursorState();
  }
}

function inviteStatusMeta(status) {
  if (status === "expired") {
    return {
      label: text("已过期", "Expired"),
      tone: "alert",
    };
  }
  if (status === "accepted") {
    return {
      label: text("已接受", "Accepted"),
      tone: "success",
    };
  }
  return {
    label: text("待接受", "Pending"),
    tone: "info",
  };
}

function inviteUrlFromRecord(invite) {
  const inviteToken = String(invite?.inviteToken || "").trim();
  if (!inviteToken) {
    return "";
  }
  return new URL(`/invite.html?invite=${encodeURIComponent(inviteToken)}`, window.location.origin).toString();
}

function closeProjectSwitcher() {
  if (!state.projectSwitcherOpen) {
    return;
  }
  state.projectSwitcherOpen = false;
  renderProjectSwitcher();
}

function clearNotificationPolling() {
  if (!notificationPollTimer) {
    return;
  }
  window.clearTimeout(notificationPollTimer);
  notificationPollTimer = 0;
}

function ensureNotificationPolling() {
  clearNotificationPolling();
  if (!state.authenticated || document.hidden) {
    return;
  }
  notificationPollTimer = window.setTimeout(async () => {
    notificationPollTimer = 0;
    try {
      await refreshNotificationCenter();
    } finally {
      ensureNotificationPolling();
    }
  }, NOTIFICATION_POLL_INTERVAL_MS);
}

function closeNotificationPanel(options = {}) {
  if (!state.notificationPanelOpen) {
    return;
  }
  state.notificationPanelOpen = false;
  if (options.render !== false) {
    renderNotificationCenter();
  }
}

function projectSwitcherMetaLabel(project) {
  if (!project) {
    return "";
  }
  const code = project.code || text("未编码", "No Code");
  const roleLabel = project.roleLabel || text("未分配角色", "No Role");
  return `${code} · ${roleLabel}`;
}

function projectSwitcherCountsLabel(project) {
  if (!project) {
    return "";
  }
  return text(
    `${project.documentCount || 0} 份文件 · ${project.workflowCount || 0} 条流程 · ${project.memberCount || 0} 名成员`,
    `${project.documentCount || 0} files · ${project.workflowCount || 0} workflows · ${project.memberCount || 0} members`,
  );
}

function renderProjectSwitcher() {
  const access = currentAccess();
  const currentProject = access.project;
  const projects = Array.isArray(access.projects) ? access.projects : [];
  const visible = Boolean(state.authenticated && currentProject && elements.projectSwitcher && state.currentView !== "access");
  elements.projectSwitcher?.classList.toggle("hidden", !visible);
  if (!visible) {
    return;
  }

  setElementText(elements.projectSwitchLabel, text("当前项目", "Project"));
  setElementText(elements.projectSwitchCurrentName, currentProject?.name || text("未选择项目", "No project selected"));
  elements.projectSwitchButton.disabled = state.projectSwitchBusy || projects.length <= 1;
  elements.projectSwitchButton.setAttribute(
    "aria-expanded",
    String(Boolean(state.projectSwitcherOpen && projects.length > 1)),
  );

  const menuOpen = state.projectSwitcherOpen && projects.length > 1;
  elements.projectSwitchMenu.classList.toggle("hidden", !menuOpen);
  elements.projectSwitchMenu.innerHTML = projects
    .map((project) => `
      <button
        class="project-switch-item${project.id === currentProject?.id ? " active" : ""}"
        type="button"
        role="menuitem"
        data-project-id="${escapeHtml(project.id)}"
        ${state.projectSwitchBusy || project.id === currentProject?.id ? "disabled" : ""}
      >
        <span class="project-switch-item-head">
          <strong class="project-switch-item-name">${escapeHtml(project.name || text("未命名项目", "Untitled Project"))}</strong>
          <span class="project-switch-item-code">${escapeHtml(project.code || "")}</span>
        </span>
        <span class="project-switch-item-meta">${escapeHtml(projectSwitcherMetaLabel(project))}</span>
        <span class="project-switch-item-counts">${escapeHtml(projectSwitcherCountsLabel(project))}</span>
      </button>
    `)
    .join("");
}

async function refreshNotificationCenter() {
  if (!state.authenticated || state.notificationRefreshing) {
    return;
  }
  state.notificationRefreshing = true;
  renderNotificationCenter();
  try {
    const response = await fetchJson("/api/notifications");
    state.notificationCenter = normalizeNotificationCenterPayload(response.notificationCenter);
  } catch (error) {
    console.warn("[notifications]", error);
  } finally {
    state.notificationRefreshing = false;
    renderNotificationCenter();
    ensureNotificationPolling();
  }
}

async function markNotificationKeysRead(keys = []) {
  const unreadKeys = [...new Set((Array.isArray(keys) ? keys : []).map((item) => String(item || "").trim()).filter(Boolean))];
  if (!unreadKeys.length) {
    return;
  }
  const response = await postJson("/api/notifications/read", {
    keys: unreadKeys,
  });
  state.notificationCenter = normalizeNotificationCenterPayload(response.notificationCenter);
  renderNotificationCenter();
}

async function markAllNotificationsRead() {
  if (state.notificationTab !== "notifications") {
    return;
  }
  const unreadKeys = currentNotificationCenter().notifications
    .filter((item) => !item.read)
    .map((item) => item.key)
    .filter(Boolean);
  if (!unreadKeys.length) {
    return;
  }
  await markNotificationKeysRead(unreadKeys);
}

async function openNotificationEntry(button) {
  const action = String(button.dataset.notificationAction || "").trim();
  const workflowId = String(button.dataset.notificationWorkflowId || "").trim();
  const documentId = String(button.dataset.notificationDocumentId || "").trim();
  const source = String(button.dataset.notificationSource || "").trim();
  const key = String(button.dataset.notificationKey || "").trim();

  if (source === "notifications" && key) {
    try {
      await markNotificationKeysRead([key]);
    } catch (error) {
      showAlert(error.message || text("更新通知状态失败，请稍后重试。", "Failed to update notification state. Please try again."));
      return;
    }
  }

  closeNotificationPanel({ render: false });

  if (action === "openWorkflowReview" && workflowId) {
    await openWorkflowReview(workflowId, documentId ? { docId: documentId } : {});
    return;
  }
  if (action === "openWorkflow" && workflowId) {
    openWorkflowView();
    await openWorkflowDetailModal(workflowId, "flow");
    return;
  }
  if (action === "openAccessMembers") {
    state.accessMenu = "members";
    openProjectSettingsView();
    return;
  }
  if (action === "openDocument" && documentId) {
    const doc = documentById(documentId);
    if (doc && canPreviewDocument(doc) && canOpenDocumentWorkspace(doc)) {
      openDocumentWorkspace(doc.id, {
        mode: "view",
      });
      void selectDocument(documentId);
      return;
    }
    await selectDocument(documentId);
    void openFilesView({
      confirm: false,
    });
    return;
  }

  render();
}

async function switchProject(projectId) {
  const currentProjectId = currentAccess().project?.id || "";
  if (!projectId || state.projectSwitchBusy || projectId === currentProjectId) {
    closeProjectSwitcher();
    return;
  }

  state.projectSwitchBusy = true;
  state.projectSwitcherOpen = false;
  renderProjectSwitcher();

  try {
    resetWorkspaceContext({ view: state.currentView === "review" ? "files" : state.currentView });
    state.libraryInitialized = false;
    state.currentFolderId = null;
    state.selectedId = null;
    state.selectedWorkflowId = null;
    resetDrawingSmartReviewRuntimeState(text("项目已切换，请重新选择图纸运行智能审查。", "Project switched. Select drawings again before running pre-check."));
    resetDrawingSpecCheckRuntimeState("Project switched. Reload Drawing-Spec Check data for this project.");

    const response = await postJson("/api/session/project", { projectId });
    state.access = normalizeAccessPayload(response.access);
    state.currentUserId = state.access.currentUser?.id || state.currentUserId;
    resetEmailConfigurationDrafts(state.access);
    resetAiConfigurationDraft(state.access);
    resetApsConfigurationDraft(state.access);
    await refreshDocuments(response);
    await hydrateResumableUploadSessions();
    if (state.currentView === "drawing-apps" && state.drawingAppTool === "drawing_register") {
      await refreshDrawingRegisterData({ renderAfter: false });
    } else if (state.currentView === "drawing-apps" && state.drawingAppTool === "redline_compare") {
      await refreshDrawingRedlineData({ renderAfter: false });
    } else if (state.currentView === "drawing-apps" && state.drawingAppTool === "spec_check") {
      await refreshDrawingSpecCheckData({ renderAfter: false });
    }
  } catch (error) {
    showAlert(error.message || text("项目切换失败，请稍后重试。", "Failed to switch projects. Please try again."));
  } finally {
    state.projectSwitchBusy = false;
    render();
  }
}

function renderUserChrome() {
  const user = currentUser();
  elements.sidebarUserAvatar.textContent = userAvatarText(user);
  elements.sidebarUserName.textContent = user?.name || text("未登录", "Not signed in");
  elements.sidebarUserRole.textContent = user?.roleLabel || text("访客", "Guest");
  elements.sidebarUserEmail.textContent = user?.email || text("请先登录", "Please sign in");
  elements.sidebarUserMenuButton.disabled = !user;
  elements.sidebarUserMenuButton.setAttribute("aria-expanded", String(Boolean(state.sidebarUserMenuOpen && user)));
  elements.sidebarUserMenu.classList.toggle("hidden", !(state.sidebarUserMenuOpen && user));
  elements.openSystemSettingsButton.classList.toggle("hidden", !canOpenSystemSettings());
  elements.openSystemSettingsButton.disabled = !canOpenSystemSettings();
  elements.sidebarLogoutButton.disabled = state.authBusy;
  renderProjectSwitcher();
  renderNotificationCenter();
}

function notificationTimestampLabel(value, { dateOnly = false } = {}) {
  if (!value || Number.isNaN(Date.parse(value))) {
    return text("刚刚", "Just now");
  }
  return dateOnly ? formatDate(value) : formatDateTime(value);
}

function notificationEmptyMessage() {
  if (state.notificationTab === "notifications") {
    return text("当前没有新的站内通知。", "There are no new in-app notifications.");
  }
  return text("当前没有待你处理的流程节点。", "There are no workflow steps waiting for you.");
}

function renderNotificationCenter() {
  const center = currentNotificationCenter();
  const visible = Boolean(state.authenticated && currentUser() && elements.notificationToggleButton);
  const panelOpen = visible && state.notificationPanelOpen;
  const badgeCount = center.badgeCount || 0;
  const notificationCount = center.unreadCount || 0;

  if (elements.notificationToggleButton) {
    elements.notificationToggleButton.disabled = !visible;
    elements.notificationToggleButton.setAttribute("aria-expanded", String(panelOpen));
  }
  if (elements.notificationBadge) {
    elements.notificationBadge.textContent = notificationBadgeText(badgeCount);
    elements.notificationBadge.classList.toggle("hidden", !visible || badgeCount <= 0);
  }
  if (elements.notificationPanel) {
    elements.notificationPanel.classList.toggle("hidden", !panelOpen);
    elements.notificationPanel.setAttribute("aria-hidden", panelOpen ? "false" : "true");
  }
  if (!visible) {
    return;
  }

  setElementText(elements.notificationPanelKicker, text("工作台提醒", "Workspace Alerts"));
  setElementText(elements.notificationPanelTitle, text("通知与待办", "Notifications & Tasks"));
  setElementText(elements.notificationMarkAllButton, text("全部已读", "Mark All Read"));
  setElementText(elements.notificationTodoTab?.querySelector("span:first-child"), text("待办", "Tasks"));
  setElementText(elements.notificationFeedTab?.querySelector("span:first-child"), text("通知", "Notifications"));
  elements.notificationMarkAllButton.disabled =
    state.notificationTab !== "notifications" || notificationCount <= 0 || state.notificationRefreshing;

  elements.notificationTodoCount.textContent = notificationBadgeText(center.todoCount || 0);
  elements.notificationFeedCount.textContent = notificationBadgeText(notificationCount);

  elements.notificationTabs.forEach((button) => {
    const active = (button.dataset.notificationTab || "") === state.notificationTab;
    button.classList.toggle("active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });

  const items = notificationCurrentItems();
  if (!items.length) {
    elements.notificationPanelList.innerHTML = `
      <div class="notification-empty-card">
        <strong>${escapeHtml(text("一切就绪", "All Clear"))}</strong>
        <p>${escapeHtml(notificationEmptyMessage())}</p>
      </div>
    `;
    return;
  }

  elements.notificationPanelList.innerHTML = items
    .map((item) => {
      if (state.notificationTab === "notifications") {
        const note = item.note || item.subject || item.label || text("有新的文件动态。", "There is a new file update.");
        return `
          <button
            class="notification-item notification-tone-${escapeHtml(item.tone || "info")}${item.read ? " is-read" : ""}"
            type="button"
            data-notification-source="notifications"
            data-notification-key="${escapeHtml(item.key || "")}"
            data-notification-action="${escapeHtml(item.action || "")}"
            data-notification-workflow-id="${escapeHtml(item.workflowId || "")}"
            data-notification-document-id="${escapeHtml(item.documentId || "")}"
          >
            <div class="notification-item-top">
            <span class="notification-item-pill ${escapeHtml(item.tone || "info")}">${escapeHtml(localizeMixedText(item.label || text("通知", "Notification")))}</span>
              <span class="notification-item-time">${escapeHtml(notificationTimestampLabel(item.timestamp))}</span>
            </div>
            <strong>${escapeHtml(localizeMixedText(item.title || text("未命名动态", "Untitled Update")))}</strong>
            <p>${escapeHtml(truncate(localizeMixedText(String(note)), 82))}</p>
            <div class="notification-item-meta">
              <span>${escapeHtml(localizeMixedText([item.actor, item.subject].filter(Boolean).join(" · ") || text("系统提醒", "System Alert")))}</span>
              ${item.read ? "" : '<span class="notification-item-unread"></span>'}
            </div>
          </button>
        `;
      }

      const dueLabel = item.dueDate
        ? text(`截止 ${notificationTimestampLabel(item.dueDate, { dateOnly: true })}`, `Due ${notificationTimestampLabel(item.dueDate, { dateOnly: true })}`)
        : text("等待处理", "Pending");
      return `
        <button
          class="notification-item notification-tone-info"
          type="button"
          data-notification-source="todo"
          data-notification-key="${escapeHtml(item.key || "")}"
          data-notification-action="${escapeHtml(item.action || "")}"
          data-notification-workflow-id="${escapeHtml(item.workflowId || "")}"
          data-notification-document-id="${escapeHtml(item.documentId || "")}"
        >
          <div class="notification-item-top">
            <span class="notification-item-pill info">${escapeHtml(localizeMixedText(item.stepName || text("待办", "Task")))}</span>
            <span class="notification-item-time">${escapeHtml(dueLabel)}</span>
          </div>
          <strong>${escapeHtml(localizeMixedText(item.title || text("未命名流程", "Untitled Workflow")))}</strong>
          <p>${escapeHtml(localizeMixedText([item.subject, item.note].filter(Boolean).join(" · ")))}</p>
          <div class="notification-item-meta">
            <span>${escapeHtml(text(`更新于 ${notificationTimestampLabel(item.updatedAt)}`, `Updated ${notificationTimestampLabel(item.updatedAt)}`))}</span>
            <span>${escapeHtml(text("点击进入处理", "Open to act"))}</span>
          </div>
        </button>
      `;
    })
    .join("");
}

function renderAccessPanel() {
  const access = currentAccess();
  const capabilities = currentCapabilities();
  const user = currentUser();
  const accessMenu = normalizeAccessMenuForView(state.accessMenu);
  state.accessMenu = accessMenu;
  setSelectorText("#accessPanel .access-panel-head .panel-kicker", accessRootTitle(state.currentView));
  setSelectorText("#accessPanel .access-panel-head h3", accessMenuTitle(accessMenu));
  const currentRoleLabel = user?.roleLabel || text("访客", "Guest");
  const lastLoginLabel = user?.lastLoginAt
    ? text(`最近登录 ${formatDateTime(user.lastLoginAt)}`, `Last login ${formatDateTime(user.lastLoginAt)}`)
    : text("尚无登录记录", "No login history");

  elements.accessMenuButtons.forEach((button) => {
    button.classList.toggle("active", button.dataset.accessMenu === accessMenu);
  });
  elements.accessViewSections.forEach((section) => {
    section.classList.toggle("hidden", section.id !== accessMenuSectionId(accessMenu));
  });

  elements.accessCurrentRoleBadge.textContent = currentRoleLabel;
  elements.profileCurrentRoleBadge.textContent = currentRoleLabel;
  elements.accessCurrentAccountName.textContent = user?.name || text("未登录", "Not signed in");
  elements.accessCurrentAccountMeta.textContent = [user?.email || text("无邮箱", "No email"), currentRoleLabel, lastLoginLabel].join(" · ");
  elements.accessSummaryCards.innerHTML = renderAccessSummaryCards(access, capabilities);
  syncProjectManagementDraft();
  renderProjectManagementPanel();
  elements.accessRoleCards.innerHTML = renderAccessRoleCards();
  elements.accessMatrixTable.innerHTML = renderAccessMatrix();
  renderGuestPolicySection(access, capabilities);
  renderEmailConfigurationSection(access, capabilities);
  renderApsConfigurationSection(access, capabilities);
  renderAiConfigurationSection(access, capabilities);

  const inviteRoleOptions = accessInviteRoleOptions();
  const defaultInviteRole = inviteRoleOptions.some((option) => option.value === "guest")
    ? "guest"
    : inviteRoleOptions[0]?.value || "";
  const currentInviteRole = inviteRoleOptions.some((option) => option.value === elements.accessAddMemberRole.value)
    ? elements.accessAddMemberRole.value
    : defaultInviteRole;

  setSelectOptions(elements.accessAddMemberRole, inviteRoleOptions, currentInviteRole);
  setSelectOptions(elements.folderPermissionFolderSelect, accessFolderOptions(), access.folders?.[0]?.id || "");
  setSelectOptions(elements.folderPermissionUserSelect, accessMemberUserOptions(), access.projectMembers?.[0]?.user?.id || "");
  setSelectOptions(elements.folderPermissionRoleSelect, accessFolderPermissionOptions(), "viewer");

  elements.accessAddMemberName.disabled = !capabilities.manageMembers;
  elements.accessAddMemberEmail.disabled = !capabilities.manageMembers;
  elements.accessAddMemberRole.disabled = !capabilities.manageMembers;
  elements.accessInviteExpiryInput.disabled = !capabilities.manageMembers;
  elements.accessAddMemberButton.disabled = !capabilities.manageMembers;
  elements.accessChangePasswordButton.disabled = state.authBusy || !user;
  elements.accessCurrentPasswordInput.disabled = state.authBusy || !user;
  elements.accessNewPasswordInput.disabled = state.authBusy || !user;
  elements.accessConfirmPasswordInput.disabled = state.authBusy || !user;
  elements.guestPolicySaveButton.disabled = !capabilities.manageGuestPolicy;
  elements.folderPermissionSaveButton.disabled = !capabilities.setFolderPermissions;
  elements.accessPasswordHint.textContent = user?.mustChangePassword
    ? text("当前账号仍在使用临时密码，请尽快完成修改。", "This account is still using a temporary password. Please change it soon.")
    : text("当前账号可在这里修改登录密码；新建账号首次登录后建议立即改密。", "You can change your sign-in password here. New accounts should change it after the first login.");
  elements.accessPasswordMessage.textContent = state.accessPasswordMessage || "";
  elements.accessPasswordMessage.classList.toggle("hidden", !state.accessPasswordMessage);
  elements.accessInviteResult.textContent = state.accessInviteResult || "";
  elements.accessInviteResult.classList.toggle("hidden", !state.accessInviteResult);

  renderMemberInvites();
  renderAccessMembers();
  renderFolderPermissionsList();
  renderAuditLogs();
}

