function drawingRegisterStatusTone(key) {
  if (["approved", "published", "pass", "uploaded", "confirmed"].includes(String(key || ""))) return "approved";
  if (["warning", "partial", "extra"].includes(String(key || ""))) return "warning";
  if (["in_review", "unmarked"].includes(String(key || ""))) return "final_review";
  if (["rejected", "not_approved", "overdue"].includes(String(key || ""))) return "rejected";
  return "neutral";
}

function drawingRegisterCompletenessKey(version) {
  const hasPdf = Boolean(version?.formats?.pdf);
  const hasDwg = Boolean(version?.formats?.dwg);
  if (hasPdf && hasDwg) return "both";
  if (hasPdf) return "onlyPdf";
  if (hasDwg) return "onlyDwg";
  return "missing";
}

function drawingRegisterCompletenessLabel(key) {
  return {
    both: text("PDF+DWG", "PDF+DWG"),
    onlyPdf: text("仅 PDF", "PDF only"),
    onlyDwg: text("仅 DWG", "DWG only"),
    missing: text("缺失", "Missing"),
  }[key] || key;
}

function drawingRegisterAutoAggregationCount(entries = state.drawingRegisterEntries || []) {
  return (entries || []).filter((entry) =>
    entry.currentVersion?.metadataSource === "auto" ||
    entry.currentVersion?.requiresMetadataConfirmation,
  ).length;
}

function drawingRegisterSourceKey(version) {
  if (!version) return "unknown";
  if (version.metadataSource === "declared") return "declared";
  if (version.metadataSource === "auto" && version.metadataConfidence === "filename_loose") return "weak";
  if (version.metadataSource === "auto" || version.requiresMetadataConfirmation) return "auto";
  return "unknown";
}

function drawingRegisterSourceSummary(entries = state.drawingRegisterEntries || []) {
  return (entries || []).reduce(
    (summary, entry) => {
      const key = drawingRegisterSourceKey(entry.currentVersion);
      summary.total += 1;
      summary[key] = (summary[key] || 0) + 1;
      return summary;
    },
    { total: 0, declared: 0, auto: 0, weak: 0, unknown: 0 },
  );
}

function drawingRegisterFilteredEntries() {
  const filters = state.drawingRegisterFilters || {};
  const query = String(filters.query || "").trim().toLowerCase();
  return (state.drawingRegisterEntries || []).filter((entry) => {
    const version = entry.currentVersion || {};
    if (query) {
      const haystack = [entry.drawingNo, entry.name, entry.discipline, version.version]
        .map((item) => String(item || "").toLowerCase())
        .join(" ");
      if (!haystack.includes(query)) {
        return false;
      }
    }
    if (filters.discipline && filters.discipline !== "all" && entry.discipline !== filters.discipline) {
      return false;
    }
    if (filters.approval && filters.approval !== "all" && version.approvalStatusKey !== filters.approval) {
      return false;
    }
    if (filters.publish && filters.publish !== "all" && version.publishStatusKey !== filters.publish) {
      return false;
    }
    if (filters.completeness && filters.completeness !== "all" && drawingRegisterCompletenessKey(version) !== filters.completeness) {
      return false;
    }
    if (filters.source && filters.source !== "all" && drawingRegisterSourceKey(version) !== filters.source) {
      return false;
    }
    return true;
  });
}

function pruneDrawingRegisterSelection() {
  const validIds = new Set((state.drawingRegisterEntries || []).flatMap((entry) => (entry.versions || []).map((version) => version.id)));
  state.drawingRegisterSelectedVersionIds = Array.from(new Set(state.drawingRegisterSelectedVersionIds || [])).filter((id) => validIds.has(id));
  state.drawingRegisterExpandedIds = Array.from(new Set(state.drawingRegisterExpandedIds || [])).filter((id) => validIds.has(id));
}

