function modelHealthTemplateProfile(ruleset) {
  const source = ruleset || {};
  const rules = source.rules || {};
  const profile = rules.templateProfile && typeof rules.templateProfile === "object" ? rules.templateProfile : {};
  const disciplines = Array.isArray(rules.templateDisciplines) ? rules.templateDisciplines : [];
  const requiredFields = rules.requiredFields && typeof rules.requiredFields === "object" ? rules.requiredFields : {};
  const aiChecks = Array.isArray(rules.aiChecks?.checks) ? rules.aiChecks.checks : [];
  const crossDisciplineChecks = Array.isArray(rules.crossDisciplineChecks) ? rules.crossDisciplineChecks : [];
  const notes = Array.isArray(rules.projectSpecificNotes) ? rules.projectSpecificNotes : [];
  const scoreCalculation = rules.scoreCalculation && typeof rules.scoreCalculation === "object" ? rules.scoreCalculation : {};
  const gateConfig = source.gateConfig || {};
  const disciplineSummaries = disciplines.map((discipline) => {
    const elementTypes = Array.isArray(discipline.element_types) ? discipline.element_types : [];
    const requiredCount = elementTypes.reduce((sum, element) => sum + (Array.isArray(element.required_properties) ? element.required_properties.length : 0), 0);
    const governanceCount = [
      ...(discipline.layer_checks?.allowlist || []),
      ...(discipline.workset_checks?.allowlist || []),
    ].length;
    return {
      id: discipline.id || "",
      name: discipline.name || discipline.id || text("未命名专业", "Unnamed discipline"),
      software: discipline.software || "",
      elementCount: elementTypes.length,
      requiredCount,
      governanceCount,
      examples: elementTypes.slice(0, 4).map((element) => element.display_name || element.type).filter(Boolean),
    };
  });
  const fallbackElementCount = Object.keys(requiredFields).length;
  const fallbackRequiredCount = Object.values(requiredFields).reduce((sum, fields) => sum + (Array.isArray(fields) ? fields.length : 0), 0);
  const totalElementTypes = disciplineSummaries.length
    ? disciplineSummaries.reduce((sum, item) => sum + item.elementCount, 0)
    : fallbackElementCount;
  const totalRequiredFields = disciplineSummaries.length
    ? disciplineSummaries.reduce((sum, item) => sum + item.requiredCount, 0)
    : fallbackRequiredCount;
  const minScore = Number(gateConfig.minScoreToSubmit ?? scoreCalculation.min_score_to_pass ?? 0) || 0;
  return {
    id: profile.id || source.id || "",
    name: profile.name || source.name || text("健康度模板", "Health template"),
    projectType: profile.projectType || profile.project_type || profile.discipline || source.description || "",
    version: profile.version || source.version || "",
    gateMode: gateConfig.mode || "standard",
    minScore,
    blockOnError: gateConfig.errorThreshold === undefined ? true : Number(gateConfig.errorThreshold) <= 0,
    requireWarningDisposition: gateConfig.requireWarningDisposition !== false,
    aiEnabled: gateConfig.aiEnabled !== false && rules.aiChecks?.enabled !== false,
    disciplineCount: disciplines.length,
    totalElementTypes,
    totalRequiredFields,
    crossDisciplineChecks,
    aiChecks,
    notes,
    disciplineSummaries,
    allowedSystemsCount: Array.isArray(rules.allowedSystems) ? rules.allowedSystems.length : 0,
    allowedWorksetsCount: Array.isArray(rules.allowedWorksets) ? rules.allowedWorksets.length : 0,
  };
}

function renderModelHealthTemplateSummary(ruleset) {
  if (!elements.modelHealthTemplateSummaryPanel) {
    return;
  }
  if (!ruleset) {
    if (elements.modelHealthTemplateSummaryBadge) {
      elements.modelHealthTemplateSummaryBadge.textContent = text("未选择", "Not selected");
      elements.modelHealthTemplateSummaryBadge.className = "mini-pill";
    }
    if (elements.modelHealthTemplateSummaryGrid) {
      elements.modelHealthTemplateSummaryGrid.innerHTML = `<div class="empty-card">${escapeHtml(text("选择规则集后显示模板概要。", "Select a ruleset to show the template summary."))}</div>`;
    }
    if (elements.modelHealthTemplateDisciplineSummary) elements.modelHealthTemplateDisciplineSummary.innerHTML = "";
    if (elements.modelHealthTemplateAiSummary) elements.modelHealthTemplateAiSummary.innerHTML = "";
    if (elements.modelHealthTemplateNotes) elements.modelHealthTemplateNotes.innerHTML = "";
    return;
  }

  const profile = modelHealthTemplateProfile(ruleset);
  if (elements.modelHealthTemplateSummaryBadge) {
    elements.modelHealthTemplateSummaryBadge.textContent = ruleset.builtIn ? text("内置模板", "Built-in") : text("项目模板", "Project");
    elements.modelHealthTemplateSummaryBadge.className = "mini-pill status-pill approved";
  }
  if (elements.modelHealthTemplateSummaryGrid) {
    const cards = [
      { label: text("模板编号", "Template ID"), value: profile.id || "—" },
      { label: text("项目类型", "Project Type"), value: profile.projectType || "—" },
      { label: text("版本", "Version"), value: profile.version || "—" },
      { label: text("门控", "Gate"), value: `${modelHealthGateModeLabel(profile.gateMode)} · ${profile.minScore ? text(`${profile.minScore} 分`, `${profile.minScore} pts`) : text("无评分阈值", "No score threshold")}` },
      { label: text("覆盖专业", "Disciplines"), value: text(`${profile.disciplineCount || 1} 个`, `${profile.disciplineCount || 1}`) },
      { label: text("构件类型", "Element Types"), value: text(`${profile.totalElementTypes} 类`, `${profile.totalElementTypes}`) },
      { label: text("必填字段", "Required Fields"), value: text(`${profile.totalRequiredFields} 项`, `${profile.totalRequiredFields}`) },
      { label: text("跨专业规则", "Cross Checks"), value: text(`${profile.crossDisciplineChecks.length} 项`, `${profile.crossDisciplineChecks.length}`) },
    ];
    elements.modelHealthTemplateSummaryGrid.innerHTML = cards.map((card) => `
      <div class="model-health-template-summary-item">
        <span>${escapeHtml(card.label)}</span>
        <strong>${escapeHtml(card.value)}</strong>
      </div>
    `).join("");
  }
  if (elements.modelHealthTemplateDisciplineSummary) {
    const disciplineRows = profile.disciplineSummaries.length
      ? profile.disciplineSummaries.map((discipline) => `
          <article class="model-health-template-discipline-row">
            <div>
              <strong>${escapeHtml(discipline.name)}</strong>
              <span>${escapeHtml(discipline.software || "—")}</span>
            </div>
            <p>${escapeHtml(text(`${discipline.elementCount} 类构件 · ${discipline.requiredCount} 个必填字段${discipline.governanceCount ? ` · ${discipline.governanceCount} 项图层/工作集约束` : ""}`, `${discipline.elementCount} element types · ${discipline.requiredCount} required fields${discipline.governanceCount ? ` · ${discipline.governanceCount} layer/workset rules` : ""}`))}</p>
            <small>${escapeHtml(discipline.examples.join(" / ") || text("暂无构件类型", "No element types"))}</small>
          </article>
        `).join("")
      : `<article class="model-health-template-discipline-row"><div><strong>${escapeHtml(ruleset.discipline || text("通用模板", "General"))}</strong><span>${escapeHtml(text("规则字段", "Rule fields"))}</span></div><p>${escapeHtml(text(`${profile.totalElementTypes} 类构件 · ${profile.totalRequiredFields} 个必填字段`, `${profile.totalElementTypes} element types · ${profile.totalRequiredFields} required fields`))}</p></article>`;
    elements.modelHealthTemplateDisciplineSummary.innerHTML = `
      <div class="model-health-template-section-title">${escapeHtml(text("专业覆盖", "Discipline Coverage"))}</div>
      ${disciplineRows}
    `;
  }
  if (elements.modelHealthTemplateAiSummary) {
    const aiRows = profile.aiChecks.length
      ? profile.aiChecks.map((check) => `
          <div class="model-health-template-ai-row">
            <strong>${escapeHtml(check.id || "AI")}</strong>
            <span>${escapeHtml(check.name || check.description || text("AI 检查", "AI check"))}</span>
          </div>
        `).join("")
      : `<div class="empty-card">${escapeHtml(text("当前模板未配置 AI 异常识别。", "No AI anomaly checks configured."))}</div>`;
    elements.modelHealthTemplateAiSummary.innerHTML = `
      <div class="model-health-template-section-title">${escapeHtml(text(`AI 异常识别 · ${profile.aiEnabled ? "已启用" : "未启用"}`, `AI Checks · ${profile.aiEnabled ? "Enabled" : "Disabled"}`))}</div>
      ${aiRows}
    `;
  }
  if (elements.modelHealthTemplateNotes) {
    const noteRows = profile.notes.length
      ? profile.notes.map((note) => `<li>${escapeHtml(note)}</li>`).join("")
      : `<li>${escapeHtml(text("暂无项目特定注意事项。", "No project-specific notes."))}</li>`;
    elements.modelHealthTemplateNotes.innerHTML = `
      <div class="model-health-template-section-title">${escapeHtml(text("海水淡化专项注意事项", "Desalination Notes"))}</div>
      <ul>${noteRows}</ul>
    `;
  }
}

