function renderModelHealthReportPanels(report) {
  if (!elements.modelHealthReportBadge) {
    return;
  }
  const summary = report?.summary || state.modelHealthLatestTask?.summary || {};
  elements.modelHealthReportBadge.textContent = report ? text(`${report.score ?? state.modelHealthLatestTask?.score ?? 0} 分`, `${report.score ?? state.modelHealthLatestTask?.score ?? 0} pts`) : text("未生成", "Not generated");
  elements.modelHealthRuleBadge.textContent = text(`${(summary.errorCount || 0) + (summary.warningCount || 0) + (summary.infoCount || 0)} 项`, `${(summary.errorCount || 0) + (summary.warningCount || 0) + (summary.infoCount || 0)} items`);
  elements.modelHealthAiBadge.textContent = text(`${summary.aiCount || 0} 项`, `${summary.aiCount || 0} items`);
  const categoryItems = modelHealthCombinedIssues().reduce((map, issue) => {
    const key = issue.category || text("未分类", "Uncategorized");
    const current = map.get(key) || { category: key, total: 0, error: 0, warning: 0, ai: 0 };
    current.total += 1;
    if (issue.source === "ai") current.ai += 1;
    else if (issue.level === "error") current.error += 1;
    else if (issue.level === "warning") current.warning += 1;
    map.set(key, current);
    return map;
  }, new Map());
  elements.modelHealthCategorySummary.innerHTML = categoryItems.size
    ? [...categoryItems.values()].sort((left, right) => right.total - left.total).map((item) => `
        <div class="model-health-category-row">
          <strong>${escapeHtml(item.category)}</strong>
          <span>${escapeHtml(text(`${item.total} 项 · Error ${item.error} · Warning ${item.warning} · AI ${item.ai}`, `${item.total} total · Error ${item.error} · Warning ${item.warning} · AI ${item.ai}`))}</span>
        </div>
      `).join("")
    : `<div class="empty-card">${escapeHtml(text("报告生成后会按问题类别、构件类型、楼层和专业汇总。", "Category, element type, floor, and discipline summaries appear after report generation."))}</div>`;
  const comparison = report?.comparison || null;
  elements.modelHealthComparisonPanel.innerHTML = comparison
    ? `
      <table class="model-health-comparison-table">
        <thead><tr><th>指标</th><th>上次</th><th>本次</th><th>变化</th></tr></thead>
        <tbody>
          ${[
            [text("总评分", "Score"), comparison.previous.score, comparison.current.score, comparison.delta.score],
            ["Error", comparison.previous.errorCount, comparison.current.errorCount, comparison.delta.errorCount],
            ["Warning", comparison.previous.warningCount, comparison.current.warningCount, comparison.delta.warningCount],
            [text("AI 疑似", "AI Suspected"), comparison.previous.aiCount, comparison.current.aiCount, comparison.delta.aiCount],
            [text("新增问题", "New Issues"), "—", comparison.delta.newIssues, comparison.delta.newIssues],
          ].map(([label, previous, current, delta]) => `
            <tr class="${Number(delta) > 0 ? "worse" : Number(delta) < 0 ? "better" : ""}">
              <td>${escapeHtml(label)}</td>
              <td>${escapeHtml(previous)}</td>
              <td>${escapeHtml(current)}</td>
              <td>${escapeHtml(`${Number(delta) > 0 ? "+" : ""}${delta}`)}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    `
    : `<div class="empty-card">${escapeHtml(text("新版本检查完成后，会自动对比上一份健康度报告。", "After a newer version is checked, it will compare against the previous report."))}</div>`;
}

function renderModelHealthIssueFilters() {
  const categories = uniqueByNormalized(modelHealthCombinedIssues().map((issue) => issue.category).filter(Boolean));
  const categoryOptions = [
    { value: "all", label: text("全部类别", "All categories") },
    ...categories.map((category) => ({ value: category, label: category })),
  ];
  setSelectOptions(elements.modelHealthIssueCategoryFilter, categoryOptions, state.modelHealthIssueCategoryFilter);
  syncInputValue(elements.modelHealthIssueSourceFilter, state.modelHealthIssueSourceFilter);
  syncInputValue(elements.modelHealthIssueLevelFilter, state.modelHealthIssueLevelFilter);
}

function renderModelHealthIssueList() {
  if (!elements.modelHealthIssueList) {
    return;
  }
  renderModelHealthIssueFilters();
  const issues = filteredModelHealthIssues();
  elements.modelHealthIssueBadge.textContent = text(`${issues.length} 项`, `${issues.length} items`);
  elements.modelHealthIssueList.innerHTML = issues.length
    ? issues.map((issue) => {
        const isAi = issue.source === "ai";
        const dbIds = Array.isArray(issue.dbIds) ? issue.dbIds : [];
        const referenceDbIds = Array.isArray(issue.referenceDbIds) ? issue.referenceDbIds : [];
        const actualExpected = isAi
          ? `${issue.confidence ? text(`置信度 ${issue.confidence}`, `Confidence ${issue.confidence}`) : text("AI 参考结论", "AI advisory")} ${referenceDbIds.length ? text(`· 参照 dbId ${referenceDbIds.slice(0, 5).join(", ")}`, `· ref dbId ${referenceDbIds.slice(0, 5).join(", ")}`) : ""}`
          : [issue.actualValue ? text(`实际：${issue.actualValue}`, `Actual: ${issue.actualValue}`) : "", issue.expectedValue ? text(`期望：${issue.expectedValue}`, `Expected: ${issue.expectedValue}`) : ""].filter(Boolean).join(" · ");
        return `
          <article class="model-health-issue-row ${isAi ? "ai" : ""}">
            <div class="model-health-issue-copy">
              <div>
                <span class="status-pill ${isAi ? "in_review" : modelHealthIssueTone(issue)}">${escapeHtml(isAi ? text("AI", "AI") : text("规则", "Rule"))}</span>
                <span class="status-pill ${modelHealthIssueTone(issue)}">${escapeHtml(modelHealthLevelLabel(issue.displayLevel))}</span>
                <span class="status-pill neutral">${escapeHtml(modelHealthResultStatusLabel(issue.displayStatus))}</span>
              </div>
              <strong>${escapeHtml(issue.description || text("未填写问题描述", "No description"))}</strong>
              <span>${escapeHtml([issue.category || text("未分类", "Uncategorized"), dbIds.length ? `dbId ${dbIds.slice(0, 8).join(", ")}` : text("未关联构件", "No linked element"), actualExpected].filter(Boolean).join(" · "))}</span>
            </div>
            <div class="model-health-issue-actions">
              <button class="ghost-button compact-button" data-model-health-action="locate" data-result-id="${escapeHtml(issue.id)}" data-result-source="${escapeHtml(issue.source)}" type="button" ${dbIds.length || referenceDbIds.length ? "" : "disabled"}>${escapeHtml(text("定位", "Locate"))}</button>
              ${isAi
                ? `
                  <button class="ghost-button compact-button" data-model-health-action="ai-confirm" data-result-id="${escapeHtml(issue.id)}" type="button" ${issue.displayStatus === "open" ? "" : "disabled"}>${escapeHtml(text("确认问题", "Confirm"))}</button>
                  <button class="ghost-button compact-button" data-model-health-action="ai-false-positive" data-result-id="${escapeHtml(issue.id)}" type="button" ${issue.displayStatus === "open" ? "" : "disabled"}>${escapeHtml(text("标记误报", "False Positive"))}</button>
                `
                : `
                  <button class="ghost-button compact-button" data-model-health-action="rule-resolve" data-result-id="${escapeHtml(issue.id)}" type="button" ${issue.displayStatus === "open" ? "" : "disabled"}>${escapeHtml(text("已修复", "Resolved"))}</button>
                  <button class="ghost-button compact-button" data-model-health-action="rule-accept" data-result-id="${escapeHtml(issue.id)}" type="button" ${issue.displayStatus === "open" ? "" : "disabled"}>${escapeHtml(text("接受", "Accept"))}</button>
                `}
            </div>
          </article>
        `;
      }).join("")
    : `<div class="empty-card">${escapeHtml(state.modelHealthLatestTask ? text("当前筛选条件下没有问题。", "No findings match the filters.") : text("完成一次健康度检查后，这里会显示规则和 AI 问题。", "Run a health check to populate rule and AI findings."))}</div>`;
}

function renderModelHealthWorkbench(activeTool = normalizeModelAppTool(state.modelAppTool)) {
  if (!elements.modelHealthDocumentSelect) {
    return;
  }
  pruneModelHealthSelection();
  renderModelHealthModelPicker();
  const docs = modelHealthDocuments();
  const doc = selectedModelHealthDocument();
  seedModelHealthRulesetSelection();
  const ruleset = modelHealthRulesetForSelection();
  const activeTask = modelHealthActiveTask();
  const latestTask = state.modelHealthLatestTask || state.modelHealthTasks[0] || null;
  const gate = state.modelHealthGate || doc?.healthGate || latestTask?.gate || null;
  setSelectOptions(
    elements.modelHealthDocumentSelect,
    [
      ...(docs.length ? [{ value: "", label: text("请选择健康度检查模型", "Select a model for health check"), disabled: true }] : []),
      ...docs.map((item) => ({
        value: item.id,
        label: `${item.name}${modelHealthDocumentReady(item) ? "" : text(" · 未就绪", " · not ready")}`,
      })),
    ],
    state.modelHealthDocumentId,
  );
  if (!docs.length) {
    elements.modelHealthDocumentSelect.innerHTML = `<option value="">${escapeHtml(text("暂无可检查模型", "No checkable models"))}</option>`;
  }
  setSelectOptions(
    elements.modelHealthRulesetSelect,
    state.modelHealthRulesets.map((item) => ({ value: item.id, label: item.name })),
    state.modelHealthRulesetId,
  );
  if (!state.modelHealthRulesets.length) {
    elements.modelHealthRulesetSelect.innerHTML = `<option value="">${escapeHtml(text("规则集加载中", "Loading rulesets"))}</option>`;
  }
  if (elements.modelHealthGateModeSelect) {
    elements.modelHealthGateModeSelect.value = ruleset?.gateConfig?.mode || "standard";
  }
  if (elements.modelHealthAiEnabledToggle) {
    elements.modelHealthAiEnabledToggle.checked = ruleset?.gateConfig?.aiEnabled !== false;
  }
  renderModelHealthGuide(doc, ruleset, latestTask, gate);
  renderModelHealthPreflight(doc, ruleset, activeTask);
  renderModelHealthRulesetSummary(ruleset);
  renderModelHealthTemplateSummary(ruleset);
  renderModelHealthLaunchSummary(doc, ruleset, latestTask, gate);
  renderModelHealthSummary(latestTask, state.modelHealthReport, gate);
  renderModelHealthTaskList(latestTask);
  renderModelHealthGatePanel(gate);
  renderModelHealthReportPanels(state.modelHealthReport);
  renderModelHealthIssueList();

  const canRun = Boolean(quantityApsConfigurationReady() && doc && modelHealthDocumentReady(doc) && ruleset && !activeTask);
  elements.modelHealthDocumentSelect.disabled = state.modelHealthBusy || !docs.length;
  elements.modelHealthRulesetSelect.disabled = state.modelHealthBusy || !state.modelHealthRulesets.length;
  elements.modelHealthRefreshButton.disabled = state.modelHealthBusy;
  elements.modelHealthRunButton.disabled = state.modelHealthBusy || !canRun;
  elements.modelHealthRunButton.textContent = activeTask
    ? text("等待当前检查", "Waiting for check")
    : !quantityApsConfigurationReady()
      ? text("先配置 APS", "Configure APS first")
      : !doc
        ? text("选择模型后检查", "Select model")
        : !modelHealthDocumentReady(doc)
          ? text("模型未就绪", "Model not ready")
          : text("开始健康度检查", "Run health check");
  if (elements.modelHealthMessage) {
    elements.modelHealthMessage.textContent = state.modelHealthMessage || (activeTool === "health" && !quantityApsConfigurationReady() ? quantityApsConfigurationPrompt() : "");
  }
}

function selectQuantityModelDocument(documentId) {
  const doc = quantityTakeoffDocuments().find((item) => item.id === documentId) || null;
  state.quantityDocumentId = doc?.id || "";
  state.quantitySelectedSummaryIndex = 0;
  state.quantityCompareDiff = [];
  state.quantityPropertyDictionary = null;
  void refreshQuantityTakeoffData({ renderAfter: true });
}

function renderQuantityModelPicker() {
  if (!elements.quantityModelList) {
    return;
  }
  const docs = quantityTakeoffDocuments();
  const selectedDoc = docs.find((doc) => doc.id === state.quantityDocumentId) || null;
  const apsReady = quantityApsConfigurationReady();
  if (elements.quantityModelCountBadge) {
    elements.quantityModelCountBadge.textContent = text(`${docs.length} 个模型`, `${docs.length} models`);
  }
  const configAlert = apsReady
    ? ""
    : `
      <div class="quantity-model-config-alert">
        <span>${escapeHtml(quantityApsConfigurationPrompt())}</span>
        <button class="ghost-button compact-button" data-model-app-action="open-aps-settings" type="button">${escapeHtml(text("去配置 APS", "Configure APS"))}</button>
      </div>
    `;
  const modelRows = docs.length
    ? docs.map((doc) => {
        const selected = selectedDoc?.id === doc.id;
        const meta = modelAppDocumentStatusMeta(doc);
        const version = doc.version || "V1";
        const updated = doc.updatedAt ? formatDateTime(doc.updatedAt) : text("无更新时间", "No update time");
        return `
          <button class="model-app-model-row ${selected ? "selected" : ""}" type="button" data-quantity-model="${escapeHtml(doc.id)}">
            <span class="model-app-model-main">
              <strong>${escapeHtml(doc.name)}</strong>
              <span>${escapeHtml([version, folderName(doc.parentId), updated].filter(Boolean).join(" · "))}</span>
            </span>
            <span class="model-app-model-meta">
              <span class="status-pill ${escapeHtml(meta.tone)}">${escapeHtml(meta.label)}</span>
              <small title="${escapeHtml(meta.detail)}">${escapeHtml(truncate(meta.detail, 48))}</small>
            </span>
          </button>
        `;
      }).join("")
    : `
      <div class="model-app-empty-state">
        <strong>${escapeHtml(text("当前项目还没有模型文件", "No model files in this project"))}</strong>
        <span>${escapeHtml(text("请先在文件管理中上传 IFC、RVT、DWG、NWD 等模型文件，完成 APS 转换后再回到工程量统计。", "Upload IFC, RVT, DWG, NWD, or other model files in File Management, then return to Quantity Takeoff."))}</span>
        <button class="ghost-button compact-button" data-model-app-action="open-files" type="button">${escapeHtml(text("去文件管理上传", "Go to File Management"))}</button>
      </div>
    `;
  elements.quantityModelList.innerHTML = `${configAlert}${modelRows}`;
}

function resetQuantityTakeoffState() {
  state.quantityDocumentId = "";
  state.quantityTemplates = [];
  state.quantityTasks = [];
  state.quantitySummaries = [];
  state.quantitySnapshots = [];
  state.quantityLatestTask = null;
  state.quantitySelectedSummaryIndex = 0;
  state.quantityBusy = false;
  state.quantityMessage = "";
  state.quantityTemplateId = "";
  state.quantityFieldMode = "template";
  state.quantityGroupPreset = "elementType,floor,discipline,material";
  state.quantityFilters = {
    floors: "",
    disciplines: "",
    elementTypes: "",
    materials: "",
  };
  state.quantityCompareLeftTaskId = "";
  state.quantityCompareRightTaskId = "";
  state.quantityCompareDiff = [];
}

function resetModelDiffState() {
  state.modelDiffDocuments = [];
  state.modelDiffTasks = [];
  state.modelDiffRecords = [];
  state.modelDiffPropChanges = [];
  state.modelDiffAiSummary = null;
  state.modelDiffSnapshots = [];
  state.modelDiffTrends = [];
  state.modelDiffDocumentId = "";
  state.modelDiffVersionAId = "";
  state.modelDiffVersionBId = "";
  state.modelDiffTaskId = "";
  state.modelDiffSelectedRecordId = "";
  state.modelDiffBusy = false;
  state.modelDiffMessage = "";
  state.modelDiffToleranceMm = "10";
  state.modelDiffTypeFilter = "all";
  state.modelDiffElementFilter = "all";
  state.modelDiffAreaFilter = "all";
  state.modelDiffDisciplineFilter = "all";
  state.modelDiffOnlyUnlinked = false;
  state.modelDiffOnlyDifferences = true;
  state.modelDiffViewerMode = "overlay";
  state.modelDiffLayerTypes = {
    added: true,
    deleted: true,
    modified: true,
    moved: true,
  };
}

function modelDiffDocuments() {
  const serverDocs = Array.isArray(state.modelDiffDocuments) ? state.modelDiffDocuments : [];
  const source = serverDocs.length ? serverDocs : quantityTakeoffDocuments();
  return source
    .filter((doc) => isModelWorkspaceDocument(doc) && canPreviewDocument(documentById(doc.id) || doc))
    .sort((left, right) => compareBySortLocale(left.name, right.name));
}

function selectedModelDiffDocument() {
  return modelDiffDocuments().find((doc) => doc.id === state.modelDiffDocumentId) || null;
}

function modelDiffVersions(doc) {
  const versions = Array.isArray(doc?.versionHistory) ? doc.versionHistory.filter((entry) => !entry.deletedAt) : [];
  return versions.length
    ? [...versions].sort((left, right) => Number(left.versionNo || 0) - Number(right.versionNo || 0) || String(left.uploadedAt || "").localeCompare(String(right.uploadedAt || "")))
    : [];
}

function modelDiffVersionReadiness(version) {
  const meta = version?.modelDiff && typeof version.modelDiff === "object" ? version.modelDiff : {};
  return {
    ready: Boolean(meta.ready || meta.canExtractNow || meta.snapshotAvailable),
    source: meta.snapshotSource || (meta.canExtractNow ? "aps-properties" : ""),
    reason: meta.reason || text("该版本缺少 APS URN 或属性快照。", "This version has no APS URN or property snapshot."),
    objectCount: Number(meta.objectCount || 0),
  };
}

function modelDiffVersionSourceLabel(version) {
  const readiness = modelDiffVersionReadiness(version);
  if (!readiness.ready) {
    return text("未就绪", "Not ready");
  }
  if (readiness.source === "quantity-cache") {
    return readiness.objectCount
      ? text(`工程量快照 ${readiness.objectCount} 对象`, `${readiness.objectCount} quantity objects`)
      : text("工程量快照", "Quantity snapshot");
  }
  if (readiness.source === "aps-properties") {
    return text("APS 可提取", "APS extractable");
  }
  return readiness.objectCount
    ? text(`属性快照 ${readiness.objectCount} 对象`, `${readiness.objectCount} snapshot objects`)
    : text("属性快照", "Property snapshot");
}

function modelDiffVersionLabel(version) {
  return [version?.version || "V1", version?.note && version.note !== "—" ? version.note : "", modelDiffVersionSourceLabel(version), version?.uploadedAt ? formatDateTime(version.uploadedAt) : ""]
    .filter(Boolean)
    .join(" · ");
}

function modelDiffDocumentReady(doc) {
  const fullDoc = documentById(doc?.id) || doc;
  return Boolean(fullDoc?.aps?.urn && apsTranslationStatus(fullDoc) === "success");
}

function selectedModelDiffVersions(doc = selectedModelDiffDocument()) {
  const versions = modelDiffVersions(doc);
  return {
    versions,
    versionA: versions.find((version) => version.id === state.modelDiffVersionAId) || null,
    versionB: versions.find((version) => version.id === state.modelDiffVersionBId) || null,
  };
}

function modelDiffSelectedVersionsSameFormat(versionA, versionB, doc) {
  if (!versionA || !versionB) {
    return false;
  }
  const extA = String(versionA.name || doc?.name || "").split(".").pop()?.toLowerCase() || "";
  const extB = String(versionB.name || doc?.name || "").split(".").pop()?.toLowerCase() || "";
  return Boolean(extA && extB && extA === extB);
}

function seedModelDiffSelection() {
  const docs = modelDiffDocuments();
  if (state.modelDiffDocumentId && docs.some((doc) => doc.id === state.modelDiffDocumentId)) {
    return;
  }
  state.modelDiffDocumentId = "";
  state.modelDiffVersionAId = "";
  state.modelDiffVersionBId = "";
  state.modelDiffTaskId = "";
  state.modelDiffRecords = [];
  state.modelDiffAiSummary = null;
  state.modelDiffTrends = [];
}

function pruneModelDiffVersions(doc = selectedModelDiffDocument()) {
  const versions = modelDiffVersions(doc);
  const ids = new Set(versions.map((version) => version.id));
  if (!ids.has(state.modelDiffVersionAId)) {
    state.modelDiffVersionAId = versions.length > 1 ? versions[versions.length - 2]?.id || "" : versions[0]?.id || "";
  }
  if (!ids.has(state.modelDiffVersionBId)) {
    state.modelDiffVersionBId = doc?.currentVersionId && ids.has(doc.currentVersionId)
      ? doc.currentVersionId
      : versions[versions.length - 1]?.id || "";
  }
  if (state.modelDiffVersionAId === state.modelDiffVersionBId && versions.length > 1) {
    state.modelDiffVersionAId = versions.find((version) => version.id !== state.modelDiffVersionBId)?.id || state.modelDiffVersionAId;
  }
}

function modelDiffTaskStatusLabel(status) {
  return {
    queued: text("排队中", "Queued"),
    extracting: text("提取中", "Extracting"),
    comparing: text("比对中", "Comparing"),
    ai_analyzing: text("AI 分析中", "AI Analyzing"),
    completed: text("已完成", "Completed"),
    failed: text("失败", "Failed"),
    canceled: text("已取消", "Canceled"),
  }[status] || status || text("未知", "Unknown");
}

function modelDiffStatusTone(status) {
  if (status === "completed") return "approved";
  if (status === "failed" || status === "canceled") return "rejected";
  if (["queued", "extracting", "comparing", "ai_analyzing"].includes(status)) return "in_review";
  return "neutral";
}

function modelDiffTypeLabel(type) {
  return {
    added: text("新增", "Added"),
    deleted: text("删除", "Deleted"),
    modified: text("属性变更", "Modified"),
    moved: text("位置移动", "Moved"),
    unchanged: text("未变更", "Unchanged"),
    unmatched: text("无法比对", "Unmatched"),
  }[type] || type || text("未知", "Unknown");
}

function modelDiffTypeTone(type) {
  return {
    added: "approved",
    deleted: "rejected",
    modified: "in_review",
    moved: "alert",
    unmatched: "neutral",
    unchanged: "neutral",
  }[type] || "neutral";
}

function modelDiffActiveTask() {
  return state.modelDiffTasks.find((task) => ["queued", "extracting", "comparing", "ai_analyzing"].includes(task.status)) || null;
}

function selectedModelDiffTask() {
  return state.modelDiffTasks.find((task) => task.id === state.modelDiffTaskId) || state.modelDiffTasks[0] || null;
}

function clearModelDiffPolling() {
  if (modelDiffPollTimer) {
    window.clearTimeout(modelDiffPollTimer);
    modelDiffPollTimer = 0;
  }
}

function ensureModelDiffPolling() {
  clearModelDiffPolling();
  if (
    !state.authenticated ||
    state.currentView !== "model-apps" ||
    normalizeModelAppTool(state.modelAppTool) !== "diff" ||
    !modelDiffActiveTask()
  ) {
    return;
  }
  modelDiffPollTimer = window.setTimeout(async () => {
    modelDiffPollTimer = 0;
    await refreshModelDiffData({ renderAfter: true });
  }, MODEL_DIFF_POLL_INTERVAL_MS);
}

function mergeModelDiffTasks(existing = [], incoming = []) {
  const map = new Map();
  [...incoming, ...existing].filter(Boolean).forEach((task) => {
    map.set(task.id, task);
  });
  return [...map.values()].sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")));
}

async function refreshModelDiffTaskDetail(taskId = state.modelDiffTaskId, options = {}) {
  const id = String(taskId || "");
  if (!id) {
    state.modelDiffRecords = [];
    state.modelDiffPropChanges = [];
    state.modelDiffAiSummary = null;
    state.modelDiffSnapshots = [];
    state.modelDiffTrends = [];
    return null;
  }
  const detail = await fetchJson(`/api/model-apps/diff/tasks/${encodeURIComponent(id)}`);
  state.modelDiffTaskId = detail.task?.id || id;
  if (detail.task) {
    state.modelDiffTasks = mergeModelDiffTasks(state.modelDiffTasks, [detail.task]);
  }
  state.modelDiffRecords = Array.isArray(detail.records) ? detail.records : [];
  state.modelDiffPropChanges = Array.isArray(detail.propChanges) ? detail.propChanges : [];
  state.modelDiffAiSummary = detail.aiSummary || null;
  state.modelDiffSnapshots = Array.isArray(detail.snapshots) ? detail.snapshots : [];
  state.modelDiffTrends = Array.isArray(detail.trends) ? detail.trends : [];
  if (!state.modelDiffSelectedRecordId || !state.modelDiffRecords.some((record) => record.id === state.modelDiffSelectedRecordId)) {
    state.modelDiffSelectedRecordId = state.modelDiffRecords.find((record) => record.diffType !== "unchanged")?.id || state.modelDiffRecords[0]?.id || "";
  }
  if (options.renderAfter) {
    renderModelAppsPanel();
  }
  return detail;
}

async function refreshModelDiffData(options = {}) {
  if (!state.authenticated) {
    return;
  }
  try {
    const payload = await fetchJson("/api/model-apps/diff");
    state.modelDiffDocuments = Array.isArray(payload.documents) ? payload.documents : [];
    state.modelDiffTasks = mergeModelDiffTasks(Array.isArray(payload.tasks) ? payload.tasks : [], state.modelDiffTasks);
    seedModelDiffSelection();
    const doc = selectedModelDiffDocument();
    pruneModelDiffVersions(doc);
    const task = state.modelDiffTaskId
      ? state.modelDiffTasks.find((item) => item.id === state.modelDiffTaskId)
      : state.modelDiffTasks.find((item) => item.documentId === state.modelDiffDocumentId) || state.modelDiffTasks[0];
    if (task) {
      await refreshModelDiffTaskDetail(task.id, { renderAfter: false });
    }
    if (payload.apsReady === false) {
      state.modelDiffMessage = payload.apsMessage || quantityApsConfigurationPrompt();
    } else if (/APS 服务尚未配置|APS 模型能力未启用|APS 配置尚未完整/.test(state.modelDiffMessage || "")) {
      state.modelDiffMessage = "";
    }
    ensureModelDiffPolling();
  } catch (error) {
    state.modelDiffMessage = error.message || text("模型差异任务加载失败。", "Failed to load model diff tasks.");
  } finally {
    if (options.renderAfter) {
      renderModelAppsPanel();
    }
  }
}

function selectModelDiffDocument(documentId) {
  const doc = modelDiffDocuments().find((item) => item.id === documentId) || null;
  state.modelDiffDocumentId = doc?.id || "";
  state.modelDiffVersionAId = "";
  state.modelDiffVersionBId = "";
  state.modelDiffTaskId = state.modelDiffTasks.find((task) => task.documentId === doc?.id)?.id || "";
  state.modelDiffSelectedRecordId = "";
  state.modelDiffRecords = [];
  state.modelDiffAiSummary = null;
  state.modelDiffTrends = [];
  pruneModelDiffVersions(doc);
  void refreshModelDiffData({ renderAfter: true });
}

function modelDiffCanRun() {
  const doc = selectedModelDiffDocument();
  const { versionA, versionB } = selectedModelDiffVersions(doc);
  return Boolean(
    quantityApsConfigurationReady() &&
    doc &&
    versionA &&
    versionB &&
    modelDiffSelectedVersionsSameFormat(versionA, versionB, doc) &&
    modelDiffVersionReadiness(versionA).ready &&
    modelDiffVersionReadiness(versionB).ready &&
    state.modelDiffVersionAId &&
    state.modelDiffVersionBId &&
    state.modelDiffVersionAId !== state.modelDiffVersionBId &&
    !modelDiffActiveTask(),
  );
}

async function runModelDiffFromSelection() {
  const doc = selectedModelDiffDocument();
  if (!doc) {
    showAlert(text("请先选择要对比的模型文件。", "Select a model file first."));
    return;
  }
  if (!quantityApsConfigurationReady()) {
    showAlert(quantityApsConfigurationPrompt());
    return;
  }
  if (!state.modelDiffVersionAId || !state.modelDiffVersionBId || state.modelDiffVersionAId === state.modelDiffVersionBId) {
    showAlert(text("请选择两个不同版本进行对比。", "Select two different versions."));
    return;
  }
  const { versionA, versionB } = selectedModelDiffVersions(doc);
  if (!modelDiffSelectedVersionsSameFormat(versionA, versionB, doc)) {
    showAlert(text("同一文件的不同格式版本不支持互相对比。", "Different file formats for the same document cannot be compared."));
    return;
  }
  const blockedVersions = [
    versionA && !modelDiffVersionReadiness(versionA).ready ? `${versionA.version}：${modelDiffVersionReadiness(versionA).reason}` : "",
    versionB && !modelDiffVersionReadiness(versionB).ready ? `${versionB.version}：${modelDiffVersionReadiness(versionB).reason}` : "",
  ].filter(Boolean);
  if (blockedVersions.length) {
    showAlert(text(`版本属性快照未就绪：${blockedVersions.join("；")}。请先完成对应版本 APS 转换，或通过工程量/健康度功能生成属性快照。`, `Version snapshots are not ready: ${blockedVersions.join("; ")}.`));
    return;
  }
  state.modelDiffBusy = true;
  state.modelDiffMessage = text("已提交模型差异对比任务，后台会复用已有属性快照。", "Model diff task queued; cached property snapshots will be reused.");
  renderModelAppsPanel();
  try {
    const payload = await postJson("/api/model-apps/diff/run", {
      documentId: doc.id,
      versionAId: state.modelDiffVersionAId,
      versionBId: state.modelDiffVersionBId,
      toleranceMm: Math.max(0, Number(state.modelDiffToleranceMm || 10) || 0),
      coordinateUnit: "m",
      source: "manual",
    });
    if (payload.task) {
      state.modelDiffTaskId = payload.task.id;
      state.modelDiffTasks = mergeModelDiffTasks(state.modelDiffTasks, [payload.task]);
      state.modelDiffMessage = payload.reused
        ? text("同一版本组合已有最新任务结果，本次已复用。", "The latest result for this version pair was reused.")
        : text("模型差异任务已进入队列。", "Model diff task has been queued.");
      ensureModelDiffPolling();
      await refreshModelDiffTaskDetail(payload.task.id, { renderAfter: false });
    }
  } catch (error) {
    state.modelDiffMessage = error.message || text("模型差异对比发起失败。", "Failed to start model diff.");
    showAlert(state.modelDiffMessage);
  } finally {
    state.modelDiffBusy = false;
    renderModelAppsPanel();
  }
}

function modelDiffFilterOptions(records, field, allLabel) {
  const values = uniqueByNormalized(records.map((record) => record[field]).filter(Boolean));
  return [{ value: "all", label: allLabel }, ...values.map((value) => ({ value, label: value }))];
}

function filteredModelDiffRecords() {
  return (Array.isArray(state.modelDiffRecords) ? state.modelDiffRecords : [])
    .filter((record) => record.diffType !== "unchanged")
    .filter((record) => state.modelDiffTypeFilter === "all" || record.diffType === state.modelDiffTypeFilter || (record.diffTypes || []).includes(state.modelDiffTypeFilter))
    .filter((record) => state.modelDiffElementFilter === "all" || record.elementType === state.modelDiffElementFilter)
    .filter((record) => state.modelDiffAreaFilter === "all" || record.floor === state.modelDiffAreaFilter)
    .filter((record) => state.modelDiffDisciplineFilter === "all" || record.discipline === state.modelDiffDisciplineFilter)
    .filter((record) => !state.modelDiffOnlyUnlinked || !record.issueId)
    .sort((left, right) => {
      const order = { unmatched: 0, deleted: 1, added: 2, modified: 3, moved: 4 };
      return (order[left.diffType] ?? 9) - (order[right.diffType] ?? 9) || compareBySortLocale(left.elementType, right.elementType);
    });
}

function renderModelDiffGuide(doc, task) {
  const steps = [
    [elements.modelDiffGuideModel, Boolean(doc), doc ? `${doc.name}` : text("请选择模型文件", "Select a model file")],
    [elements.modelDiffGuideVersions, Boolean(doc && state.modelDiffVersionAId && state.modelDiffVersionBId && state.modelDiffVersionAId !== state.modelDiffVersionBId), text("选择两个版本", "Select two versions")],
    [elements.modelDiffGuideRun, Boolean(task), task ? modelDiffTaskStatusLabel(task.status) : text("等待发起", "Waiting to run")],
    [elements.modelDiffGuideReport, Boolean(task?.status === "completed"), task?.status === "completed" ? text("报告已生成", "Report ready") : text("等待完成", "Waiting for completion")],
  ];
  steps.forEach(([element, complete, label], index) => {
    if (!element) return;
    element.classList.toggle("active", !complete && steps.findIndex(([, done]) => !done) === index);
    element.classList.toggle("done", complete);
    const copy = element.querySelector("p");
    if (copy) copy.textContent = label;
  });
}

function renderModelDiffModelPicker() {
  if (!elements.modelDiffModelList) {
    return;
  }
  const docs = modelDiffDocuments();
  const selected = selectedModelDiffDocument();
  const apsReady = quantityApsConfigurationReady();
  elements.modelDiffModelCountBadge.textContent = text(`${docs.length} 个模型`, `${docs.length} models`);
  const configAlert = apsReady
    ? ""
    : `
      <div class="quantity-model-config-alert">
        <span>${escapeHtml(quantityApsConfigurationPrompt())}</span>
        <button class="ghost-button compact-button" data-model-app-action="open-aps-settings" type="button">${escapeHtml(text("去配置 APS", "Configure APS"))}</button>
      </div>
    `;
  elements.modelDiffModelList.innerHTML = docs.length
    ? `${configAlert}${docs.map((doc) => {
        const fullDoc = documentById(doc.id) || doc;
        const meta = modelAppDocumentStatusMeta(fullDoc);
        const diffVersions = modelDiffVersions(doc);
        const versions = diffVersions.length || fullDoc.versionHistory?.length || 1;
        const readyVersions = diffVersions.filter((version) => modelDiffVersionReadiness(version).ready).length;
        return `
          <button class="model-app-model-row ${selected?.id === doc.id ? "selected" : ""}" type="button" data-model-diff-model="${escapeHtml(doc.id)}">
            <span class="model-app-model-main">
              <strong>${escapeHtml(doc.name)}</strong>
              <span>${escapeHtml(`${versions} 个版本 · ${folderName(fullDoc.parentId)} · ${formatDateTime(fullDoc.updatedAt || doc.updatedAt)}`)}</span>
            </span>
            <span class="model-app-model-meta">
              <span class="status-pill ${escapeHtml(readyVersions >= 2 ? "approved" : meta.tone)}">${escapeHtml(readyVersions >= 2 ? "可对比" : meta.label)}</span>
              <small>${escapeHtml(readyVersions >= 2 ? `${readyVersions} 个版本快照/URN 就绪` : truncate(meta.detail || "等待版本快照", 42))}</small>
            </span>
          </button>
        `;
      }).join("")}`
    : `
      <div class="model-app-empty-state">
        <strong>${escapeHtml(text("当前项目还没有可对比模型", "No comparable model files"))}</strong>
        <span>${escapeHtml(text("请先上传 IFC、RVT、NWD/NWC 等模型，并完成 APS 转换。", "Upload IFC, RVT, NWD/NWC models and complete APS translation first."))}</span>
        <button class="ghost-button compact-button" data-model-app-action="open-files" type="button">${escapeHtml(text("去文件管理上传", "Go to File Management"))}</button>
      </div>
    `;
}

function renderModelDiffPreflight(doc, versions) {
  if (!elements.modelDiffPreflightList) {
    return;
  }
  const versionA = versions.find((version) => version.id === state.modelDiffVersionAId) || null;
  const versionB = versions.find((version) => version.id === state.modelDiffVersionBId) || null;
  const hasVersionPair = Boolean(versionA && versionB && versionA.id !== versionB.id);
  const sameExt = hasVersionPair && modelDiffSelectedVersionsSameFormat(versionA, versionB, doc);
  const versionAReady = versionA ? modelDiffVersionReadiness(versionA) : null;
  const versionBReady = versionB ? modelDiffVersionReadiness(versionB) : null;
  const versionsReady = Boolean(hasVersionPair && versionAReady?.ready && versionBReady?.ready);
  const sourceNote = versionsReady
    ? text(`A：${modelDiffVersionSourceLabel(versionA)}；B：${modelDiffVersionSourceLabel(versionB)}`, `A: ${modelDiffVersionSourceLabel(versionA)}; B: ${modelDiffVersionSourceLabel(versionB)}`)
    : hasVersionPair
      ? [versionAReady && !versionAReady.ready ? `${versionA.version} ${versionAReady.reason}` : "", versionBReady && !versionBReady.ready ? `${versionB.version} ${versionBReady.reason}` : ""].filter(Boolean).join("；") || text("版本属性来源待确认", "Version property sources pending")
      : text("选择两个版本后检查属性来源", "Select two versions to check property sources");
  const items = [
    { ok: Boolean(quantityApsConfigurationReady()), label: text("APS 配置", "APS configuration"), note: quantityApsConfigurationReady() ? text("已配置", "Configured") : quantityApsConfigurationPrompt() },
    { ok: Boolean(doc), label: text("模型文件", "Model file"), note: doc ? doc.name : text("未选择", "Not selected") },
    { ok: hasVersionPair, label: text("版本组合", "Version pair"), note: hasVersionPair ? text(`${versionA.version} → ${versionB.version}`, `${versionA.version} → ${versionB.version}`) : text("请选择两个不同版本", "Select two different versions") },
    { ok: sameExt, label: text("格式一致", "Same format"), note: !hasVersionPair ? text("选择版本后检查格式", "Select versions to check format") : sameExt ? text("格式一致", "Same format") : text("不支持 DWG 与 RVT 等跨格式互比", "Cross-format comparison is not supported") },
    { ok: versionsReady, label: text("属性快照/URN", "Property snapshot / URN"), note: sourceNote },
  ];
  elements.modelDiffPreflightList.innerHTML = items.map((item) => `
    <div class="quantity-preflight-row ${item.ok ? "done" : "blocked"}">
      <span>${escapeHtml(item.ok ? "✓" : "!")}</span>
      <strong>${escapeHtml(item.label)}</strong>
      <small>${escapeHtml(item.note)}</small>
    </div>
  `).join("");
}

function renderModelDiffTaskList(selectedTask) {
  if (!elements.modelDiffTaskList) {
    return;
  }
  const tasks = state.modelDiffTasks.filter((task) => !state.modelDiffDocumentId || task.documentId === state.modelDiffDocumentId).slice(0, 8);
  elements.modelDiffTaskBadge.textContent = selectedTask
    ? `${modelDiffTaskStatusLabel(selectedTask.status)} · ${formatDateTime(selectedTask.completedAt || selectedTask.updatedAt || selectedTask.createdAt)}`
    : text("未运行", "Not run");
  elements.modelDiffTaskBadge.className = `mini-pill ${selectedTask ? `status-pill ${modelDiffStatusTone(selectedTask.status)}` : ""}`;
  elements.modelDiffTaskList.innerHTML = tasks.length
    ? tasks.map((task) => `
      <button class="quantity-task-row model-diff-task-row ${task.id === state.modelDiffTaskId ? "selected" : ""} ${["queued", "extracting", "comparing", "ai_analyzing"].includes(task.status) ? "active" : ""}" type="button" data-model-diff-task="${escapeHtml(task.id)}">
        <span class="status-pill ${modelDiffStatusTone(task.status)}">${escapeHtml(modelDiffTaskStatusLabel(task.status))}</span>
        <div>
          <strong>${escapeHtml(`${task.versionALabel || "版本A"} → ${task.versionBLabel || "版本B"}`)}</strong>
          <span>${escapeHtml(task.fileName || selectedModelDiffDocument()?.name || "")}</span>
        </div>
        <span>${escapeHtml(formatDateTime(task.completedAt || task.updatedAt || task.createdAt))}</span>
        <span>${escapeHtml(`${task.summary?.totalDiffs || 0} 项`)}</span>
      </button>
    `).join("")
    : `<div class="empty-card">${escapeHtml(text("尚未发起模型差异对比。", "No model diff task has been started yet."))}</div>`;
}

function renderModelDiffReport(task) {
  if (!elements.modelDiffReportBadge) {
    return;
  }
  const summary = task?.summary || {};
  elements.modelDiffReportBadge.textContent = task?.status === "completed"
    ? text("报告已生成", "Report ready")
    : task ? modelDiffTaskStatusLabel(task.status) : text("未生成", "Not generated");
  elements.modelDiffReportBadge.className = `mini-pill ${task ? `status-pill ${modelDiffStatusTone(task.status)}` : ""}`;
  elements.modelDiffSummaryGrid.innerHTML = renderManagerSummaryCards([
    { label: text("新增", "Added"), value: String(summary.added || 0) },
    { label: text("删除", "Deleted"), value: String(summary.deleted || 0) },
    { label: text("属性变更", "Modified"), value: String(summary.modified || 0) },
    { label: text("位置移动", "Moved"), value: String(summary.moved || 0) },
    { label: text("无法比对", "Unmatched"), value: String(summary.unmatched || 0) },
  ]);
  const ai = state.modelDiffAiSummary;
  elements.modelDiffAiSummaryPanel.innerHTML = ai?.summary
    ? `
      <p>${escapeHtml(ai.summary)}</p>
      <div class="model-diff-discipline-list">
        ${(ai.detailByDiscipline || []).map((item) => `
          <div>
            <strong>${escapeHtml(item.discipline || text("未指定专业", "Unassigned"))}</strong>
            <span>${escapeHtml(item.text || "")}</span>
          </div>
        `).join("")}
      </div>
    `
    : `<div class="empty-card">${escapeHtml(task ? text("任务完成后会生成自然语言变更说明。", "A natural-language change summary appears when the task completes.") : text("选择模型并发起对比后生成报告。", "Select a model and run a comparison to generate a report."))}</div>`;
  elements.modelDiffOpenViewerButton.disabled = !task || task.status !== "completed";
  elements.modelDiffCopySummaryButton.disabled = !ai?.summary;
}

function renderModelDiffFilters(records) {
  setSelectOptions(elements.modelDiffElementFilter, modelDiffFilterOptions(records, "elementType", text("全部对象类型", "All object types")), state.modelDiffElementFilter);
  setSelectOptions(elements.modelDiffAreaFilter, modelDiffFilterOptions(records, "floor", text("全部系统/区域", "All systems/areas")), state.modelDiffAreaFilter);
  setSelectOptions(elements.modelDiffDisciplineFilter, modelDiffFilterOptions(records, "discipline", text("全部专业", "All disciplines")), state.modelDiffDisciplineFilter);
  syncInputValue(elements.modelDiffTypeFilter, state.modelDiffTypeFilter);
  elements.modelDiffOnlyUnlinkedToggle.checked = state.modelDiffOnlyUnlinked;
}

function modelDiffRecordChangeText(record) {
  if ((record.diffTypes || []).includes("moved") && record.bboxDelta?.distanceMm) {
    return `${Math.round(Number(record.bboxDelta.distanceMm || 0))} mm`;
  }
  if (record.changedPropCount) {
    return `${record.changedPropCount} 个字段`;
  }
  if (record.diffType === "unmatched") {
    return record.unmatchedReason || text("需人工核查", "Manual review");
  }
  return "—";
}

function renderModelDiffRecordTable() {
  if (!elements.modelDiffRecordTableBody) {
    return;
  }
  const allRecords = (state.modelDiffRecords || []).filter((record) => record.diffType !== "unchanged");
  renderModelDiffFilters(allRecords);
  const records = filteredModelDiffRecords();
  if (elements.modelDiffBulkIssueButton) {
    const bulkCount = records.filter((record) => !record.issueId).length;
    elements.modelDiffBulkIssueButton.disabled = state.modelDiffBusy || !bulkCount;
    elements.modelDiffBulkIssueButton.textContent = bulkCount
      ? text(`批量创建 Issue（${bulkCount}）`, `Create Issues (${bulkCount})`)
      : text("批量创建 Issue", "Create Issues");
  }
  elements.modelDiffRecordBadge.textContent = `${records.length} / ${allRecords.length}`;
  elements.modelDiffRecordTableBody.innerHTML = records.length
    ? records.map((record) => `
      <tr class="${record.id === state.modelDiffSelectedRecordId ? "selected" : ""}" data-model-diff-record="${escapeHtml(record.id)}">
        <td>
          <strong>${escapeHtml(record.elementType || text("未分类", "Uncategorized"))}</strong>
          <span>${escapeHtml(record.name || record.uniqueId || record.stableKey || "—")}</span>
        </td>
        <td><span class="status-pill ${modelDiffTypeTone(record.diffType)}">${escapeHtml(modelDiffTypeLabel(record.diffType))}</span></td>
        <td>${escapeHtml(record.floor || text("未指定区域", "Unassigned area"))}</td>
        <td>${escapeHtml(record.discipline || text("未指定专业", "Unassigned discipline"))}</td>
        <td>${escapeHtml(modelDiffRecordChangeText(record))}</td>
        <td>
          <button class="ghost-button compact-button" data-model-diff-action="detail" data-record-id="${escapeHtml(record.id)}" type="button">${escapeHtml(text("详情", "Detail"))}</button>
          <button class="ghost-button compact-button" data-model-diff-action="viewer" data-record-id="${escapeHtml(record.id)}" type="button">${escapeHtml(text("定位", "Locate"))}</button>
          <button class="ghost-button compact-button" data-model-diff-action="issue" data-record-id="${escapeHtml(record.id)}" type="button" ${record.issueId ? "disabled" : ""}>${escapeHtml(record.issueId ? text("已关联", "Linked") : text("创建 Issue", "Create Issue"))}</button>
        </td>
      </tr>
    `).join("")
    : `<tr><td colspan="6"><div class="empty-card">${escapeHtml(text("当前筛选条件下没有差异记录。", "No diff records match the current filters."))}</div></td></tr>`;
  renderModelDiffDetailPanel(records.find((record) => record.id === state.modelDiffSelectedRecordId) || records[0] || null);
}

function renderModelDiffDetailPanel(record) {
  if (!elements.modelDiffDetailPanel) {
    return;
  }
  if (!record) {
    elements.modelDiffDetailPanel.innerHTML = `<div class="empty-card">${escapeHtml(text("选择一条差异查看属性对比和 Issue 操作。", "Select a diff record to review properties and Issue actions."))}</div>`;
    return;
  }
  const changed = Array.isArray(record.changedProps) ? record.changedProps : [];
  const unchangedKeys = Object.keys(record.propsAfter || record.propsBefore || {}).filter((key) => !changed.some((item) => item.propName === key)).slice(0, 6);
  elements.modelDiffDetailPanel.innerHTML = `
    <div class="model-diff-detail-head">
      <span class="status-pill ${modelDiffTypeTone(record.diffType)}">${escapeHtml(modelDiffTypeLabel(record.diffType))}</span>
      <strong>${escapeHtml(record.name || record.elementType)}</strong>
      <span>${escapeHtml([record.uniqueId ? `ID ${record.uniqueId.slice(0, 12)}` : "", record.matchMethod ? text(`匹配 ${record.matchMethod}`, `Match ${record.matchMethod}`) : "", record.issueId ? `Issue ${record.issueId.slice(0, 8)}` : ""].filter(Boolean).join(" · "))}</span>
    </div>
    <div class="model-diff-detail-meta">
      <div><span>对象类型</span><strong>${escapeHtml(record.elementType || "—")}</strong></div>
      <div><span>系统/区域</span><strong>${escapeHtml(record.floor || "—")}</strong></div>
      <div><span>专业</span><strong>${escapeHtml(record.discipline || "—")}</strong></div>
      <div><span>dbId</span><strong>${escapeHtml([record.dbIdBefore, record.dbIdAfter].filter((item) => item !== null && item !== undefined).join(" → ") || "—")}</strong></div>
    </div>
    <div class="model-diff-prop-panel">
      <strong>${escapeHtml(text("变更字段", "Changed properties"))}</strong>
      ${changed.length ? `
        <table class="model-diff-prop-table">
          <thead><tr><th>属性</th><th>版本 A</th><th>版本 B</th></tr></thead>
          <tbody>
            ${changed.map((item) => `
              <tr class="changed"><td>${escapeHtml(item.propName)}</td><td>${escapeHtml(item.valueA || "空")}</td><td>${escapeHtml(item.valueB || "空")}</td></tr>
            `).join("")}
          </tbody>
        </table>
      ` : `<div class="empty-card compact-empty">${escapeHtml(record.diffType === "moved" ? text("本条主要为位置移动，属性未变化。", "This record is mainly a movement; properties are unchanged.") : text("无属性变更明细。", "No changed property details."))}</div>`}
      ${record.bboxDelta?.distanceMm ? `<p class="access-policy-summary">${escapeHtml(text(`位移 ${Math.round(record.bboxDelta.distanceMm)}mm，向量 dx ${Math.round(record.bboxDelta.dxMm || 0)} / dy ${Math.round(record.bboxDelta.dyMm || 0)} / dz ${Math.round(record.bboxDelta.dzMm || 0)} mm。`, `Moved ${Math.round(record.bboxDelta.distanceMm)}mm.`))}</p>` : ""}
      ${unchangedKeys.length ? `
        <details class="model-diff-unchanged-props">
          <summary>查看未变字段</summary>
          <div>${unchangedKeys.map((key) => `<span>${escapeHtml(key)}：${escapeHtml(record.propsAfter?.[key] ?? record.propsBefore?.[key] ?? "")}</span>`).join("")}</div>
        </details>
      ` : ""}
    </div>
    <div class="model-diff-detail-actions">
      <button class="ghost-button compact-button" data-model-diff-action="viewer" data-record-id="${escapeHtml(record.id)}" type="button">${escapeHtml(text("跳转 Viewer", "Open Viewer"))}</button>
      <button class="primary-button compact-button" data-model-diff-action="issue" data-record-id="${escapeHtml(record.id)}" type="button" ${record.issueId ? "disabled" : ""}>${escapeHtml(record.issueId ? text("已关联 Issue", "Issue linked") : text("创建 Issue", "Create Issue"))}</button>
    </div>
  `;
}

function renderModelDiffTrend() {
  if (!elements.modelDiffTrendTable) {
    return;
  }
  const rows = Array.isArray(state.modelDiffTrends) ? state.modelDiffTrends : [];
  elements.modelDiffTrendBadge.textContent = text(`${rows.length} 组`, `${rows.length} groups`);
  const max = Math.max(1, ...rows.map((row) => Number(row.total || 0)));
  elements.modelDiffTrendChart.innerHTML = rows.length
    ? rows.map((row) => `
      <div class="model-diff-trend-bar ${row.attention ? "attention" : ""}" style="--bar-height:${Math.max(8, Math.round((Number(row.total || 0) / max) * 100))}%">
        <span>${escapeHtml(String(row.total || 0))}</span>
        <strong>${escapeHtml(row.versionPair || "")}</strong>
      </div>
    `).join("")
    : `<div class="empty-card">${escapeHtml(text("完成至少一次版本对比后，趋势图会显示变更数量走向。", "Complete at least one comparison to see trend movement."))}</div>`;
  elements.modelDiffTrendTable.innerHTML = rows.length
    ? `
      <table class="model-diff-table compact">
        <thead><tr><th>版本对</th><th>新增</th><th>删除</th><th>变更</th><th>移动</th><th>合计</th></tr></thead>
        <tbody>
          ${rows.map((row) => `
            <tr>
              <td>${escapeHtml(row.versionPair)}</td>
              <td>${escapeHtml(row.added)}</td>
              <td>${escapeHtml(row.deleted)}</td>
              <td>${escapeHtml(row.modified)}</td>
              <td>${escapeHtml(row.moved)}</td>
              <td><strong>${escapeHtml(row.total)}</strong>${row.attention ? `<span class="status-pill alert">${escapeHtml(text("重点关注", "Attention"))}</span>` : ""}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    `
    : "";
}

function renderModelDiffWorkbench(activeTool = normalizeModelAppTool(state.modelAppTool)) {
  if (!elements.modelDiffDocumentSelect) {
    return;
  }
  seedModelDiffSelection();
  const docs = modelDiffDocuments();
  const doc = selectedModelDiffDocument();
  pruneModelDiffVersions(doc);
  const versions = modelDiffVersions(doc);
  const task = selectedModelDiffTask();
  const { versionA, versionB } = selectedModelDiffVersions(doc);
  const hasVersionPair = Boolean(versionA && versionB && versionA.id !== versionB.id);
  const versionsReady = Boolean(hasVersionPair && modelDiffSelectedVersionsSameFormat(versionA, versionB, doc) && modelDiffVersionReadiness(versionA).ready && modelDiffVersionReadiness(versionB).ready);
  renderModelDiffGuide(doc, task);
  renderModelDiffModelPicker();
  setSelectOptions(
    elements.modelDiffDocumentSelect,
    [
      ...(docs.length ? [{ value: "", label: text("请选择要对比的模型", "Select a model to compare"), disabled: true }] : []),
      ...docs.map((item) => ({ value: item.id, label: item.name })),
    ],
    state.modelDiffDocumentId,
  );
  if (!docs.length) {
    elements.modelDiffDocumentSelect.innerHTML = `<option value="">${escapeHtml(text("暂无可对比模型", "No comparable models"))}</option>`;
  }
  const versionOptions = versions.map((version) => ({ value: version.id, label: modelDiffVersionLabel(version) }));
  setSelectOptions(elements.modelDiffVersionASelect, versionOptions, state.modelDiffVersionAId);
  setSelectOptions(elements.modelDiffVersionBSelect, versionOptions, state.modelDiffVersionBId);
  if (!versionOptions.length) {
    elements.modelDiffVersionASelect.innerHTML = `<option value="">${escapeHtml(text("暂无版本", "No versions"))}</option>`;
    elements.modelDiffVersionBSelect.innerHTML = `<option value="">${escapeHtml(text("暂无版本", "No versions"))}</option>`;
  }
  syncInputValue(elements.modelDiffToleranceInput, state.modelDiffToleranceMm);
  renderModelDiffPreflight(doc, versions);
  renderModelDiffTaskList(task);
  renderModelDiffReport(task);
  renderModelDiffRecordTable();
  renderModelDiffTrend();
  const canRun = modelDiffCanRun();
  elements.modelDiffReadinessBadge.textContent = !doc
    ? text("待选择模型", "Select model")
    : !quantityApsConfigurationReady()
      ? text("APS 未配置", "APS not configured")
      : canRun
        ? text("可发起", "Ready")
        : modelDiffActiveTask()
          ? text("任务运行中", "Task running")
          : text("待完善", "Needs input");
  elements.modelDiffReadinessBadge.className = `mini-pill ${canRun ? "status-pill approved" : "status-pill in_review"}`;
  elements.modelDiffDocumentSelect.disabled = state.modelDiffBusy || !docs.length;
  elements.modelDiffVersionASelect.disabled = state.modelDiffBusy || versions.length < 2;
  elements.modelDiffVersionBSelect.disabled = state.modelDiffBusy || versions.length < 2;
  elements.modelDiffToleranceInput.disabled = state.modelDiffBusy;
  elements.modelDiffRefreshButton.disabled = state.modelDiffBusy;
  elements.modelDiffRunButton.disabled = state.modelDiffBusy || !canRun;
  elements.modelDiffRunButton.textContent = modelDiffActiveTask()
    ? text("等待当前任务", "Waiting for task")
    : !quantityApsConfigurationReady()
      ? text("先配置 APS", "Configure APS first")
      : !doc
        ? text("选择模型后发起", "Select model")
        : !hasVersionPair
          ? text("选择版本后发起", "Select versions")
          : !versionsReady
            ? text("快照未就绪", "Snapshot not ready")
        : text("发起版本对比", "Run version diff");
  elements.modelDiffMessage.textContent = state.modelDiffMessage || (activeTool === "diff" && !quantityApsConfigurationReady() ? quantityApsConfigurationPrompt() : "");
  if (elements.modelDiffViewerModeSelect) {
    elements.modelDiffViewerModeSelect.value = state.modelDiffViewerMode || "overlay";
  }
  elements.modelDiffShowAddedToggle.checked = Boolean(state.modelDiffLayerTypes.added);
  elements.modelDiffShowDeletedToggle.checked = Boolean(state.modelDiffLayerTypes.deleted);
  elements.modelDiffShowModifiedToggle.checked = Boolean(state.modelDiffLayerTypes.modified);
  elements.modelDiffShowMovedToggle.checked = Boolean(state.modelDiffLayerTypes.moved);
  elements.modelDiffOnlyDifferencesToggle.checked = Boolean(state.modelDiffOnlyDifferences);
}

function openModelDiffViewer(recordId = "") {
  const doc = selectedModelDiffDocument();
  const task = selectedModelDiffTask();
  if (!doc || !task) {
    return;
  }
  const record = state.modelDiffRecords.find((item) => item.id === recordId) || state.modelDiffRecords.find((item) => item.id === state.modelDiffSelectedRecordId) || null;
  const dbIds = record?.dbIds?.length ? record.dbIds : [];
  openApsDocument(doc.id, {
    mode: "review",
    workspace: "model",
    versionId: task.versionBId || doc.currentVersionId,
    dbIds,
    modelDiffTaskId: task.id,
    modelDiffRecordId: record?.id || "",
    modelDiffViewMode: state.modelDiffViewerMode || "overlay",
    modelDiffTypes: Object.entries(state.modelDiffLayerTypes).filter(([, enabled]) => enabled).map(([type]) => type),
    modelDiffOnlyDifferences: state.modelDiffOnlyDifferences,
  });
}

async function createIssueFromModelDiff(recordId) {
  const record = state.modelDiffRecords.find((item) => item.id === recordId);
  if (!record) {
    return;
  }
  const changedText = (record.changedProps || [])
    .slice(0, 6)
    .map((change) => `${change.propName}: ${change.valueA || "空"} → ${change.valueB || "空"}`)
    .join("；");
  const issueDraft = await formAction(
    text("从差异记录创建 Issue，会自动带入构件 dbId、稳定 ID、版本和差异明细。", "Create an Issue from this diff record with dbIds, stable IDs, versions, and change details attached."),
    [
      {
        key: "title",
        label: text("Issue 标题", "Issue title"),
        defaultValue: `${modelDiffTypeLabel(record.diffType)}复核：${record.name || record.elementType}`,
        required: true,
      },
      {
        key: "responsible",
        label: text("责任专业/责任人", "Responsible discipline/person"),
        defaultValue: record.discipline || "",
        placeholder: text("如：管道专业 / 张三", "e.g. Piping / owner"),
      },
      {
        key: "dueDate",
        label: text("截止日期", "Due date"),
        type: "date",
      },
      {
        key: "note",
        label: text("补充说明", "Additional note"),
        type: "textarea",
        rows: 4,
        defaultValue: [changedText, record.bboxDelta?.distanceMm ? `位移 ${Math.round(record.bboxDelta.distanceMm)}mm` : ""].filter(Boolean).join("\n"),
      },
    ],
    {
      title: text("创建差异 Issue", "Create Diff Issue"),
      kicker: text("差异闭环", "Diff Closure"),
      confirmLabel: text("创建 Issue", "Create Issue"),
    },
  );
  if (!issueDraft || !String(issueDraft.title || "").trim()) {
    return;
  }
  state.modelDiffBusy = true;
  state.modelDiffMessage = text("正在从差异记录创建 Issue…", "Creating Issue from diff record...");
  renderModelAppsPanel();
  try {
    const payload = await postJson(`/api/model-apps/diff/records/${encodeURIComponent(record.id)}/issue`, {
      title: String(issueDraft.title || "").trim(),
      responsible: String(issueDraft.responsible || "").trim(),
      dueDate: String(issueDraft.dueDate || "").trim(),
      note: String(issueDraft.note || "").trim(),
    });
    if (payload.record) {
      state.modelDiffRecords = state.modelDiffRecords.map((item) => (item.id === payload.record.id ? payload.record : item));
      state.modelDiffMessage = text("Issue 已创建并关联到该差异记录。", "Issue created and linked to this diff record.");
    }
    await refreshDocuments();
  } catch (error) {
    state.modelDiffMessage = error.message || text("创建 Issue 失败。", "Failed to create Issue.");
    showAlert(state.modelDiffMessage);
  } finally {
    state.modelDiffBusy = false;
    renderModelAppsPanel();
  }
}

async function createBulkIssuesFromModelDiff() {
  const records = filteredModelDiffRecords().filter((record) => !record.issueId);
  if (!records.length) {
    showAlert(text("当前筛选条件下没有未关联 Issue 的差异。", "No unlinked diff records match the current filters."));
    return;
  }
  const draft = await formAction(
    text(`将为当前筛选出的 ${records.length} 条未关联差异逐条创建 Issue，并自动带入各自构件与差异明细。`, `Create one Issue for each of the ${records.length} currently filtered unlinked diffs.`),
    [
      {
        key: "titlePrefix",
        label: text("标题前缀", "Title prefix"),
        defaultValue: text("模型差异复核", "Model diff review"),
      },
      {
        key: "responsible",
        label: text("责任专业/责任人", "Responsible discipline/person"),
        placeholder: text("留空则使用每条差异的专业", "Leave empty to use each record discipline"),
      },
      {
        key: "dueDate",
        label: text("统一截止日期", "Shared due date"),
        type: "date",
      },
      {
        key: "note",
        label: text("统一补充说明", "Shared note"),
        type: "textarea",
        rows: 4,
        placeholder: text("可填写本批次审阅背景或会议要求", "Optional review context"),
      },
    ],
    {
      title: text("批量创建差异 Issue", "Create Diff Issues"),
      kicker: text("批量闭环", "Bulk Closure"),
      confirmLabel: text("逐条创建", "Create separately"),
    },
  );
  if (!draft) {
    return;
  }
  state.modelDiffBusy = true;
  state.modelDiffMessage = text(`正在批量创建 ${records.length} 个 Issue…`, `Creating ${records.length} Issues...`);
  renderModelAppsPanel();
  const updatedRecords = [];
  const failures = [];
  try {
    for (const record of records) {
      try {
        const payload = await postJson(`/api/model-apps/diff/records/${encodeURIComponent(record.id)}/issue`, {
          title: `${String(draft.titlePrefix || text("模型差异复核", "Model diff review")).trim()}：${modelDiffTypeLabel(record.diffType)} ${record.name || record.elementType}`,
          responsible: String(draft.responsible || record.discipline || "").trim(),
          dueDate: String(draft.dueDate || "").trim(),
          note: String(draft.note || "").trim(),
        });
        if (payload.record) {
          updatedRecords.push(payload.record);
        }
      } catch (error) {
        failures.push(`${record.name || record.id}：${error.message || text("创建失败", "Failed")}`);
      }
    }
    const updatedMap = new Map(updatedRecords.map((record) => [record.id, record]));
    state.modelDiffRecords = state.modelDiffRecords.map((record) => updatedMap.get(record.id) || record);
    state.modelDiffMessage = failures.length
      ? text(`已创建 ${updatedRecords.length} 个 Issue，${failures.length} 个失败：${failures.slice(0, 3).join("；")}`, `Created ${updatedRecords.length} Issues, ${failures.length} failed.`)
      : text(`已创建 ${updatedRecords.length} 个 Issue 并关联到差异记录。`, `Created and linked ${updatedRecords.length} Issues.`);
    if (failures.length) {
      showAlert(state.modelDiffMessage);
    }
    await refreshDocuments();
  } finally {
    state.modelDiffBusy = false;
    renderModelAppsPanel();
  }
}

const CONSTRUCTION_SCHEDULE_GUIDE_PAGES = [
  {
    key: "model",
    title: "选择模型",
    note: "先选定要绑定 4D 进度的三维模型；APS 未配置时仍可导入计划，但不能打开 Viewer 播放。",
  },
  {
    key: "import",
    title: "导入 XER",
    note: "上传或粘贴 P6 XER，先解析预览，再确认导入为一个可追溯计划版本。",
  },
  {
    key: "mapping",
    title: "构件映射",
    note: "通过自动映射、批量规则、CSV 或 Viewer 手动选择，把 Activity 与构件闭口绑定。",
  },
  {
    key: "review",
    title: "可视化闭环",
    note: "加载时间点后查看 4D 着色、甘特、预警、Issue 和报表导出。",
  },
];

function normalizeConstructionScheduleGuidePage(value) {
  return CONSTRUCTION_SCHEDULE_GUIDE_PAGES.some((page) => page.key === value) ? value : "model";
}

function constructionScheduleGuidePageIndex(page = state.scheduleGuidePage) {
  return Math.max(0, CONSTRUCTION_SCHEDULE_GUIDE_PAGES.findIndex((item) => item.key === normalizeConstructionScheduleGuidePage(page)));
}

function setConstructionScheduleGuidePage(page) {
  state.scheduleGuidePage = normalizeConstructionScheduleGuidePage(page);
  renderModelAppsPanel();
}

function moveConstructionScheduleGuidePage(direction) {
  const index = constructionScheduleGuidePageIndex();
  const next = CONSTRUCTION_SCHEDULE_GUIDE_PAGES[Math.max(0, Math.min(CONSTRUCTION_SCHEDULE_GUIDE_PAGES.length - 1, index + direction))];
  if (next) {
    setConstructionScheduleGuidePage(next.key);
  }
}

function constructionScheduleDocuments() {
  const serverDocs = Array.isArray(state.scheduleDocuments) ? state.scheduleDocuments : [];
  const source = serverDocs.length ? serverDocs : state.documents;
  return source
    .filter((doc) => isModelWorkspaceDocument(doc) && canPreviewDocument(documentById(doc.id) || doc))
    .sort((left, right) => compareBySortLocale(left.name, right.name));
}

function selectedConstructionScheduleDocument() {
  return constructionScheduleDocuments().find((doc) => doc.id === state.scheduleDocumentId) || null;
}

function constructionScheduleVersionsForSelectedDocument() {
  return (Array.isArray(state.scheduleSchedules) ? state.scheduleSchedules : [])
    .filter((schedule) => !state.scheduleDocumentId || schedule.documentId === state.scheduleDocumentId)
    .sort((left, right) => String(right.importedAt || "").localeCompare(String(left.importedAt || "")));
}

function selectedConstructionSchedule() {
  return constructionScheduleVersionsForSelectedDocument().find((schedule) => schedule.id === state.scheduleId) || constructionScheduleVersionsForSelectedDocument()[0] || null;
}

function constructionScheduleDocumentReady(doc) {
  const fullDoc = documentById(doc?.id) || doc;
  return Boolean(fullDoc?.aps?.urn && apsTranslationStatus(fullDoc) === "success");
}

function seedConstructionScheduleSelection() {
  const docs = constructionScheduleDocuments();
  if (!state.scheduleDocumentId || !docs.some((doc) => doc.id === state.scheduleDocumentId)) {
    state.scheduleDocumentId = docs[0]?.id || "";
  }
  const schedules = constructionScheduleVersionsForSelectedDocument();
  if (!state.scheduleId || !schedules.some((schedule) => schedule.id === state.scheduleId)) {
    state.scheduleId = schedules.find((schedule) => schedule.isCurrent)?.id || schedules[0]?.id || "";
  }
}

function mergeConstructionSchedules(existing = [], incoming = []) {
  const map = new Map();
  [...incoming, ...existing].filter(Boolean).forEach((schedule) => {
    map.set(schedule.id, schedule);
  });
  return [...map.values()].sort((left, right) => String(right.importedAt || "").localeCompare(String(left.importedAt || "")));
}

async function refreshConstructionScheduleDocumentDetail(renderAfter = false) {
  if (!state.scheduleDocumentId) {
    state.scheduleSchedules = [];
    state.scheduleActivities = [];
    state.scheduleWbsNodes = [];
    state.scheduleMappings = [];
    state.scheduleCompleteness = null;
    state.scheduleAlerts = [];
    state.scheduleReports = [];
    return null;
  }
  const payload = await fetchJson(`/api/model-apps/schedule/documents/${encodeURIComponent(state.scheduleDocumentId)}`);
  state.scheduleSchedules = mergeConstructionSchedules(state.scheduleSchedules, Array.isArray(payload.schedules) ? payload.schedules : []);
  state.scheduleActivities = Array.isArray(payload.activities) ? payload.activities : [];
  state.scheduleWbsNodes = Array.isArray(payload.wbsNodes) ? payload.wbsNodes : [];
  state.scheduleMappings = Array.isArray(payload.mappings) ? payload.mappings : [];
  state.scheduleCompleteness = payload.completeness || null;
  state.scheduleAlerts = Array.isArray(payload.alerts) ? payload.alerts : [];
  state.scheduleReports = Array.isArray(payload.reports) ? payload.reports : [];
  if (payload.latestSchedule && !state.scheduleId) {
    state.scheduleId = payload.latestSchedule.id;
  }
  if (renderAfter) {
    renderModelAppsPanel();
  }
  return payload;
}

async function refreshConstructionScheduleData(options = {}) {
  if (!state.authenticated) return;
  try {
    const payload = await fetchJson("/api/model-apps/schedule");
    state.scheduleDocuments = Array.isArray(payload.documents) ? payload.documents : [];
    state.scheduleSchedules = mergeConstructionSchedules(state.scheduleSchedules, Array.isArray(payload.schedules) ? payload.schedules : []);
    state.scheduleAlerts = Array.isArray(payload.alerts) ? payload.alerts : state.scheduleAlerts;
    if (payload.apsReady === false) {
      state.scheduleMessage = payload.apsMessage || quantityApsConfigurationPrompt();
    } else if (/APS 服务尚未配置|APS 模型能力未启用|APS 配置尚未完整/.test(state.scheduleMessage || "")) {
      state.scheduleMessage = "";
    }
    seedConstructionScheduleSelection();
    if (state.scheduleDocumentId) {
      await refreshConstructionScheduleDocumentDetail(false);
      seedConstructionScheduleSelection();
    }
  } catch (error) {
    state.scheduleMessage = error.message || text("施工进度数据加载失败。", "Failed to load schedule data.");
  } finally {
    if (options.renderAfter) {
      renderModelAppsPanel();
    }
  }
}

function selectConstructionScheduleDocument(documentId) {
  const doc = constructionScheduleDocuments().find((item) => item.id === documentId) || null;
  state.scheduleDocumentId = doc?.id || "";
  state.scheduleId = "";
  state.scheduleActivities = [];
  state.scheduleWbsNodes = [];
  state.scheduleMappings = [];
  state.scheduleCompleteness = null;
  state.scheduleTimeline = null;
  state.scheduleWeeklyReport = null;
  state.scheduleReports = [];
  void refreshConstructionScheduleDocumentDetail(true);
}

function selectConstructionScheduleVersion(scheduleId) {
  state.scheduleId = scheduleId || "";
  state.scheduleTimeline = null;
  state.scheduleWeeklyReport = null;
  const schedule = selectedConstructionSchedule();
  if (schedule?.dataDate && !state.scheduleDate) {
    state.scheduleDate = schedule.dataDate;
  }
  renderModelAppsPanel();
}

async function readConstructionScheduleXerFile(file) {
  if (!file) {
    return;
  }
  const name = String(file.name || "").trim();
  if (name && !/\.(xer|txt)$/i.test(name)) {
    showAlert(text("请选择 .xer 或 .txt 格式的 P6 导出文件。", "Choose a .xer or .txt P6 export file."));
    if (elements.scheduleXerFileInput) elements.scheduleXerFileInput.value = "";
    return;
  }
  state.scheduleBusy = true;
  state.scheduleMessage = text("正在读取 XER 文件…", "Reading XER file...");
  renderModelAppsPanel();
  try {
    const content = await file.text();
    state.scheduleXerText = content || "";
    if (!state.scheduleVersionName && name) {
      state.scheduleVersionName = name.replace(/\.[^.]+$/, "");
    }
    state.schedulePreview = null;
    state.scheduleMessage = text("XER 文件已读取，请先解析预览再确认导入。", "XER file loaded. Preview it before importing.");
  } catch (error) {
    state.scheduleMessage = error.message || text("读取 XER 文件失败。", "Failed to read XER file.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

function constructionScheduleXerPayload() {
  const versionName = state.scheduleVersionName || elements.scheduleVersionNameInput?.value || "";
  const xerText = state.scheduleXerText || elements.scheduleXerInput?.value || "";
  return {
    documentId: state.scheduleDocumentId,
    versionName: versionName.trim(),
    xerText,
    isBaseline: Boolean(elements.scheduleBaselineToggle?.checked),
  };
}

async function previewConstructionScheduleXer() {
  const doc = selectedConstructionScheduleDocument();
  if (!doc) {
    showAlert(text("请先选择要绑定施工进度的模型。", "Select a model first."));
    return;
  }
  const payload = constructionScheduleXerPayload();
  if (!payload.xerText.trim()) {
    showAlert(text("请先粘贴或上传 XER 内容。", "Paste or upload XER content first."));
    return;
  }
  state.scheduleBusy = true;
  state.scheduleMessage = text("正在解析 XER 计划文件…", "Parsing XER schedule...");
  renderModelAppsPanel();
  try {
    const response = await postJson("/api/model-apps/schedule/preview", payload);
    state.schedulePreview = response.preview || null;
    state.scheduleMessage = text("XER 解析完成，请核对项目、数据日期、Activity 数量和警告后确认导入。", "XER parsed. Review project, data date, activity counts, and warnings before import.");
  } catch (error) {
    state.scheduleMessage = error.message || text("XER 解析失败。", "Failed to parse XER.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

async function importConstructionScheduleXer() {
  const doc = selectedConstructionScheduleDocument();
  if (!doc) {
    showAlert(text("请先选择要绑定施工进度的模型。", "Select a model first."));
    return;
  }
  const payload = constructionScheduleXerPayload();
  if (!payload.xerText.trim()) {
    showAlert(text("请先粘贴或上传 XER 内容。", "Paste or upload XER content first."));
    return;
  }
  state.scheduleBusy = true;
  state.scheduleMessage = text("正在导入施工进度计划…", "Importing construction schedule...");
  renderModelAppsPanel();
  try {
    const response = await postJson("/api/model-apps/schedule/import", payload);
    state.scheduleSchedules = mergeConstructionSchedules(state.scheduleSchedules, [response.schedule]);
    state.scheduleId = response.schedule?.id || state.scheduleId;
    state.schedulePreview = response.preview || state.schedulePreview;
    state.scheduleActivities = Array.isArray(response.activities) ? response.activities : [];
    state.scheduleWbsNodes = Array.isArray(response.wbsNodes) ? response.wbsNodes : [];
    state.scheduleMappings = [];
    state.scheduleCompleteness = null;
    state.scheduleReports = [];
    state.scheduleDate = response.schedule?.dataDate || state.scheduleDate;
    state.scheduleGuidePage = "mapping";
    state.scheduleMessage = text("计划已导入。下一步可复用模型属性快照进行自动映射，或进入 Viewer 手动关联。", "Schedule imported. Next, reuse model property snapshots for auto-mapping or bind manually in Viewer.");
    await refreshDocuments();
  } catch (error) {
    state.scheduleMessage = error.message || text("施工进度计划导入失败。", "Failed to import schedule.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

async function autoMapConstructionSchedule() {
  const schedule = selectedConstructionSchedule();
  if (!schedule) {
    showAlert(text("请先导入或选择一个进度计划版本。", "Import or select a schedule version first."));
    return;
  }
  state.scheduleBusy = true;
  state.scheduleMessage = text("正在按 Tag、系统区域、楼层和 WBS 规则匹配构件…", "Matching elements by tag, system area, level, and WBS...");
  renderModelAppsPanel();
  try {
    const payload = await postJson(`/api/model-apps/schedule/${encodeURIComponent(schedule.id)}/auto-map`, {});
    state.scheduleMappings = Array.isArray(payload.mappings) ? payload.mappings : [];
    state.scheduleCompleteness = payload.completeness || null;
    state.scheduleSchedules = mergeConstructionSchedules(state.scheduleSchedules, [payload.schedule]);
    state.scheduleMessage = text(`自动映射完成：${state.scheduleCompleteness?.mappedActivities || 0}/${state.scheduleCompleteness?.totalActivities || 0} 个 Activity 已绑定构件。`, `Auto-mapping complete: ${state.scheduleCompleteness?.mappedActivities || 0}/${state.scheduleCompleteness?.totalActivities || 0} activities mapped.`);
  } catch (error) {
    state.scheduleMessage = error.message || text("自动映射失败，请先生成模型属性快照或转入手动关联。", "Auto-mapping failed. Generate a property snapshot first or use manual binding.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

function selectedScheduleBulkActivityId() {
  return state.scheduleBulkActivityId || elements.scheduleBulkActivitySelect?.value || state.scheduleActivities[0]?.id || "";
}

async function runBulkConstructionScheduleMapping() {
  const schedule = selectedConstructionSchedule();
  const activityRowId = selectedScheduleBulkActivityId();
  if (!schedule || !activityRowId) {
    showAlert(text("请先选择计划版本和目标 Activity。", "Select a schedule version and target activity first."));
    return;
  }
  state.scheduleBusy = true;
  state.scheduleMessage = text("正在执行批量构件映射…", "Running bulk element mapping...");
  renderModelAppsPanel();
  try {
    const payload = await postJson(`/api/model-apps/schedule/${encodeURIComponent(schedule.id)}/bulk-map`, {
      activityRowId,
      mode: state.scheduleBulkMode || elements.scheduleBulkModeSelect?.value || "floor_type",
      floor: state.scheduleBulkFloor || elements.scheduleBulkFloorInput?.value || "",
      elementType: state.scheduleBulkElementType || elements.scheduleBulkElementTypeInput?.value || "",
      discipline: state.scheduleBulkDiscipline || elements.scheduleBulkDisciplineInput?.value || "",
    });
    state.scheduleMappings = Array.isArray(payload.mappings) ? payload.mappings : state.scheduleMappings;
    state.scheduleCompleteness = payload.completeness || state.scheduleCompleteness;
    state.scheduleSchedules = mergeConstructionSchedules(state.scheduleSchedules, [payload.schedule]);
    state.scheduleMessage = text(`批量映射完成：新增 ${payload.createdMappings?.length || 0} 条构件绑定。`, `Bulk mapping complete: ${payload.createdMappings?.length || 0} mappings added.`);
  } catch (error) {
    state.scheduleMessage = error.message || text("批量映射失败。", "Bulk mapping failed.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

async function importConstructionScheduleMappingsFromCsv() {
  const schedule = selectedConstructionSchedule();
  const csvText = state.scheduleMappingCsvText || elements.scheduleMappingCsvInput?.value || "";
  if (!schedule || !csvText.trim()) {
    showAlert(text("请先选择计划版本并填写 CSV 映射内容。", "Select a schedule version and provide mapping CSV first."));
    return;
  }
  state.scheduleBusy = true;
  state.scheduleMessage = text("正在导入 CSV 映射…", "Importing CSV mappings...");
  renderModelAppsPanel();
  try {
    const payload = await postJson(`/api/model-apps/schedule/${encodeURIComponent(schedule.id)}/import-mappings`, { csvText });
    state.scheduleMappings = Array.isArray(payload.mappings) ? payload.mappings : state.scheduleMappings;
    state.scheduleCompleteness = payload.completeness || state.scheduleCompleteness;
    state.scheduleSchedules = mergeConstructionSchedules(state.scheduleSchedules, [payload.schedule]);
    state.scheduleMessage = text(`CSV 映射已导入：新增 ${payload.createdMappings?.length || 0} 条，跳过 ${payload.skippedRows?.length || 0} 行。`, `CSV mappings imported: ${payload.createdMappings?.length || 0} added, ${payload.skippedRows?.length || 0} skipped.`);
  } catch (error) {
    state.scheduleMessage = error.message || text("CSV 映射导入失败。", "CSV mapping import failed.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

async function reportConstructionScheduleActivity(activityRowId) {
  const activity = state.scheduleActivities.find((item) => item.id === activityRowId);
  if (!activity) return;
  const draft = await formAction(
    text("上报现场实际进度，系统会保留历史记录并用于滞后、临期和长期未上报预警。", "Report field progress. History is retained and used for delay, due-soon, and stale-report alerts."),
    [
      { key: "actualStart", label: text("实际开始", "Actual start"), type: "date", defaultValue: activity.actualStart || "" },
      { key: "actualFinish", label: text("实际完成", "Actual finish"), type: "date", defaultValue: activity.actualFinish || "" },
      { key: "percentComplete", label: text("完成百分比", "Percent complete"), type: "number", defaultValue: String(activity.percentComplete || 0), required: true },
      { key: "note", label: text("上报说明", "Report note"), type: "textarea", rows: 4, placeholder: text("填写现场进展、阻碍原因或下一步计划。", "Record field progress, blockers, or next actions.") },
    ],
    {
      title: text("上报实际进度", "Report Progress"),
      kicker: `${activity.activityId} ${activity.name}`,
      confirmLabel: text("提交上报", "Submit Report"),
    },
  );
  if (!draft) return;
  state.scheduleBusy = true;
  renderModelAppsPanel();
  try {
    const payload = await postJson(`/api/model-apps/schedule/activities/${encodeURIComponent(activity.id)}/report`, {
      actualStart: String(draft.actualStart || "").trim(),
      actualFinish: String(draft.actualFinish || "").trim(),
      percentComplete: Number(draft.percentComplete || 0),
      note: String(draft.note || "").trim(),
    });
    state.scheduleActivities = state.scheduleActivities.map((item) => (item.id === payload.activity.id ? payload.activity : item));
    state.scheduleReports = [payload.report, ...state.scheduleReports.filter((item) => item.id !== payload.report.id)];
    state.scheduleTimeline = null;
    state.scheduleMessage = text("现场进度已上报，请重新加载时间点刷新 4D 状态。", "Progress reported. Reload the date to refresh 4D status.");
  } catch (error) {
    state.scheduleMessage = error.message || text("进度上报失败。", "Progress report failed.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

async function exportConstructionSchedule(kind) {
  const schedule = selectedConstructionSchedule();
  if (!schedule) {
    showAlert(text("请先选择计划版本。", "Select a schedule version first."));
    return;
  }
  const label = kind === "weekly_pdf" ? "周报 PDF" : kind === "gantt_pdf" ? "甘特 PDF" : "进度 Excel";
  state.scheduleBusy = true;
  state.scheduleMessage = text(`正在生成${label}…`, `Generating ${label}...`);
  renderModelAppsPanel();
  try {
    const weekEnd = state.scheduleDate || elements.scheduleDateInput?.value || schedule.dataDate || "";
    const payload = await postJson(`/api/model-apps/schedule/${encodeURIComponent(schedule.id)}/export`, {
      kind,
      weekEnd,
      weekStart: weekEnd ? scheduleDateMinusDays(weekEnd, 6) : "",
      language: currentLanguage(),
    });
    state.scheduleMessage = text(`${label} 已生成。`, `${label} is ready.`);
    if (payload.downloadUrl) {
      window.open(payload.downloadUrl, "_blank", "noopener");
    }
  } catch (error) {
    state.scheduleMessage = error.message || text("施工进度导出失败。", "Construction schedule export failed.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

async function loadConstructionScheduleTimeline() {
  const schedule = selectedConstructionSchedule();
  if (!schedule) {
    showAlert(text("请先选择计划版本。", "Select a schedule version first."));
    return;
  }
  const date = state.scheduleDate || elements.scheduleDateInput?.value || schedule.dataDate || "";
  state.scheduleBusy = true;
  state.scheduleMessage = text("正在计算当前时间点的构件进度状态…", "Calculating element status for the selected date...");
  renderModelAppsPanel();
  try {
    const payload = await fetchJson(`/api/model-apps/schedule/${encodeURIComponent(schedule.id)}/timeline?date=${encodeURIComponent(date)}`);
    state.scheduleTimeline = payload.timeline || null;
    state.scheduleCompleteness = payload.completeness || state.scheduleCompleteness;
    const alertPayload = await fetchJson(`/api/model-apps/schedule/${encodeURIComponent(schedule.id)}/alerts?date=${encodeURIComponent(date)}`);
    state.scheduleAlerts = Array.isArray(alertPayload.alerts) ? alertPayload.alerts : [];
    state.scheduleGuidePage = "review";
    state.scheduleMessage = text("时间点状态已加载，可打开 Viewer 查看 4D 着色。", "Timeline state loaded. Open Viewer to inspect 4D coloring.");
  } catch (error) {
    state.scheduleMessage = error.message || text("加载施工进度时间轴失败。", "Failed to load schedule timeline.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

function scheduleDateMinusDays(value, days) {
  const parsed = value ? new Date(`${value}T00:00:00.000Z`) : new Date();
  if (Number.isNaN(parsed.getTime())) return "";
  parsed.setUTCDate(parsed.getUTCDate() - Number(days || 0));
  return parsed.toISOString().slice(0, 10);
}

async function loadConstructionWeeklyReport() {
  const schedule = selectedConstructionSchedule();
  if (!schedule) {
    showAlert(text("请先选择计划版本。", "Select a schedule version first."));
    return;
  }
  const weekEnd = state.scheduleDate || elements.scheduleDateInput?.value || schedule.dataDate || new Date().toISOString().slice(0, 10);
  const weekStart = scheduleDateMinusDays(weekEnd, 6);
  state.scheduleBusy = true;
  renderModelAppsPanel();
  try {
    const payload = await fetchJson(`/api/model-apps/schedule/${encodeURIComponent(schedule.id)}/weekly-report?weekStart=${encodeURIComponent(weekStart)}&weekEnd=${encodeURIComponent(weekEnd)}`);
    state.scheduleWeeklyReport = payload;
    state.scheduleMessage = text("进度周报已生成，可用于周会或审批附言。", "Weekly report generated for review meetings or approval notes.");
  } catch (error) {
    state.scheduleMessage = error.message || text("进度周报生成失败。", "Failed to generate weekly report.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

function openConstructionScheduleViewer() {
  const doc = selectedConstructionScheduleDocument();
  const schedule = selectedConstructionSchedule();
  if (!doc || !schedule) {
    return;
  }
  openApsDocument(doc.id, {
    mode: "review",
    workspace: "model",
    scheduleId: schedule.id,
    scheduleDate: state.scheduleDate || schedule.dataDate || "",
    scheduleSpeed: state.schedulePlaybackSpeed || "week",
  });
}

async function createIssueFromConstructionScheduleAlert(alertId) {
  const alert = state.scheduleAlerts.find((item) => item.id === alertId);
  if (!alert) return;
  const draft = await formAction(
    text("从进度预警创建 Issue，会自动带入 Activity、滞后天数、完成率和关联构件 dbId。", "Create an Issue from this schedule alert with activity, delay, progress, and dbIds attached."),
    [
      { key: "title", label: text("Issue 标题", "Issue title"), defaultValue: `${alert.activityCode} ${alert.activityName} 进度预警`, required: true },
      { key: "responsible", label: text("责任专业/责任人", "Responsible discipline/person"), defaultValue: alert.activityName?.includes("管道") ? "管道" : "" },
      { key: "dueDate", label: text("截止日期", "Due date"), type: "date" },
    ],
    {
      title: text("创建进度 Issue", "Create Schedule Issue"),
      kicker: text("进度闭环", "Schedule Closure"),
      confirmLabel: text("创建 Issue", "Create Issue"),
    },
  );
  if (!draft?.title) return;
  state.scheduleBusy = true;
  renderModelAppsPanel();
  try {
    const payload = await postJson(`/api/model-apps/schedule/alerts/${encodeURIComponent(alert.id)}/issue`, {
      title: String(draft.title || "").trim(),
      responsible: String(draft.responsible || "").trim(),
      dueDate: String(draft.dueDate || "").trim(),
    });
    if (payload.alert) {
      state.scheduleAlerts = state.scheduleAlerts.map((item) => (item.id === payload.alert.id ? payload.alert : item));
    }
    state.scheduleMessage = text("进度 Issue 已创建并关联预警。", "Schedule Issue created and linked to the alert.");
    await refreshDocuments();
  } catch (error) {
    state.scheduleMessage = error.message || text("创建进度 Issue 失败。", "Failed to create schedule Issue.");
    showAlert(state.scheduleMessage);
  } finally {
    state.scheduleBusy = false;
    renderModelAppsPanel();
  }
}

function handleConstructionScheduleAction(action, button) {
  if (action === "issue") {
    void createIssueFromConstructionScheduleAlert(button.dataset.alertId || "");
  }
  if (action === "viewer") {
    openConstructionScheduleViewer();
  }
  if (action === "report") {
    void reportConstructionScheduleActivity(button.dataset.activityRowId || "");
  }
}

function renderConstructionScheduleWorkbench(activeTool = normalizeModelAppTool(state.modelAppTool)) {
  if (!elements.scheduleDocumentSelect) return;
  seedConstructionScheduleSelection();
  const docs = constructionScheduleDocuments();
  const doc = selectedConstructionScheduleDocument();
  const schedules = constructionScheduleVersionsForSelectedDocument();
  const schedule = selectedConstructionSchedule();
  const apsReady = quantityApsConfigurationReady();
  const modelReady = constructionScheduleDocumentReady(doc);
  const hasSchedule = Boolean(schedule);
  const completeness = state.scheduleCompleteness;
  const mappedRatio = Number(completeness?.mappedActivityRatio || 0);

  if (elements.scheduleModelCountBadge) {
    elements.scheduleModelCountBadge.textContent = text(`${docs.length} 个模型`, `${docs.length} models`);
  }
  const configAlert = apsReady
    ? ""
    : `<div class="quantity-model-config-alert"><span>${escapeHtml(quantityApsConfigurationPrompt())}</span><button class="ghost-button compact-button" data-model-app-action="open-aps-settings" type="button">${escapeHtml(text("去配置 APS", "Configure APS"))}</button></div>`;
  elements.scheduleModelList.innerHTML = `${configAlert}${docs.length ? docs.map((item) => {
    const selected = item.id === state.scheduleDocumentId;
    const meta = modelAppDocumentStatusMeta(item);
    return `
      <button class="model-app-model-row ${selected ? "selected" : ""}" type="button" data-schedule-model="${escapeHtml(item.id)}">
        <span class="model-app-model-main">
          <strong>${escapeHtml(item.name)}</strong>
          <span>${escapeHtml([item.version || "V1", item.scheduleCount ? `${item.scheduleCount} 个计划版本` : "未导入计划", item.updatedAt ? formatDateTime(item.updatedAt) : ""].filter(Boolean).join(" · "))}</span>
        </span>
        <span class="model-app-model-meta">
          <span class="status-pill ${escapeHtml(meta.tone)}">${escapeHtml(meta.label)}</span>
          <small>${escapeHtml(truncate(meta.detail, 48))}</small>
        </span>
      </button>
    `;
  }).join("") : `<div class="model-app-empty-state"><strong>${escapeHtml(text("当前项目还没有模型文件", "No model files"))}</strong><span>${escapeHtml(text("请先在文件管理中上传海水淡化项目三维模型。", "Upload the project model in File Management first."))}</span><button class="ghost-button compact-button" data-model-app-action="open-files" type="button">${escapeHtml(text("去文件管理上传", "Go to File Management"))}</button></div>`}`;

  setSelectOptions(elements.scheduleDocumentSelect, docs.map((item) => ({ value: item.id, label: item.name })), state.scheduleDocumentId);
  if (!docs.length) elements.scheduleDocumentSelect.innerHTML = `<option value="">${escapeHtml(text("暂无模型", "No models"))}</option>`;
  setSelectOptions(
    elements.scheduleVersionSelect,
    schedules.map((item) => ({ value: item.id, label: `${item.name} · ${item.dataDate || text("无数据日期", "No data date")}${item.isBaseline ? text(" · 基准", " · Baseline") : ""}` })),
    state.scheduleId,
  );
  if (!schedules.length) elements.scheduleVersionSelect.innerHTML = `<option value="">${escapeHtml(text("暂无计划版本", "No schedules"))}</option>`;
  if (!state.scheduleBulkActivityId || !state.scheduleActivities.some((item) => item.id === state.scheduleBulkActivityId)) {
    state.scheduleBulkActivityId = state.scheduleActivities[0]?.id || "";
  }
  setSelectOptions(
    elements.scheduleBulkActivitySelect,
    state.scheduleActivities.map((item) => ({ value: item.id, label: `${item.activityId} ${item.name}` })),
    state.scheduleBulkActivityId,
  );
  if (!state.scheduleActivities.length && elements.scheduleBulkActivitySelect) {
    elements.scheduleBulkActivitySelect.innerHTML = `<option value="">${escapeHtml(text("暂无 Activity", "No activities"))}</option>`;
  }
  syncInputValue(elements.scheduleVersionNameInput, state.scheduleVersionName);
  syncInputValue(elements.scheduleXerInput, state.scheduleXerText);
  syncInputValue(elements.scheduleDateInput, state.scheduleDate || schedule?.dataDate || "");
  syncInputValue(elements.schedulePlaybackSpeedSelect, state.schedulePlaybackSpeed || "week");
  syncInputValue(elements.scheduleBulkModeSelect, state.scheduleBulkMode || "floor_type");
  syncInputValue(elements.scheduleBulkFloorInput, state.scheduleBulkFloor);
  syncInputValue(elements.scheduleBulkElementTypeInput, state.scheduleBulkElementType);
  syncInputValue(elements.scheduleBulkDisciplineInput, state.scheduleBulkDiscipline);
  syncInputValue(elements.scheduleMappingCsvInput, state.scheduleMappingCsvText);

  const guide = [
    [elements.scheduleGuideModel, elements.scheduleGuideModelText, doc ? (modelReady ? "done" : "active") : "active", doc ? (modelReady ? text("模型已就绪", "Model ready") : text("可导入计划，Viewer 待 APS", "Import allowed, Viewer waits APS")) : text("待选择", "Pending")],
    [elements.scheduleGuideImport, elements.scheduleGuideImportText, hasSchedule ? "done" : state.schedulePreview ? "active" : "pending", hasSchedule ? `${schedules.length} 个版本` : state.schedulePreview ? text("已预览", "Preview ready") : text("待预览", "Pending")],
    [elements.scheduleGuideMapping, elements.scheduleGuideMappingText, mappedRatio > 0 ? (mappedRatio >= 80 ? "done" : "active") : hasSchedule ? "active" : "pending", completeness ? `${completeness.mappedActivities}/${completeness.totalActivities} Activity` : text("未映射", "Not mapped")],
    [elements.scheduleGuideReview, elements.scheduleGuideReviewText, state.scheduleTimeline ? "done" : hasSchedule ? "active" : "pending", state.scheduleTimeline ? text("时间轴已加载", "Timeline loaded") : text("待生成", "Pending")],
  ];
  guide.forEach(([el, textEl, cls, label]) => {
    el?.classList.remove("pending", "active", "done", "blocked");
    el?.classList.add(cls);
    if (textEl) textEl.textContent = label;
  });
  renderConstructionSchedulePager({ doc, hasSchedule });

  const preflight = [
    { ok: Boolean(doc), label: text("模型选择", "Model"), note: doc?.name || text("未选择", "Not selected") },
    { ok: Boolean(apsReady), label: "APS", note: apsReady ? text("已配置", "Configured") : quantityApsConfigurationPrompt() },
    { ok: Boolean(modelReady), label: text("Viewer", "Viewer"), note: modelReady ? text("可播放 4D", "4D ready") : text("模型未完成 APS 转换", "Model not translated") },
    { ok: Boolean(hasSchedule), label: "XER", note: hasSchedule ? `${schedule.name} · ${schedule.dataDate || ""}` : text("待导入", "Import needed") },
    { ok: Boolean(mappedRatio > 0), label: text("映射", "Mapping"), note: completeness ? `${mappedRatio}%` : text("待映射", "Pending") },
  ];
  elements.schedulePreflightList.innerHTML = preflight.map((item) => `
    <div class="quantity-preflight-row ${item.ok ? "done" : "blocked"}">
      <span>${escapeHtml(item.label)}</span>
      <strong>${escapeHtml(item.ok ? text("通过", "OK") : text("待处理", "Pending"))}</strong>
      <small>${escapeHtml(item.note)}</small>
    </div>
  `).join("");

  elements.scheduleReadinessBadge.textContent = !doc ? text("待选择模型", "Select model") : !hasSchedule ? text("待导入 XER", "Import XER") : mappedRatio ? text("可视化就绪", "Ready") : text("待映射", "Mapping needed");
  elements.scheduleReadinessBadge.className = `mini-pill ${hasSchedule && mappedRatio ? "status-pill approved" : "status-pill in_review"}`;
  elements.schedulePreviewBadge.textContent = state.schedulePreview ? text("已解析", "Parsed") : text("未解析", "Not parsed");
  elements.schedulePreviewPanel.innerHTML = renderConstructionSchedulePreview();
  elements.scheduleVersionList.innerHTML = renderConstructionScheduleVersionList(schedules);
  elements.scheduleSummaryGrid.innerHTML = renderManagerSummaryCards([
    { label: text("计划版本", "Schedule Versions"), value: String(schedules.length) },
    { label: "Activity", value: String(state.scheduleActivities.length || schedule?.activityCount || 0) },
    { label: text("已映射 Activity", "Mapped Activities"), value: String(completeness?.mappedActivities || 0) },
    { label: text("映射覆盖率", "Mapping Coverage"), value: `${mappedRatio || 0}%` },
    { label: text("打开预警", "Open Alerts"), value: String((state.scheduleAlerts || []).filter((item) => item.status === "open").length) },
  ]);
  renderConstructionScheduleTimelinePanel();
  renderConstructionScheduleGanttPanel();
  renderConstructionScheduleAlerts();
  renderConstructionWeeklyPanel();

  elements.scheduleDocumentSelect.disabled = state.scheduleBusy || !docs.length;
  elements.scheduleVersionSelect.disabled = state.scheduleBusy || !schedules.length;
  if (elements.scheduleXerFileInput) {
    elements.scheduleXerFileInput.disabled = state.scheduleBusy || !doc;
  }
  elements.schedulePreviewButton.disabled = state.scheduleBusy || !doc;
  elements.scheduleImportButton.disabled = state.scheduleBusy || !doc;
  elements.scheduleAutoMapButton.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleLoadTimelineButton.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleOpenViewerButton.disabled = state.scheduleBusy || !hasSchedule || !modelReady;
  elements.scheduleWeeklyReportButton.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleBulkActivitySelect.disabled = state.scheduleBusy || !hasSchedule || !state.scheduleActivities.length;
  elements.scheduleBulkModeSelect.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleBulkFloorInput.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleBulkElementTypeInput.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleBulkDisciplineInput.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleBulkMapButton.disabled = state.scheduleBusy || !hasSchedule || !state.scheduleActivities.length;
  elements.scheduleMappingCsvInput.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleImportMappingButton.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleExportWorkbookButton.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleExportWeeklyButton.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleExportGanttButton.disabled = state.scheduleBusy || !hasSchedule;
  elements.scheduleMessage.textContent = state.scheduleMessage || (activeTool === "schedule" && !apsReady ? quantityApsConfigurationPrompt() : "");
}

function renderConstructionSchedulePreview() {
  const preview = state.schedulePreview;
  if (!preview) {
    return `<div class="empty-card">${escapeHtml(text("粘贴 P6 XER 内容后先解析预览，再确认导入。", "Paste P6 XER content, preview it, then confirm import."))}</div>`;
  }
  const stats = preview.stats || {};
  const status = preview.statusDistribution || {};
  const warnings = Array.isArray(preview.warnings) ? preview.warnings : [];
  return `
    <div class="construction-schedule-preview-grid">
      <div><span>项目</span><strong>${escapeHtml(preview.project?.name || "—")}</strong></div>
      <div><span>数据日期</span><strong>${escapeHtml(preview.project?.dataDate || "—")}</strong></div>
      <div><span>Activity</span><strong>${escapeHtml(stats.activityCount || 0)}</strong></div>
      <div><span>WBS</span><strong>${escapeHtml(text(`${stats.wbsCount || 0} 节点 / ${stats.wbsLevels || 0} 级`, `${stats.wbsCount || 0} nodes / ${stats.wbsLevels || 0} levels`))}</strong></div>
      <div><span>进行中</span><strong>${escapeHtml(status.inProgress || 0)}</strong></div>
      <div><span>已完成</span><strong>${escapeHtml(status.completed || 0)}</strong></div>
    </div>
    ${warnings.length ? `<div class="construction-schedule-warning-list">${warnings.slice(0, 6).map((item) => `<span>${escapeHtml(item)}</span>`).join("")}</div>` : `<div class="empty-card compact-empty">${escapeHtml(text("未发现日期反转等基础异常。", "No basic date warnings found."))}</div>`}
  `;
}

function renderConstructionScheduleVersionList(schedules) {
  return schedules.length ? schedules.map((schedule) => `
    <button class="quantity-task-row construction-schedule-version-row ${schedule.id === state.scheduleId ? "selected" : ""}" data-schedule-version="${escapeHtml(schedule.id)}" type="button">
      <span class="status-pill ${schedule.isBaseline ? "neutral" : "approved"}">${escapeHtml(schedule.isBaseline ? "基准" : "当前")}</span>
      <div>
        <strong>${escapeHtml(schedule.name)}</strong>
        <span>${escapeHtml([schedule.projectName, schedule.dataDate, formatDateTime(schedule.importedAt)].filter(Boolean).join(" · "))}</span>
        ${schedule.importSummary?.baseScheduleId ? `<small>${escapeHtml(text(`较上一版：新增 ${schedule.importSummary.added || 0} / 删除 ${schedule.importSummary.deleted || 0} / 日期调整 ${schedule.importSummary.dateChanged || 0} / 进度变化 ${schedule.importSummary.progressChanged || 0}`, `vs previous: +${schedule.importSummary.added || 0} added / ${schedule.importSummary.deleted || 0} deleted / ${schedule.importSummary.dateChanged || 0} date changes / ${schedule.importSummary.progressChanged || 0} progress changes`))}</small>` : ""}
      </div>
      <span>${escapeHtml(`${schedule.activityCount || 0} Activity`)}</span>
      <span>${escapeHtml(text(`${schedule.mappedActivityCount || 0} 已映射`, `${schedule.mappedActivityCount || 0} mapped`))}</span>
    </button>
  `).join("") : `<div class="empty-card">${escapeHtml(text("还没有导入任何施工进度计划。", "No schedule version imported yet."))}</div>`;
}

function renderConstructionScheduleTimelinePanel() {
  const timeline = state.scheduleTimeline;
  if (!timeline) {
    elements.scheduleTimelineBadge.textContent = text("未加载", "Not loaded");
    elements.scheduleTimelinePanel.innerHTML = `<div class="empty-card">${escapeHtml(text("选择日期后加载时间点，系统会按构件关联 Activity 计算未来、进行中、完成和滞后状态。", "Load a date to calculate future, in-progress, complete, and delayed element status."))}</div>`;
    return;
  }
  const stats = timeline.stats || {};
  elements.scheduleTimelineBadge.textContent = text(`${timeline.date} · ${timeline.elements?.length || 0} 构件`, `${timeline.date} · ${timeline.elements?.length || 0} elements`);
  elements.scheduleTimelinePanel.innerHTML = `
    <div class="construction-schedule-stat-strip">
      ${[
        ["future", "未来", stats.future || 0],
        ["not_started", "未开始", stats.notStarted || 0],
        ["in_progress", "进行中", stats.inProgress || 0],
        ["completed", "已完成", stats.completed || 0],
        ["delayed", "滞后", stats.delayed || 0],
        ["unmapped", "无映射", stats.unmapped || 0],
      ].map(([key, label, value]) => `<div><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join("")}
    </div>
    <div class="model-diff-table-wrap">
      <table class="model-diff-table compact">
        <thead><tr><th>构件</th><th>状态</th><th>专业</th><th>系统/区域</th><th>关联工序</th></tr></thead>
        <tbody>
          ${(timeline.elements || []).slice(0, 80).map((element) => `
            <tr>
              <td><strong>${escapeHtml(element.name || element.uniqueId || `dbId ${element.dbId}`)}</strong><span>${escapeHtml(element.elementType || "")}</span></td>
              <td><span class="status-pill ${scheduleStatusTone(element.status)}">${escapeHtml(scheduleStatusLabel(element.status))}</span></td>
              <td>${escapeHtml(element.discipline || "—")}</td>
              <td>${escapeHtml(element.floor || "—")}</td>
              <td>${escapeHtml((element.activities || []).map((item) => item.activityId).join(" / ") || "—")}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function scheduleStatusLabel(status) {
  return {
    future: "未来计划",
    not_started: "未开始",
    in_progress: "进行中",
    completed: "已完成",
    early: "提前完成",
    delayed: "滞后",
    unmapped: "无映射",
  }[status] || status || "未知";
}

function scheduleStatusTone(status) {
  return {
    future: "neutral",
    not_started: "neutral",
    in_progress: "in_review",
    completed: "approved",
    early: "approved",
    delayed: "rejected",
    unmapped: "neutral",
  }[status] || "neutral";
}

function renderConstructionScheduleGanttPanel() {
  const rows = state.scheduleActivities.slice(0, 40);
  const reportsByActivity = new Map();
  (state.scheduleReports || []).forEach((report) => {
    const list = reportsByActivity.get(report.activityId) || [];
    list.push(report);
    reportsByActivity.set(report.activityId, list);
  });
  elements.scheduleGanttBadge.textContent = `${state.scheduleActivities.length || 0} Activity`;
  elements.scheduleGanttPanel.innerHTML = rows.length ? rows.map((activity) => {
    const pct = Math.max(0, Math.min(100, Number(activity.percentComplete || 0)));
    const delayed = activity.plannedFinish && state.scheduleDate && activity.actualFinish === "" && activity.plannedFinish < state.scheduleDate;
    const reports = reportsByActivity.get(activity.activityId) || [];
    return `
      <article class="construction-schedule-gantt-row ${delayed ? "delayed" : ""}">
        <div>
          <strong>${escapeHtml(`${activity.activityId} ${activity.name}`)}</strong>
          <span>${escapeHtml(text(`${activity.plannedStart || "—"} → ${activity.plannedFinish || "—"} · ${activity.type || "Task"} · 上报 ${reports.length} 次`, `${activity.plannedStart || "—"} → ${activity.plannedFinish || "—"} · ${activity.type || "Task"} · ${reports.length} reports`))}</span>
        </div>
        <div class="construction-schedule-gantt-track"><i style="width:${pct}%"></i></div>
        <span class="mini-pill">${escapeHtml(`${pct}%`)}</span>
        <button class="ghost-button compact-button" data-schedule-action="report" data-activity-row-id="${escapeHtml(activity.id)}" type="button">${escapeHtml(text("上报", "Report"))}</button>
      </article>
    `;
  }).join("") : `<div class="empty-card">${escapeHtml(text("导入 XER 后显示 Activity 甘特条，并与 Viewer 构件联动。", "Import XER to show activity bars linked with Viewer elements."))}</div>`;
}

function renderConstructionScheduleAlerts() {
  const alerts = Array.isArray(state.scheduleAlerts) ? state.scheduleAlerts : [];
  elements.scheduleAlertBadge.textContent = text(`${alerts.filter((item) => item.status === "open").length} 条未处理`, `${alerts.filter((item) => item.status === "open").length} unhandled`);
  elements.scheduleAlertList.innerHTML = alerts.length ? alerts.slice(0, 30).map((alert) => `
    <article class="construction-schedule-alert-row ${alert.severity}">
      <div>
        <span class="status-pill ${alert.severity === "critical" || alert.severity === "high" ? "rejected" : "in_review"}">${escapeHtml(scheduleAlertLabel(alert.type))}</span>
        <strong>${escapeHtml(`${alert.activityCode} ${alert.activityName}`)}</strong>
        <small>${escapeHtml(alert.message || "")}</small>
      </div>
      <span>${escapeHtml(alert.delayDays ? text(`${alert.delayDays} 天`, `${alert.delayDays} d`) : `${alert.percentComplete || 0}%`)}</span>
      <button class="ghost-button compact-button" data-schedule-action="issue" data-alert-id="${escapeHtml(alert.id)}" type="button" ${alert.issueId ? "disabled" : ""}>${escapeHtml(alert.issueId ? text("已关联", "Linked") : text("创建 Issue", "Create Issue"))}</button>
    </article>
  `).join("") : `<div class="empty-card">${escapeHtml(text("加载时间点后，滞后、临期、里程碑风险和长期未上报会显示在这里。", "After loading a date, delayed, due-soon, milestone, and stale-report alerts appear here."))}</div>`;
}

function scheduleAlertLabel(type) {
  return {
    delayed: "工序滞后",
    due_soon: "临期预警",
    progress_regression: "进度异常",
    milestone_risk: "里程碑风险",
    stale_report: "长期未上报",
  }[type] || type || "预警";
}

function scheduleGuidePageAvailable(page, context = {}) {
  if (page === "model") return true;
  if (page === "import") return Boolean(context.doc);
  return Boolean(context.hasSchedule);
}

function renderConstructionSchedulePager(context = {}) {
  state.scheduleGuidePage = normalizeConstructionScheduleGuidePage(state.scheduleGuidePage);
  if (!scheduleGuidePageAvailable(state.scheduleGuidePage, context)) {
    state.scheduleGuidePage = context.doc ? "import" : "model";
  }
  const pageIndex = constructionScheduleGuidePageIndex();
  const page = CONSTRUCTION_SCHEDULE_GUIDE_PAGES[pageIndex] || CONSTRUCTION_SCHEDULE_GUIDE_PAGES[0];
  const prevPage = CONSTRUCTION_SCHEDULE_GUIDE_PAGES[pageIndex - 1] || null;
  const nextPage = CONSTRUCTION_SCHEDULE_GUIDE_PAGES[pageIndex + 1] || null;
  document.querySelectorAll("[data-schedule-page]").forEach((section) => {
    const pages = String(section.getAttribute("data-schedule-page") || "").split(/\s+/).filter(Boolean);
    section.classList.toggle("hidden", !pages.includes(page.key));
  });
  [elements.scheduleGuideModel, elements.scheduleGuideImport, elements.scheduleGuideMapping, elements.scheduleGuideReview].forEach((step) => {
    const key = step?.dataset?.scheduleStep || "";
    step?.classList.toggle("current", key === page.key);
    step?.classList.toggle("disabled", !scheduleGuidePageAvailable(key, context));
  });
  if (elements.schedulePagerTitle) {
    elements.schedulePagerTitle.textContent = localizedDisplayName(page.title);
  }
  if (elements.schedulePagerNote) {
    elements.schedulePagerNote.textContent = localizeMixedText(page.note);
  }
  if (elements.schedulePrevStepButton) {
    elements.schedulePrevStepButton.disabled = !prevPage;
    elements.schedulePrevStepButton.textContent = prevPage ? text(`上一步：${prevPage.title}`, `Previous: ${localizedDisplayName(prevPage.title)}`) : text("上一步", "Previous");
  }
  if (elements.scheduleNextStepButton) {
    elements.scheduleNextStepButton.disabled = !nextPage || !scheduleGuidePageAvailable(nextPage.key, context);
    elements.scheduleNextStepButton.textContent = nextPage ? text(`下一步：${nextPage.title}`, `Next: ${localizedDisplayName(nextPage.title)}`) : text("完成", "Done");
  }
}

function renderConstructionWeeklyPanel() {
  const payload = state.scheduleWeeklyReport;
  if (!payload?.report) {
    elements.scheduleWeeklyBadge.textContent = text("未生成", "Not generated");
    elements.scheduleWeeklyPanel.innerHTML = `<div class="empty-card">${escapeHtml(text("选择数据日期后生成周报，包含 S 曲线、专业矩阵、本周未完成和下周计划。", "Generate a weekly report with S-curve, discipline matrix, unfinished work, and lookahead plan."))}</div>`;
    return;
  }
  const report = payload.report;
  elements.scheduleWeeklyBadge.textContent = `${report.weekStart} → ${report.weekEnd}`;
  elements.scheduleWeeklyPanel.innerHTML = `
    <div class="construction-schedule-weekly-grid">
      <div><span>计划进度</span><strong>${escapeHtml(`${report.projectProgress?.planPercent || 0}%`)}</strong></div>
      <div><span>实际进度</span><strong>${escapeHtml(`${report.projectProgress?.actualPercent || 0}%`)}</strong></div>
      <div><span>偏差</span><strong>${escapeHtml(`${report.projectProgress?.variance || 0}%`)}</strong></div>
      <div><span>S 曲线点</span><strong>${escapeHtml((payload.sCurve || []).length)}</strong></div>
    </div>
    <div class="construction-schedule-weekly-columns">
      <section>
        <strong>本周未完成</strong>
        ${(report.thisWeekPlannedUnfinished || []).slice(0, 8).map((item) => `<span>${escapeHtml(`${item.activityId} ${item.name} · ${item.percentComplete}%`)}</span>`).join("") || `<span>无</span>`}
      </section>
      <section>
        <strong>下阶段计划</strong>
        ${(report.nextWeekPlan || []).slice(0, 8).map((item) => `<span>${escapeHtml(`${item.activityId} ${item.name}`)}</span>`).join("") || `<span>无</span>`}
      </section>
      <section>
        <strong>专业矩阵</strong>
        ${(payload.disciplineMatrix || []).map((item) => `<span>${escapeHtml(`${item.discipline}: ${item.actualPercent}% / ${item.status}`)}</span>`).join("") || `<span>无</span>`}
      </section>
    </div>
  `;
}

function quantityTakeoffDocuments() {
  return state.documents
    .filter((doc) => isModelWorkspaceDocument(doc) && canPreviewDocument(doc))
    .sort((left, right) => compareBySortLocale(left.name, right.name));
}

function quantityDocumentReady(doc) {
  return Boolean(doc?.aps?.urn && apsTranslationStatus(doc) === "success");
}

function quantityApsConfigurationReady() {
  const system = currentApsConfiguration().system || createEmptyApsConfigurationState().system;
  return Boolean(system.enabled && system.status === "configured" && system.clientId && system.hasClientSecret);
}

function quantityApsConfigurationPrompt() {
  const system = currentApsConfiguration().system || createEmptyApsConfigurationState().system;
  if (!system.enabled || system.status === "disabled") {
    return text("APS 模型能力未启用，请到系统设置 / APS 配置开启并填写 Client ID、Client Secret。", "APS model services are disabled. Enable APS in System Settings / APS Configuration and enter Client ID plus Client Secret.");
  }
  if (system.status === "incomplete" || !system.clientId || !system.hasClientSecret) {
    return text("APS 配置尚未完整，模型应用需要 Client ID、Client Secret 和可用 Bucket。", "APS configuration is incomplete. Model applications require Client ID, Client Secret, and an available bucket.");
  }
  return "";
}

function seedQuantityDocumentSelection() {
  const docs = quantityTakeoffDocuments();
  if (state.quantityDocumentId && docs.some((doc) => doc.id === state.quantityDocumentId)) {
    return;
  }
  state.quantityDocumentId = "";
}

function csvInputValues(value) {
  return String(value || "")
    .split(/[,\n，、]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

const QUANTITY_FILTER_DEFINITIONS = [
  {
    key: "floors",
    field: "floor",
    label: text("系统/区域", "System/Area"),
    emptyLabel: text("不限系统/区域", "All systems/areas"),
    presetLabel: text("海淡系统预设", "Desalination presets"),
    presets: ["取水泵房", "预处理", "超滤系统", "RO 一段", "RO 二段", "能量回收", "加药间", "CIP 清洗", "产水箱", "浓盐水排放"],
  },
  {
    key: "disciplines",
    field: "discipline",
    label: text("专业", "Discipline"),
    emptyLabel: text("不限专业", "All disciplines"),
    presetLabel: text("专业预设", "Discipline presets"),
    presets: ["工艺", "管道", "设备", "电仪", "土建结构"],
  },
  {
    key: "elementTypes",
    field: "elementType",
    label: text("对象类型", "Object Type"),
    emptyLabel: text("不限对象类型", "All object types"),
    presetLabel: text("对象预设", "Object presets"),
    presets: ["取水泵", "高压泵", "RO膜壳", "压力容器", "管线", "阀门", "流量计", "压力表", "加药撬", "储罐"],
  },
  {
    key: "materials",
    field: "material",
    label: text("材质/规格", "Material/Spec"),
    emptyLabel: text("不限材质/规格", "All materials/specs"),
    presetLabel: text("材质规格预设", "Material/spec presets"),
    presets: ["316L", "2205", "HDPE", "UPVC", "FRP", "碳钢防腐", "DN100", "DN200", "DN300", "PN16"],
  },
];

function selectedQuantityFilterValues(key) {
  return csvInputValues(state.quantityFilters[key]);
}

function setQuantityFilterValues(key, values) {
  const uniqueValues = uniqueByNormalized(values.map((item) => String(item || "").trim()).filter(Boolean));
  state.quantityFilters[key] = uniqueValues.join(", ");
}

function uniqueByNormalized(values) {
  const seen = new Set();
  return (Array.isArray(values) ? values : []).filter((value) => {
    const normalized = String(value || "").trim().toLowerCase();
    if (!normalized || seen.has(normalized)) {
      return false;
    }
    seen.add(normalized);
    return true;
  });
}

function extractedQuantityFilterValues(definition) {
  const rows = [...state.quantitySnapshots, ...state.quantitySummaries];
  const blockedPrefixes = ["全部", "未指定"];
  return uniqueByNormalized(
    rows
      .map((item) => item?.[definition.field])
      .map((item) => String(item || "").trim())
      .filter((item) => item && !blockedPrefixes.some((prefix) => item.startsWith(prefix))),
  );
}

function quantityFilterOptions(definition) {
  return uniqueByNormalized([
    ...selectedQuantityFilterValues(definition.key),
    ...extractedQuantityFilterValues(definition),
    ...definition.presets,
  ]).slice(0, 18);
}

function handleQuantityFilterAction(button) {
  const key = button.dataset.quantityFilterKey || "";
  const action = button.dataset.quantityFilterAction || "";
  const definition = QUANTITY_FILTER_DEFINITIONS.find((item) => item.key === key);
  if (!definition) {
    return;
  }
  if (action === "clear") {
    state.quantityFilters[key] = "";
    renderModelAppsPanel();
    return;
  }
  if (action === "toggle") {
    const value = button.dataset.quantityFilterValue || "";
    const values = selectedQuantityFilterValues(key);
    const normalized = value.toLowerCase();
    const exists = values.some((item) => item.toLowerCase() === normalized);
    setQuantityFilterValues(
      key,
      exists ? values.filter((item) => item.toLowerCase() !== normalized) : [...values, value],
    );
    renderModelAppsPanel();
  }
}

function renderQuantityFilterBuilder() {
  if (!elements.quantityFilterBuilder) {
    return;
  }
  const disabled = state.quantityBusy;
  const filterCount = QUANTITY_FILTER_DEFINITIONS.reduce((sum, definition) => sum + selectedQuantityFilterValues(definition.key).length, 0);
  if (elements.quantityFilterBadge) {
    elements.quantityFilterBadge.textContent = filterCount ? text(`${filterCount} 项条件`, `${filterCount} filters`) : text("不限", "All");
    elements.quantityFilterBadge.className = `mini-pill ${filterCount ? "status-pill approved" : ""}`;
  }
  elements.quantityFilterBuilder.innerHTML = QUANTITY_FILTER_DEFINITIONS.map((definition) => {
    const selectedValues = selectedQuantityFilterValues(definition.key);
    const selected = new Set(selectedValues.map((item) => item.toLowerCase()));
    const extractedCount = extractedQuantityFilterValues(definition).length;
    const options = quantityFilterOptions(definition);
    return `
      <section class="quantity-filter-card" data-quantity-filter-key="${escapeHtml(definition.key)}">
        <div class="quantity-filter-card-head">
          <div>
            <strong>${escapeHtml(definition.label)}</strong>
            <span>${escapeHtml(extractedCount ? text(`来自已提取属性 ${extractedCount} 项`, `${extractedCount} extracted values`) : definition.presetLabel)}</span>
          </div>
          <button class="quantity-filter-clear" data-quantity-filter-action="clear" data-quantity-filter-key="${escapeHtml(definition.key)}" type="button" ${disabled || !selectedValues.length ? "disabled" : ""}>${escapeHtml(text("不限", "All"))}</button>
        </div>
        <div class="quantity-filter-options">
          ${options.map((value) => {
            const active = selected.has(value.toLowerCase());
            return `
              <button class="quantity-filter-option ${active ? "active" : ""}" data-quantity-filter-action="toggle" data-quantity-filter-key="${escapeHtml(definition.key)}" data-quantity-filter-value="${escapeHtml(value)}" type="button" ${disabled ? "disabled" : ""}>
                ${escapeHtml(value)}
              </button>
            `;
          }).join("")}
        </div>
      </section>
    `;
  }).join("");
}

function quantityGroupByFields() {
  return csvInputValues(state.quantityGroupPreset || "elementType,floor,discipline,material");
}

function quantityFilterPayload() {
  return {
    floors: csvInputValues(state.quantityFilters.floors),
    disciplines: csvInputValues(state.quantityFilters.disciplines),
    elementTypes: csvInputValues(state.quantityFilters.elementTypes),
    materials: csvInputValues(state.quantityFilters.materials),
  };
}

function quantityExtractionPayload() {
  const payload = {
    config: {
      groupBy: quantityGroupByFields(),
      filters: quantityFilterPayload(),
    },
  };
  if (state.quantityTemplateId) {
    payload.templateId = state.quantityTemplateId;
  }
  if (state.quantityFieldMode === "all") {
    payload.config.fields = "*";
  }
  return payload;
}

async function refreshQuantityTakeoffData({ renderAfter = false } = {}) {
  if (!state.authenticated) {
    return;
  }
  try {
    const homePayload = await fetchJson("/api/model-apps/quantity");
    state.quantityAllDocuments = Array.isArray(homePayload.documents) ? homePayload.documents : [];
    state.quantityAllTasks = Array.isArray(homePayload.tasks) ? homePayload.tasks : [];
    state.quantityTemplates = Array.isArray(homePayload.templates) ? homePayload.templates : state.quantityTemplates;
  } catch (error) {
    state.quantityMessage = error.message || text("工程量数据加载失败。", "Failed to load quantity takeoff data.");
  }
  seedQuantityDocumentSelection();
  if (!state.quantityDocumentId) {
    const docs = quantityTakeoffDocuments();
    state.quantityTasks = [];
    state.quantitySummaries = [];
    state.quantitySnapshots = [];
    state.quantityLatestTask = null;
    state.quantityMessage = docs.length
      ? text("请先在工程量统计页内选择一个模型，再配置口径并手动发起提取。", "Select a model inside Quantity Takeoff before configuring scope and manually submitting extraction.")
      : text("当前项目还没有可统计的模型文件。", "No model files available for quantity takeoff.");
    clearQuantityTakeoffPolling();
    if (renderAfter) {
      renderModelAppsPanel();
    }
    return;
  }
  try {
    const payload = await fetchJson(`/api/model-apps/quantity/documents/${encodeURIComponent(state.quantityDocumentId)}`);
    state.quantityTemplates = Array.isArray(payload.templates) ? payload.templates : [];
    state.quantityTasks = Array.isArray(payload.tasks) ? payload.tasks : [];
    state.quantityAllTasks = mergeQuantityTasks(state.quantityAllTasks, state.quantityTasks);
    state.quantitySummaries = Array.isArray(payload.summaries) ? payload.summaries : [];
    state.quantitySnapshots = Array.isArray(payload.snapshots) ? payload.snapshots : [];
    state.quantityLatestTask = payload.latestTask || null;
    state.quantitySelectedSummaryIndex = Math.min(state.quantitySelectedSummaryIndex, Math.max(0, state.quantitySummaries.length - 1));
    if (!state.quantityTemplateId || !state.quantityTemplates.some((template) => template.id === state.quantityTemplateId)) {
      state.quantityTemplateId = state.quantityTemplates[0]?.id || "";
    }
    seedQuantityCompareSelection();
    state.quantityMessage = "";
  } catch (error) {
    state.quantityMessage = error.message || text("工程量数据加载失败。", "Failed to load quantity takeoff data.");
  }
  if (renderAfter) {
    renderModelAppsPanel();
  }
  ensureQuantityTakeoffPolling();
}

function seedQuantityCompareSelection() {
  const succeeded = quantityCompletedCompareTasks();
  if (!state.quantityCompareRightTaskId || !succeeded.some((task) => task.id === state.quantityCompareRightTaskId)) {
    state.quantityCompareRightTaskId = succeeded[0]?.id || "";
  }
  if (!state.quantityCompareLeftTaskId || !succeeded.some((task) => task.id === state.quantityCompareLeftTaskId)) {
    state.quantityCompareLeftTaskId = succeeded[1]?.id || succeeded[0]?.id || "";
  }
}

function mergeQuantityTasks(baseTasks, nextTasks) {
  const next = Array.isArray(nextTasks) ? nextTasks : [];
  const nextIds = new Set(next.map((task) => task.id));
  return [...next, ...(Array.isArray(baseTasks) ? baseTasks : []).filter((task) => !nextIds.has(task.id))];
}

function quantityCompletedCompareTasks() {
  return uniqueByNormalized([...(state.quantityAllTasks || []), ...(state.quantityTasks || [])].filter((task) => task.status === "succeeded").map((task) => task.id))
    .map((id) => [...(state.quantityAllTasks || []), ...(state.quantityTasks || [])].find((task) => task.id === id))
    .filter(Boolean)
    .sort((left, right) => (Date.parse(right.completedAt || right.updatedAt || right.createdAt || "") || 0) - (Date.parse(left.completedAt || left.updatedAt || left.createdAt || "") || 0));
}

function quantityActiveTask() {
  return state.quantityTasks.find((task) => ["queued", "running"].includes(task.status)) || null;
}

function clearQuantityTakeoffPolling() {
  if (!quantityTakeoffPollTimer) {
    return;
  }
  window.clearTimeout(quantityTakeoffPollTimer);
  quantityTakeoffPollTimer = 0;
}

function ensureQuantityTakeoffPolling() {
  clearQuantityTakeoffPolling();
  if (
    !state.authenticated ||
    state.currentView !== "model-apps" ||
    normalizeModelAppTool(state.modelAppTool) !== "quantity" ||
    !quantityActiveTask()
  ) {
    return;
  }
  quantityTakeoffPollTimer = window.setTimeout(async () => {
    quantityTakeoffPollTimer = 0;
    await refreshQuantityTakeoffData({ renderAfter: true });
  }, QUANTITY_TAKEOFF_POLL_INTERVAL_MS);
}

async function scanQuantityPropertyDictionary() {
  const doc = documentById(state.quantityDocumentId);
  if (!doc) {
    showAlert(text("请选择要扫描字段的模型文件。", "Select a model before scanning fields."));
    return;
  }
  if (!quantityApsConfigurationReady()) {
    showAlert(quantityApsConfigurationPrompt());
    return;
  }
  if (!quantityDocumentReady(doc)) {
    showAlert(text("该模型还没有完成 APS 转换，暂不能扫描属性字段。", "This model is not ready in APS yet."));
    return;
  }
  state.quantityBusy = true;
  state.quantityMessage = text("正在扫描模型属性字典…", "Scanning model property dictionary...");
  renderModelAppsPanel();
  try {
    const payload = await postJson(
      `/api/model-apps/quantity/documents/${encodeURIComponent(doc.id)}/property-dictionary`,
      quantityExtractionPayload(),
    );
    state.quantityPropertyDictionary = payload.dictionary || null;
    state.quantityMessage = text("字段覆盖率扫描完成，可据此调整模板或筛选条件。", "Field coverage scan completed; adjust the template or filters if needed.");
  } catch (error) {
    state.quantityMessage = error.message || text("字段覆盖率扫描失败。", "Field coverage scan failed.");
    showAlert(state.quantityMessage);
  } finally {
    state.quantityBusy = false;
    renderModelAppsPanel();
  }
}

async function runQuantityExtractionFromSelection() {
  const doc = documentById(state.quantityDocumentId);
  if (!doc) {
    showAlert(text("请选择要统计的模型文件。", "Select a model file for quantity takeoff."));
    return;
  }
  if (!quantityApsConfigurationReady()) {
    showAlert(quantityApsConfigurationPrompt());
    return;
  }
  if (!quantityDocumentReady(doc)) {
    showAlert(text("该模型还没有完成 APS 转换，暂不能提取工程量。", "This model is not ready in APS yet."));
    return;
  }
  if (quantityActiveTask()) {
    showAlert(text("当前模型已有工程量提取任务在队列中，请等待完成后再发起。", "A quantity extraction task is already active for this model."));
    return;
  }
  state.quantityBusy = true;
  state.quantityMessage = text("已提交后台属性提取任务…", "Queued property extraction in the background...");
  renderModelAppsPanel();
  try {
    const payload = await postJson(
      `/api/model-apps/quantity/documents/${encodeURIComponent(doc.id)}/extract`,
      {
        ...quantityExtractionPayload(),
        source: "manual",
      },
    );
    const taskId = payload.task?.id || "";
    if (taskId) {
      state.quantityTasks = [payload.task, ...state.quantityTasks.filter((task) => task.id !== taskId)];
      state.quantityLatestTask = payload.task;
      state.quantityMessage = payload.reused
        ? text("已有工程量提取任务正在运行，本次操作已复用当前任务。", "An extraction task is already active; this request reused it.")
        : text("工程量提取任务已提交，后台完成后会刷新汇总结果。", "Quantity extraction has been queued. Results will refresh when the background task completes.");
      ensureQuantityTakeoffPolling();
    }
    await refreshDocuments();
    await refreshQuantityTakeoffData({ renderAfter: false });
  } catch (error) {
    state.quantityMessage = error.message || text("工程量提取失败。", "Quantity extraction failed.");
  } finally {
    state.quantityBusy = false;
    render();
  }
}

async function exportLatestQuantityTakeoff() {
  const task = state.quantityLatestTask || state.quantityTasks.find((item) => item.status === "succeeded");
  if (!state.quantityDocumentId || !task) {
    showAlert(text("当前还没有可导出的工程量结果。", "There is no quantity result to export yet."));
    return;
  }
  state.quantityBusy = true;
  state.quantityMessage = text("正在生成工程量 Excel…", "Generating quantity workbook...");
  renderModelAppsPanel();
  try {
    const payload = await postJson(`/api/model-apps/quantity/documents/${encodeURIComponent(state.quantityDocumentId)}/export`, {
      taskId: task.id,
      language: currentLanguage(),
    });
    state.quantityMessage = text("工程量 Excel 已生成。", "Quantity workbook is ready.");
    if (payload.downloadUrl) {
      window.open(payload.downloadUrl, "_blank", "noopener");
    }
  } catch (error) {
    state.quantityMessage = error.message || text("工程量导出失败。", "Quantity export failed.");
  } finally {
    state.quantityBusy = false;
    renderModelAppsPanel();
  }
}

async function saveCurrentQuantityTemplate() {
  const name = await promptAction(
    text("请输入工程量模板名称", "Enter a quantity template name"),
    text("工程量统计模板", "Quantity Takeoff Template"),
    { label: text("模板名称", "Template Name") },
  );
  if (name === null || !String(name).trim()) {
    return;
  }
  state.quantityBusy = true;
  state.quantityMessage = text("正在保存工程量模板…", "Saving quantity template...");
  renderModelAppsPanel();
  try {
    const payload = await postJson("/api/model-apps/quantity/templates", {
      name: String(name).trim(),
      description: text("从模型应用工程量统计界面保存。", "Saved from the quantity takeoff workbench."),
      config: quantityExtractionPayload().config,
    });
    if (payload.template) {
      state.quantityTemplates = [
        payload.template,
        ...state.quantityTemplates.filter((template) => template.id !== payload.template.id),
      ];
      state.quantityTemplateId = payload.template.id;
    }
    state.quantityMessage = text("工程量模板已保存，可在新模型上一键套用。", "Quantity template saved for reuse on new models.");
  } catch (error) {
    state.quantityMessage = error.message || text("工程量模板保存失败。", "Failed to save quantity template.");
  } finally {
    state.quantityBusy = false;
    renderModelAppsPanel();
  }
}

function quantityTaskById(taskId) {
  return [...(state.quantityTasks || []), ...(state.quantityAllTasks || [])].find((task) => task.id === taskId) || null;
}

async function handleQuantityTaskAction(action, taskId) {
  const task = quantityTaskById(taskId);
  if (!task) {
    return;
  }
  if (action === "cancel") {
    state.quantityBusy = true;
    state.quantityMessage = text("正在取消工程量提取任务…", "Canceling quantity extraction task...");
    renderModelAppsPanel();
    try {
      const payload = await postJson(`/api/model-apps/quantity/documents/${encodeURIComponent(task.documentId)}/tasks/${encodeURIComponent(task.id)}/cancel`, {
        reason: text("用户在工程量统计页面取消", "Canceled from quantity takeoff workbench"),
      });
      if (payload.task) {
        state.quantityTasks = state.quantityTasks.map((item) => (item.id === payload.task.id ? payload.task : item));
        state.quantityAllTasks = mergeQuantityTasks(state.quantityAllTasks, [payload.task]);
        state.quantityLatestTask = payload.task;
      }
      state.quantityMessage = text("工程量提取任务已取消。", "Quantity extraction task canceled.");
    } catch (error) {
      state.quantityMessage = error.message || text("取消工程量任务失败。", "Failed to cancel quantity task.");
      showAlert(state.quantityMessage);
    } finally {
      state.quantityBusy = false;
      await refreshQuantityTakeoffData({ renderAfter: true });
    }
    return;
  }
  if (action === "retry") {
    state.quantityBusy = true;
    state.quantityMessage = text("正在重新发起工程量提取…", "Retrying quantity extraction...");
    renderModelAppsPanel();
    try {
      const payload = await postJson(`/api/model-apps/quantity/documents/${encodeURIComponent(task.documentId)}/tasks/${encodeURIComponent(task.id)}/retry`, {});
      if (payload.task) {
        state.quantityTasks = [payload.task, ...state.quantityTasks.filter((item) => item.id !== payload.task.id)];
        state.quantityAllTasks = mergeQuantityTasks(state.quantityAllTasks, [payload.task]);
        state.quantityLatestTask = payload.task;
      }
      state.quantityMessage = text("工程量提取已重新进入队列。", "Quantity extraction has been re-queued.");
      ensureQuantityTakeoffPolling();
    } catch (error) {
      state.quantityMessage = error.message || text("重跑工程量任务失败。", "Failed to retry quantity task.");
      showAlert(state.quantityMessage);
    } finally {
      state.quantityBusy = false;
      await refreshQuantityTakeoffData({ renderAfter: true });
    }
  }
}

async function compareQuantityTasksFromSelection() {
  if (!state.quantityCompareLeftTaskId || !state.quantityCompareRightTaskId) {
    showAlert(text("请选择两个已完成的工程量任务。", "Select two completed quantity tasks."));
    return;
  }
  state.quantityBusy = true;
  state.quantityMessage = text("正在对比两个版本的工程量…", "Comparing quantity results...");
  renderModelAppsPanel();
  try {
    const payload = await postJson("/api/model-apps/quantity/compare", {
      leftTaskId: state.quantityCompareLeftTaskId,
      rightTaskId: state.quantityCompareRightTaskId,
    });
    state.quantityCompareDiff = Array.isArray(payload.diff) ? payload.diff : [];
    state.quantityMessage = text("工程量对比已完成。", "Quantity comparison completed.");
  } catch (error) {
    state.quantityMessage = error.message || text("工程量对比失败。", "Quantity comparison failed.");
  } finally {
    state.quantityBusy = false;
    renderModelAppsPanel();
  }
}

function quantityTaskLabel(task) {
  if (!task) {
    return text("未提取", "No extraction");
  }
  return `${task.version || "V1"} · ${quantityStatusLabel(task.status)} · ${formatDateTime(task.completedAt || task.updatedAt || task.createdAt)}`;
}

function quantityStatusLabel(status) {
  return {
    queued: text("排队中", "Queued"),
    running: text("提取中", "Running"),
    succeeded: text("已完成", "Done"),
    failed: text("失败", "Failed"),
    canceled: text("已取消", "Canceled"),
  }[status] || status || text("未知", "Unknown");
}

function quantityStatusTone(status) {
  if (status === "succeeded") return "approved";
  if (status === "failed") return "rejected";
  if (status === "canceled") return "neutral";
  if (status === "running" || status === "queued") return "in_review";
  return "neutral";
}

function selectedQuantitySummary() {
  return state.quantitySummaries[state.quantitySelectedSummaryIndex] || state.quantitySummaries[0] || null;
}

function quantityMetricTotal(metricKey) {
  return state.quantitySummaries.reduce((sum, item) => sum + Number(item.metrics?.[metricKey]?.value || 0), 0);
}

function selectedQuantitySnapshots() {
  const summary = selectedQuantitySummary();
  if (!summary || !Array.isArray(summary.dbIds) || !summary.dbIds.length) {
    return state.quantitySnapshots.slice(0, 80);
  }
  const dbIds = new Set(summary.dbIds.map((item) => Number(item)));
  return state.quantitySnapshots.filter((snapshot) => dbIds.has(Number(snapshot.dbId))).slice(0, 120);
}

function modelClashHeatmapOptions() {
  return state.modelClashHeatmaps.map((heatmap) => {
    const run = state.modelClashRuns.find((item) => item.id === heatmap.clashTaskId);
    const clashCount = heatmap.summary?.clashCount ?? run?.summary?.clashCount ?? 0;
    return {
      value: heatmap.id,
      label: `${formatDateTime(heatmap.createdAt)} · ${clashCount} 项 · ${heatmap.gridSize}m`,
    };
  });
}

function modelClashRecordById(recordId) {
  return state.modelClashRecords.find((record) => record.id === recordId) || null;
}

function modelClashFloorSliceAllowsCell(cell) {
  const raw = String(state.modelClashHeatmapFloorSlice || "").trim();
  if (!raw) {
    return true;
  }
  const bbox = cell.bbox || {};
  const minZ = Number(bbox.min?.[2] ?? cell.z ?? 0);
  const maxZ = Number(bbox.max?.[2] ?? minZ);
  if (raw.includes("-")) {
    const [left, right] = raw.split("-").map((item) => Number(item.trim()));
    if (!Number.isFinite(left) || !Number.isFinite(right)) {
      return true;
    }
    const sliceMin = Math.min(left, right);
    const sliceMax = Math.max(left, right);
    return maxZ >= sliceMin && minZ <= sliceMax;
  }
  const z = Number(raw);
  return !Number.isFinite(z) || (z >= minZ && z <= maxZ);
}

function filteredModelClashHeatmapCells() {
  const cells = Array.isArray(state.modelClashHeatmapDetail?.cells) ? state.modelClashHeatmapDetail.cells : [];
  return cells.filter(modelClashFloorSliceAllowsCell);
}

function renderModelClashHeatmapCanvas(cells) {
  if (!elements.modelClashHeatmapCanvas) {
    return;
  }
  if (!state.modelClashHeatmapVisible) {
    elements.modelClashHeatmapCanvas.innerHTML = `<div class="empty-card">${escapeHtml(text("热力图层已关闭，可随时重新打开。", "Heatmap layer is hidden and can be turned back on."))}</div>`;
    return;
  }
  if (!cells.length) {
    elements.modelClashHeatmapCanvas.innerHTML = `<div class="empty-card">${escapeHtml(text("当前筛选条件下没有热力网格。", "No heatmap cells match the current filters."))}</div>`;
    return;
  }
  const minX = Math.min(...cells.map((cell) => Number(cell.bbox?.min?.[0] ?? cell.x ?? 0)));
  const maxX = Math.max(...cells.map((cell) => Number(cell.bbox?.max?.[0] ?? (Number(cell.x || 0) + Number(cell.gridSize || 1)))));
  const minY = Math.min(...cells.map((cell) => Number(cell.bbox?.min?.[1] ?? cell.y ?? 0)));
  const maxY = Math.max(...cells.map((cell) => Number(cell.bbox?.max?.[1] ?? (Number(cell.y || 0) + Number(cell.gridSize || 1)))));
  const spanX = Math.max(1, maxX - minX);
  const spanY = Math.max(1, maxY - minY);
  const opacity = Math.max(0.15, Math.min(0.8, Number(state.modelClashHeatmapOpacity || 0.45) || 0.45));
  elements.modelClashHeatmapCanvas.innerHTML = `
    <div class="model-clash-heatmap-plane">
      ${cells.map((cell) => {
        const cellMinX = Number(cell.bbox?.min?.[0] ?? cell.x ?? 0);
        const cellMaxX = Number(cell.bbox?.max?.[0] ?? (cellMinX + Number(cell.gridSize || 1)));
        const cellMinY = Number(cell.bbox?.min?.[1] ?? cell.y ?? 0);
        const cellMaxY = Number(cell.bbox?.max?.[1] ?? (cellMinY + Number(cell.gridSize || 1)));
        const left = ((cellMinX - minX) / spanX) * 100;
        const width = Math.max(3, ((cellMaxX - cellMinX) / spanX) * 100);
        const top = 100 - ((cellMaxY - minY) / spanY) * 100;
        const height = Math.max(3, ((cellMaxY - cellMinY) / spanY) * 100);
        return `
          <button
            class="model-clash-heatmap-cell"
            type="button"
            title="${escapeHtml(text(`${cell.disciplinePair} · ${cell.density} 项`, `${cell.disciplinePair} · ${cell.density} items`))}"
            style="left:${left.toFixed(2)}%;top:${top.toFixed(2)}%;width:${width.toFixed(2)}%;height:${height.toFixed(2)}%;background:${escapeHtml(cell.color || "#237df0")};opacity:${opacity};"
          >
            <span>${escapeHtml(cell.density)}</span>
          </button>
        `;
      }).join("")}
    </div>
  `;
}

function renderModelClashHotspots(hotspots) {
  if (!elements.modelClashHotspotList) {
    return;
  }
  elements.modelClashHotspotBadge.textContent = hotspots.length ? `Top ${hotspots.length}` : "Top 0";
  elements.modelClashHotspotList.innerHTML = hotspots.length
    ? hotspots.map((hotspot, index) => {
        const bbox = hotspot.bbox || {};
        const firstRecordId = hotspot.recordIds?.[0] || "";
        return `
          <article class="model-clash-hotspot-row">
            <span class="model-clash-hotspot-rank">${index + 1}</span>
            <div>
              <strong>${escapeHtml(text(`${hotspot.clashCount || 0} 项碰撞 · ${hotspot.openIssueCount || 0} 未关闭`, `${hotspot.clashCount || 0} clashes · ${hotspot.openIssueCount || 0} open`))}</strong>
              <span>${escapeHtml((hotspot.disciplinePairs || []).join(" / ") || text("未指定专业对", "No discipline pair"))}</span>
              <small>${escapeHtml(`min ${JSON.stringify(bbox.min || [])} / max ${JSON.stringify(bbox.max || [])}`)}</small>
            </div>
            <button class="ghost-button compact-button" data-model-clash-hotspot-record="${escapeHtml(firstRecordId)}" type="button" ${firstRecordId ? "" : "disabled"}>${escapeHtml(text("定位", "Locate"))}</button>
          </article>
        `;
      }).join("")
    : `<div class="empty-card">${escapeHtml(text("暂无热点区域。", "No hotspot areas yet."))}</div>`;
}

function renderModelClashMatrix(matrix) {
  if (!elements.modelClashMatrixTable) {
    return;
  }
  const disciplines = Array.isArray(matrix?.disciplines) ? matrix.disciplines : [];
  elements.modelClashMatrixBadge.textContent = text(`${disciplines.length} 专业`, `${disciplines.length} disciplines`);
  if (!disciplines.length) {
    elements.modelClashMatrixTable.innerHTML = `<div class="empty-card">${escapeHtml(text("检测后会在这里显示专业之间的碰撞数量矩阵。", "The discipline clash matrix appears after detection."))}</div>`;
    return;
  }
  const values = disciplines.flatMap((row) => disciplines.map((col) => Number(matrix.counts?.[row]?.[col] || 0)));
  const maxValue = Math.max(1, ...values);
  elements.modelClashMatrixTable.innerHTML = `
    <table>
      <thead>
        <tr>
          <th></th>
          ${disciplines.map((discipline) => `<th>${escapeHtml(modelClashDisciplineLabel(discipline))}</th>`).join("")}
        </tr>
      </thead>
      <tbody>
        ${disciplines.map((row) => `
          <tr>
            <th>${escapeHtml(modelClashDisciplineLabel(row))}</th>
            ${disciplines.map((col) => {
              const value = matrix.counts?.[row]?.[col];
              const intensity = value ? Math.min(1, Number(value) / maxValue) : 0;
              const pair = [row, col].sort().join(":");
              return `
                <td>
                  ${row === col
                    ? `<span class="model-clash-matrix-empty">—</span>`
                    : `<button data-model-clash-matrix-pair="${escapeHtml(pair)}" type="button" style="--matrix-alpha:${(0.08 + intensity * 0.5).toFixed(2)}">${escapeHtml(value || 0)}</button>`}
                </td>
              `;
            }).join("")}
          </tr>
        `).join("")}
      </tbody>
    </table>
  `;
}

function heatmapSummaryById(heatmapId) {
  const heatmap = state.modelClashHeatmaps.find((item) => item.id === heatmapId);
  return heatmap?.summary || {};
}

function renderModelClashTrendPanel() {
  if (!elements.modelClashTrendTable) {
    return;
  }
  const options = modelClashHeatmapOptions();
  if (!state.modelClashTrendRightId || !state.modelClashHeatmaps.some((item) => item.id === state.modelClashTrendRightId)) {
    state.modelClashTrendRightId = state.modelClashHeatmaps[0]?.id || "";
  }
  if (!state.modelClashTrendLeftId || !state.modelClashHeatmaps.some((item) => item.id === state.modelClashTrendLeftId)) {
    state.modelClashTrendLeftId = state.modelClashHeatmaps[1]?.id || state.modelClashHeatmaps[0]?.id || "";
  }
  setSelectOptions(elements.modelClashTrendLeftSelect, options, state.modelClashTrendLeftId);
  setSelectOptions(elements.modelClashTrendRightSelect, options, state.modelClashTrendRightId);
  if (!state.modelClashTrendLeftId || !state.modelClashTrendRightId || state.modelClashTrendLeftId === state.modelClashTrendRightId) {
    elements.modelClashTrendBadge.textContent = text("选择两个版本", "Select two versions");
    elements.modelClashTrendTable.innerHTML = `<div class="empty-card">${escapeHtml(text("选择两个热力图版本后，对比碰撞总数、热点区域和最密集区域变化。", "Select two heatmap versions to compare clash totals, hotspots, and densest areas."))}</div>`;
    return;
  }
  const left = heatmapSummaryById(state.modelClashTrendLeftId);
  const right = heatmapSummaryById(state.modelClashTrendRightId);
  const rows = [
    [text("碰撞总数", "Total clashes"), left.clashCount || 0, right.clashCount || 0],
    [text("热点区域数", "Hotspot areas"), left.hotspotCount || 0, right.hotspotCount || 0],
    [text("最密集区域碰撞数", "Densest area"), left.topHotspotClashCount || 0, right.topHotspotClashCount || 0],
    [text("新增碰撞数", "New clashes"), 0, Math.max(0, Number(right.clashCount || 0) - Number(left.clashCount || 0))],
  ];
  elements.modelClashTrendBadge.textContent = text("已对比", "Compared");
  elements.modelClashTrendTable.innerHTML = `
    <table>
      <thead><tr><th>指标</th><th>版本 A</th><th>版本 B</th><th>变化</th></tr></thead>
      <tbody>
        ${rows.map(([label, leftValue, rightValue]) => {
          const delta = Number(rightValue || 0) - Number(leftValue || 0);
          return `
            <tr class="${delta > 0 ? "hotter" : delta < 0 ? "cooler" : ""}">
              <td>${escapeHtml(label)}</td>
              <td>${escapeHtml(leftValue)}</td>
              <td>${escapeHtml(rightValue)}</td>
              <td>${escapeHtml(`${delta > 0 ? "+" : ""}${delta}`)}</td>
            </tr>
          `;
        }).join("")}
      </tbody>
    </table>
  `;
}

function renderModelClashHeatmapPanel() {
  if (!elements.modelClashHeatmapSelect) {
    return;
  }
  const options = modelClashHeatmapOptions();
  setSelectOptions(elements.modelClashHeatmapSelect, options, state.modelClashHeatmapId);
  if (!options.length) {
    elements.modelClashHeatmapSelect.innerHTML = `<option value="">${escapeHtml(text("暂无热力图", "No heatmap"))}</option>`;
  }
  syncInputValue(elements.modelClashHeatmapPairSelect, state.modelClashHeatmapPair);
  syncInputValue(elements.modelClashHeatmapStatusSelect, state.modelClashHeatmapStatus);
  syncInputValue(elements.modelClashHeatmapMinVolumeInput, state.modelClashHeatmapMinVolume);
  syncInputValue(elements.modelClashHeatmapFloorInput, state.modelClashHeatmapFloorSlice);
  syncInputValue(elements.modelClashHeatmapOpacityInput, state.modelClashHeatmapOpacity);
  elements.modelClashHeatmapVisibleToggle.checked = state.modelClashHeatmapVisible;
  const detail = state.modelClashHeatmapDetail;
  const summary = detail?.summary || {};
  elements.modelClashHeatmapBadge.textContent = detail?.task
    ? `${summary.cellCount || 0} 网格 · ${summary.openClashCount || 0} 未关闭`
    : text("未生成", "Not generated");
  const cells = filteredModelClashHeatmapCells();
  renderModelClashHeatmapCanvas(cells);
  renderModelClashHotspots(Array.isArray(detail?.hotspots) ? detail.hotspots : []);
  renderModelClashMatrix(detail?.matrix || null);
  renderModelClashTrendPanel();
  const hasHeatmap = Boolean(state.modelClashHeatmapId);
  [
    elements.modelClashExportSnapshotButton,
    elements.modelClashExportMatrixButton,
    elements.modelClashExportHotspotsButton,
    elements.modelClashExportPackageButton,
    elements.modelClashOpenHeatmapViewerButton,
  ].forEach((button) => {
    if (button) {
      button.disabled = state.modelClashBusy || !hasHeatmap;
    }
  });
}

function renderModelAppsPanel() {
  if (!elements.modelAppsPanel) {
    return;
  }
  const activeTool = normalizeModelAppTool(state.modelAppTool);
  state.modelAppTool = activeTool;
  syncApplicationPageChrome("model", activeTool);
  const features = modelAppFeatures();
  elements.modelAppToolButtons.forEach((button) => {
    const tool = normalizeModelAppTool(button.dataset.modelAppTool);
    const feature = features.find((item) => item.id === tool);
    if (feature && button.classList.contains("model-app-entry-card")) {
      button.innerHTML = `
        <span class="model-app-entry-index">${escapeHtml(feature.index)}</span>
        <strong>${escapeHtml(feature.title)}</strong>
        <span>${escapeHtml(feature.subtitle)}</span>
        <small>${escapeHtml(feature.description)}</small>
      `;
    } else if (tool === "home") {
      button.textContent = text("返回模型应用", "Back to Model Apps");
    }
    button.classList.toggle("active", tool === activeTool);
    button.disabled = false;
    button.classList.remove("disabled");
    button.title = "";
  });
  Array.from(elements.modelAppsPanel.querySelectorAll("[data-model-app-view]")).forEach((section) => {
    section.classList.toggle("hidden", section.dataset.modelAppView !== activeTool);
  });
  renderQuantityTakeoffPanel(activeTool);
  renderModelHealthWorkbench(activeTool);
  renderModelDiffWorkbench(activeTool);
  renderConstructionScheduleWorkbench(activeTool);
  const docs = modelClashDocuments();
  pruneModelClashSelection();
  const selected = new Set(state.modelClashSelectedIds);
  const counts = modelClashStatusCounts();
  const activeBadgeLabel = {
    home: text("5 个模型应用入口", "5 Model App Entries"),
    quantity: text("工程量统计", "Quantity Takeoff"),
    health: text("健康度检查", "Health Check"),
    diff: text("版本差异", "Version Diff"),
    schedule: text("4D 进度", "4D Schedule"),
  }[activeTool];
  elements.modelClashStatusBadge.textContent = activeTool === "clash"
    ? text(`${counts.open} 项未闭环`, `${counts.open} open`)
    : activeBadgeLabel || text("模型应用", "Model Apps");
  elements.modelClashStatusBadge.className = `mini-pill ${activeTool === "clash" && counts.open ? "signal-pill open" : ""}`;
  syncInputValue(elements.modelClashToleranceInput, state.modelClashTolerance);
  if (elements.modelClashDisciplinePairSelect.value !== state.modelClashDisciplinePair) {
    elements.modelClashDisciplinePairSelect.value = state.modelClashDisciplinePair;
  }
  if (elements.modelClashHeatmapGridSizeSelect && elements.modelClashHeatmapGridSizeSelect.value !== state.modelClashHeatmapGridSize) {
    elements.modelClashHeatmapGridSizeSelect.value = state.modelClashHeatmapGridSize;
  }
  elements.modelClashIgnoreSameToggle.checked = state.modelClashIgnoreSameDiscipline;
  elements.modelClashRunButton.disabled = state.modelClashBusy || !state.modelClashSelectedIds.length;
  elements.modelClashRefreshButton.disabled = state.modelClashBusy;
  elements.modelClashSelectionBadge.textContent = `${selected.size} / ${docs.length}`;

  elements.modelClashModelList.innerHTML = docs.length
    ? docs.map((doc) => {
        const ready = modelClashDocumentReady(doc);
        const status = doc.aps?.translationStatus || "idle";
        const geometryCount = Array.isArray(doc.aps?.geometryIndex) ? doc.aps.geometryIndex.length : 0;
        const readyLabel = geometryCount ? `${geometryCount} 构件` : text("检测前提取几何", "Extract on run");
        return `
          <label class="model-clash-model-row ${selected.has(doc.id) ? "selected" : ""} ${ready ? "" : "disabled"}">
            <input type="checkbox" data-model-clash-doc="${escapeHtml(doc.id)}" ${selected.has(doc.id) ? "checked" : ""} ${ready ? "" : "disabled"} />
            <span class="model-clash-model-main">
              <strong>${escapeHtml(doc.name)}</strong>
              <span>${escapeHtml(doc.aps?.urn || text("未配置 URN", "No URN"))}</span>
            </span>
            <span class="status-pill ${ready ? "approved" : "neutral"}">${escapeHtml(ready ? readyLabel : status)}</span>
          </label>
        `;
      }).join("")
    : `<div class="empty-card">${escapeHtml(text("当前项目还没有可检测的模型。", "No model files available."))}</div>`;

  const latestRun = state.modelClashRuns[0] || null;
  elements.modelClashRunBadge.textContent = latestRun
    ? `${latestRun.status} · ${formatDateTime(latestRun.createdAt)}`
    : text("未运行", "Not run");
  const summary = latestRun?.summary || {};
  elements.modelClashSummaryGrid.innerHTML = renderManagerSummaryCards([
    { label: text("总记录", "Records"), value: String(counts.total) },
    { label: text("未闭环", "Open"), value: String(counts.open || 0) },
    { label: text("构件对", "Pairs"), value: String(summary.candidatePairs || 0) },
    { label: text("本次碰撞", "Clashes"), value: String(summary.clashCount || latestRun?.recordIds?.length || 0) },
  ]);

  const records = [...state.modelClashRecords]
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))
    .slice(0, 40);
  elements.modelClashRecordList.innerHTML = records.length
    ? records.map(renderModelClashRecordRow).join("")
    : `<div class="empty-card">${escapeHtml(text("还没有碰撞记录。", "No clash records yet."))}</div>`;
  renderModelClashHeatmapPanel();
  elements.modelClashMessage.textContent = state.modelClashMessage;
}

function renderQuantityTakeoffPanel(activeTool = normalizeModelAppTool(state.modelAppTool)) {
  if (!elements.quantityDocumentSelect) {
    return;
  }

  const docs = quantityTakeoffDocuments();
  seedQuantityDocumentSelection();
  renderQuantityModelPicker();
  setSelectOptions(
    elements.quantityDocumentSelect,
    [
      ...(docs.length
        ? [{ value: "", label: text("请选择工程量统计模型", "Select a quantity takeoff model"), disabled: true }]
        : []),
      ...docs.map((doc) => ({
      value: doc.id,
      label: `${doc.name}${quantityDocumentReady(doc) ? "" : text(" · 未就绪", " · not ready")}`,
      })),
    ],
    state.quantityDocumentId,
  );
  if (!docs.length) {
    elements.quantityDocumentSelect.innerHTML = `<option value="">${escapeHtml(text("暂无可统计模型", "No takeoff-ready models"))}</option>`;
  }
  setSelectOptions(
    elements.quantityTemplateSelect,
    state.quantityTemplates.map((template) => ({
      value: template.id,
      label: template.name,
    })),
    state.quantityTemplateId,
  );
  if (!state.quantityTemplates.length) {
    elements.quantityTemplateSelect.innerHTML = `<option value="">${escapeHtml(text("默认模板加载中", "Loading templates"))}</option>`;
  }
  syncInputValue(elements.quantityFieldModeSelect, state.quantityFieldMode);
  syncInputValue(elements.quantityGroupPresetSelect, state.quantityGroupPreset);
  renderQuantityFilterBuilder();

  const doc = documentById(state.quantityDocumentId);
  const ready = quantityDocumentReady(doc);
  const apsReady = quantityApsConfigurationReady();
  const canExtract = Boolean(apsReady && ready);
  const latestTask = state.quantityLatestTask || state.quantityTasks[0] || null;
  const succeededTasks = state.quantityTasks.filter((task) => task.status === "succeeded");
  const activeTask = quantityActiveTask();
  renderQuantityGuide(doc, latestTask, ready, apsReady);
  renderQuantityPreflight(doc, ready, activeTask, apsReady);
  renderQuantityLaunchSummary(doc, ready, latestTask, activeTask, apsReady);
  renderQuantityPropertyDictionaryPanel();
  elements.quantityDocumentSelect.disabled = state.quantityBusy || !docs.length;
  elements.quantityTemplateSelect.disabled = state.quantityBusy || state.quantityFieldMode === "all" || !state.quantityTemplates.length;
  elements.quantityFieldModeSelect.disabled = state.quantityBusy;
  elements.quantityGroupPresetSelect.disabled = state.quantityBusy;
  elements.quantityRefreshButton.disabled = state.quantityBusy || !state.quantityDocumentId;
  elements.quantityScanFieldsButton.disabled = state.quantityBusy || !canExtract;
  elements.quantityExtractButton.disabled = state.quantityBusy || !canExtract || Boolean(activeTask);
  elements.quantityExtractButton.textContent = activeTask
    ? text("等待当前任务", "Waiting for task")
    : !apsReady
      ? text("先配置 APS", "Configure APS first")
    : !doc
      ? text("选择模型后提取", "Select model")
      : !ready
        ? text("模型未就绪", "Model not ready")
        : text("确认并提交提取", "Submit extraction");
  elements.quantitySaveTemplateButton.disabled = state.quantityBusy || !state.quantityDocumentId;
  elements.quantityExportButton.disabled = state.quantityBusy || !succeededTasks.length;
  elements.quantityTaskBadge.textContent = quantityTaskLabel(latestTask);
  elements.quantityTaskBadge.className = `mini-pill ${latestTask ? `status-pill ${quantityStatusTone(latestTask.status)}` : ""}`;
  elements.quantitySummaryGrid.innerHTML = renderManagerSummaryCards([
    { label: text("对象快照", "Snapshots"), value: String(latestTask?.snapshotCount || state.quantitySnapshots.length || 0) },
    { label: text("汇总行", "Summary Rows"), value: String(latestTask?.summaryCount || state.quantitySummaries.length || 0) },
    { label: text("总数量", "Total Count"), value: String(state.quantitySummaries.reduce((sum, item) => sum + Number(item.count || 0), 0)) },
    { label: text("管线米数", "Pipe Length"), value: formatQuantityNumber(quantityMetricTotal("pipeLength")) },
    { label: text("阀门台数", "Valve Count"), value: formatQuantityNumber(quantityMetricTotal("valveCount")) },
    { label: text("设备重量", "Equipment Weight"), value: formatQuantityNumber(quantityMetricTotal("equipmentWeight")) },
  ]);

  elements.quantityTaskList.innerHTML = state.quantityTasks.length
    ? state.quantityTasks.slice(0, 5).map((task) => `
        <div class="quantity-task-row ${["queued", "running"].includes(task.status) ? "active" : ""}">
          <span class="status-pill ${quantityStatusTone(task.status)}">${escapeHtml(quantityStatusLabel(task.status))}</span>
          <div>
            <strong>${escapeHtml(task.version || "V1")}</strong>
            <span>${escapeHtml(task.createdBy || text("系统", "System"))}</span>
          </div>
          <span>${escapeHtml(formatDateTime(task.completedAt || task.updatedAt || task.createdAt))}</span>
          <span>${escapeHtml(text(`${task.snapshotCount || 0} 对象 / ${task.summaryCount || 0} 汇总`, `${task.snapshotCount || 0} objects / ${task.summaryCount || 0} summaries`))}</span>
          <span class="quantity-task-actions">
            <button class="ghost-button compact-button" data-quantity-task-action="cancel" data-quantity-task-id="${escapeHtml(task.id)}" type="button" ${["queued", "running"].includes(task.status) && !state.quantityBusy ? "" : "disabled"}>${escapeHtml(text("取消", "Cancel"))}</button>
            <button class="ghost-button compact-button" data-quantity-task-action="retry" data-quantity-task-id="${escapeHtml(task.id)}" type="button" ${["failed", "canceled"].includes(task.status) && !state.quantityBusy ? "" : "disabled"}>${escapeHtml(text("重跑", "Retry"))}</button>
          </span>
        </div>
      `).join("")
    : `<div class="empty-card">${escapeHtml(!apsReady
      ? quantityApsConfigurationPrompt()
      : ready
        ? text("还没有工程量统计任务。", "No quantity extraction tasks yet.")
        : text("模型转换完成后才能提取属性。", "The model must be translated before extraction."))}</div>`;

  renderQuantitySummaryTable();
  renderQuantitySnapshotList();
  renderQuantityComparePanel();
  elements.quantityMessage.textContent = state.quantityMessage || (activeTool === "quantity" && !apsReady
    ? quantityApsConfigurationPrompt()
    : activeTool === "quantity" && doc && !ready
      ? text("所选模型尚未完成 APS 转换，暂不能拉取全量属性。", "Selected model is not translated in APS yet.")
      : "");
}

function renderQuantityGuide(doc, latestTask, ready, apsReady = quantityApsConfigurationReady()) {
  const hasTemplateScope = Boolean(state.quantityFieldMode === "all" || state.quantityTemplateId);
  const templateLabel = state.quantityFieldMode === "all"
    ? text("全量字段", "All fields")
    : state.quantityTemplates.find((template) => template.id === state.quantityTemplateId)?.name || text("等待模板", "Waiting template");
  const guideItems = [
    {
      element: elements.quantityGuideModel,
      textElement: elements.quantityGuideModelText,
      state: !doc ? "active" : ready ? "done" : "blocked",
      label: !doc ? text("待选择", "Pending") : ready ? text("模型已就绪", "Ready") : text("等待转换", "Waiting"),
    },
    {
      element: elements.quantityGuideTemplate,
      textElement: elements.quantityGuideTemplateText,
      state: !doc || !ready ? "pending" : hasTemplateScope ? "done" : "active",
      label: !doc
        ? text("待选择模型", "Select model first")
        : !ready
          ? text("待模型就绪", "Waiting model")
          : templateLabel,
    },
    {
      element: elements.quantityGuideExtract,
      textElement: elements.quantityGuideExtractText,
      state: latestTask?.status === "succeeded" ? "done" : ["queued", "running"].includes(latestTask?.status) ? "active" : !apsReady ? "blocked" : ready ? "active" : "pending",
      label: latestTask ? quantityStatusLabel(latestTask.status) : !apsReady ? text("待配置 APS", "Configure APS") : text("未发起", "Not started"),
    },
    {
      element: elements.quantityGuideResult,
      textElement: elements.quantityGuideResultText,
      state: succeededTasksForGuide().length ? "done" : latestTask?.status === "failed" ? "blocked" : "pending",
      label: succeededTasksForGuide().length
        ? text(`${state.quantitySummaries.length} 条汇总`, `${state.quantitySummaries.length} summaries`)
        : latestTask?.status === "failed"
          ? text("提取失败", "Failed")
          : text("待生成", "Pending"),
    },
  ];

  guideItems.forEach((item) => {
    if (!item.element || !item.textElement) {
      return;
    }
    item.element.classList.remove("pending", "active", "done", "blocked");
    item.element.classList.add(item.state);
    item.textElement.textContent = item.label;
  });
}

function renderQuantityPreflight(doc, ready, activeTask, apsReady = quantityApsConfigurationReady()) {
  if (!elements.quantityPreflightList) {
    return;
  }
  const template = state.quantityTemplates.find((item) => item.id === state.quantityTemplateId) || null;
  const filters = quantityFilterPayload();
  const filterCount = Object.values(filters).reduce((sum, values) => sum + values.length, 0);
  const items = [
    {
      state: apsReady ? "done" : "blocked",
      label: text("APS 配置", "APS Configuration"),
      value: apsReady ? text("已配置", "Configured") : text("待配置", "Required"),
      title: apsReady ? text("系统设置中的 APS 通道已就绪。", "APS channel in System Settings is ready.") : quantityApsConfigurationPrompt(),
    },
    {
      state: !doc ? "pending" : ready ? "done" : "blocked",
      label: text("模型转换", "Model Translation"),
      value: !doc
        ? text("未选择", "Not selected")
        : ready
          ? text("已完成", "Ready")
          : quantityStatusLabel(doc.aps?.translationStatus || text("未就绪", "Not ready")),
    },
    {
      state: doc?.aps?.urn ? "done" : doc ? "blocked" : "pending",
      label: "APS URN",
      value: doc?.aps?.urn ? truncate(doc.aps.urn, 26) : text("未回填", "Missing"),
      title: doc?.aps?.urn || "",
    },
    {
      state: !apsReady || !doc || !ready ? "pending" : state.quantityFieldMode === "all" || template ? "done" : "active",
      label: text("统计字段", "Fields"),
      value: !apsReady
        ? text("待 APS 配置", "Waiting APS")
        : !doc
        ? text("待选择模型", "Select model first")
        : !ready
          ? text("待模型就绪", "Waiting model")
          : state.quantityFieldMode === "all"
            ? text("全量属性", "All properties")
            : template?.name || text("等待模板", "Waiting template"),
    },
    {
      state: activeTask ? "blocked" : apsReady && ready ? "done" : "pending",
      label: text("任务队列", "Task Queue"),
      value: activeTask
        ? quantityStatusLabel(activeTask.status)
        : apsReady && ready
          ? text("可提交", "Available")
          : apsReady
            ? text("待模型就绪", "Waiting model")
            : text("待 APS 配置", "Waiting APS"),
    },
    {
      state: "done",
      label: text("过滤条件", "Filters"),
      value: filterCount
        ? text(`${filterCount} 项过滤`, `${filterCount} filters`)
        : text("不过滤", "No filters"),
    },
  ];

  elements.quantityPreflightList.innerHTML = items.map((item) => `
    <div class="quantity-preflight-row ${item.state}" title="${escapeHtml(item.title || item.value)}">
      <span>${escapeHtml(item.label)}</span>
      <strong>${escapeHtml(item.value)}</strong>
    </div>
  `).join("");
}

function quantityCoverageLabel(key) {
  return {
    elementType: text("对象类型", "Object Type"),
    floor: text("系统/区域", "System/Area"),
    discipline: text("专业", "Discipline"),
    material: text("材质/规格", "Material/Spec"),
    area: text("面积", "Area"),
    length: text("管线长度", "Line Length"),
    volume: text("体积", "Volume"),
    diameter: text("管径", "Diameter"),
    weight: text("重量", "Weight"),
  }[key] || key;
}

function renderQuantityPropertyDictionaryPanel() {
  if (!elements.quantityPropertyDictionaryPanel) {
    return;
  }
  const dictionary = state.quantityPropertyDictionary;
  if (!dictionary) {
    if (elements.quantityDictionaryBadge) {
      elements.quantityDictionaryBadge.textContent = text("未扫描", "Not scanned");
      elements.quantityDictionaryBadge.className = "mini-pill";
    }
    elements.quantityPropertyDictionaryPanel.innerHTML = `<div class="empty-card">${escapeHtml(text("正式提取前先扫描字段，可提前发现模板字段和模型属性不匹配的问题。", "Scan fields before extraction to catch template-to-model property mismatches."))}</div>`;
    return;
  }
  const coverageItems = Object.entries(dictionary.coverage || {});
  const matched = coverageItems.filter(([, item]) => Number(item.matched || 0) > 0).length;
  if (elements.quantityDictionaryBadge) {
    elements.quantityDictionaryBadge.textContent = text(`${dictionary.objectCount || 0} 对象 · ${matched}/${coverageItems.length} 字段`, `${dictionary.objectCount || 0} objects · ${matched}/${coverageItems.length} fields`);
    elements.quantityDictionaryBadge.className = `mini-pill ${matched === coverageItems.length ? "status-pill approved" : "status-pill in_review"}`;
  }
  elements.quantityPropertyDictionaryPanel.innerHTML = `
    <div class="quantity-dictionary-grid">
      ${coverageItems.map(([key, item]) => {
        const rate = Math.max(0, Math.min(1, Number(item.rate || 0)));
        return `
          <div class="quantity-dictionary-row">
            <strong>${escapeHtml(quantityCoverageLabel(key))}</strong>
            <span>${escapeHtml(text(`${item.matched || 0}/${item.total || 0} 对象匹配`, `${item.matched || 0}/${item.total || 0} matched`))}</span>
            <span title="${escapeHtml((item.aliases || []).join(", "))}">${escapeHtml(truncate((item.aliases || []).slice(0, 3).join(" / "), 32))}</span>
            <div class="quantity-dictionary-meter" aria-hidden="true"><i style="--coverage:${(rate * 100).toFixed(0)}%"></i></div>
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function renderQuantityLaunchSummary(doc, ready, latestTask, activeTask, apsReady = quantityApsConfigurationReady()) {
  const template = state.quantityTemplates.find((item) => item.id === state.quantityTemplateId) || null;
  const filters = quantityFilterPayload();
  const filterSummary = [
    filters.floors.length ? `${text("系统/区域", "System/Area")}: ${filters.floors.join(" / ")}` : "",
    filters.disciplines.length ? `${text("专业", "Disciplines")}: ${filters.disciplines.join(" / ")}` : "",
    filters.elementTypes.length ? `${text("对象类型", "Object Types")}: ${filters.elementTypes.join(" / ")}` : "",
    filters.materials.length ? `${text("材质/规格", "Material/Spec")}: ${filters.materials.join(" / ")}` : "",
  ].filter(Boolean).join(" · ") || text("不过滤", "No filters");
  const groupSummary = quantityGroupByFields().map(quantityDimensionLabel).join(" / ");
  const activeText = activeTask
    ? text(`后台任务 ${quantityStatusLabel(activeTask.status)}`, `Background task ${quantityStatusLabel(activeTask.status)}`)
    : latestTask
      ? quantityTaskLabel(latestTask)
      : text("未发起", "Not started");

  if (elements.quantityReadinessBadge) {
    elements.quantityReadinessBadge.textContent = !doc
      ? text("待选择模型", "Select a model")
      : !apsReady
        ? text("APS 未配置", "APS not configured")
      : ready
        ? text("模型可提取", "Ready to extract")
        : text("模型未就绪", "Model not ready");
    elements.quantityReadinessBadge.className = `mini-pill ${apsReady && ready ? "status-pill approved" : doc || !apsReady ? "status-pill in_review" : ""}`;
  }

  if (!elements.quantityLaunchSummary) {
    return;
  }
  elements.quantityLaunchSummary.innerHTML = `
    <div>
      <span>${escapeHtml(text("模型版本", "Model Version"))}</span>
      <strong>${escapeHtml(doc ? `${doc.name} · ${doc.version || "V1"}` : text("未选择", "Not selected"))}</strong>
    </div>
    <div>
      <span>${escapeHtml(text("模型 URN", "Model URN"))}</span>
      <strong title="${escapeHtml(doc?.aps?.urn || "")}">${escapeHtml(truncate(doc?.aps?.urn || text("未配置", "Not configured"), 36))}</strong>
    </div>
    <div>
      <span>${escapeHtml(text("统计口径", "Takeoff Scope"))}</span>
      <strong>${escapeHtml(state.quantityFieldMode === "all" ? text("全量属性", "All properties") : template?.name || text("默认模板", "Default template"))}</strong>
    </div>
    <div>
      <span>${escapeHtml(text("分组维度", "Group By"))}</span>
      <strong>${escapeHtml(groupSummary || text("对象类型", "Object type"))}</strong>
    </div>
    <div class="wide">
      <span>${escapeHtml(text("过滤条件", "Filters"))}</span>
      <strong>${escapeHtml(filterSummary)}</strong>
    </div>
    <div>
      <span>${escapeHtml(text("任务状态", "Task State"))}</span>
      <strong>${escapeHtml(activeText)}</strong>
    </div>
  `;
}

function quantityDimensionLabel(value) {
  return {
    elementType: text("对象类型", "Object Type"),
    floor: text("系统/区域", "System/Area"),
    discipline: text("专业", "Discipline"),
    material: text("材质/规格", "Material/Spec"),
  }[value] || value;
}

function succeededTasksForGuide() {
  return state.quantityTasks.filter((task) => task.status === "succeeded");
}

function renderQuantitySummaryTable() {
  if (!state.quantitySummaries.length) {
    const activeTask = quantityActiveTask();
    elements.quantitySummaryTableBody.innerHTML = `
      <tr>
        <td colspan="8" class="quantity-empty-cell">${escapeHtml(activeTask
          ? text("后台正在提取属性，完成后这里会按模板维度生成汇总。", "Property extraction is running; summaries will appear here when it completes.")
          : text("完成提取后，这里会按模板维度汇总数量、面积、长度和体积。", "After extraction, summary quantities appear here."))}</td>
      </tr>
    `;
    return;
  }
  elements.quantitySummaryTableBody.innerHTML = state.quantitySummaries.map((summary, index) => {
    const selected = index === state.quantitySelectedSummaryIndex ? "selected" : "";
    return `
      <tr class="${selected}" data-quantity-summary-index="${index}" tabindex="0">
        <td>${escapeHtml(summary.elementType || "未分类")}</td>
        <td>${escapeHtml(summary.floor || "全部区域")}</td>
        <td>${escapeHtml(summary.discipline || "全部专业")}</td>
        <td>${escapeHtml(summary.material || "全部材质/规格")}</td>
        <td>${escapeHtml(formatQuantityNumber(summary.count))}</td>
        <td>${escapeHtml(formatQuantityNumber(summary.area))}</td>
        <td>${escapeHtml(formatQuantityNumber(summary.length))}</td>
        <td>${escapeHtml(formatQuantityNumber(summary.volume))}</td>
      </tr>
    `;
  }).join("");
}

function renderQuantitySnapshotList() {
  const snapshots = selectedQuantitySnapshots();
  elements.quantitySnapshotBadge.textContent = text(`${snapshots.length} 对象`, `${snapshots.length} objects`);
  elements.quantitySnapshotList.innerHTML = snapshots.length
    ? snapshots.map((snapshot) => `
        <article class="quantity-snapshot-row">
          <div>
            <strong>${escapeHtml(snapshot.name || `dbId ${snapshot.dbId}`)}</strong>
            <span>${escapeHtml(`${snapshot.elementType || "未分类"} · ${snapshot.floor || "未指定区域"} · ${snapshot.discipline || "未指定专业"}`)}</span>
          </div>
          <span class="mini-pill">dbId ${escapeHtml(snapshot.dbId)}</span>
          <span>${escapeHtml(formatQuantityNumber(snapshot.area))} m²</span>
          <span>${escapeHtml(formatQuantityNumber(snapshot.length))} m</span>
          <span>${escapeHtml(formatQuantityNumber(snapshot.volume))} m³</span>
        </article>
      `).join("")
    : `<div class="empty-card">${escapeHtml(state.quantitySummaries.length
      ? text("选中汇总行后可查看分组内对象。", "Select a summary row to inspect objects.")
      : text("完成一次工程量提取后，这里会显示可下钻的设备、管线和仪表对象清单。", "Run a quantity extraction to populate equipment, piping, and instrument objects."))}</div>`;
}

function renderQuantityComparePanel() {
  const succeeded = quantityCompletedCompareTasks();
  const options = succeeded.map((task) => ({
    value: task.id,
    label: `${quantityTaskDocumentLabel(task)} · ${quantityTaskLabel(task)}`,
  }));
  setSelectOptions(elements.quantityCompareLeftSelect, options, state.quantityCompareLeftTaskId);
  setSelectOptions(elements.quantityCompareRightSelect, options, state.quantityCompareRightTaskId);
  if (!succeeded.length) {
    const emptyOption = `<option value="">${escapeHtml(text("暂无完成任务", "No completed tasks"))}</option>`;
    elements.quantityCompareLeftSelect.innerHTML = emptyOption;
    elements.quantityCompareRightSelect.innerHTML = emptyOption;
  }
  elements.quantityCompareButton.disabled = state.quantityBusy || succeeded.length < 2 || !state.quantityCompareLeftTaskId || !state.quantityCompareRightTaskId;
  elements.quantityCompareBadge.textContent = state.quantityCompareDiff.length
    ? `${state.quantityCompareDiff.filter((item) => item.status !== "unchanged").length} 项差异`
    : succeeded.length >= 2
      ? text("可对比", "Ready")
      : text("至少需要两次结果", "Need two results");

  if (!state.quantityCompareDiff.length) {
    elements.quantityCompareTable.innerHTML = `<div class="empty-card">${escapeHtml(text("选择任意两个已完成的模型版本或提取任务后，对比数量、面积、长度、体积和模板指标变化。", "Select any two completed model versions or extraction tasks to compare quantity and template metric changes."))}</div>`;
    return;
  }

  elements.quantityCompareTable.innerHTML = `
    <table class="quantity-table">
      <thead>
        <tr>
          <th>对象类型</th>
          <th>系统/区域</th>
          <th>专业</th>
          <th>材质/规格</th>
          <th>状态</th>
          <th>数量差异</th>
          <th>面积差异</th>
          <th>长度差异</th>
          <th>体积差异</th>
          <th>指标差异</th>
        </tr>
      </thead>
      <tbody>
        ${state.quantityCompareDiff.map((item) => `
          <tr class="${item.status !== "unchanged" ? "changed" : ""}">
            <td>${escapeHtml(item.elementType)}</td>
            <td>${escapeHtml(item.floor)}</td>
            <td>${escapeHtml(item.discipline)}</td>
            <td>${escapeHtml(item.material)}</td>
            <td>${escapeHtml(quantityDiffStatusLabel(item.status))}</td>
            <td>${escapeHtml(formatSignedQuantity(item.countDelta))}</td>
            <td>${escapeHtml(formatSignedQuantity(item.areaDelta))}</td>
            <td>${escapeHtml(formatSignedQuantity(item.lengthDelta))}</td>
            <td>${escapeHtml(formatSignedQuantity(item.volumeDelta))}</td>
            <td>${escapeHtml(quantityMetricsDeltaLabel(item.metricsDelta))}</td>
          </tr>
        `).join("")}
      </tbody>
    </table>
  `;
}

function quantityMetricsDeltaLabel(metricsDelta) {
  const changed = Object.values(metricsDelta || {}).filter((metric) => Number(metric.delta || 0));
  if (!changed.length) {
    return "—";
  }
  return changed.slice(0, 3).map((metric) => `${metric.label || metric.key} ${formatSignedQuantity(metric.delta)}${metric.unit || ""}`).join(" / ");
}

function quantityTaskDocumentLabel(task) {
  const doc = documentById(task?.documentId) || (state.quantityAllDocuments || []).find((item) => item.id === task?.documentId);
  return doc?.name || text("模型", "Model");
}

function quantityDiffStatusLabel(status) {
  return {
    added: text("新增", "Added"),
    removed: text("删除", "Removed"),
    changed: text("变化", "Changed"),
    unchanged: text("无变化", "Unchanged"),
  }[status] || status;
}

function formatQuantityNumber(value) {
  const number = Number(value || 0);
  if (!Number.isFinite(number)) {
    return "0";
  }
  return Number.isInteger(number) ? String(number) : number.toFixed(2);
}

function formatSignedQuantity(value) {
  const number = Number(value || 0);
  if (!Number.isFinite(number) || number === 0) {
    return "0";
  }
  return `${number > 0 ? "+" : ""}${formatQuantityNumber(number)}`;
}

function renderModelClashRecordRow(record) {
  const statusLabel = {
    open: text("未闭环", "Open"),
    resolved: text("已解决", "Resolved"),
    approved: text("已批准", "Approved"),
  }[record.status] || record.status;
  const statusTone = record.status === "open" ? "open" : "resolved";
  const title = `${record.elementNameA || `dbId ${record.dbIdA}`} / ${record.elementNameB || `dbId ${record.dbIdB}`}`;
  const meta = [
    `${record.disciplineA || "A"} ↔ ${record.disciplineB || "B"}`,
    `dbId ${record.dbIdA} / ${record.dbIdB}`,
    Number(record.clashVolume || 0).toFixed(3),
  ].join(" · ");
  return `
    <article class="model-clash-record-row">
      <div class="model-clash-record-copy">
        <strong>${escapeHtml(title)}</strong>
        <span>${escapeHtml(meta)}</span>
      </div>
      <span class="status-pill ${statusTone}">${escapeHtml(statusLabel)}</span>
      <div class="model-clash-record-actions">
        <button class="ghost-button compact-button" data-model-clash-action="open-issue" data-model-clash-record="${escapeHtml(record.id)}" type="button" ${record.issueId ? "" : "disabled"}>${escapeHtml(text("定位", "Locate"))}</button>
        <button class="ghost-button compact-button" data-model-clash-action="resolve" data-model-clash-record="${escapeHtml(record.id)}" type="button" ${record.status === "open" ? "" : "disabled"}>${escapeHtml(text("关闭", "Close"))}</button>
      </div>
    </article>
  `;
}

function renderProfileCenterModal() {
  const visible = Boolean(state.profileCenterModalOpen && currentUser());
  const activeTab = normalizeProfileCenterTab(state.profileCenterTab);
  const binding = currentUserLarkBinding();
  elements.profileCenterModal.classList.toggle("hidden", !visible);
  elements.profileCenterModal.setAttribute("aria-hidden", String(!visible));
  elements.profileCenterOverview.classList.toggle("hidden", activeTab !== "overview");
  elements.profileCenterSecurity.classList.toggle("hidden", activeTab !== "security");
  elements.profileCenterTabs.forEach((button) => {
    button.classList.toggle("active", button.dataset.profileTab === activeTab);
  });
  setElementText(elements.profileLarkBindingStatus, binding.bound ? text("已绑定", "Bound") : text("未绑定", "Not Bound"));
  if (elements.profileLarkBindingStatus) {
    elements.profileLarkBindingStatus.className = binding.bound ? "mini-pill signal-pill success" : "mini-pill";
  }
  setElementText(
    elements.profileLarkBindingName,
    binding.bound
      ? binding.name || text("已绑定飞书账号", "Bound Lark Account")
      : text("未绑定飞书账号", "No Lark Account Bound"),
  );
  setElementText(
    elements.profileLarkBindingMeta,
    binding.bound
      ? [
        binding.email || text("飞书未返回邮箱", "No email returned by Lark"),
        binding.boundAt
          ? text(`绑定于 ${formatDateTime(binding.boundAt)}`, `Bound ${formatDateTime(binding.boundAt)}`)
          : "",
      ].filter(Boolean).join(" · ")
      : text("绑定后可直接使用飞书登录当前 CDE 账户。", "Bind your Lark account to sign in to this CDE account directly."),
  );
  elements.profileLarkBindButton.disabled = state.authBusy || binding.bound;
  elements.profileLarkUnbindButton.disabled = state.authBusy || !binding.bound;
  elements.profileLarkBindingMessage.textContent = state.profileLarkMessage || "";
  elements.profileLarkBindingMessage.classList.toggle("hidden", !state.profileLarkMessage);
  elements.profileLarkBindingMessage.classList.toggle("success", state.profileLarkMessageTone === "success");
  elements.profileLarkBindingMessage.classList.toggle("error", state.profileLarkMessageTone === "alert");
}

function renderGuestPolicySection(access, capabilities) {
  const guestPolicy = access.project?.guestPolicy || {};
  const canManage = Boolean(capabilities.manageGuestPolicy);

  elements.guestDownloadToggle.checked = Boolean(guestPolicy.canDownload);
  elements.guestAnnotateToggle.checked = Boolean(guestPolicy.canAnnotate);
  elements.guestReplyToggle.checked = Boolean(guestPolicy.canReply);

  elements.guestDownloadToggle.disabled = !canManage;
  elements.guestAnnotateToggle.disabled = !canManage;
  elements.guestReplyToggle.disabled = !canManage;

  const labels = [];
  labels.push(guestPolicy.canDownload ? text("允许下载", "Download allowed") : text("仅预览", "Preview only"));
  labels.push(guestPolicy.canAnnotate ? text("允许批注", "Annotations allowed") : text("禁止批注", "No annotations"));
  labels.push(guestPolicy.canReply ? text("允许回复", "Replies allowed") : text("禁止回复", "No replies"));
  elements.guestPolicySummary.textContent = canManage
    ? text(
      `当前访客策略：${labels.join(" / ")}。保存后会立即影响访客在文件、审阅和流程入口中的可见操作。`,
      `Current guest policy: ${labels.join(" / ")}. Saving will immediately update the actions guests can see in files, review, and workflow entries.`,
    )
    : text(
      `当前访客策略：${labels.join(" / ")}。只有项目管理员和超级管理员可以修改。`,
      `Current guest policy: ${labels.join(" / ")}. Only project admins and super admins can change it.`,
    );
}

