function renderEmailConfigurationSection(access = currentAccess(), capabilities = currentCapabilities()) {
  const canManageSystem = Boolean(capabilities.manageEmailChannel);
  const canManageProject = Boolean(capabilities.manageProjectNotifications);
  const systemDraft = state.systemEmailDraft;
  const projectDraft = state.projectEmailNotificationDraft;
  const systemStatus = systemEmailDraftStatusMeta(systemDraft);
  const projectStatus = projectEmailDraftStatusMeta(projectDraft, systemDraft);
  const activeMenu = normalizeAccessMenu(state.accessMenu);
  const systemChannelMode = activeMenu !== "project_notifications";
  const projectNotificationMode = activeMenu === "project_notifications";

  elements.emailConfigCapabilityBadge.textContent = canManageSystem
    ? text("超级管理员", "Super Admin")
    : canManageProject
      ? text("项目管理员", "Project Admin")
      : text("只读", "Read Only");
  setSelectorText(
    "#accessEmailNotificationsView .panel-kicker",
    projectNotificationMode ? text("当前项目设置", "Current Project Settings") : text("系统级设置", "System-Level Settings"),
  );
  setSelectorText(
    "#accessEmailNotificationsView h3",
    projectNotificationMode ? text("项目通知", "Project Notifications") : text("邮件通道", "Mail Channel"),
  );
  elements.systemEmailConfigCard?.classList.toggle("hidden", !systemChannelMode);
  elements.projectEmailNotificationCard?.classList.toggle("hidden", !projectNotificationMode);
  elements.emailConfigSummary.innerHTML = renderEmailConfigurationSummaryCards(systemDraft, projectDraft, capabilities);

  elements.systemEmailEnabledToggle.checked = Boolean(systemDraft.enabled);
  elements.systemEmailAuthToggle.checked = Boolean(systemDraft.authRequired);
  elements.systemEmailHostInput.value = systemDraft.host;
  elements.systemEmailPortInput.value = systemDraft.port;
  setSelectOptions(elements.systemEmailEncryptionSelect, systemEmailEncryptionOptions(), systemDraft.encryption);
  elements.systemEmailUsernameInput.value = systemDraft.username;
  elements.systemEmailPasswordInput.value = systemDraft.password;
  elements.systemEmailPasswordInput.placeholder = systemDraft.hasPassword
    ? text("留空则保持已保存密码", "Leave blank to keep the saved password")
    : text("请输入 SMTP 密码", "Enter the SMTP password");
  elements.systemEmailSenderNameInput.value = systemDraft.senderName;
  elements.systemEmailSenderEmailInput.value = systemDraft.senderEmail;
  elements.systemEmailReplyToInput.value = systemDraft.replyTo;
  elements.systemEmailSubjectPrefixInput.value = systemDraft.subjectPrefix;

  const systemFieldsDisabled = !canManageSystem || state.systemEmailSaving;
  elements.systemEmailEnabledToggle.disabled = systemFieldsDisabled;
  elements.systemEmailAuthToggle.disabled = systemFieldsDisabled;
  elements.systemEmailHostInput.disabled = systemFieldsDisabled;
  elements.systemEmailPortInput.disabled = systemFieldsDisabled;
  elements.systemEmailEncryptionSelect.disabled = systemFieldsDisabled;
  elements.systemEmailUsernameInput.disabled = systemFieldsDisabled || !systemDraft.authRequired;
  elements.systemEmailPasswordInput.disabled = systemFieldsDisabled || !systemDraft.authRequired;
  elements.systemEmailSenderNameInput.disabled = systemFieldsDisabled;
  elements.systemEmailSenderEmailInput.disabled = systemFieldsDisabled;
  elements.systemEmailReplyToInput.disabled = systemFieldsDisabled;
  elements.systemEmailSubjectPrefixInput.disabled = systemFieldsDisabled;
  elements.saveSystemEmailConfigButton.disabled = !canManageSystem || state.systemEmailSaving;
  elements.systemEmailSummary.textContent = canManageSystem
    ? text(`当前状态：${systemStatus.label}。${systemStatus.note}`, `Current status: ${systemStatus.label}. ${systemStatus.note}`)
    : text(`当前状态：${systemStatus.label}。仅超级管理员可修改。`, `Current status: ${systemStatus.label}. Only super admins can edit it.`);

  elements.projectEmailEnabledToggle.checked = Boolean(projectDraft.enabled);
  elements.projectEmailGuestToggle.checked = Boolean(projectDraft.includeGuests);
  setSelectOptions(elements.projectEmailDigestSelect, projectEmailDigestOptions(), projectDraft.digestMode);
  elements.projectEmailEnabledToggle.disabled = !canManageProject || state.projectEmailSaving;
  elements.projectEmailGuestToggle.disabled = !canManageProject || state.projectEmailSaving || !projectDraft.enabled;
  elements.projectEmailDigestSelect.disabled = !canManageProject || state.projectEmailSaving || !projectDraft.enabled;
  elements.projectEmailRecipientGrid.innerHTML = renderEmailOptionCards(
    emailRecipientOptions(),
    projectDraft.recipients,
    "project-email-recipient",
  );
  elements.projectEmailEventGrid.innerHTML = renderEmailOptionCards(
    emailEventOptions(),
    projectDraft.events,
    "project-email-event",
  );
  Array.from(elements.projectEmailRecipientGrid.querySelectorAll("input[type=\"checkbox\"]")).forEach((input) => {
    input.disabled = !canManageProject || state.projectEmailSaving || !projectDraft.enabled;
  });
  Array.from(elements.projectEmailEventGrid.querySelectorAll("input[type=\"checkbox\"]")).forEach((input) => {
    input.disabled = !canManageProject || state.projectEmailSaving || !projectDraft.enabled;
  });
  elements.saveProjectEmailConfigButton.disabled = !canManageProject || state.projectEmailSaving;
  elements.projectEmailSummary.textContent = canManageProject
    ? text(
      `当前项目状态：${projectStatus.label}。发送频率 ${projectDigestModeText(projectDraft.digestMode)}，已启用 ${enabledEmailFlagCount(projectDraft.recipients)} 类接收对象 / ${enabledEmailFlagCount(projectDraft.events)} 个事件。`,
      `Project status: ${projectStatus.label}. Frequency ${projectDigestModeText(projectDraft.digestMode)}, with ${enabledEmailFlagCount(projectDraft.recipients)} recipient groups and ${enabledEmailFlagCount(projectDraft.events)} events enabled.`,
    )
    : text(`当前项目状态：${projectStatus.label}。仅项目管理员和超级管理员可修改。`, `Project status: ${projectStatus.label}. Only project admins and super admins can edit it.`);

  elements.emailConfigMessage.textContent = state.emailConfigMessage || "";
  elements.emailConfigMessage.classList.toggle("hidden", !state.emailConfigMessage);
  elements.emailConfigMessage.classList.toggle("success", state.emailConfigMessageTone === "success");
  elements.emailConfigMessage.classList.toggle("error", state.emailConfigMessageTone === "alert");
}

function renderAiConfigurationSection(access = currentAccess(), capabilities = currentCapabilities()) {
  if (!elements.aiConfigSummary) {
    return;
  }
  const canManage = Boolean(capabilities.manageAiSettings);
  const aiDraft = state.systemAiDraft;
  const status = systemAiDraftStatusMeta(aiDraft);

  elements.aiConfigCapabilityBadge.textContent = canManage ? text("超级管理员", "Super Admin") : text("只读", "Read Only");
  elements.aiConfigSummary.innerHTML = renderAiConfigurationSummaryCards(aiDraft, capabilities);
  elements.systemAiEnabledToggle.checked = Boolean(aiDraft.enabled);
  elements.systemAiEndpointInput.value = aiDraft.endpoint;
  elements.systemAiModelInput.value = aiDraft.model;
  elements.systemAiApiKeyInput.value = aiDraft.apiKey;
  elements.systemAiApiKeyInput.placeholder = aiDraft.hasApiKey
    ? text("留空则保持已保存密钥", "Leave blank to keep the saved key")
    : text("请输入 API Key（如接口需要）", "Enter the API key if required");
  elements.systemAiTimeoutInput.value = aiDraft.timeoutMs;
  elements.systemAiBatchSizeInput.value = aiDraft.batchSize;

  const fieldsDisabled = !canManage || state.systemAiSaving || state.systemAiTesting;
  const canTestAi = canManage && Boolean(String(aiDraft.endpoint || "").trim());
  const enableToggleLocked = !aiDraft.enabled && !aiDraft.testPassed;
  elements.systemAiEnabledToggle.disabled = fieldsDisabled || enableToggleLocked;
  elements.systemAiEndpointInput.disabled = fieldsDisabled;
  elements.systemAiModelInput.disabled = fieldsDisabled;
  elements.systemAiApiKeyInput.disabled = fieldsDisabled;
  elements.systemAiTimeoutInput.disabled = fieldsDisabled;
  elements.systemAiBatchSizeInput.disabled = fieldsDisabled;
  elements.saveSystemAiConfigButton.disabled = !canManage || state.systemAiSaving || state.systemAiTesting || (aiDraft.enabled && !aiDraft.testPassed);
  elements.saveSystemAiConfigButton.textContent = state.systemAiSaving
    ? text("保存中…", "Saving...")
    : text("保存 AI 配置", "Save AI Settings");
  elements.testSystemAiConfigButton.disabled = !canTestAi || state.systemAiSaving || state.systemAiTesting;
  elements.testSystemAiConfigButton.textContent = state.systemAiTesting
    ? text("测试中…", "Testing...")
    : text("调用测试", "Test Call");
  elements.systemAiSummary.textContent = canManage
    ? text(
      `当前状态：${status.label}。${status.note} 调用测试可在启用前执行。`,
      `Current status: ${status.label}. ${status.note} Test calls can be run before enabling AI.`,
    )
    : text(`当前状态：${status.label}。仅超级管理员可修改。`, `Current status: ${status.label}. Only super admins can edit it.`);

  elements.aiConfigMessage.textContent = state.aiConfigMessage || "";
  elements.aiConfigMessage.classList.toggle("hidden", !state.aiConfigMessage);
  elements.aiConfigMessage.classList.toggle("success", state.aiConfigMessageTone === "success");
  elements.aiConfigMessage.classList.toggle("error", state.aiConfigMessageTone === "alert");
}

function apsBucketPolicyOptions() {
  return [
    { value: "persistent", label: text("persistent · 长期归档", "persistent · Long-lived") },
    { value: "temporary", label: text("temporary · 临时存储", "temporary · Temporary") },
    { value: "transient", label: text("transient · 短期缓存", "transient · Short-lived") },
  ];
}

function apsSourceLabel(value) {
  return {
    system_settings: text("系统设置", "System Settings"),
    system: text("系统设置", "System Settings"),
    unset: text("未配置", "Unset"),
  }[value] || value || text("未配置", "Unset");
}

function systemApsDraftStatusMeta(draft = state.systemApsDraft) {
  const missingCredentials =
    !String(draft.clientId || "").trim() ||
    (!String(draft.clientSecret || "").trim() && !draft.hasClientSecret);
  if (!draft.enabled) {
    return {
      label: text("未启用", "Disabled"),
      tone: "neutral",
      note: text("模型转换、Viewer 和工程量提取会保持关闭。", "Model translation, Viewer, and quantity extraction remain disabled."),
    };
  }
  if (missingCredentials) {
    return {
      label: text("待完善", "Incomplete"),
      tone: "alert",
      note: text("启用前需要填写 Client ID 和 Client Secret。", "Client ID and Client Secret are required before enabling."),
    };
  }
  return {
    label: text("已配置", "Configured"),
    tone: "success",
    note: text("APS 模型能力已具备调用条件。", "APS model services are ready."),
  };
}

function renderApsConfigurationSummaryCards(apsDraft, capabilities) {
  const status = systemApsDraftStatusMeta(apsDraft);
  return [
    workflowStatCard(
      text("APS 状态", "APS Status"),
      status.label,
      status.note,
      status.tone,
    ),
    workflowStatCard(
      "Client",
      apsDraft.clientId ? text("已填写", "Set") : text("未配置", "Not Configured"),
      apsDraft.hasClientSecret || apsDraft.clientSecret ? text("Client Secret 已保存", "Client Secret saved") : text("仍缺少 Client Secret。", "Client Secret is still missing."),
      apsDraft.clientId && (apsDraft.hasClientSecret || apsDraft.clientSecret) ? "info" : "neutral",
    ),
    workflowStatCard(
      "Bucket",
      apsDraft.bucketKey || text("自动生成", "Auto"),
      `${apsDraft.bucketPolicy || "persistent"} · ${apsDraft.bucketRegion || "US"}`,
      apsDraft.bucketKey ? "info" : "neutral",
    ),
    workflowStatCard(
      "Viewer",
      apsDraft.viewerVersion || "7.*",
      capabilities.manageApsSettings
        ? text(`${apsDraft.viewerEnv || "AutodeskProduction2"} · ${apsDraft.viewerApi || "streamingV2"}`, `${apsDraft.viewerEnv || "AutodeskProduction2"} · ${apsDraft.viewerApi || "streamingV2"}`)
        : text("当前角色只能查看 APS 配置。", "This role can only view APS settings."),
      "info",
    ),
  ].join("");
}

