    "user.password.change": text("修改登录密码", "Change Password"),
    "project.create": text("新建项目", "Create Project"),
    "project.update": text("修改项目基础信息", "Update Project Basics"),
    "project.settings.update": text("更新访客策略", "Update Guest Policy"),
    "system.email.update": text("更新邮件发信配置", "Update Mail Delivery Settings"),
    "project.notification.update": text("更新项目邮件通知策略", "Update Project Mail Policy"),
    "project_member.invite": text("生成邀请链接", "Generate Invite Link"),
    "project_member.accept_invite": text("接受项目邀请", "Accept Project Invite"),
    "project_member.upsert": text("新增 / 恢复成员", "Create / Restore Member"),
    "project_member.update_role": text("修改成员角色", "Update Member Role"),
    "project_member.remove": text("移除成员", "Remove Member"),
