function renderAuditLogs() {
  const logs = currentAccess().auditLogs || [];
  const filterMeta = currentAccess().auditLogFilter || {};
  if (elements.auditLogDateFromInput) {
    elements.auditLogDateFromInput.value = state.auditLogDateFrom || "";
    elements.auditLogDateFromInput.disabled = !currentCapabilities().viewAuditLogs;
  }
  if (elements.auditLogDateToInput) {
    elements.auditLogDateToInput.value = state.auditLogDateTo || "";
    elements.auditLogDateToInput.disabled = !currentCapabilities().viewAuditLogs;
  }
  if (elements.auditLogClearFilterButton) {
    elements.auditLogClearFilterButton.disabled = !currentCapabilities().viewAuditLogs || (!state.auditLogDateFrom && !state.auditLogDateTo);
  }
  if (elements.auditLogFilterSummary) {
    const hasFilter = Boolean(state.auditLogDateFrom || state.auditLogDateTo);
    const rangeText = hasFilter
      ? text(
        `筛选范围：${state.auditLogDateFrom || "最早"} 至 ${state.auditLogDateTo || "今天"}`,
        `Range: ${state.auditLogDateFrom || "Earliest"} to ${state.auditLogDateTo || "Today"}`,
      )
      : text("默认显示最近 120 条审计日志。", "Showing the latest 120 audit logs by default.");
    const matchedCount = Number(filterMeta.matchedCount || logs.length);
    const totalCount = Number(filterMeta.totalCount || 0);
    const limitCount = Number(filterMeta.limit || 120);
    const countText = hasFilter
      ? text(
        `命中 ${matchedCount} 条，当前显示 ${logs.length}${matchedCount > limitCount ? ` / ${matchedCount}` : ""} 条，项目总计 ${totalCount} 条。`,
        `Matched ${matchedCount}; showing ${logs.length}${matchedCount > limitCount ? ` / ${matchedCount}` : ""}; project total ${totalCount}.`,
      )
      : text(
        `当前显示 ${logs.length} 条，项目总计 ${totalCount} 条。`,
        `Showing ${logs.length}; project total ${totalCount}.`,
      );
    elements.auditLogFilterSummary.textContent = currentCapabilities().viewAuditLogs
      ? `${rangeText} ${countText}`
      : text("当前角色无权查看审计日志。", "This role cannot view audit logs.");
  }

  if (!logs.length) {
    elements.auditLogList.innerHTML = currentCapabilities().viewAuditLogs
      ? `<div class="empty-card">${escapeHtml(state.auditLogDateFrom || state.auditLogDateTo ? text("当前日期范围内没有审计日志。", "There are no audit logs in the selected date range.") : text("当前还没有权限相关审计日志。", "There are no access-related audit logs yet."))}</div>`
      : `<div class="empty-card">${escapeHtml(text("当前角色无权查看审计日志。", "This role cannot view audit logs."))}</div>`;
    return;
  }

  elements.auditLogList.innerHTML = logs
    .map(
      (log) => `
        <article class="access-audit-card">
          <div class="access-card-head">
            <div class="access-card-copy">
              <strong>${escapeHtml(log.userName || text("系统", "System"))}</strong>
              <p>${escapeHtml(auditActionLabel(log.action))} · ${escapeHtml(log.resourceType || "system")} · ${escapeHtml(log.resourceId || "—")}</p>
            </div>
            <span class="mini-pill">${escapeHtml(formatDateTime(log.createdAt))}</span>
          </div>
          <p>${escapeHtml(renderAuditLogDetail(log.detail))}</p>
        </article>
      `,
    )
    .join("");
}

function applyAccessPayload(access) {
  state.access = normalizeAccessPayload(access);
  if (state.access.currentUser?.id) {
    state.currentUserId = state.access.currentUser.id;
  }
  resetAiConfigurationDraft(state.access);
  resetApsConfigurationDraft(state.access);
  render();
}

function suggestedProjectCode(name) {
  return String(name || "")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
}

function updateProjectManagementDraft(patch = {}, options = {}) {
  const previousDraft = state.projectManagementDraft;
  state.projectManagementDraft = normalizeProjectManagementDraft(
    {
      ...state.projectManagementDraft,
      ...patch,
    },
    currentProjectManagement(),
  );
  if (options.autoCodeFromName && !String(previousDraft.code || "").trim() && !String(state.projectManagementDraft.code || "").trim()) {
    state.projectManagementDraft.code = suggestedProjectCode(state.projectManagementDraft.name);
  }
  if (!options.preserveMessage) {
    state.projectManagementMessage = "";
  }
  renderProjectManagementPanel();
}

function useProjectAsMemberSource(projectId) {
  updateProjectManagementDraft({
    memberInitMode: "copy_project",
    memberSourceProjectId: projectId,
  });
}

function useProjectAsTemplateSource(projectId) {
  updateProjectManagementDraft({
    templateInitMode: "copy_project",
    templateSourceProjectId: projectId,
  });
}

function projectManagementDraftFromProject(project) {
  if (!project) {
    return createEmptyProjectManagementDraft(currentProjectManagement());
  }
  return normalizeProjectManagementDraft({
    name: project.name || "",
    code: project.code || "",
    description: project.description || "",
    memberInitMode: project.memberInitMode || "creator_only",
    memberSourceProjectId: project.memberSourceProjectId || "",
    templateInitMode: project.templateInitMode || "default_templates",
    templateSourceProjectId: project.templateSourceProjectId || "",
    folderPolicyKey: project.folderPolicyKey || "cde_standard",
  }, currentProjectManagement());
}

function cancelProjectManagementEdit(options = {}) {
  state.projectManagementEditingId = "";
  state.projectManagementDraft = createEmptyProjectManagementDraft(currentProjectManagement());
  if (!options.preserveMessage) {
    state.projectManagementMessage = "";
  }
  renderProjectManagementPanel();
}

function startProjectManagementEdit(projectId) {
  if (!currentActorCanManageProjects()) {
    showAlert(text("当前账号没有项目管理权限。", "This account cannot manage projects."));
    return;
  }
  const project = projectManagementProjectById(projectId);
  if (!project) {
    showAlert(text("未找到要编辑的项目。", "The project to edit could not be found."));
    return;
  }
  state.projectManagementEditingId = project.id;
  state.projectManagementDraft = projectManagementDraftFromProject(project);
  state.projectManagementMessage = "";
  renderProjectManagementPanel();
  document.querySelector("#accessProjectManagementView .project-management-create-card")?.scrollIntoView({
    block: "start",
    behavior: "smooth",
  });
}

async function submitProjectManagementAction() {
  if (!currentActorCanManageProjects()) {
    showAlert(text("当前账号没有项目管理权限。", "This account cannot manage projects."));
    return;
  }

  const editingProjectId = state.projectManagementEditingId;
  const isEditing = Boolean(editingProjectId);
  const editingProject = editingProjectId ? projectManagementProjectById(editingProjectId) : null;
  if (isEditing && !editingProject) {
    cancelProjectManagementEdit();
    showAlert(text("要编辑的项目不存在，已返回创建模式。", "The project being edited no longer exists. Returned to create mode."));
    return;
  }

  const draft = normalizeProjectManagementDraft({
    ...state.projectManagementDraft,
    name: elements.projectNameInput.value.trim(),
    code: elements.projectCodeInput.value.trim(),
    description: elements.projectDescriptionInput.value.trim(),
    memberSourceProjectId: elements.projectMemberSourceSelect.value,
    templateSourceProjectId: elements.projectTemplateSourceSelect.value,
  });
  state.projectManagementDraft = draft;

  if (!draft.name) {
    showAlert(text("请先填写项目名称。", "Please enter the project name first."));
    return;
  }
  if (!draft.code) {
    showAlert(text("请先填写项目编码。", "Please enter the project code first."));
    return;
  }
  if (!isEditing && draft.memberInitMode === "copy_project" && !draft.memberSourceProjectId) {
    showAlert(text("请选择成员复制来源项目。", "Please choose a source project for members."));
    return;
  }
  if (!isEditing && draft.templateInitMode === "copy_project" && !draft.templateSourceProjectId) {
    showAlert(text("请选择模板复制来源项目。", "Please choose a source project for templates."));
    return;
  }

  state.projectManagementSubmitting = true;
  state.projectManagementMessage = "";
  renderProjectManagementPanel();

  try {
    const response = isEditing
      ? await patchJson(`/api/projects/${encodeURIComponent(editingProjectId)}`, {
        name: draft.name,
        code: draft.code,
        description: draft.description,
      })
      : await postJson("/api/projects", draft);
    state.projectManagementSubmitting = false;
    state.projectManagementMessage = text(
      isEditing
        ? `项目“${response.project?.name || draft.name}”的基础信息已更新。`
        : `项目“${response.project?.name || draft.name}”已创建，可在下方列表中直接切换。`,
      isEditing
        ? `Project "${response.project?.name || draft.name}" basic information has been updated.`
        : `Project "${response.project?.name || draft.name}" has been created and can now be switched to from the list below.`,
    );
    state.access = normalizeAccessPayload(response.access);
    state.projectManagementEditingId = "";
    state.projectManagementDraft = createEmptyProjectManagementDraft(state.access.projectManagement);
    await refreshDocuments();
  } catch (error) {
    state.projectManagementSubmitting = false;
    state.projectManagementMessage =
      error.message ||
      (isEditing
        ? text("保存项目修改失败，请稍后重试。", "Failed to save project changes. Please try again.")
        : text("创建项目失败，请稍后重试。", "Failed to create the project. Please try again."));
    renderProjectManagementPanel();
  }
}

async function addProjectMember() {
  if (!currentActorCanManageMembers()) {
    showAlert(text("当前角色无权管理项目成员。", "The current role cannot manage project members."));
    return;
  }

  const name = elements.accessAddMemberName.value.trim();
  const email = elements.accessAddMemberEmail.value.trim();
  const role = elements.accessAddMemberRole.value || "guest";
  const expiresInDays = Math.max(1, Math.min(30, Number(elements.accessInviteExpiryInput.value || 7) || 7));
  if (!name) {
    showAlert(text("请先填写成员姓名。", "Enter the member name first."));
    return;
  }
  if (!email) {
    showAlert(text("请先填写成员邮箱。", "Enter the member email first."));
    return;
  }

  try {
    const response = await postJson("/api/member-invites", {
      name,
      email,
      role,
      expiresInDays,
    });
    elements.accessAddMemberName.value = "";
    elements.accessAddMemberEmail.value = "";
    elements.accessAddMemberRole.value = "guest";
    elements.accessInviteExpiryInput.value = String(expiresInDays);
    const inviteUrl = String(response.invite?.inviteUrl || "").trim() || inviteUrlFromRecord(response.invite);
    state.accessInviteResult = inviteUrl
      ? text(
        `已生成邀请链接：${inviteUrl}\n请将链接发送给 ${email}，对方可通过该链接自行设置密码并加入项目。`,
        `Invite link generated: ${inviteUrl}\nSend this link to ${email}. They can set their password and join the project from it.`,
      )
      : text(
        `已为 ${email} 生成邀请，请在列表中复制邀请链接。`,
        `Invite generated for ${email}. Copy the invite link from the list.`,
      );
    applyAccessPayload(response.access);
  } catch (error) {
    state.accessInviteResult = "";
    showAlert(error.message || text("创建账号失败，请稍后重试。", "Failed to create the account. Please try again later."));
  }
}

async function changeOwnPasswordAction() {
  if (!currentUser()) {
    return;
  }

  try {
    const response = await postJson("/api/users/me/password", {
      currentPassword: elements.accessCurrentPasswordInput.value,
      newPassword: elements.accessNewPasswordInput.value,
      confirmPassword: elements.accessConfirmPasswordInput.value,
    });
    elements.accessCurrentPasswordInput.value = "";
    elements.accessNewPasswordInput.value = "";
    elements.accessConfirmPasswordInput.value = "";
    state.accessPasswordMessage = text("登录密码已更新。", "Login password updated.");
    applyAccessPayload(response.access);
    await refreshDocuments();
  } catch (error) {
    state.accessPasswordMessage = error.message || text("修改密码失败，请稍后重试。", "Failed to change password. Please try again later.");
    render();
  }
}

async function resetProjectMemberPasswordAction(userId) {
  if (!userId || !currentActorCanManageMembers()) {
    return;
  }
  const member = (currentAccess().projectMembers || []).find((item) => item.user?.id === userId);
  if (!member) {
    return;
  }
  const memberName = member.user?.name || text("未命名成员", "Unnamed member");
  if (!await confirmAction(text(`确认重置成员“${memberName}”的登录密码吗？`, `Reset the login password for "${memberName}"?`))) {
    return;
  }

  try {
    const response = await postJson(`/api/users/${userId}/reset-password`, {});
    const accountLabel = member.user?.email || member.user?.name || text("该成员", "this member");
    state.accessInviteResult = text(
      `已重置 ${accountLabel} 的密码。\n新的临时密码：${response.tempPassword}\n请提醒该成员登录后立即修改密码。`,
      `Password reset for ${accountLabel}.\nTemporary password: ${response.tempPassword}\nRemind this member to change it immediately after signing in.`,
    );
    await refreshDocuments();
  } catch (error) {
    showAlert(error.message || text("重置密码失败，请稍后重试。", "Failed to reset password. Please try again later."));
  }
}

