async function testSystemAiConfigurationAction() {
  if (!currentActorCanManageAiSettings()) {
    showAlert(text("当前账号无权测试系统 AI 配置。", "This account cannot test system AI settings."));
    return;
  }
  if (!String(state.systemAiDraft.endpoint || "").trim()) {
    state.aiConfigMessage = text("请先填写 AI API 地址。", "Enter the AI API endpoint first.");
    state.aiConfigMessageTone = "alert";
    renderAiConfigurationSection();
    return;
  }

  state.systemAiTesting = true;
  state.aiConfigMessage = text("正在执行 AI 调用测试…", "Running AI test call...");
  state.aiConfigMessageTone = "info";
  renderAiConfigurationSection();

  try {
    const result = await postJson("/api/system/ai-settings/test", {
      enabled: state.systemAiDraft.enabled,
      endpoint: state.systemAiDraft.endpoint.trim(),
      model: state.systemAiDraft.model.trim(),
      apiKey: state.systemAiDraft.apiKey,
      timeoutMs: Number(state.systemAiDraft.timeoutMs || 0),
      batchSize: Number(state.systemAiDraft.batchSize || 0),
    });
    state.systemAiTesting = false;
    if (result.access) {
      state.access = normalizeAccessPayload(result.access);
      resetAiConfigurationDraft(state.access);
    } else {
      state.systemAiDraft.testPassed = true;
      state.systemAiDraft.lastTestStatus = "success";
      state.systemAiDraft.lastTestedAt = result.testedAt || new Date().toISOString();
      state.systemAiDraft.lastTestLatencyMs = Number(result.latencyMs || 0);
      state.systemAiDraft.lastTestResponseShape = String(result.responseShape || "json");
    }
    state.aiConfigMessage = text(
      `调用测试通过：${result.latencyMs}ms，响应类型 ${result.responseShape || "json"}，现在可以启用AI。`,
      `AI test passed: ${result.latencyMs}ms, response shape ${result.responseShape || "json"}. AI can now be enabled.`,
    );
    state.aiConfigMessageTone = "success";
    renderAiConfigurationSection();
  } catch (error) {
    state.systemAiTesting = false;
    state.aiConfigMessage = error.message || text("AI 调用测试失败，请检查地址、鉴权和响应格式。", "AI test failed. Check endpoint, auth, and response shape.");
    state.aiConfigMessageTone = "alert";
    renderAiConfigurationSection();
  }
}

