function activeLibraryFilterCount() {
  const filters = normalizedLibraryFilters();
  return Object.entries(DEFAULT_LIBRARY_FILTERS)
    .filter(([key, value]) => filters[key] !== value)
    .length;
}

function hasActiveLibraryFilters() {
  return activeLibraryFilterCount() > 0;
}

function isLibraryColumnConfigurationDefault() {
  const visible = normalizedLibraryVisibleColumns();
  return LIBRARY_COLUMN_DEFINITIONS.every((column) => visible[column.key] === DEFAULT_LIBRARY_VISIBLE_COLUMNS[column.key]);
}

function libraryColumnConfigurationSummary() {
  const hiddenCount = LIBRARY_COLUMN_DEFINITIONS.length - visibleLibraryColumnDefinitions().length;
  if (!hiddenCount && (state.libraryTableDensity || "standard") === "standard") {
    return text("默认列", "Default Columns");
  }
  const densityLabel = {
    compact: text("紧凑", "Compact"),
    standard: text("标准", "Standard"),
    comfortable: text("舒展", "Comfortable"),
  }[state.libraryTableDensity || "standard"];
  return hiddenCount
    ? text(`隐藏 ${hiddenCount} 列 · ${densityLabel}`, `${hiddenCount} hidden · ${densityLabel}`)
    : densityLabel;
}

function documentLibraryType(doc) {
  const ext = fileExtension(doc?.name || "");
  if (ext === "pdf") {
    return "pdf";
  }
  if (DRAWING_WORKSPACE_DOCUMENT_EXTENSIONS.has(ext)) {
    return "drawing";
  }
  if (MODEL_WORKSPACE_DOCUMENT_EXTENSIONS.has(ext)) {
    return "model";
  }
  if (ONLYOFFICE_DOCUMENT_EXTENSIONS.has(ext)) {
    return "office";
  }
  return "other";
}

function documentMatchesLibraryFilters(doc) {
  const filters = normalizedLibraryFilters();
  if (filters.type !== "all" && filters.type !== documentLibraryType(doc)) {
    return false;
  }

  const currentVersion = documentCurrentVersionEntry(doc);
  const parseStatus = currentVersion?.parseStatus || doc.parseStatus || "pending";
  if (filters.parse !== "all" && filters.parse !== parseStatus) {
    return false;
  }

  const checkedOutBy = documentCheckedOutBy(doc);
  const occupancy = documentOccupancyMeta(doc);
  if (filters.checkout === "available" && checkedOutBy) {
    return false;
  }
  if (filters.checkout === "checked_out" && !checkedOutBy) {
    return false;
  }
  if (filters.checkout === "mine" && checkedOutBy !== currentActorLabel()) {
    return false;
  }
  if (filters.checkout === "readonly" && occupancy.label !== text("只读", "Read Only")) {
    return false;
  }

  const reviewKey = doc.status === "uploaded" && doc.versionHistory?.length > 1 ? "pending_review" : doc.status;
  if (filters.review !== "all" && filters.review !== reviewKey) {
    return false;
  }

  const shareUrl = documentShareUrl(doc);
  if (filters.share === "shared" && !shareUrl) {
    return false;
  }
  if (filters.share === "unshared" && shareUrl) {
    return false;
  }
  if (filters.share === "download" && (!shareUrl || doc.share?.permission !== "download")) {
    return false;
  }
  if (filters.share === "preview" && (!shareUrl || doc.share?.permission === "download")) {
    return false;
  }

  return true;
}

function folderMatchesLibraryFilters() {
  const filters = normalizedLibraryFilters();
  const documentSpecificFilterActive =
    filters.review !== "all" ||
    filters.share !== "all" ||
    filters.parse !== "all" ||
    filters.checkout !== "all";
  if (documentSpecificFilterActive) {
    return false;
  }
  return filters.type === "all" || filters.type === "folder";
}

