  elements.libraryFilterButton?.setAttribute("aria-expanded", String(Boolean(state.libraryFilterPopoverOpen)));
  elements.libraryColumnSettingsButton?.setAttribute("aria-expanded", String(Boolean(state.libraryColumnSettingsPopoverOpen)));
  elements.libraryFilterPopover?.classList.toggle("hidden", !state.libraryFilterPopoverOpen);
  elements.libraryColumnSettingsPopover?.classList.toggle("hidden", !state.libraryColumnSettingsPopoverOpen);

