function normalizeProjectManagementDraft(draft = state.projectManagementDraft, projectManagement = currentProjectManagement()) {
  const base = createEmptyProjectManagementDraft(projectManagement);
  const sourceProjects = Array.isArray(projectManagement.sourceProjects) ? projectManagement.sourceProjects : [];
  const memberInitModes = new Set((projectManagement.memberInitModes || []).map((item) => item.value));
  const templateInitModes = new Set((projectManagement.templateInitModes || []).map((item) => item.value));
  const folderPolicies = new Set((projectManagement.folderPolicies || []).map((item) => item.value));
  const next = {
    ...base,
    ...(draft && typeof draft === "object" ? draft : {}),
  };
  next.memberInitMode = memberInitModes.has(next.memberInitMode) ? next.memberInitMode : base.memberInitMode;
  next.templateInitMode = templateInitModes.has(next.templateInitMode) ? next.templateInitMode : base.templateInitMode;
  next.folderPolicyKey = folderPolicies.has(next.folderPolicyKey) ? next.folderPolicyKey : base.folderPolicyKey;
  next.memberSourceProjectId =
    next.memberInitMode === "copy_project" && sourceProjects.some((item) => item.value === next.memberSourceProjectId)
      ? next.memberSourceProjectId
      : "";
  next.templateSourceProjectId =
    next.templateInitMode === "copy_project" && sourceProjects.some((item) => item.value === next.templateSourceProjectId)
      ? next.templateSourceProjectId
      : "";
  return next;
}

function syncProjectManagementDraft() {
  state.projectManagementDraft = normalizeProjectManagementDraft(state.projectManagementDraft, currentProjectManagement());
}

