  const selected = Boolean(normalizedFolderId);
  const path = selected ? workflowTemplateExportPathForFolder(normalizedFolderId) : String(autoExport?.targetPath || "").trim();
  const stale = !selected && Boolean(path);
  return {
    selected,
    folderId: normalizedFolderId,
    path: path || workflowTemplateProjectRootPath(),
    title: selected ? path : stale ? text(`${path} · 待重新绑定`, `${path} · Rebind required`) : text("请选择导出目录", "Select Export Folder"),
    hint: selected
      ? text("已绑定真实项目目录，审批通过后会直接导出到这里。", "A real project folder is bound. Approved files will export directly here.")
      : stale
        ? text("当前模板存在历史路径，但未绑定真实目录，请重新选择。", "This template has a historical path but no real folder binding. Select again.")
        : text("点击从项目目录中选择一个真实目标文件夹。", "Click to choose a real target folder from the project directory."),
  };
