function formatAuditLogValue(key, value) {
  if (value === null || value === undefined || value === "") {
    return "";
  }
  if (key === "guestPolicy" && value && typeof value === "object") {
    return [
      `下载${value.canDownload ? "开启" : "关闭"}`,
      `批注${value.canAnnotate ? "开启" : "关闭"}`,
      `回复${value.canReply ? "开启" : "关闭"}`,
    ].join(" / ");
  }
  if (typeof value === "boolean") {
    return value ? "是" : "否";
  }
  if (Array.isArray(value)) {
    return value.join("、");
  }
  if (typeof value === "object") {
    return JSON.stringify(value);
  }
  return String(value);
}

function renderAuditLogDetail(detail) {
  if (!detail || typeof detail !== "object") {
    return "无附加说明";
  }
  const pairs = Object.entries(detail)
    .filter(([, value]) => value !== null && value !== undefined && value !== "")
    .map(([key, value]) => `${key}: ${formatAuditLogValue(key, value)}`)
    .filter((item) => !item.endsWith(": "));
  return pairs.length ? pairs.join(" · ") : "无附加说明";
}

function auditLogFilterQueryString() {
  const params = new URLSearchParams();
  if (state.auditLogDateFrom) {
    params.set("auditFrom", state.auditLogDateFrom);
  }
  if (state.auditLogDateTo) {
    params.set("auditTo", state.auditLogDateTo);
  }
  const query = params.toString();
  return query ? `?${query}` : "";
}

function auditLogFilterDateRangeValid(from, to) {
  return !from || !to || from <= to;
}

async function applyAuditLogDateFilter({ clear = false } = {}) {
  const nextFrom = clear ? "" : String(elements.auditLogDateFromInput?.value || "").slice(0, 10);
  const nextTo = clear ? "" : String(elements.auditLogDateToInput?.value || "").slice(0, 10);
  if (!auditLogFilterDateRangeValid(nextFrom, nextTo)) {
    showAlert(text("审计日志开始日期不能晚于结束日期。", "Audit log start date cannot be later than the end date."));
    renderAuditLogs();
    return;
  }
  state.auditLogDateFrom = nextFrom;
  state.auditLogDateTo = nextTo;
  await refreshDocuments();
  render();
}

function documentPermissions(doc) {
  return doc?.permissions || {};
}

function annotationPermissionProfile(doc = currentDocument()) {
  return documentPermissions(doc).annotations || {};
}

function folderPermissionsMeta(folder) {
  return folder?.permissions || rootFolderPermissions();
}

function canShareDocument(doc) {
  return Boolean(documentPermissions(doc).share);
}

function canRenameDocument(doc) {
  return Boolean(documentPermissions(doc).rename);
}

function canMoveDocument(doc) {
  return Boolean(documentPermissions(doc).move);
}

function canDeleteDocument(doc) {
  return Boolean(documentPermissions(doc).delete);
}

function canDownloadDocument(doc) {
  return Boolean(documentPermissions(doc).download);
}

function canPreviewDocument(doc) {
  return Boolean(documentPermissions(doc).preview);
}

function isPdfWorkspaceReadOnly(doc = currentDocument()) {
  if (state.currentView !== "review") {
    return false;
  }
  return state.reviewWorkspaceMode === "view" && isReviewableDocument(doc);
}

function canEditOnlyOfficeDocument(doc) {
  return Boolean(documentPermissions(doc).onlyOfficeEdit);
}

function canCreateAnnotation(doc = currentDocument()) {
  return Boolean(annotationPermissionProfile(doc).create) && !isPdfWorkspaceReadOnly(doc);
}

function canReplyAnnotation(doc = currentDocument()) {
  return Boolean(annotationPermissionProfile(doc).reply) && !isPdfWorkspaceReadOnly(doc);
}

function canExportReview(doc = currentDocument()) {
  return Boolean(annotationPermissionProfile(doc).export);
}

function canRunWorkflow(doc = currentDocument()) {
  return Boolean(documentPermissions(doc).workflow?.run);
}

function canViewWorkflow(doc = currentDocument()) {
  return Boolean(documentPermissions(doc).workflow?.visible);
}

function canUpdateOwnAnnotation(doc = currentDocument()) {
  const permissions = annotationPermissionProfile(doc);
  return Boolean(permissions.updateOwn ?? permissions.create);
}

function canDeleteOwnAnnotation(doc = currentDocument()) {
  const permissions = annotationPermissionProfile(doc);
  return Boolean(permissions.deleteOwn ?? permissions.updateOwn ?? permissions.create);
}

function canChangeAnnotation(annotation, doc = currentDocument()) {
  if (!annotation || !doc) {
    return false;
  }
  if (isPdfWorkspaceReadOnly(doc)) {
    return false;
  }
  const permissions = annotationPermissionProfile(doc);
  if (annotation.actor === currentActorLabel()) {
    return canUpdateOwnAnnotation(doc);
  }
  return Boolean(permissions.deleteOthers);
}

function canDeleteAnnotation(annotation, doc = currentDocument()) {
  if (!annotation || !doc) {
    return false;
  }
  if (isPdfWorkspaceReadOnly(doc)) {
    return false;
  }
  const permissions = annotationPermissionProfile(doc);
  if (annotation.actor === currentActorLabel()) {
    return canDeleteOwnAnnotation(doc);
  }
  return Boolean(permissions.deleteOthers);
}

function canChangeAnnotationStatus(annotation, doc = currentDocument()) {
  if (!annotation || !doc) {
    return false;
  }
  if (isPdfWorkspaceReadOnly(doc)) {
    return false;
  }
  const permissions = annotationPermissionProfile(doc);
  if (!permissions.changeStatus) {
    return false;
  }
  if (permissions.changeStatusAny || permissions.deleteOthers) {
    return true;
  }
  return annotation.actor === currentActorLabel() && canUpdateOwnAnnotation(doc);
}

function canSaveAnnotation(annotation, doc = currentDocument()) {
  return canChangeAnnotation(annotation, doc) || canChangeAnnotationStatus(annotation, doc);
}

function canDeleteReply(reply, doc = currentDocument()) {
  if (!reply || !doc) {
    return false;
  }
  if (isPdfWorkspaceReadOnly(doc)) {
    return false;
  }
  const permissions = annotationPermissionProfile(doc);
  if (reply.actor === currentActorLabel()) {
    return Boolean(permissions.reply);
  }
  return Boolean(permissions.deleteOthers);
}

function documentCheckedOutBy(doc) {
  return String(doc?.checkedOutBy || "").trim();
}

function documentMimeType(doc) {
  return String(doc?.mimeType || inferMimeType(doc?.name || "", "document")).toLowerCase();
}

function isApsModelDocument(doc) {
  return APS_MODEL_DOCUMENT_EXTENSIONS.has(fileExtension(doc?.name || ""));
}

function apsWorkspaceKind(doc) {
  return isDrawingWorkspaceDocument(doc) ? "drawing" : "model";
}

function apsWorkspaceLabels(doc) {
  return apsWorkspaceKind(doc) === "drawing"
    ? {
        asset: "图纸",
        workspace: "图纸工作台",
        preview: "图纸浏览",
      }
    : {
        asset: "模型",
        workspace: "模型工作台",
        preview: "模型浏览",
      };
}

function isDrawingWorkspaceDocument(doc) {
  return DRAWING_WORKSPACE_DOCUMENT_EXTENSIONS.has(fileExtension(doc?.name || ""));
}

function isModelWorkspaceDocument(doc) {
  return MODEL_WORKSPACE_DOCUMENT_EXTENSIONS.has(fileExtension(doc?.name || ""));
}

function annotationHasModelLocation(annotation) {
  return Boolean(
    annotation?.viewerState ||
    annotation?.viewer_state ||
    (Array.isArray(annotation?.dbIds) && annotation.dbIds.length) ||
    (Array.isArray(annotation?.dbids) && annotation.dbids.length) ||
    annotation?.modelUrn ||
    annotation?.model_urn ||
    annotation?.sheetGuid ||
    annotation?.sheet_guid,
  );
}

function isOnlyOfficeDocument(doc) {
  return ONLYOFFICE_DOCUMENT_EXTENSIONS.has(fileExtension(doc?.name || ""));
}

function isReviewableDocument(doc) {
  return documentMimeType(doc) === "application/pdf" || fileExtension(doc?.name || "") === "pdf";
}

function canOpenDocumentWorkspace(doc) {
  return isReviewableDocument(doc) || isOnlyOfficeDocument(doc) || isDrawingWorkspaceDocument(doc) || isModelWorkspaceDocument(doc);
}

function documentWorkspaceActionLabel(doc) {
  if (isModelWorkspaceDocument(doc)) {
    return "打开模型工作台";
  }
  if (isOnlyOfficeDocument(doc)) {
    return "打开文档";
  }
  return isDrawingWorkspaceDocument(doc) ? "进入图纸审阅" : "打开PDF审阅页";
}

function documentWorkspaceActionTitle(doc) {
  if (isModelWorkspaceDocument(doc)) {
    return "直接打开独立的模型浏览工作台";
  }
  if (isOnlyOfficeDocument(doc)) {
    return "直接在 OnlyOffice 中打开当前文档";
  }
  return isDrawingWorkspaceDocument(doc) ? "进入图纸审阅工作台" : "在独立页面打开 PDF 审阅工作台";
}

function apsTranslationStatus(doc) {
  const urn = String(doc?.aps?.urn || "").trim();
  const raw = String(doc?.aps?.translationStatus || "").trim().toLowerCase();
  if (["queued", "uploading", "uploaded", "translating", "success", "failed"].includes(raw)) {
    return raw;
  }
  return urn ? "success" : "idle";
}

function isApsTranslationActive(doc) {
  return ["queued", "uploading", "uploaded", "translating"].includes(apsTranslationStatus(doc));
}

function apsTranslationMeta(doc) {
  const labels = apsWorkspaceLabels(doc);
  const status = apsTranslationStatus(doc);
  const progress = String(doc?.aps?.translationProgress || "").trim();
  const error = String(doc?.aps?.translationError || "").trim();
  const message = String(doc?.aps?.translationMessage || "").trim();

  if (status === "success" && doc?.aps?.urn) {
    return {
      label: text("已就绪", "Ready"),
      helper:
        text(`当前${labels.asset}已完成 APS 转换并自动回填 URN，可直接打开${labels.workspace}。`, `The current ${labels.asset} has completed APS translation and the URN has been backfilled. You can open ${labels.workspace} directly.`),
    };
  }

  if (status === "failed") {
    return {
      label: text("转换失败", "Translation Failed"),
      helper: error || message || text("APS 自动转换失败，请检查模型文件或凭证配置后重试。", "APS auto-translation failed. Check the model file or credential configuration and try again."),
    };
  }

  if (["queued", "uploading", "uploaded", "translating"].includes(status)) {
    return {
      label: progress ? text(`转换中 ${progress}`, `Translating ${progress}`) : text("转换中", "Translating"),
      helper: message || text(`${labels.asset}文件已自动提交到 APS，转换完成后会自动回填 URN。`, `${labels.asset} file has been submitted to APS automatically. The URN will be backfilled after translation completes.`),
    };
  }

  return {
    label: text("待转换", "Pending Translation"),
    helper: text(`${labels.asset}文件上传后会自动走 APS OSS + Model Derivative；也支持手动填写 URN，2D / 3D GUID 可选。`, `${labels.asset} files automatically go through APS OSS + Model Derivative after upload. You can also enter a URN manually; 2D / 3D GUIDs are optional.`),
  };
}

function documentPreviewActionLabel(doc, compact = false) {
  if (isModelWorkspaceDocument(doc)) {
    return compact ? text("模型", "Model") : text("浏览模型", "View Model");
  }
  if (isDrawingWorkspaceDocument(doc)) {
    return compact ? text("图纸", "Drawing") : text("浏览图纸", "View Drawing");
  }
  if (isOnlyOfficeDocument(doc)) {
    return compact ? text("打开", "Open") : text("OnlyOffice 打开", "Open in OnlyOffice");
  }
  if (isReviewableDocument(doc)) {
    return compact ? "PDF" : text("浏览PDF", "View PDF");
  }
  return compact ? text("打开", "Open") : text("浏览文件", "View File");
}

function canUploadNewVersion(doc, actor = currentActorLabel()) {
  const permissions = documentPermissions(doc);
  if (!permissions.uploadVersion) {
    return false;
  }
  const checkedOutBy = documentCheckedOutBy(doc);
  return !checkedOutBy || checkedOutBy === actor || permissions.forceUnlock;
}

function canToggleDocumentCheckout(doc, actor = currentActorLabel()) {
  const permissions = documentPermissions(doc);
  if (!permissions.checkout && !permissions.forceUnlock) {
    return false;
  }
  const checkedOutBy = documentCheckedOutBy(doc);
  return !checkedOutBy || checkedOutBy === actor || permissions.forceUnlock;
}

function documentUploadBlockMessage(doc, actor = currentActorLabel()) {
  const permissions = documentPermissions(doc);
  if (permissions.publishLocked) {
    return text("当前文件位于发布目录，仅管理员或系统流程可写入。", "This file is in a published directory. Only admins or system workflows can write to it.");
  }
  if (permissions.approvalLocked) {
    return text("当前文件正处于审批锁定状态，流程结束前不能上传新版本。", "This file is approval-locked. New versions cannot be uploaded until the workflow ends.");
  }
  const checkedOutBy = documentCheckedOutBy(doc);
  if (checkedOutBy && checkedOutBy !== actor && !permissions.forceUnlock) {
    return text(`当前文件已被 ${checkedOutBy} 占用，其他人只能只读下载，不能上传新版本覆盖。`, `This file is checked out by ${checkedOutBy}. Others can only download read-only and cannot upload replacement versions.`);
  }
  if (!permissions.uploadVersion && !permissions.checkout && !permissions.forceUnlock) {
    return text("你没有修改该文件的权限。", "You do not have permission to modify this file.");
  }
  return "";
}

function documentOccupancyMeta(doc, actor = currentActorLabel()) {
  const checkedOutBy = documentCheckedOutBy(doc);
  const permissions = documentPermissions(doc);
  if (!checkedOutBy) {
    return {
      label: permissions.checkout || permissions.forceUnlock || permissions.uploadVersion ? text("未占用", "Available") : text("只读", "Read Only"),
      tone: "neutral",
      hint: permissions.uploadVersion ? text("当前无人占用，可直接上传新版本。", "No one has checked this file out. You can upload a new version directly.") : text("当前文件未被占用，但你没有写入该文件的权限。", "This file is not checked out, but you do not have write permission."),
    };
  }

  const selfHeld = checkedOutBy === actor;
  const checkedOutAt = doc?.checkedOutAt ? ` · ${formatDateTime(doc.checkedOutAt)}` : "";
  return {
    label: checkedOutBy,
    tone: selfHeld ? "info" : "alert",
    hint: selfHeld
      ? documentUploadBlockMessage(doc) || text(`当前由你占用${checkedOutAt}，可继续上传新版本，完成后记得释放占用。`, `Checked out by you${checkedOutAt}. You can upload a new version; remember to release the checkout when done.`)
      : text(`当前由 ${checkedOutBy} 占用${checkedOutAt}，其他人只能只读下载。`, `Checked out by ${checkedOutBy}${checkedOutAt}. Others can only download read-only.`),
  };
}

function documentShareUrl(doc) {
  if (!doc?.share?.enabled || !doc.shareUrl) {
    return "";
  }
  return new URL(doc.shareUrl, window.location.origin).toString();
}

function defaultShareExpiryInputValue() {
  const date = new Date();
  date.setDate(date.getDate() + 1);
  return date.toISOString().slice(0, 10);
}

function ensureVersionStatusPolling() {
  window.clearTimeout(versionStatusPollTimer);

  const hasProcessingVersion = state.documents.some((doc) =>
    Array.isArray(doc.versionHistory) && doc.versionHistory.some((entry) => entry.parseStatus === "processing"),
  );
  const hasProcessingApsTranslation = state.documents.some((doc) => isApsTranslationActive(doc));
  const hasGeneratingWorkflowCrs = state.workflows.some((workflow) => ["queued", "running"].includes(String(workflow?.crsDraft?.status || "").trim()));
  if (!hasProcessingVersion && !hasProcessingApsTranslation && !hasGeneratingWorkflowCrs) {
    versionStatusPollTimer = 0;
    return;
  }

  versionStatusPollTimer = window.setTimeout(() => {
    void refreshDocuments()
      .then(() => {
        render();
      })
      .catch(() => {});
  }, 1800);
}

function openOnlyOfficeDocument(docId, options = {}) {
  const doc = documentById(docId);
  if (!doc || !canPreviewDocument(doc)) {
    return;
  }
  const requestedMode = options.mode === "review" ? "edit" : options.mode || "edit";
  const resolvedMode = requestedMode === "edit" && !canEditOnlyOfficeDocument(doc) ? "view" : requestedMode;

  const params = new URLSearchParams({
    docId: doc.id,
    mode: resolvedMode,
    actor: currentActorLabel(),
  });

  if (options.versionId) {
    params.set("versionId", options.versionId);
  }

  window.open(`/onlyoffice.html?${params.toString()}`, "_blank", "noopener");
}

function openApsDocument(docId, options = {}) {
  const doc = documentById(docId);
  if (!doc || !canPreviewDocument(doc)) {
    return;
  }

  const params = new URLSearchParams({
    docId: doc.id,
    mode: options.mode || "review",
    actor: currentActorLabel(),
    workspace: options.workspace || apsWorkspaceKind(doc),
  });

  if (options.versionId) {
    params.set("versionId", options.versionId);
  }
  if (options.issueId) {
    params.set("issueId", options.issueId);
  }
  if (Array.isArray(options.dbIds) && options.dbIds.length) {
    params.set("dbIds", options.dbIds.map((item) => Number(item)).filter((item) => Number.isFinite(item)).join(","));
  }
  if (Array.isArray(options.referenceDbIds) && options.referenceDbIds.length) {
    params.set("referenceDbIds", options.referenceDbIds.map((item) => Number(item)).filter((item) => Number.isFinite(item)).join(","));
  }
  if (options.healthResultId) {
    params.set("healthResultId", options.healthResultId);
    params.set("healthSource", options.healthSource || "");
  }
  if (options.heatmapId) {
    params.set("heatmapId", options.heatmapId);
    params.set("heatmapStatus", options.heatmapStatus || "open");
    params.set("heatmapDisciplinePair", options.heatmapDisciplinePair || "all");
    params.set("heatmapMinClashVolume", options.heatmapMinClashVolume || "0");
    params.set("heatmapOpacity", options.heatmapOpacity || "0.45");
    params.set("heatmapFloorSlice", options.heatmapFloorSlice || "");
    params.set("heatmapVisible", options.heatmapVisible === "0" || options.heatmapVisible === false ? "0" : "1");
  }
  if (options.modelDiffTaskId) {
    params.set("modelDiffTaskId", options.modelDiffTaskId);
    params.set("modelDiffRecordId", options.modelDiffRecordId || "");
    params.set("modelDiffViewMode", options.modelDiffViewMode === "split" ? "split" : "overlay");
    if (Array.isArray(options.modelDiffTypes) && options.modelDiffTypes.length) {
      params.set("modelDiffTypes", options.modelDiffTypes.join(","));
    }
    params.set("modelDiffOnlyDifferences", options.modelDiffOnlyDifferences === false ? "0" : "1");
  }
  if (options.scheduleId) {
    params.set("scheduleId", options.scheduleId);
    params.set("scheduleDate", options.scheduleDate || "");
    params.set("scheduleSpeed", options.scheduleSpeed || "week");
  }

  window.open(`/apsviewer.html?${params.toString()}`, "_blank", "noopener");
}

function openDrawingDocument(docId, options = {}) {
  const doc = documentById(docId);
  if (!doc || !canPreviewDocument(doc) || !isDrawingWorkspaceDocument(doc)) {
    return;
  }
  openApsDocument(doc.id, {
    ...options,
    workspace: "drawing",
  });
}

function buildPdfDocumentUrl(docId, options = {}) {
  const doc = documentById(docId);
  if (!doc || !canPreviewDocument(doc) || !isReviewableDocument(doc)) {
    return "";
  }
  const params = new URLSearchParams({
    id: doc.id,
    mode: options.mode === "view" ? "view" : "review",
    actor: currentActorLabel(),
  });
  if (options.versionId) {
    params.set("versionId", options.versionId);
  }
  if (options.annotationId) {
    params.set("annotationId", options.annotationId);
  }
  if (options.issueId) {
    params.set("issueId", options.issueId);
  }
  if (options.page) {
    params.set("page", String(Math.max(1, Number(options.page || 1) || 1)));
  }
  const highlight = normalizeReviewSearchHighlight(options.ocrMatch || null);
  if (highlight) {
    params.set("ocrMatch", JSON.stringify(highlight));
    params.set("page", String(Math.max(1, Number(highlight.page || options.page || 1) || 1)));
  }
  return `/pdf.html?${params.toString()}`;
}

function openPdfDocument(docId, options = {}) {
  const url = buildPdfDocumentUrl(docId, options);
  if (!url) {
    showAlert(text("当前 PDF 无法打开，请确认文件权限和文件类型。", "This PDF cannot be opened. Check file permissions and type."));
    return false;
  }
  const opened = window.open(url, "_blank", "noopener");
  if (!opened) {
    notify(text("浏览器拦截了 PDF 新窗口，请允许弹窗后重试。", "The browser blocked the PDF popup. Allow popups and try again."), "alert");
    return false;
  }
  return true;
}

function openDocumentWorkspace(docId, options = {}) {
  const doc = documentById(docId);
  if (!doc || !canPreviewDocument(doc)) {
    return false;
  }
  if (isModelWorkspaceDocument(doc)) {
    openApsDocument(doc.id, options);
    return true;
  }
  if (isOnlyOfficeDocument(doc)) {
    openOnlyOfficeDocument(doc.id, {
      ...options,
      mode: options.mode === "edit" && canEditOnlyOfficeDocument(doc) ? "edit" : options.mode || (canEditOnlyOfficeDocument(doc) ? "edit" : "view"),
    });
    return true;
  }
  if (isDrawingWorkspaceDocument(doc)) {
    openDrawingDocument(doc.id, options);
    return true;
  }
  if (isReviewableDocument(doc)) {
    openPdfDocument(doc.id, options);
    return true;
  }
  return false;
}

function currentActionableDocument() {
  if (state.currentView === "files") {
    if (state.fileSearchQuery) {
      return currentDocument();
    }
    const doc = currentDocument();
    return doc?.parentId === state.currentFolderId ? doc : null;
  }
  return currentDocument();
}

function documentUpdatedBy(doc) {
  return localizedDisplayName(doc.activity?.[doc.activity.length - 1]?.actor || doc.reviewer || doc.initiator || text("系统", "System"));
}

function fileTypeLabel(name) {
  const ext = String(name || "").split(".").pop()?.toLowerCase() || "file";
  return ext.slice(0, 4);
}

function fileTypeTone(name) {
  const ext = String(name || "").split(".").pop()?.toLowerCase() || "";
  if (ext === "pdf") return "pdf";
  if (["xlsx", "xls", "csv"].includes(ext)) return "sheet";
  if (["dwg", "nwd", "nwc", "rvt", "ifc"].includes(ext)) return "drawing";
  return "file";
}

function renderReviewNavigator() {
  if (state.currentView !== "review") {
    return;
  }

  const doc = currentDocument();
  if (!doc) {
    elements.reviewDocSummary.innerHTML = `<div class="empty-card">${text("选中文件后，这里会显示页缩略图和批注列表。", "Select a file to show page thumbnails and annotations here.")}</div>`;
    elements.reviewAnnotationSidebarList.innerHTML = `<div class="empty-card">${text("暂无批注。", "No annotations yet.")}</div>`;
    elements.reviewThumbList.innerHTML = "";
    return;
  }

  elements.reviewDocSummary.innerHTML = `
    <article class="review-doc-card">
      <p class="panel-kicker">${text("当前文件", "Current File")}</p>
      <strong>${escapeHtml(doc.name)}</strong>
      <p>${escapeHtml(doc.workflowName)}</p>
      <div class="doc-stat-row">
        <span>${statusLabels[doc.status]}</span>
        <span>${state.pdfDoc?.numPages || 0} ${text("页", "pages")}</span>
        <span>${doc.annotations.length} ${text("条批注", "annotations")}</span>
      </div>
    </article>
  `;

  elements.annotationTabBadge.textContent = String(doc.annotations.length);
  elements.reviewSideTabs.forEach((button) => {
    button.classList.toggle("active", button.dataset.reviewTab === state.reviewSidebarTab);
  });

  const showAnnotations = state.reviewSidebarTab === "annotations";
  elements.reviewAnnotationSidebar.classList.toggle("hidden", !showAnnotations);
  elements.reviewThumbList.classList.toggle("hidden", showAnnotations);

  if (showAnnotations) {
    renderReviewAnnotationSidebarList(doc);
    return;
  }

  renderReviewThumbnailList(doc);
}

function renderReviewAnnotationSidebarList(doc) {
  const annotations = filteredAnnotations(doc);

  if (!annotations.length) {
    elements.reviewAnnotationSidebarList.innerHTML =
      `<div class="empty-card">${text("当前筛选条件下还没有批注，可以切换筛选或在图面上新增一条。", "No annotations match the current filters. Change filters or add one on the canvas.")}</div>`;
    return;
  }

  elements.reviewAnnotationSidebarList.innerHTML = annotations
    .map((annotation) => {
      const selected = annotation.id === state.selectedAnnotationId ? "selected" : "";
      const index = annotationSequence(doc, annotation.id);
      const attachmentCount = countAnnotationAttachments(annotation);
      const replyCount = Array.isArray(annotation.replies) ? annotation.replies.length : 0;
      const canSave = canSaveAnnotation(annotation, doc);
      const canDelete = canDeleteAnnotation(annotation, doc);
      const locateBadge = annotationHasModelLocation(annotation)
        ? `<span class="mini-pill locate-pill">${text("定位", "Locate")}</span>`
        : "";
      const saveLabel = text("保存批注", "Save Annotation");
      const deleteLabel = text("删除批注", "Delete Annotation");
      return `
        <article
          class="comment-card ${selected}"
          data-select-annotation="${annotation.id}"
          data-page="${annotation.page}"
          tabindex="0"
          role="button"
          aria-label="${escapeHtml(`${annotationDisplayTitle(annotation)}, ${text("第", "page")} ${annotation.page}${text(" 页", "")}`)}"
        >
          <div class="comment-card-top">
            <span class="comment-index color-${annotation.color || defaultColorForType(annotation.type)}">${index}</span>
            <div class="comment-copy">
              <strong>${escapeHtml(annotationDisplayTitle(annotation))}</strong>
              <p>${escapeHtml(truncate(annotation.note || text("未填写说明", "No description provided"), 70))}</p>
            </div>
            <div class="comment-card-actions">
              <button
                class="comment-card-action save-action"
                type="button"
                data-card-action="save"
                data-annotation-id="${annotation.id}"
                data-page="${annotation.page}"
                aria-label="${saveLabel}"
                title="${saveLabel}"
                ${canSave ? "" : "disabled"}
              >
                √
              </button>
              <button
                class="comment-card-action delete-action"
                type="button"
                data-card-action="delete"
                data-annotation-id="${annotation.id}"
                data-page="${annotation.page}"
                aria-label="${deleteLabel}"
                title="${deleteLabel}"
                ${canDelete ? "" : "disabled"}
              >
                ×
              </button>
            </div>
          </div>
          <div class="comment-meta-row">
            <span>${text("第", "Page")} ${annotation.page}${text(" 页", "")}</span>
            <span>${escapeHtml(localizedDisplayName(annotation.actor))}</span>
            <span>${formatDateTime(annotation.createdAt)}</span>
          </div>
          <div class="comment-card-foot">
            <span class="status-dot-chip ${normalizeAnnotationStatusValue(annotation.status)}">${annotationStatusDisplayLabel(annotation.status)}</span>
            <span class="comment-type-pill">${annotationToolLabels[annotation.type]}</span>
            <span class="mini-pill">${replyCount} ${text("条回复", "replies")}</span>
            <span class="mini-pill">${attachmentCount} ${text("个附件", "attachments")}</span>
            ${locateBadge}
          </div>
        </article>
      `;
    })
    .join("");

  Array.from(elements.reviewAnnotationSidebarList.querySelectorAll("[data-select-annotation]")).forEach((card) => {
    card.addEventListener("click", async (event) => {
      if (event.target instanceof HTMLElement && event.target.closest("[data-card-action]")) {
        return;
      }
      const page = Number(card.dataset.page);
      await selectSavedAnnotation(card.dataset.selectAnnotation, page);
    });
    card.addEventListener("keydown", async (event) => {
      if (event.key !== "Enter" && event.key !== " ") {
        return;
      }
      event.preventDefault();
      const page = Number(card.dataset.page);
      await selectSavedAnnotation(card.dataset.selectAnnotation, page);
    });
  });

  Array.from(elements.reviewAnnotationSidebarList.querySelectorAll("[data-card-action]")).forEach((button) => {
    button.addEventListener("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();
      const annotationId = button.dataset.annotationId;
      const page = Number(button.dataset.page);
      if (!annotationId) {
        return;
      }
      await selectSavedAnnotation(annotationId, page);
      if (button.dataset.cardAction === "save") {
        await commitAnnotation();
        return;
      }
      if (button.dataset.cardAction === "delete") {
        await deleteCurrentAnnotation();
      }
    });
  });
}

function renderReviewThumbnailList(doc) {
  const pageCount = state.pdfDoc?.numPages || 0;

  if (!pageCount) {
    elements.reviewThumbList.innerHTML = `<div class="empty-card">${text("PDF 加载完成后，这里会生成页面缩略图。", "Page thumbnails will appear here after the PDF loads.")}</div>`;
    return;
  }

  elements.reviewThumbList.innerHTML = Array.from({ length: pageCount }, (_, index) => {
    const page = index + 1;
    const count = doc.annotations.filter((annotation) => annotation.page === page).length;
    const current = page === state.currentPage ? "active" : "";
    return `
      <button class="thumb-card ${current}" data-thumb-page="${page}" type="button">
        <canvas class="thumb-canvas" data-thumb-canvas="${page}"></canvas>
        <div class="thumb-meta">
          <strong>${text("第", "Page")} ${page}${text(" 页", "")}</strong>
          <span>${count} ${text("条批注", "annotations")}</span>
        </div>
      </button>
    `;
  }).join("");

  Array.from(elements.reviewThumbList.querySelectorAll("[data-thumb-page]")).forEach((button) => {
    button.addEventListener("click", async () => {
      state.currentPage = Number(button.dataset.thumbPage);
      render();
      await renderCurrentPdfPage();
    });
  });

  void renderReviewThumbnails();
}

async function renderReviewThumbnails() {
  if (state.reviewSidebarTab !== "thumbnails" || !state.pdfDoc) {
    return;
  }

  const token = ++state.thumbnailToken;
  const canvases = Array.from(elements.reviewThumbList.querySelectorAll("[data-thumb-canvas]"));

  for (const canvas of canvases) {
    if (token !== state.thumbnailToken) {
      return;
    }

    const pageNumber = Number(canvas.dataset.thumbCanvas);
    const page = await state.pdfDoc.getPage(pageNumber);
    if (token !== state.thumbnailToken) {
      return;
    }

    const viewport = page.getViewport({ scale: 1 });
    const cssWidth = 172;
    const cssHeight = 224;
    const scale = Math.min(cssWidth / viewport.width, cssHeight / viewport.height);
    const thumbViewport = page.getViewport({ scale });
    const outputScale = window.devicePixelRatio || 1;
    const thumbContext = canvas.getContext("2d");

    canvas.width = Math.floor(thumbViewport.width * outputScale);
    canvas.height = Math.floor(thumbViewport.height * outputScale);
    canvas.style.width = `${thumbViewport.width}px`;
    canvas.style.height = `${thumbViewport.height}px`;
    thumbContext.setTransform(outputScale, 0, 0, outputScale, 0, 0);

    await page.render({
      canvasContext: thumbContext,
      viewport: thumbViewport,
    }).promise;
  }
}

function renderSelectedDocumentMeta() {
  const doc = currentDocument();

  if (!doc) {
    const footerLabels = reviewFooterButtonLabels();
    elements.annotationActionGroup.classList.remove("hidden");
    elements.annotationAttachmentToolbar.classList.remove("hidden");
    elements.remarksActionGroup.classList.remove("hidden");
    elements.replySection.classList.remove("hidden");
    elements.replyComposer.classList.remove("hidden");
    state.toolbarPreviewTool = null;
    elements.reviewProjectLine.textContent = text("CDE文件管理系统 / PDF Review Workspace", "CDE File Management System / PDF Review Workspace");
    elements.documentTitle.textContent = text("请选择一份 PDF", "Select a PDF");
    elements.documentVersion.textContent = "V1";
    elements.documentMeta.textContent = text("文件上传后，这里会显示 PDF 按页预览，并在 PDF 审阅工作台中完成批注。", "After upload, PDF page previews appear here and annotations are completed in the PDF review workspace.");
    elements.documentStatus.className = "status-pill neutral";
    elements.documentStatus.textContent = text("未选择", "Not Selected");
    elements.documentPageSummary.textContent = "0 / 0";
    elements.pageAnnotationSummary.textContent = text("本页 0 条", "0 on this page");
    elements.pageIndicator.textContent = "0 / 0";
    syncInputValue(elements.zoomIndicator, "100%");
    elements.reviewFooterNote.textContent = text("支持点击已有批注查看属性，也支持在画布上拖拽新增批注区域。", "Click an existing annotation to view properties, or drag on the canvas to create one.");
    elements.reviewPermissionHint.textContent = text("选中文件后显示当前节点权限。", "Select a file to view step permissions.");
    elements.annotationModeButton.disabled = true;
    elements.annotationModeButton.title = text("选择工具", "Select Tool");
    elements.annotationModeButton.setAttribute("aria-label", text("选择工具", "Select Tool"));
    elements.cancelDraftButton.disabled = true;
    elements.prevPageButton.disabled = true;
    elements.nextPageButton.disabled = true;
    elements.zoomOutButton.disabled = true;
    elements.zoomInButton.disabled = true;
    elements.zoomIndicator.disabled = true;
    elements.fitViewButton.disabled = true;
    elements.fitViewButton.title = text("进入全屏", "Enter Full Screen");
    elements.fitViewButton.setAttribute("aria-label", text("进入全屏", "Enter Full Screen"));
    elements.toolButtons.forEach((button) => {
      button.disabled = true;
    });
    elements.toolbarFauxButtons.forEach((button) => {
      button.disabled = true;
    });
    elements.toolbarColorButtons.forEach((button) => {
      button.disabled = true;
    });
    elements.exportButton.disabled = true;
    elements.exportButton.textContent = footerLabels.export;
    elements.exportButton.classList.remove("hidden");
    elements.commentReportButton.disabled = true;
    elements.commentReportButton.textContent = footerLabels.commentReport;
    elements.commentReportButton.classList.remove("hidden");
    elements.printButton.disabled = true;
    elements.printButton.textContent = footerLabels.print;
    elements.printButton.classList.add("hidden");
    elements.shareButton.disabled = true;
    elements.shareButton.textContent = footerLabels.share;
    elements.shareButton.classList.add("hidden");
    elements.startFlowButton.disabled = true;
    elements.startFlowButton.textContent = footerLabels.startFlow;
    elements.saveRemarksButton.disabled = true;
    elements.replyButton.disabled = true;
    elements.remarksInput.disabled = true;
    elements.replyInput.disabled = true;
    elements.cancelAnnotationEditButton.disabled = true;
    elements.deleteAnnotationButton.disabled = true;
    elements.viewerEmpty.classList.remove("hidden");
    elements.canvasWrap.classList.add("hidden");
    elements.reviewPageFloater.classList.add("hidden");
    elements.viewerFrame.classList.remove("pan-mode", "panning");
    elements.workflowSteps.innerHTML = `<div class="empty-card">${text("选中文件后，这里显示流程进度。", "Select a file to show workflow progress here.")}</div>`;
    elements.activityList.innerHTML = `<div class="empty-card">${text("流程动作和导出记录会显示在这里。", "Workflow actions and export records appear here.")}</div>`;
    syncReviewCursorState();
    return;
  }

  const pageCount = state.pdfDoc?.numPages || 0;
  const pageAnnotations = doc.annotations.filter((annotation) => annotation.page === state.currentPage).length;
  const readOnlyView = isPdfWorkspaceReadOnly(doc);
  const annotationCreateAllowed = canCreateAnnotation(doc);
  const annotationReplyAllowed = canReplyAnnotation(doc);
  const exportAllowed = canExportReview(doc);
  const currentAnnotation = currentSelectedAnnotation();
  const permissionMeta = reviewNodePermissionMeta(doc);
  const footerLabels = reviewFooterButtonLabels(doc);

  if (!annotationCreateAllowed) {
    state.annotationMode = false;
    if (state.draftAnnotation) {
      state.draftAnnotation = null;
    }
  }

  if (readOnlyView && !["hand", "comment", "clipboard"].includes(state.toolbarPreviewTool || "")) {
    state.toolbarPreviewTool = null;
  }

  elements.annotationActionGroup.classList.toggle("hidden", readOnlyView);
  elements.annotationAttachmentToolbar.classList.toggle("hidden", readOnlyView);
  elements.remarksActionGroup.classList.toggle("hidden", readOnlyView);
  elements.replySection.classList.toggle("hidden", readOnlyView);
  elements.replyComposer.classList.toggle("hidden", readOnlyView);

  elements.reviewProjectLine.textContent = `${localizedDisplayName(doc.workflowName) || text("未关联流程", "No Linked Workflow")} / ${workflowHealthMeta(doc).stage} · ${permissionMeta.compact}`;
  elements.documentTitle.textContent = doc.name;
  elements.documentVersion.textContent = doc.version;
  elements.documentMeta.textContent = `${formatBytes(doc.size)} · ${text("上传于", "Uploaded")} ${formatDateTime(doc.uploadedAt)} · ${pageCount} ${text("页", "pages")}`;
  elements.documentStatus.className = `status-pill ${doc.status}`;
  elements.documentStatus.textContent = statusLabels[doc.status];
  elements.documentPageSummary.textContent = `${state.currentPage} / ${pageCount}`;
  elements.pageAnnotationSummary.textContent = text(`本页 ${pageAnnotations} 条`, `${pageAnnotations} on this page`);
  elements.pageIndicator.textContent = `${state.currentPage} / ${pageCount}`;
  syncInputValue(elements.zoomIndicator, formatZoomIndicatorValue());
  elements.reviewPermissionHint.textContent = permissionMeta.summary;
  elements.reviewFooterNote.textContent = reviewWorkspaceFooterNote(doc, { readOnlyView });

  elements.annotationModeButton.disabled = !annotationCreateAllowed;
  const annotationModeButtonLabel =
    state.toolbarPreviewTool === "hand" || isReviewAnnotationToolSuspended()
      ? text("返回绘制工具", "Return to Drawing")
      : currentReviewConfiguredTool()
        ? text("退出批注模式", "Exit Annotation Mode")
        : text("选择工具", "Select Tool");
  elements.annotationModeButton.title = annotationModeButtonLabel;
  elements.annotationModeButton.setAttribute(
    "aria-label",
    annotationModeButtonLabel,
  );
  elements.cancelDraftButton.disabled = !state.draftAnnotation || !annotationCreateAllowed;
  elements.prevPageButton.disabled = state.currentPage <= 1;
  elements.nextPageButton.disabled = state.currentPage >= pageCount;
  elements.zoomOutButton.disabled = false;
  elements.zoomInButton.disabled = false;
  elements.zoomIndicator.disabled = false;
  elements.fitViewButton.disabled = false;
  elements.fitViewButton.title = state.reviewFullscreen
    ? text("退出全屏", "Exit Full Screen")
    : text("进入全屏", "Enter Full Screen");
  elements.fitViewButton.setAttribute(
    "aria-label",
    state.reviewFullscreen ? text("退出全屏", "Exit Full Screen") : text("进入全屏", "Enter Full Screen"),
  );
  elements.toolButtons.forEach((button) => {
    button.disabled = !annotationCreateAllowed;
  });
  elements.toolbarFauxButtons.forEach((button) => {
    const fauxTool = button.dataset.fauxTool || "";
    button.disabled = readOnlyView && !["hand", "comment", "clipboard"].includes(fauxTool);
  });
  elements.toolbarColorButtons.forEach((button) => {
    button.disabled = !annotationCreateAllowed;
  });
  elements.exportButton.disabled = !exportAllowed;
  elements.exportButton.textContent = footerLabels.export;
  elements.exportButton.classList.toggle("hidden", !exportAllowed);
  elements.commentReportButton.disabled = !exportAllowed;
  elements.commentReportButton.textContent = footerLabels.commentReport;
  elements.commentReportButton.classList.toggle("hidden", !exportAllowed);
  elements.printButton.disabled = false;
  elements.printButton.textContent = footerLabels.print;
  elements.printButton.classList.add("hidden");
  elements.shareButton.disabled = false;
  elements.shareButton.textContent = footerLabels.share;
  elements.shareButton.classList.add("hidden");
  elements.startFlowButton.disabled = !canStartFlow(doc);
  elements.startFlowButton.textContent = canStartFlow(doc)
    ? footerLabels.startFlow
    : doc.status === "uploaded"
      ? text("等待有权限成员发起", "Waiting for Launcher")
      : doc.status === "rejected"
        ? text("等待有权限成员重发", "Waiting for Relaunch")
        : footerLabels.startFlow;
  const remarksSaving = isActionPending("remarks:save");
  elements.saveRemarksButton.disabled = remarksSaving || !annotationCreateAllowed;
  setButtonBusy(elements.saveRemarksButton, remarksSaving, text("保存备注", "Save Remarks"), text("保存中…", "Saving..."));
  elements.replyButton.disabled = isActionPending("reply:send") || !currentAnnotation || !annotationReplyAllowed;
  elements.remarksInput.disabled = !annotationCreateAllowed;
  elements.replyInput.disabled = !currentAnnotation || !annotationReplyAllowed;
  elements.viewerEmpty.classList.toggle("hidden", Boolean(state.pdfDoc));
  elements.canvasWrap.classList.toggle("hidden", !state.pdfDoc);
  elements.reviewPageFloater.classList.toggle("hidden", !state.pdfDoc);
  elements.annotationLayer.classList.toggle("interactive", isReviewDrawModeActive(doc));
  elements.viewerFrame.classList.toggle("pan-mode", currentReviewPrimaryTool() === "hand");
  syncReviewCursorState();

  syncInputValue(elements.workflowName, doc.workflowName);
  syncInputValue(elements.initiatorName, doc.initiator);
  syncInputValue(elements.reviewerSelect, doc.reviewer);
  syncInputValue(elements.approverSelect, doc.approver);
  syncInputValue(elements.dueDate, doc.dueDate);
}

function renderWorkflowOverview() {
  const doc = currentDocument();
  if (!doc) {
    elements.workflowHealthBadge.className = "mini-pill signal-pill neutral";
    elements.workflowHealthBadge.textContent = text("待发起", "Ready");
    elements.workflowSummaryGrid.innerHTML =
      `<div class="empty-card">${escapeHtml(text("选中文件后，这里会显示当前节点、责任人、截止日期和下一步动作。", "Select a file to show the current step, owner, due date, and next action."))}</div>`;
    return;
  }

  const issues = issueStats(doc);
  const health = workflowHealthMeta(doc, issues);

  elements.workflowHealthBadge.className = `mini-pill signal-pill ${health.tone}`;
  elements.workflowHealthBadge.textContent = health.label;
  elements.workflowSummaryGrid.innerHTML = [
    workflowStatCard(text("当前节点", "Current Step"), health.stage, health.stageNote, health.tone),
    workflowStatCard(text("当前责任人", "Current Owner"), health.owner, health.ownerNote, "info"),
    workflowStatCard(text("截止日期", "Due Date"), health.dueLabel, health.dueNote, health.dueTone),
    workflowStatCard(text("问题闭环率", "Issue Closure Rate"), `${health.closeRate}%`, health.closeRateNote, issues.open ? "alert" : "success"),
  ].join("");
}

function renderWorkflowActions() {
  const doc = currentDocument();
  if (!doc) {
    elements.workflowActions.innerHTML = "";
    return;
  }

  const actions = reviewWorkflowActionDefinitions(doc).map((item) => actionButton(item.action, item.label));

  elements.workflowActions.innerHTML = actions.join("");
  Array.from(elements.workflowActions.querySelectorAll(".action-button")).forEach((button) => {
    button.addEventListener("click", async () => {
      await postJson(`/api/documents/${doc.id}/actions`, {
        action: button.dataset.action,
        actor: workflowActorLabel(doc),
      });
      await refreshDocuments();
    });
  });
}

function renderWorkflowSteps() {
  const doc = currentDocument();
  if (!doc) {
    return;
  }

  const steps = [
    {
      title: text("发起者", "Initiator"),
      owner: doc.initiator,
      state: doc.status === "uploaded" || doc.status === "rejected" ? "current" : "done",
      text:
        doc.status === "rejected"
          ? text("文件已退回，等待发起者修订后重新提交", "The file was returned and is waiting for the initiator to revise and resubmit")
          : doc.status === "uploaded"
            ? text("文件已上传，待发起流程", "File uploaded and waiting for workflow launch")
            : text("流程已由发起者提交", "Workflow submitted by the initiator"),
    },
    {
      title: text("初始审阅", "Initial Review"),
      owner: doc.reviewer,
      state: doc.status === "in_review" ? "current" : doc.status === "final_review" || doc.status === "approved" ? "done" : "",
      text:
        doc.status === "in_review"
          ? text("当前处于初审节点，可以继续批注、退回或提交终审", "Currently in initial review. You can continue annotating, return, or submit for final review")
          : doc.status === "final_review" || doc.status === "approved"
            ? text("初审已经完成", "Initial review completed")
            : text("等待发起者提交", "Waiting for initiator submission"),
    },
    {
      title: text("最终审阅", "Final Review"),
      owner: doc.approver,
      state: doc.status === "final_review" ? "current" : doc.status === "approved" ? "done" : "",
      text:
        doc.status === "final_review"
          ? text("当前处于终审节点，可以批准归档或驳回", "Currently in final review. You can approve for archive or reject")
          : doc.status === "approved"
            ? text("文档已完成终审并归档", "Document completed final review and was archived")
            : text("等待初审通过后进入终审", "Waiting for initial review approval before final review"),
    },
  ];

  elements.workflowSteps.innerHTML = steps
    .map(
      (step) => `
        <article class="step-card ${step.state}">
          <strong>${step.title}</strong>
          <p>${escapeHtml(step.owner)}</p>
          <p>${escapeHtml(step.text)}</p>
        </article>
      `,
    )
    .join("");
}

function renderActivity() {
  const doc = currentDocument();
  if (!doc) {
    return;
  }

  if (!doc.activity.length) {
    elements.activityList.innerHTML = `<div class="empty-card">${escapeHtml(text("暂无活动记录。", "No activity records yet."))}</div>`;
    return;
  }

  elements.activityList.innerHTML = [...doc.activity]
    .reverse()
    .map(
      (item) => `
        <article class="item-card">
          <div class="item-meta">
            <strong>${escapeHtml(localizedDisplayName(item.actor))}</strong>
            <span class="mini-pill">${escapeHtml(localizedDisplayName(item.label))}</span>
          </div>
          <p>${escapeHtml(localizeMixedText(item.note))}</p>
          <p>${formatDateTime(item.timestamp)}</p>
        </article>
      `,
    )
    .join("");
}

function renderIssueModule() {
  const doc = currentDocument();
  if (!doc) {
    elements.issueModuleBadge.className = "mini-pill signal-pill neutral";
    elements.issueModuleBadge.textContent = text("0 项", "0 Items");
    elements.issueSummaryGrid.innerHTML =
      `<div class="empty-card">${escapeHtml(text("从审阅模块产生的批注会在这里汇总成 issue，按状态持续跟踪。", "Annotations from the review module are summarized here as issues and tracked by status."))}</div>`;
    elements.issueBoard.innerHTML = "";
    return;
  }

  const issues = issueStats(doc);
  const badgeTone = issues.open ? "alert" : issues.inProgress ? "info" : issues.total ? "success" : "neutral";
  elements.issueModuleBadge.className = `mini-pill signal-pill ${badgeTone}`;
  elements.issueModuleBadge.textContent = text(`${issues.total} 项`, `${issues.total} items`);

  elements.issueSummaryGrid.innerHTML = [
    workflowStatCard(text("总问题数", "Total Issues"), String(issues.total), issues.total ? text("来自审阅批注", "From review annotations") : text("还没有 issue", "No issues yet"), "info"),
    workflowStatCard(text("待解决", "Open"), String(issues.open), issues.open ? text("需要优先跟进", "Needs priority follow-up") : text("当前为空", "None currently"), issues.open ? "alert" : "neutral"),
    workflowStatCard(text("处理中", "In Progress"), String(issues.inProgress), issues.inProgress ? text("已有负责人推进", "Owner is progressing") : text("当前为空", "None currently"), issues.inProgress ? "info" : "neutral"),
    workflowStatCard(text("已解决", "Resolved"), String(issues.resolved), issues.resolved ? text("已进入闭环", "Closed") : text("尚未闭环", "Not closed yet"), issues.resolved ? "success" : "neutral"),
  ].join("");

  const columns = [
    { status: "open", title: text("未解决", "Open"), hint: text("待认领 / 待修订", "Needs owner / revision"), items: doc.annotations.filter((item) => item.status === "open") },
    {
      status: "in_progress",
      title: text("进行中", "In Progress"),
      hint: text("处理中 / 待确认", "Being handled / pending confirmation"),
      items: doc.annotations.filter((item) => item.status === "in_progress"),
    },
    { status: "resolved", title: text("已解决", "Resolved"), hint: text("已闭环 / 可归档", "Closed / ready to archive"), items: doc.annotations.filter((item) => item.status === "resolved") },
  ];

  elements.issueBoard.innerHTML = columns
    .map((column) => {
      const cards = column.items.length
        ? [...column.items]
            .sort((left, right) => right.createdAt.localeCompare(left.createdAt))
            .map((annotation) => {
              const index = annotationSequence(doc, annotation.id);
              const attachmentCount = countAnnotationAttachments(annotation);
              const replyCount = Array.isArray(annotation.replies) ? annotation.replies.length : 0;
              const locateBadge = annotationHasModelLocation(annotation)
                ? `<span class="mini-pill locate-pill">${text("定位", "Locate")}</span>`
                : "";
              return `
                <button class="issue-card" data-open-issue="${annotation.id}" data-page="${annotation.page}" type="button">
                  <div class="issue-card-top">
                    <span class="comment-index color-${annotation.color || defaultColorForType(annotation.type)}">${index}</span>
                    <div class="issue-copy">
                      <strong>${escapeHtml(annotationDisplayTitle(annotation))}</strong>
                      <p>${escapeHtml(truncate(annotation.note || text("未填写说明", "No description provided"), 82))}</p>
                    </div>
                  </div>
                  <div class="issue-card-meta">
                    <span class="comment-type-pill">${text("第", "Page")} ${annotation.page}${text(" 页", "")}</span>
                    <span class="comment-type-pill">${annotationToolLabels[annotation.type]}</span>
                    <span class="comment-type-pill">${escapeHtml(localizedDisplayName(annotation.actor))}</span>
                  </div>
                  <div class="issue-card-foot">
                    <span class="status-dot-chip ${normalizeAnnotationStatusValue(annotation.status)}">${annotationStatusDisplayLabel(annotation.status)}</span>
                    <span class="mini-pill">${replyCount} ${text("条回复", "replies")}</span>
                    <span class="mini-pill">${attachmentCount} ${text("个附件", "attachments")}</span>
                    ${locateBadge}
                  </div>
                </button>
              `;
            })
            .join("")
        : `<div class="empty-card compact-empty">${text("当前列暂无 issue。", "No issues in this column.")}</div>`;

      return `
        <section class="issue-column ${column.status}">
          <div class="issue-column-head">
            <div>
              <strong>${column.title}</strong>
              <p>${column.hint}</p>
            </div>
            <span class="mini-pill">${column.items.length}</span>
          </div>
          <div class="issue-column-list">${cards}</div>
        </section>
      `;
    })
    .join("");

  Array.from(elements.issueBoard.querySelectorAll("[data-open-issue]")).forEach((button) => {
    button.addEventListener("click", async () => {
      await openIssueInReview(button.dataset.openIssue, Number(button.dataset.page));
    });
  });
}

function renderReportModule() {
  const doc = currentDocument();
  if (!doc) {
    elements.reportModuleBadge.className = "mini-pill signal-pill neutral";
    elements.reportModuleBadge.textContent = text("待生成", "Pending");
    elements.reportChecklist.innerHTML =
      `<div class="empty-card">${text("选中文件后，这里会显示归档条件、报告摘要和最近导出记录。", "Select a file to show archive conditions, report summary, and recent export records.")}</div>`;
    elements.reportPreview.innerHTML = "";
    elements.reportActivityList.innerHTML = "";
    elements.workflowExportButton.disabled = true;
    elements.workflowExportButton.textContent = reviewFooterButtonLabels().workflowExport;
    elements.copyReportButton.disabled = true;
    elements.openLatestExportButton.disabled = true;
    return;
  }

  const issues = issueStats(doc);
  const reportState = reportStatusMeta(doc, issues);
  const checklist = reportChecklist(doc, issues);
  const reportEvents = doc.activity
    .filter((item) => ["发起流程", "提交终审", "批准归档", "驳回修改", "导出文件"].includes(item.label))
    .slice()
    .reverse();

  elements.reportModuleBadge.className = `mini-pill signal-pill ${reportState.tone}`;
  elements.reportModuleBadge.textContent = reportState.label;
  elements.workflowExportButton.disabled = !canExportReview(doc);
  elements.workflowExportButton.textContent = reviewFooterButtonLabels(doc).workflowExport;
  elements.copyReportButton.disabled = false;
  elements.openLatestExportButton.disabled = !doc.exportUrl;

  elements.reportChecklist.innerHTML = checklist
    .map(
      (item) => `
        <article class="report-check ${item.tone}">
          <span class="report-check-mark">${item.symbol}</span>
          <div>
            <strong>${localizedDisplayName(item.title)}</strong>
            <p>${escapeHtml(localizeMixedText(item.note))}</p>
          </div>
        </article>
      `,
    )
    .join("");

  elements.reportPreview.innerHTML = `
    <article class="report-preview-card">
      <div class="mini-section-head">
        <strong>${text("归档摘要", "Archive Summary")}</strong>
        <span class="mini-pill">${localizedDisplayName(reportState.summaryLabel)}</span>
      </div>
      <div class="report-summary-grid">
        <div class="report-summary-item">
          <span>${text("文件", "File")}</span>
          <strong>${escapeHtml(doc.name)}</strong>
        </div>
        <div class="report-summary-item">
          <span>${text("流程", "Workflow")}</span>
          <strong>${escapeHtml(localizedDisplayName(doc.workflowName))}</strong>
        </div>
        <div class="report-summary-item">
          <span>${text("参与人", "Participants")}</span>
          <strong>${escapeHtml([doc.initiator, doc.reviewer, doc.approver].map(localizedDisplayName).join(" / "))}</strong>
        </div>
        <div class="report-summary-item">
          <span>${text("问题状态", "Issue Status")}</span>
          <strong>${issues.total} ${text("项", "items")} / ${text("已解决", "Resolved")} ${issues.resolved}</strong>
        </div>
      </div>
      <p class="report-summary-note">${escapeHtml(doc.remarks || text("还没有填写整份文件备注，建议在归档前补充审批结论和执行要求。", "No document-level remarks yet. Add approval conclusions and execution requirements before archiving."))}</p>
      <div class="report-export-row">
        <span class="mini-pill">${statusLabels[doc.status]}</span>
        <span class="mini-pill">${doc.exportUrl ? text("已有导出文件", "Export available") : text("未导出", "Not exported")}</span>
      </div>
    </article>
  `;

  if (!reportEvents.length) {
    elements.reportActivityList.innerHTML = `<div class="empty-card">${text("流程推进后，这里会沉淀报告相关动作和导出记录。", "Report actions and export records will appear here as the workflow progresses.")}</div>`;
    return;
  }

  elements.reportActivityList.innerHTML = reportEvents
    .map(
      (item) => `
        <article class="item-card">
          <div class="item-meta">
            <strong>${escapeHtml(localizedDisplayName(item.actor))}</strong>
            <span class="mini-pill">${escapeHtml(localizedDisplayName(item.label))}</span>
          </div>
          <p>${escapeHtml(localizeMixedText(item.note))}</p>
          <p>${formatDateTime(item.timestamp)}</p>
        </article>
      `,
    )
    .join("");
}

function renderRemarks() {
  const doc = currentDocument();
  if (!doc) {
    elements.remarksInput.value = "";
    return;
  }
  syncInputValue(elements.remarksInput, doc.remarks || "");
}

function renderAnnotationDetail() {
  const target = currentAnnotationTarget();
  const doc = currentDocument();
  const readOnlyView = isPdfWorkspaceReadOnly(doc);

  if (!doc || !target) {
    elements.annotationDetailHeading.textContent = text("未选中批注", "No annotation selected");
    elements.annotationDetailBadge.textContent = "--";
    setElementText(elements.annotationMetaLine, readOnlyView
      ? text("只读模式：选择批注后可查看详情、证据和讨论记录。", "Read-only mode: select an annotation to review details, evidence, and discussion.")
      : text("选择图面批注，或使用工具新建批注。", "Select a markup on the drawing, or create a new annotation with the tools."));
    elements.annotationEmptyCard.innerHTML = `
      <strong>${escapeHtml(text("选择或创建一条批注", "Select or create an annotation"))}</strong>
      <p>${escapeHtml(readOnlyView
        ? text("选择批注后，右侧会显示详情、证据和讨论记录。", "Select an annotation to review details, evidence, and discussion.")
        : text("在图面或左侧列表中选择批注。右侧会集中显示问题详情、证据和处理讨论。", "Select a markup on the drawing or from the list. Details, evidence, and discussion will appear here."))}</p>
    `;
    elements.annotationEmptyCard.classList.remove("hidden");
    elements.annotationDetailBody.classList.add("hidden");
    elements.cancelAnnotationEditButton.disabled = true;
    elements.saveAnnotationButton.disabled = true;
    elements.resolveQuickButton.disabled = true;
    elements.deleteAnnotationButton.disabled = true;
    syncInputValue(elements.annotationActorInput, "--");
    syncInputValue(elements.annotationCreatedInput, "--");
    syncInputValue(elements.annotationPageInput, "--");
    syncInputValue(elements.annotationTypeInput, "--");
    return;
  }

  const annotation = target.annotation;
  const editor = state.annotationEditor;
  const targetIsDraft = target.kind === "draft";
  const canEdit = targetIsDraft ? canCreateAnnotation(doc) : canChangeAnnotation(annotation, doc);
  const canStatusChange = targetIsDraft ? false : canChangeAnnotationStatus(annotation, doc);
  const canSave = targetIsDraft ? canCreateAnnotation(doc) : canSaveAnnotation(annotation, doc);
  const canDelete = targetIsDraft ? canCreateAnnotation(doc) : canDeleteAnnotation(annotation, doc);

  elements.annotationEmptyCard.classList.add("hidden");
  elements.annotationDetailBody.classList.remove("hidden");
  const sequenceLabel = targetIsDraft ? text("草稿", "Draft") : `#${annotationSequence(doc, annotation.id)}`;
  const statusPreview = targetIsDraft ? inferredAnnotationStatus(state.draftAnnotation || {}, doc, editor) : inferredAnnotationStatus(annotation, doc, editor);
  elements.annotationDetailHeading.textContent = targetIsDraft ? text("新增批注草稿", "New Annotation Draft") : annotationDisplayTitle(annotation);
  elements.annotationDetailBadge.textContent = sequenceLabel;
  setElementText(
    elements.annotationMetaLine,
    [
      sequenceLabel,
      annotationTypeLabels[annotation.type],
      text(`第 ${annotation.page} 页`, `Page ${annotation.page}`),
      annotationStatusDisplayLabel(statusPreview),
    ].filter(Boolean).join(" · "),
  );

  syncInputValue(elements.annotationTitleInput, editor.title);
  syncInputValue(elements.annotationDetailInput, editor.note);
  syncInputValue(elements.annotationActorInput, targetIsDraft ? workflowActorLabel(doc) : annotation.actor);
  syncInputValue(
    elements.annotationCreatedInput,
    targetIsDraft ? text("待保存", "Pending Save") : formatDateTime(annotation.createdAt),
  );
  syncInputValue(elements.annotationPageInput, text(`第 ${annotation.page} 页`, `Page ${annotation.page}`));
  syncInputValue(elements.annotationTypeInput, annotationTypeLabels[annotation.type]);

  const autoStatus = statusPreview;
  editor.status = autoStatus;
  if (elements.annotationStatusGroup) {
    elements.annotationStatusGroup.innerHTML = `<span class="mini-pill signal-pill ${annotationStatusSignalTone(autoStatus)} annotation-status-${autoStatus}">${escapeHtml(annotationStatusDisplayLabel(autoStatus))}</span>`;
  }
  elements.detailColorButtons.forEach((button) => {
    button.classList.toggle("active", button.dataset.detailColor === editor.color);
    button.disabled = !canEdit;
  });

  elements.annotationTitleInput.disabled = !canEdit;
  elements.annotationDetailInput.disabled = !canEdit;
  const annotationSaving = isActionPending("annotation:save");
  elements.cancelAnnotationEditButton.disabled = annotationSaving || !canSave;
  elements.cancelAnnotationEditButton.textContent = targetIsDraft ? text("取消草稿", "Cancel Draft") : text("取消修改", "Cancel Changes");
  elements.saveAnnotationButton.disabled = annotationSaving || !canSave;
  setButtonBusy(
    elements.saveAnnotationButton,
    annotationSaving,
    targetIsDraft
      ? text("提交批注", "Submit Annotation")
      : canEdit
        ? text("更新批注", "Update Annotation")
        : text("保存状态", "Save Status"),
    text("保存中…", "Saving..."),
  );
  elements.resolveQuickButton.classList.add("hidden");
  elements.resolveQuickButton.disabled = true;
  elements.resolveQuickButton.textContent = text("自动判断状态", "Auto Status");
  const annotationDeleting = isActionPending("annotation:delete");
  elements.deleteAnnotationButton.disabled = annotationSaving || annotationDeleting || !canDelete;
  setButtonBusy(
    elements.deleteAnnotationButton,
    annotationDeleting,
    targetIsDraft ? text("删除草稿", "Delete Draft") : text("删除批注", "Delete Annotation"),
    text("删除中…", "Deleting..."),
  );
}

function renderAnnotationAttachments() {
  const target = currentAnnotationTarget();
  const attachments = target ? state.annotationEditor.attachments || [] : [];
  const doc = currentDocument();
  const canEdit =
    target && doc
      ? target.kind === "draft"
        ? canCreateAnnotation(doc)
        : canChangeAnnotation(target.annotation, doc)
      : false;

  elements.attachImageButton.disabled = !target || !canEdit;
  elements.attachFileButton.disabled = !target || !canEdit;
  elements.attachLinkButton.disabled = !target || !canEdit;
  elements.attachmentCountBadge.textContent = text(`${attachments.length} 项`, `${attachments.length} items`);
  if (elements.annotationEvidenceDisclosure) {
    elements.annotationEvidenceDisclosure.open = Boolean(target && attachments.length);
  }
  renderAttachmentHelperText(target, attachments.length);

  if (!target) {
    elements.annotationAttachmentList.innerHTML =
      text('<div class="empty-card">保存或选中一条批注后，可以补充现场照片、参考文件或链接。</div>', '<div class="empty-card">Save or select an annotation to add site photos, reference files, or links.</div>');
    return;
  }
  renderAttachmentCollection(elements.annotationAttachmentList, attachments, {
    emptyText: text("当前批注还没有附件。可以补充现场图、参考资料或外部链接。", "This annotation has no attachments yet. Add site images, reference files, or external links."),
    onRemove: canEdit ? removeAnnotationAttachment : null,
  });
}

function renderAttachmentHelperText(target, attachmentCount) {
  if (!target) {
    elements.attachmentHelperText.textContent = text("选择批注后可添加证据附件。", "Select an annotation to add evidence.");
    return;
  }

  if (elements.attachmentBlock.classList.contains("drag-active")) {
    elements.attachmentHelperText.textContent = text("松手即可把图片或文件加到当前批注。", "Release to add images or files to the current annotation.");
    return;
  }

  const countLeft = Math.max(0, MAX_ATTACHMENT_COUNT - attachmentCount);
  elements.attachmentHelperText.textContent = attachmentCount
    ? text(`已附加 ${attachmentCount} 项证据，还可继续添加 ${countLeft} 项。`, `${attachmentCount} evidence item(s) attached. You can add ${countLeft} more.`)
    : text("暂无证据附件。展开上方操作可添加图片、文件或链接。", "No evidence attached. Expand the action above to add an image, file, or link.");
}

function renderReplyAttachmentHelperText(attachmentCount) {
  if (elements.replyAttachmentBlock.classList.contains("drag-active")) {
    elements.replyAttachmentHelperText.textContent = text("松手即可把图片或文件加入当前回复。", "Release to add images or files to the current reply.");
    return;
  }

  const countLeft = Math.max(0, MAX_ATTACHMENT_COUNT - attachmentCount);
  elements.replyAttachmentHelperText.textContent = attachmentCount
    ? text(`当前回复已附加 ${attachmentCount} 项证据，还可继续添加 ${countLeft} 项。`, `${attachmentCount} reply evidence item(s) attached. You can add ${countLeft} more.`)
    : text("回复证据为可选项，需要时再展开添加。", "Reply evidence is optional. Expand this only when needed.");
}

function renderAttachmentCollection(container, attachments, { emptyText, onRemove = null } = {}) {
  if (!attachments.length) {
    container.innerHTML = `<div class="empty-card">${emptyText}</div>`;
    return;
  }

  const removable = typeof onRemove === "function";
  const imageAttachments = attachments.filter((item) => item.kind === "image");
  const fileAttachments = attachments.filter((item) => item.kind === "document");
  const linkAttachments = attachments.filter((item) => item.kind === "link");
  const sections = [];

  if (imageAttachments.length) {
    sections.push(`
      <section class="attachment-section">
        <div class="attachment-section-head">
          <strong>${text("参考图片", "Reference Images")} (${imageAttachments.length})</strong>
        </div>
        <div class="attachment-image-grid">
          ${imageAttachments.map((attachment) => attachmentImageCard(attachment, removable)).join("")}
        </div>
      </section>
    `);
  }

  if (fileAttachments.length) {
    sections.push(`
      <section class="attachment-section">
        <div class="attachment-section-head">
          <strong>${text("参考文件", "Reference Files")} (${fileAttachments.length})</strong>
        </div>
        <div class="attachment-file-list">
          ${fileAttachments.map((attachment) => attachmentFileCard(attachment, removable)).join("")}
        </div>
      </section>
    `);
  }

  if (linkAttachments.length) {
    sections.push(`
      <section class="attachment-section">
        <div class="attachment-section-head">
          <strong>${text("外部链接", "External Links")} (${linkAttachments.length})</strong>
        </div>
        <div class="attachment-file-list">
          ${linkAttachments.map((attachment) => attachmentLinkCard(attachment, removable)).join("")}
        </div>
      </section>
    `);
  }

  container.innerHTML = sections.join("");
  Array.from(container.querySelectorAll("[data-preview-attachment]")).forEach((button) => {
    const attachment = attachments.find((item) => item.id === button.dataset.previewAttachment);
    if (attachment) {
      button.addEventListener("click", () => {
        openAttachmentPreview(attachment);
      });
    }
  });
  Array.from(container.querySelectorAll("[data-remove-attachment]")).forEach((button) => {
    button.addEventListener("click", () => {
      onRemove?.(button.dataset.removeAttachment);
    });
  });
}

function attachmentImageCard(attachment, removable) {
  const src = attachment.previewUrl || attachment.url || "";
  return `
    <article class="attachment-image-card">
      ${removable ? `<button class="attachment-remove" data-remove-attachment="${attachment.id}" type="button">×</button>` : ""}
      <button class="attachment-image-frame" data-preview-attachment="${attachment.id}" type="button">
        ${src ? `<img src="${escapeHtml(src)}" alt="${escapeHtml(attachment.name)}" />` : `<span>${text("图片", "Image")}</span>`}
      </button>
      <div class="attachment-meta">
        <strong>${escapeHtml(attachment.name)}</strong>
        <span>${formatBytes(Number(attachment.size || 0))}${attachment.url ? "" : ` · ${text("待保存", "Pending Save")}`}</span>
      </div>
    </article>
  `;
}

function attachmentFileCard(attachment, removable) {
  return `
    <article class="attachment-file-card">
      <div class="attachment-file-icon">${text("文", "FILE")}</div>
      <div class="attachment-file-copy">
        <strong>${escapeHtml(attachment.name)}</strong>
        <span>${formatBytes(Number(attachment.size || 0))} · ${escapeHtml(attachment.mimeType || text("文件", "File"))}${attachment.url ? "" : ` · ${text("待保存", "Pending Save")}`}</span>
      </div>
      <div class="attachment-file-actions">
        ${attachment.url ? `<a class="attachment-link" href="${escapeHtml(attachment.url)}" target="_blank" rel="noreferrer">${text("查看", "View")}</a>` : `<span class="attachment-pending">${text("待保存", "Pending Save")}</span>`}
        ${removable ? `<button class="attachment-remove" data-remove-attachment="${attachment.id}" type="button">${text("删除", "Delete")}</button>` : ""}
      </div>
    </article>
  `;
}

function attachmentLinkCard(attachment, removable) {
  return `
    <article class="attachment-file-card">
      <div class="attachment-file-icon link">${text("链", "LINK")}</div>
      <div class="attachment-file-copy">
        <strong>${escapeHtml(attachment.name)}</strong>
        <span>${escapeHtml(attachment.url)}</span>
      </div>
      <div class="attachment-file-actions">
        <a class="attachment-link" href="${escapeHtml(attachment.url)}" target="_blank" rel="noreferrer">${text("打开", "Open")}</a>
        ${removable ? `<button class="attachment-remove" data-remove-attachment="${attachment.id}" type="button">${text("删除", "Delete")}</button>` : ""}
      </div>
    </article>
  `;
}

function renderReplies() {
  const annotation = currentSelectedAnnotation();

  if (!annotation) {
    elements.replyList.innerHTML = `<div class="compact-empty">${text("保存并选中一条批注后，可以在这里跟进处理记录。", "Save and select an annotation to track updates here.")}</div>`;
    return;
  }

  if (!annotation.replies?.length) {
    elements.replyList.innerHTML = `<div class="compact-empty">${text("还没有处理记录。添加第一条回复来说明进展或结论。", "No updates yet. Add the first reply to record progress or a decision.")}</div>`;
    return;
  }

  elements.replyList.innerHTML = [...annotation.replies]
    .reverse()
    .map(
      (reply) => `
        <article class="reply-card">
          <div class="reply-card-head">
            <div class="item-meta">
              <strong>${escapeHtml(reply.actor)}</strong>
              <span class="mini-pill">${formatDateTime(reply.createdAt)}</span>
              ${countReplyAttachments(reply) ? `<span class="mini-pill">${countReplyAttachments(reply)} ${text("个附件", "attachments")}</span>` : ""}
            </div>
            ${canDeleteReply(reply, currentDocument())
              ? `<button class="reply-remove-button" data-delete-reply="${reply.id}" type="button">${text("删除", "Delete")}</button>`
              : ""}
          </div>
          <p>${escapeHtml(reply.content || text("本条回复未填写文字说明，仅补充了附件。", "This reply has no text and only includes attachments."))}</p>
          ${renderReplyAttachmentStrip(reply)}
        </article>
      `,
    )
    .join("");

  Array.from(elements.replyList.querySelectorAll("[data-reply-preview-attachment]")).forEach((button) => {
    const reply = annotation.replies.find((item) => item.id === button.dataset.replyId);
    const attachment = reply?.attachments?.find((item) => item.id === button.dataset.replyPreviewAttachment);
    if (attachment) {
      button.addEventListener("click", () => {
        openAttachmentPreview(attachment);
      });
    }
  });
  Array.from(elements.replyList.querySelectorAll("[data-delete-reply]")).forEach((button) => {
    button.addEventListener("click", () => {
      void deleteReply(button.dataset.deleteReply);
    });
  });
}

function renderReplyComposer() {
  const annotation = currentSelectedAnnotation();
  const hasAnnotation = Boolean(annotation);
  const attachments = state.replyEditor.attachments || [];
  const canReply = hasAnnotation && canReplyAnnotation(currentDocument());

  const replySending = isActionPending("reply:send");
  elements.replyInput.disabled = replySending || !canReply;
  elements.replyButton.disabled = replySending || !canReply;
  setButtonBusy(elements.replyButton, replySending, text("发布更新", "Post Update"), text("发送中…", "Posting..."));
  elements.replyAttachImageButton.disabled = replySending || !canReply;
  elements.replyAttachFileButton.disabled = replySending || !canReply;
  elements.replyAttachLinkButton.disabled = replySending || !canReply;
  elements.replyAttachmentCountBadge.textContent = text(`${attachments.length} 项`, `${attachments.length} items`);
  if (elements.replyEvidenceDisclosure) {
    elements.replyEvidenceDisclosure.open = Boolean(hasAnnotation && attachments.length);
  }

  if (!hasAnnotation) {
    elements.replyAttachmentHelperText.textContent = text("选中批注后，可在回复中附加证据。", "Select an annotation to attach evidence to a reply.");
    elements.replyAttachmentList.innerHTML =
      text('<div class="compact-empty">选中批注后可添加回复证据。</div>', '<div class="compact-empty">Select an annotation to add reply evidence.</div>');
    return;
  }

  if (!canReply) {
    elements.replyAttachmentHelperText.textContent = text("当前角色没有回复批注的权限。", "The current role cannot reply to annotations.");
  } else {
    renderReplyAttachmentHelperText(attachments.length);
  }
  renderAttachmentCollection(elements.replyAttachmentList, attachments, {
    emptyText: text("当前回复还没有证据附件。", "No reply evidence attached."),
    onRemove: canReply ? removeReplyAttachment : null,
  });
}

function renderReplyAttachmentStrip(reply) {
  const attachments = Array.isArray(reply.attachments) ? reply.attachments : [];
  if (!attachments.length) {
    return "";
  }

  return `
    <div class="reply-attachment-strip">
      ${attachments
        .map((attachment) => {
          const label = `${attachment.kind === "image" ? text("图", "IMG") : attachment.kind === "link" ? text("链", "LINK") : text("文", "FILE")} ${attachment.name || text("未命名附件", "Untitled attachment")}`;
          if (attachment.kind === "image") {
            return `<button class="reply-attachment-chip" data-reply-id="${reply.id}" data-reply-preview-attachment="${attachment.id}" type="button">${escapeHtml(label)}</button>`;
          }
          return `<a class="reply-attachment-chip" href="${escapeHtml(attachment.url || "#")}" target="_blank" rel="noreferrer">${escapeHtml(label)}</a>`;
        })
        .join("")}
    </div>
  `;
}

function renderExportState() {
  const doc = currentDocument();
  if (!doc || !doc.exportUrl) {
    elements.exportLink.classList.add("hidden");
    elements.exportLink.removeAttribute("href");
    return;
  }

  elements.exportLink.classList.remove("hidden");
  elements.exportLink.href = `${doc.exportUrl}?t=${Date.now()}`;
  elements.exportLink.textContent = reviewFooterButtonLabels(doc).exportLink;
}

function renderReviewWorkflowActionGroup() {
  const doc = currentDocument();
  if (!doc || state.currentView !== "review") {
    elements.reviewWorkflowActionGroup.innerHTML = "";
    return;
  }

  const actions = reviewWorkflowActionGroupItems(doc);
  const health = workflowHealthMeta(doc);
  const permissionMeta = reviewNodePermissionMeta(doc);
  const idleNote = !actions.length ? reviewWorkflowActionIdleNote(doc) : "";

  elements.reviewWorkflowActionGroup.innerHTML = `
    <span class="mini-pill signal-pill ${health.tone}" title="${escapeHtml(health.stageNote)}">${escapeHtml(health.stage)}</span>
    <span class="mini-pill review-permission-chip ${permissionMeta.tone}" title="${escapeHtml(permissionMeta.summary)}">${escapeHtml(permissionMeta.badge)}</span>
    ${idleNote ? `<span class="review-workflow-action-note" title="${escapeHtml(idleNote)}">${escapeHtml(idleNote)}</span>` : ""}
    ${actions
      .map((action) => {
      const className =
        action.tone === "primary"
          ? "primary-button"
          : action.tone === "danger"
            ? "ghost-button danger-button"
            : "ghost-button";
      return `<button class="${className}" data-review-workflow-action="${action.action}" type="button">${escapeHtml(action.label)}</button>`;
    })
    .join("")}
  `;
}

function renderToolButtons() {
  const primaryTool = currentReviewPrimaryTool();
  const configuredTool = currentReviewConfiguredTool();
  const panel = currentToolbarPanel();
  const suspended = isReviewAnnotationToolSuspended(panel);
  elements.toolButtons.forEach((button) => {
    const active = button.dataset.tool === configuredTool && Boolean(configuredTool);
    button.classList.toggle("active", active);
    button.classList.toggle("suspended", active && suspended);
  });

  elements.toolbarFauxButtons.forEach((button) => {
    const fauxTool = button.dataset.fauxTool || "";
    const active = fauxTool === "hand" ? primaryTool === "hand" : fauxTool === panel;
    button.classList.toggle("active", active);
  });

  elements.toolbarColorButtons.forEach((button) => {
    button.classList.toggle("active", button.dataset.toolbarColor === state.activeColor);
  });

  elements.annotationModeButton.classList.toggle("active", Boolean(configuredTool));
  elements.annotationModeButton.classList.toggle("suspended", suspended || state.toolbarPreviewTool === "hand");
  if (elements.lineToolButton) {
    const lineLabel = lineVariantLabels[state.lineVariant] || annotationToolLabels.line;
    elements.lineToolButton.title = lineLabel;
    elements.lineToolButton.setAttribute("aria-label", lineLabel);
  }
  syncReviewCursorState();
}

function renderDraftHint() {
  const primaryTool = currentReviewPrimaryTool();
  const configuredTool = currentReviewConfiguredTool();
  const panel = currentToolbarPanel();
  if (state.toolbarHintMessage) {
    elements.draftHint.textContent = state.toolbarHintMessage;
    return;
  }

  if (!currentDocument()) {
    elements.draftHint.textContent = text("进入批注模式后，可落点、框选或添加文本。", "After entering annotation mode, place points, draw boxes, or add text.");
    return;
  }

  if (isPdfWorkspaceReadOnly(currentDocument()) && !state.toolbarPreviewTool) {
    elements.draftHint.textContent = text("当前为只读浏览，可查看批注、回复和附件；如需调整请进入 PDF 审阅。", "Read-only view. You can inspect annotations, replies, and attachments; enter PDF Review to make changes.");
    return;
  }

  if (state.draftAnnotation) {
    const draftLabel =
      state.draftAnnotation.type === "line"
        ? lineVariantLabels[normalizeLineVariant(state.draftAnnotation.variant)] || annotationToolLabels.line
        : annotationToolLabels[state.draftAnnotation.type];
    elements.draftHint.textContent = text(
      `已生成${draftLabel}草稿，补充右侧信息后保存。`,
      `${draftLabel} draft created. Complete the details on the right, then save.`,
    );
    return;
  }

  if (panel) {
    if (isReviewAnnotationToolSuspended(panel) && configuredTool) {
      elements.draftHint.textContent = text(
        `已暂停${reviewToolDisplayLabel(configuredTool)}绘制，当前正在使用${reviewToolbarPanelLabel(panel)}快捷操作；点左侧游标按钮可立即返回绘制。`,
        `${reviewToolDisplayLabel(configuredTool)} drawing is paused while ${reviewToolbarPanelLabel(panel)} shortcuts are open. Use the left cursor button to return to drawing.`,
      );
      return;
    }
    elements.draftHint.textContent = toolbarHintText(panel);
    return;
  }

  if (primaryTool === "hand") {
    elements.draftHint.textContent = toolbarHintText("hand");
    return;
  }

  elements.draftHint.textContent = primaryTool
    ? text(
        `${primaryTool === "line" ? lineVariantLabels[state.lineVariant] || annotationToolLabels.line : annotationToolLabels[primaryTool]}已启用，${primaryTool === "note" ? "单击" : "拖拽"}图面即可生成批注。`,
        `${primaryTool === "line" ? lineVariantLabels[state.lineVariant] || annotationToolLabels.line : annotationToolLabels[primaryTool]} is enabled. ${primaryTool === "note" ? "Click" : "Drag"} on the page to create an annotation.`,
      )
    : text("开启批注模式后可新增审阅标记。", "Enable annotation mode to add review markups.");
}

function renderToolbarQuickActions() {
  if (!elements.toolbarQuickActions) {
    return;
  }

  const actions = toolbarShortcutActions();
  if (!actions.length) {
    elements.toolbarQuickActions.innerHTML = "";
    elements.toolbarQuickActions.classList.add("hidden");
    return;
  }

  elements.toolbarQuickActions.classList.remove("hidden");
  elements.toolbarQuickActions.innerHTML = actions
    .map((action) => {
      const className = ["toolbar-quick-action", action.tone].filter(Boolean).join(" ");
      const disabled = action.disabled ? "disabled" : "";
      const valueAttr = action.value ? `data-toolbar-shortcut-value="${escapeHtml(action.value)}"` : "";
      return `<button class="${className}" data-toolbar-shortcut-action="${action.action}" ${valueAttr} type="button" ${disabled}>${escapeHtml(action.label)}</button>`;
    })
    .join("");
}

function toolbarShortcutActions() {
  const doc = currentDocument();
  if (!doc || state.currentView !== "review") {
    return [];
  }

  const readOnlyView = isPdfWorkspaceReadOnly(doc);
  const panel = currentToolbarPanel();

  if (panel === "comment") {
    return [
      { action: "comment-sidebar", label: text("定位列表", "Locate List") },
      { action: "comment-focus", label: text("写说明", "Write Notes"), disabled: readOnlyView || !currentAnnotationTarget() },
      { action: "comment-reply", label: text("写回复", "Write Reply"), disabled: readOnlyView || !currentSelectedAnnotation() || !canReplyAnnotation(doc) },
      { action: "comment-note", label: text("文本批注", "Text Note"), tone: "accent", disabled: readOnlyView || !canCreateAnnotation(doc) },
    ];
  }

  if (panel === "clipboard") {
    return [
      { action: "clipboard-copy-annotation", label: text("复制当前批注", "Copy Current Annotation"), disabled: !currentAnnotationTarget() },
      { action: "clipboard-copy-page", label: text("复制本页摘要", "Copy Page Summary"), disabled: !doc.annotations.some((annotation) => annotation.page === state.currentPage) },
      { action: "clipboard-duplicate", label: text("生成副本", "Duplicate"), tone: "accent", disabled: readOnlyView || !currentSelectedAnnotation() },
    ];
  }

  if (readOnlyView) {
    return [];
  }

  if (panel === "mention") {
    const mentionTargets = uniqueStrings(availableMentionTargets());
    const quickMentions = mentionTargets.map((name) => ({
      action: "mention-insert",
      label: `@${name}`,
      value: name,
    }));
    quickMentions.push({ action: "mention-custom", label: text("自定义", "Custom") });
    return quickMentions;
  }

  if (panel === "attach") {
    const actions = [];
    if (currentAnnotationTarget()) {
      actions.push(
        { action: "attach-annotation-image", label: text("批注图片", "Annotation Image") },
        { action: "attach-annotation-file", label: text("批注文件", "Annotation File") },
        { action: "attach-annotation-link", label: text("批注链接", "Annotation Link") },
      );
    }
    if (currentSelectedAnnotation() && canReplyAnnotation(doc)) {
      actions.push(
        { action: "attach-reply-image", label: text("回复图片", "Reply Image") },
        { action: "attach-reply-file", label: text("回复文件", "Reply File") },
        { action: "attach-reply-link", label: text("回复链接", "Reply Link") },
      );
    }
    if (!actions.length) {
      actions.push({ action: "attach-disabled", label: text("先选中批注", "Select Annotation First"), disabled: true });
    }
    return actions;
  }

  if (panel === "line") {
    return [
      { action: "line-variant", label: text("直箭头", "Straight Arrow"), value: "arrow", tone: state.lineVariant === "arrow" ? "accent" : "" },
      { action: "line-variant", label: text("折引线", "Leader Line"), value: "leader", tone: state.lineVariant === "leader" ? "accent" : "" },
      { action: "line-focus", label: text("开始绘制", "Start Drawing"), disabled: !canCreateAnnotation(doc) },
    ];
  }

  return [];
}

function toolbarHintText(tool) {
  if (tool === "hand") {
    return text("平移模式已启用，拖动画布可查看放大后的区域。", "Pan mode is enabled. Drag the canvas to inspect zoomed areas.");
  }
  if (tool === "comment") {
    return text("批注卡片快捷操作已展开，可定位列表、补写说明或直接切到回复。", "Annotation card shortcuts are open. You can jump to the list, update notes, or switch to reply.");
  }
  if (tool === "clipboard") {
    return text("剪贴板快捷操作已展开，可复制当前批注或整理本页摘要。", "Clipboard shortcuts are open. You can copy the current annotation or summarize this page.");
  }
  if (tool === "mention") {
    return text("提及快捷操作已展开，可从流程参与人中快速插入 @ 提及。", "Mention shortcuts are open so you can insert @mentions from workflow participants.");
  }
  if (tool === "attach") {
    return text("附件快捷操作已展开，可直接给批注或回复补充图片、文件和链接。", "Attachment shortcuts are open so you can add images, files, or links to an annotation or reply.");
  }
  if (tool === "line") {
    return text(
      `${lineVariantLabels[state.lineVariant] || text("直箭头", "Straight Arrow")}已就绪，拖拽图面即可生成线型批注。`,
      `${lineVariantLabels[state.lineVariant] || text("直箭头", "Straight Arrow")} is ready. Drag on the page to create a line annotation.`,
    );
  }
  return text(`${toolbarPlaceholderLabels[tool]}已就绪。`, `${toolbarPlaceholderLabels[tool]} is ready.`);
}

function normalizeReviewSearchHighlight(value) {
  if (!value || typeof value !== "object") {
    return null;
  }
  const bbox = value.bbox && typeof value.bbox === "object" ? value.bbox : null;
  if (!bbox) {
    return null;
  }
  return {
    id: value.id || `search-${Date.now()}`,
    source: value.source || "drawing_ocr_search",
    text: value.text || "",
    context: value.context || "",
    page: Math.max(1, Number(value.page || 1) || 1),
    bbox: {
      x: Math.max(0, Math.min(1, Number(bbox.x || 0) || 0)),
      y: Math.max(0, Math.min(1, Number(bbox.y || 0) || 0)),
      width: Math.max(0.01, Math.min(1, Number(bbox.width || 0.12) || 0.12)),
      height: Math.max(0.01, Math.min(1, Number(bbox.height || 0.05) || 0.05)),
    },
  };
}

function renderReviewSearchHighlight() {
  const highlight = state.reviewSearchHighlight;
  if (!highlight || highlight.page !== state.currentPage) {
    return "";
  }
  const style = positionStyle({
    x: highlight.bbox.x,
    y: highlight.bbox.y,
    width: highlight.bbox.width,
    height: highlight.bbox.height,
  });
  return `
    <div class="review-search-highlight" style="${style}" data-review-search-highlight="${escapeHtml(highlight.id)}">
      <span>${escapeHtml(text("OCR 命中", "OCR Match"))}</span>
      <strong>${escapeHtml(truncate(highlight.text || highlight.context || "", 42))}</strong>
    </div>
  `;
}

function renderAnnotationLayer() {
  const doc = currentDocument();
  if (!doc || !state.pdfDoc) {
    elements.annotationLayer.innerHTML = "";
    syncReviewCursorState();
    return;
  }
  syncAnnotationLayerBounds();

  const html = doc.annotations
    .filter((annotation) => annotation.page === state.currentPage)
    .map((annotation) => {
      const previewAnnotation =
        !state.draftAnnotation &&
        annotation.id === state.selectedAnnotationId &&
        state.annotationEditor.targetKey === `saved:${annotation.id}`
          ? {
              ...annotation,
              title: state.annotationEditor.title,
              note: state.annotationEditor.note,
              color: state.annotationEditor.color || annotation.color,
              status: state.annotationEditor.status || annotation.status,
              attachments: cloneAttachments(state.annotationEditor.attachments),
            }
          : annotation;
      return renderAnnotationElement(previewAnnotation, annotationSequence(doc, annotation.id), {
        selected: annotation.id === state.selectedAnnotationId,
      });
    })
    .join("");

  const draftHtml = state.draftAnnotation && state.draftAnnotation.page === state.currentPage
    ? renderAnnotationElement(
        {
          ...state.draftAnnotation,
          title: state.annotationEditor.title || newAnnotationTitle(state.draftAnnotation.type, state.draftAnnotation.page, state.draftAnnotation.variant),
          note: state.annotationEditor.note,
          color: state.annotationEditor.color,
          status: state.annotationEditor.status,
        },
        "+",
        { pending: true, selected: true },
      )
    : "";

  elements.annotationLayer.innerHTML = renderReviewSearchHighlight() + html + draftHtml;
  syncReviewCursorState();
}

function renderAnnotationElement(annotation, badgeText, { pending = false, selected = false } = {}) {
  const doc = currentDocument();
  const color = annotation.color || defaultColorForType(annotation.type);
  const status = annotation.status || "open";
  const targetId = pending ? "draft" : annotation.id || "";
  const isPageAnchoredPen = annotation.type === "pen";
  const renderFrame = isPageAnchoredPen
    ? { ...annotation, x: 0, y: 0, width: 1, height: 1, pageAnchored: true }
    : annotation;
  const style = positionStyle(renderFrame);
  const classes = [
    "annotation-shape",
    annotation.type,
    `color-${color}`,
    `status-${status}`,
    pending ? "pending" : "",
    selected ? "selected" : "",
    isPageAnchoredPen ? "page-anchored" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const dataAttribute = annotation.id ? `data-annotation-id="${annotation.id}"` : "";
  const actionTargetAttributes = pending
    ? 'data-annotation-target="draft"'
    : annotation.id
      ? `data-annotation-target="${annotation.id}" data-annotation-page="${annotation.page}"`
      : "";
  const attachmentCount = pending ? (state.annotationEditor.attachments || []).length : countAnnotationAttachments(annotation);
  const label = escapeHtml(annotationDisplayTitle(annotation));
  const noteText = escapeHtml(truncate(annotation.note || "", 56));
  const noteEditable = selected && annotation.type === "note" && (pending ? canCreateAnnotation(doc) : canChangeAnnotation(annotation, doc));
  const noteLabelMarkup = noteEditable
    ? `<textarea
        class="annotation-note-label annotation-note-editor"
        data-annotation-inline-note="${escapeHtml(targetId)}"
        aria-label="${text("编辑文本批注内容", "Edit text annotation content")}"
      >${escapeHtml(annotation.note || "")}</textarea>`
    : `<span class="annotation-note-label">${noteText}</span>`;
  const statusLabel = escapeHtml(pending ? text("草稿", "Draft") : annotationStatusDisplayLabel(annotation.status));
  const canSave = pending ? canCreateAnnotation(doc) : canSaveAnnotation(annotation, doc);
  const canDelete = pending ? canCreateAnnotation(doc) : canDeleteAnnotation(annotation, doc);
  const attachmentBadge =
    attachmentCount > 0
      ? `
        <button
          class="annotation-attachment-badge"
          type="button"
          data-annotation-action="attachments"
          ${actionTargetAttributes}
          aria-label="${text(`附件 ${attachmentCount} 项`, `${attachmentCount} attachments`)}"
          title="${text(`附件 ${attachmentCount} 项，点击定位附件区`, `${attachmentCount} attachments. Click to focus the attachment panel.`)}"
        >
          <svg class="annotation-attachment-icon" viewBox="0 0 24 24" aria-hidden="true">
            <path d="m9 12.5 5.17-5.17a3 3 0 1 1 4.24 4.24l-7.07 7.07a5 5 0 0 1-7.07-7.07l7.78-7.78" />
          </svg>
          <span>${attachmentCount}</span>
        </button>
      `
      : "";
  const statusBadge = `<span class="annotation-status-pill ${pending ? "draft" : annotation.status || "open"}">${statusLabel}</span>`;
  const actionButtons = `
    <div class="annotation-actions">
      <button
        class="annotation-action-button save-action"
        type="button"
        data-annotation-action="save"
        ${actionTargetAttributes}
        aria-label="${text("保存批注", "Save Annotation")}"
        title="${text("保存批注", "Save Annotation")}"
        ${canSave ? "" : "disabled"}
      >
        √
      </button>
      <button
        class="annotation-action-button delete-action"
        type="button"
        data-annotation-action="delete"
        ${actionTargetAttributes}
        aria-label="${pending ? text("删除草稿", "Delete Draft") : text("删除批注", "Delete Annotation")}"
        title="${pending ? text("删除草稿", "Delete Draft") : text("删除批注", "Delete Annotation")}"
        ${canDelete ? "" : "disabled"}
      >
        ×
      </button>
    </div>
  `;

  if (isVectorAnnotationType(annotation.type)) {
    const inlineVectorChrome = `
      <span class="annotation-badge">${badgeText}</span>
      ${statusBadge}
      <span class="annotation-chip">${label}</span>
      ${attachmentBadge}
      ${actionButtons}
    `;
    const vectorChrome = isPageAnchoredPen
      ? `<div class="annotation-vector-chrome" style="${positionStyle(annotationBoundsFromPoints(vectorPointsForRender(annotation), vectorAnnotationPadding(annotation.type)))}">${inlineVectorChrome}</div>`
      : inlineVectorChrome;
    return `
      <div class="${classes}" style="${style}" ${dataAttribute}>
        ${renderVectorAnnotationSvg(renderFrame)}
        ${vectorChrome}
      </div>
    `;
  }

  if (annotation.type === "note") {
    return `
      <div class="${classes}" style="${style}" ${dataAttribute}>
        <span class="annotation-badge">${badgeText}</span>
        ${statusBadge}
        <span class="annotation-note-title">${label}</span>
        ${noteLabelMarkup}
        ${attachmentBadge}
        ${actionButtons}
      </div>
    `;
  }

  return `
    <div class="${classes}" style="${style}" ${dataAttribute}>
      <span class="annotation-badge">${badgeText}</span>
      ${statusBadge}
      <span class="annotation-chip">${label}</span>
      ${attachmentBadge}
      ${actionButtons}
    </div>
  `;
}

const DRAWING_DISCIPLINE_OPTIONS = [
  "总图",
  "工艺",
  "管道",
  "设备",
  "土建",
  "结构",
  "建筑",
  "电气",
  "仪表自控",
  "给排水",
  "暖通",
  "消防",
  "海水取排水",
  "预处理",
  "反渗透",
  "化学加药",
  "排放/污泥",
  "通信",
  "弱电",
  "道路",
  "其他",
];

async function handleUpload(event) {
  const descriptors = buildUploadDescriptors(Array.from(event.target.files || []));
  try {
    await queueLibraryUploads(descriptors);
  } finally {
    event.target.value = "";
  }
}

async function handleFolderUploadSelection(event) {
  const descriptors = buildUploadDescriptors(Array.from(event.target.files || []), {
    preferRelativePath: true,
  });
  try {
    await queueLibraryUploads(descriptors);
  } finally {
    event.target.value = "";
  }
}

function buildUploadDescriptors(files, options = {}) {
  const preferRelativePath = Boolean(options.preferRelativePath);
  return files
    .filter((file) => file instanceof File)
    .filter((file) => file.name && file.name !== ".DS_Store")
    .map((file) => createUploadDescriptor(
      file,
      preferRelativePath ? file.webkitRelativePath || file.name : file.name,
    ));
}

function createUploadDescriptor(file, relativePath) {
  const normalizedPath = normalizeUploadRelativePath(relativePath || file?.name || "");
  const split = splitUploadRelativePath(normalizedPath, file?.name || "");
  return {
    id: crypto.randomUUID(),
    file,
    relativePath: normalizedPath,
    drawingMetadataDraft: inferDrawingMetadataFromFileName(split.fileName || file?.name || ""),
    drawingMetadata: null,
  };
}

function ensureUploadDescriptor(descriptor) {
  if (!descriptor?.file) {
    return descriptor;
  }
  const relativePath = normalizeUploadRelativePath(descriptor.relativePath || descriptor.file.name);
  const split = splitUploadRelativePath(relativePath, descriptor.file.name);
  return {
    ...descriptor,
    id: descriptor.id || crypto.randomUUID(),
    relativePath,
    drawingMetadataDraft:
      descriptor.drawingMetadataDraft || inferDrawingMetadataFromFileName(split.fileName || descriptor.file.name),
    drawingMetadata: descriptor.drawingMetadata || null,
  };
}

function isPdfUploadDescriptor(descriptor) {
  const name = splitUploadRelativePath(descriptor?.relativePath, descriptor?.file?.name || "").fileName || descriptor?.file?.name || "";
  return String(descriptor?.file?.type || "").toLowerCase() === "application/pdf" || fileExtension(name) === "pdf";
}

function inferDrawingMetadataFromFileName(name) {
  const fileName = splitUploadRelativePath(name, name).fileName || name;
  const baseName = pathBaseName(fileName).trim();
  const parts = baseName.split("_").map((part) => part.trim()).filter(Boolean);
  const revisionCandidate = parts.length ? parts[parts.length - 1] : "";
  const hasRevisionPart = /^rev[.\-_\s]?[a-z0-9]+$/i.test(revisionCandidate);
  const revision = normalizeDrawingRevisionLabel(hasRevisionPart ? revisionCandidate : inferDrawingRevisionFromName(baseName));
  const drawingNumber = parts[0] || inferDrawingNumberFromName(baseName);
  const nameParts = parts.length > 1
    ? parts.slice(1, hasRevisionPart ? -1 : undefined)
    : [];
  const drawingName = nameParts.join("_") || baseName
    .replace(drawingNumber, "")
    .replace(revisionCandidate, "")
    .replace(/[_\-\s]+$/g, "")
    .replace(/^[_\-\s]+/g, "")
    .trim();
  return {
    markedAsDrawing: false,
    drawingNumber,
    drawingName,
    discipline: inferDrawingDisciplineFromName(drawingName || baseName),
    revision,
    relatedDrawingNumber: "",
    relatedDrawingId: "",
  };
}

function inferDrawingNumberFromName(name) {
  const match = String(name || "").match(/[A-Z]{1,6}[-_]\d{2,}[-_A-Z0-9]*/i);
  return match ? match[0].replace(/_/g, "-") : "";
}

function inferDrawingRevisionFromName(name) {
  const match = String(name || "").match(/(?:^|[_\-\s.])((?:rev[._-]?\s*[A-Z0-9]+|R\d+|V\d+))(?:$|[_\-\s.]|\b)/i);
  return match ? match[1] : "";
}

function normalizeDrawingRevisionLabel(value) {
  const raw = String(value || "").trim();
  if (!raw) {
    return "";
  }
  const compact = raw.replace(/\s+/g, "").replace(/_/g, ".");
  const match = compact.match(/^rev\.?([A-Za-z0-9.-]+)$/i);
  return match ? `Rev.${match[1].replace(/^\./, "").toUpperCase()}` : compact;
}

function inferDrawingDisciplineFromName(name) {
  const value = String(name || "");
  if (/总图|总平面|平面布置|总布置/.test(value)) return "总图";
  if (/建筑|建施|装修/.test(value)) return "建筑";
  if (/结构|结施|钢筋|基础/.test(value)) return "结构";
  if (/工艺|流程|PID|P&ID|管道仪表/i.test(value)) return "工艺";
  if (/电气|电力|照明|弱电/.test(value)) return "电气";
  if (/仪表|自控|控制/.test(value)) return "仪表";
  if (/给排水|给水|排水|水施/.test(value)) return "给排水";
  if (/暖通|空调|通风|HVAC/i.test(value)) return "暖通";
  if (/消防|喷淋/.test(value)) return "消防";
  if (/管道|配管/.test(value)) return "管道";
  if (/道路|场坪/.test(value)) return "道路";
  return "其他";
}

function normalizeUploadRelativePath(value) {
  return String(value || "")
    .replaceAll("\\", "/")
    .split("/")
    .filter(Boolean)
    .join("/");
}

function splitUploadRelativePath(relativePath, fallbackName = "") {
  const normalized = normalizeUploadRelativePath(relativePath || fallbackName);
  const parts = normalized.split("/").filter(Boolean);
  if (!parts.length) {
    return {
      fileName: fallbackName,
      folderSegments: [],
    };
  }

  return {
    fileName: parts[parts.length - 1] || fallbackName,
    folderSegments: parts.slice(0, -1),
  };
}

function existingDrawingRelationOptions() {
  const seen = new Set();
  return state.documents
    .map((doc) => {
      const drawing = doc?.drawingMetadata || {};
      const number = String(drawing.drawingNumber || "").trim();
      return {
        id: String(doc?.id || ""),
        number,
        name: String(drawing.drawingName || doc?.name || ""),
        discipline: String(drawing.discipline || ""),
        revision: String(drawing.revision || doc?.version || ""),
      };
    })
    .filter((option) => {
      if (!option.id || !option.number || seen.has(option.number)) {
        return false;
      }
      seen.add(option.number);
      return true;
    })
    .sort((left, right) => left.number.localeCompare(right.number, "zh-CN"));
}

function existingDrawingRelationById(id) {
  const targetId = String(id || "").trim();
  return existingDrawingRelationOptions().find((option) => option.id === targetId) || null;
}

function existingDrawingRelationByNumber(number) {
  const targetNumber = String(number || "").trim();
  return existingDrawingRelationOptions().find((option) => option.number === targetNumber) || null;
}

async function requestUploadDrawingMetadata(descriptors) {
  const nextDescriptors = descriptors.map(ensureUploadDescriptor);
  if (!nextDescriptors.some(isPdfUploadDescriptor)) {
    return nextDescriptors;
  }
  if (uploadDrawingMetadataResolver) {
    uploadDrawingMetadataResolver(null);
  }
  return new Promise((resolve) => {
    uploadDrawingMetadataResolver = resolve;
    state.uploadDrawingMetadataDescriptors = nextDescriptors;
    state.uploadDrawingMetadataError = "";
    state.uploadDrawingMetadataModalOpen = true;
    renderUploadDrawingMetadataModal();
    applyOverlayChromeState();
    syncOverlayFocus();
  });
}

function resolveUploadDrawingMetadata(result) {
  if (!uploadDrawingMetadataResolver) {
    return;
  }
  const resolver = uploadDrawingMetadataResolver;
  uploadDrawingMetadataResolver = null;
  state.uploadDrawingMetadataModalOpen = false;
  state.uploadDrawingMetadataDescriptors = [];
  state.uploadDrawingMetadataError = "";
  renderUploadDrawingMetadataModal();
  applyOverlayChromeState();
  resolver(result);
}

function uploadDrawingDescriptorById(id) {
  return state.uploadDrawingMetadataDescriptors.find((descriptor) => descriptor.id === id) || null;
}

function handleUploadDrawingMetadataInput(event) {
  const target = event.target;
  if (!(target instanceof HTMLInputElement) && !(target instanceof HTMLSelectElement)) {
    return;
  }
  const row = target.closest("[data-upload-drawing-row]");
  const descriptor = uploadDrawingDescriptorById(row?.dataset.uploadDrawingRow || "");
  if (!descriptor) {
    return;
  }
  descriptor.drawingMetadataDraft = descriptor.drawingMetadataDraft || inferDrawingMetadataFromFileName(descriptor.file?.name || "");
  if (target.matches("[data-upload-drawing-mark]")) {
    descriptor.drawingMetadataDraft.markedAsDrawing = Boolean(target.checked);
    state.uploadDrawingMetadataError = "";
    renderUploadDrawingMetadataModal();
    return;
  }
  const field = target.dataset.uploadDrawingField;
  if (field) {
    descriptor.drawingMetadataDraft[field] =
      field === "revision" ? normalizeDrawingRevisionLabel(target.value) : String(target.value || "").trim();
    if (field === "relatedDrawingNumber") {
      const related = existingDrawingRelationByNumber(descriptor.drawingMetadataDraft.relatedDrawingNumber);
      descriptor.drawingMetadataDraft.relatedDrawingId = related?.id || "";
    }
    state.uploadDrawingMetadataError = "";
    if (elements.uploadDrawingMetadataError) {
      elements.uploadDrawingMetadataError.classList.add("hidden");
      elements.uploadDrawingMetadataError.textContent = "";
    }
    if (field === "relatedDrawingNumber") {
      renderUploadDrawingMetadataModal();
    }
    return;
  }
  const relatedSelect = target.dataset.uploadDrawingRelatedSelect;
  if (relatedSelect !== undefined) {
    const related = existingDrawingRelationById(target.value);
    descriptor.drawingMetadataDraft.relatedDrawingId = related?.id || "";
    descriptor.drawingMetadataDraft.relatedDrawingNumber = related?.number || "";
    state.uploadDrawingMetadataError = "";
    renderUploadDrawingMetadataModal();
  }
}

function normalizedUploadDrawingMetadata(draft) {
  const value = draft && typeof draft === "object" ? draft : {};
  const markedAsDrawing = Boolean(value.markedAsDrawing);
  return {
    markedAsDrawing,
    drawingNumber: markedAsDrawing ? String(value.drawingNumber || "").trim() : "",
    drawingName: markedAsDrawing ? String(value.drawingName || "").trim() : "",
    discipline: markedAsDrawing ? String(value.discipline || "").trim() : "",
    revision: markedAsDrawing ? normalizeDrawingRevisionLabel(value.revision) : "",
    relatedDrawingNumber: markedAsDrawing ? String(value.relatedDrawingNumber || "").trim() : "",
    relatedDrawingId: markedAsDrawing ? String(value.relatedDrawingId || "").trim() : "",
  };
}

function confirmUploadDrawingMetadata() {
  const nextDescriptors = [];
  for (const descriptor of state.uploadDrawingMetadataDescriptors) {
    const metadata = normalizedUploadDrawingMetadata(descriptor.drawingMetadataDraft);
    if (metadata.markedAsDrawing) {
      const missing = [];
      if (!metadata.drawingNumber) missing.push(text("图纸编号", "Drawing No."));
      if (!metadata.drawingName) missing.push(text("图纸名称", "Drawing Name"));
      if (!metadata.discipline) missing.push(text("专业", "Discipline"));
      if (!metadata.revision) missing.push(text("版本号", "Revision"));
      if (missing.length) {
        state.uploadDrawingMetadataError = text(
          `文件“${descriptor.file?.name || ""}”缺少必填项：${missing.join("、")}`,
          `File "${descriptor.file?.name || ""}" is missing required fields: ${missing.join(", ")}`,
        );
        renderUploadDrawingMetadataModal();
        return;
      }
    }
    nextDescriptors.push({
      ...descriptor,
      drawingMetadata: metadata.markedAsDrawing ? metadata : null,
    });
  }
  resolveUploadDrawingMetadata(nextDescriptors);
}

function renderUploadDrawingMetadataModal() {
  const visible = Boolean(state.uploadDrawingMetadataModalOpen);
  if (!elements.uploadDrawingMetadataModal) {
    return;
  }
  elements.uploadDrawingMetadataModal.classList.toggle("hidden", !visible);
  elements.uploadDrawingMetadataModal.setAttribute("aria-hidden", visible ? "false" : "true");
  if (!visible) {
    if (elements.uploadDrawingMetadataList) {
      elements.uploadDrawingMetadataList.innerHTML = "";
    }
    return;
  }

  const pdfCount = state.uploadDrawingMetadataDescriptors.filter(isPdfUploadDescriptor).length;
  if (elements.uploadDrawingMetadataTitle) {
    elements.uploadDrawingMetadataTitle.textContent = text("上传前确认图纸属性", "Confirm Drawing Attributes");
  }
  if (elements.uploadDrawingMetadataMeta) {
    elements.uploadDrawingMetadataMeta.textContent = text(
      `本次选择 ${state.uploadDrawingMetadataDescriptors.length} 个文件，其中 ${pdfCount} 个 PDF 可声明为图纸。未勾选的文件会按普通文档上传。`,
      `${state.uploadDrawingMetadataDescriptors.length} files selected; ${pdfCount} PDFs can be declared as drawings. Unchecked files upload as regular documents.`,
    );
  }
  if (elements.uploadDrawingRelatedOptions) {
    elements.uploadDrawingRelatedOptions.innerHTML = existingDrawingRelationOptions()
      .map((option) => `<option value="${escapeHtml(option.number)}" label="${escapeHtml([option.name, option.discipline, option.revision].filter(Boolean).join(" · "))}"></option>`)
      .join("");
  }
  elements.uploadDrawingMetadataList.innerHTML = state.uploadDrawingMetadataDescriptors
    .map(renderUploadDrawingMetadataRow)
    .join("");
  if (elements.uploadDrawingMetadataError) {
    elements.uploadDrawingMetadataError.textContent = state.uploadDrawingMetadataError || "";
    elements.uploadDrawingMetadataError.classList.toggle("hidden", !state.uploadDrawingMetadataError);
  }
  if (elements.confirmUploadDrawingMetadataButton) {
    elements.confirmUploadDrawingMetadataButton.textContent = text("开始上传", "Start Upload");
  }
  if (elements.cancelUploadDrawingMetadataButton) {
    elements.cancelUploadDrawingMetadataButton.textContent = text("取消", "Cancel");
  }
}

function renderUploadDrawingMetadataRow(descriptor) {
  const isPdf = isPdfUploadDescriptor(descriptor);
  const draft = descriptor.drawingMetadataDraft || inferDrawingMetadataFromFileName(descriptor.file?.name || "");
  const checked = Boolean(draft.markedAsDrawing && isPdf);
  const relative = normalizeUploadRelativePath(descriptor.relativePath || descriptor.file?.name || "");
  const pathLabel = relative.includes("/") ? relative.split("/").slice(0, -1).join(" / ") : text("根目录", "Root");
  const fields = checked ? renderUploadDrawingMetadataFields(descriptor, draft) : "";
  return `
    <article class="upload-drawing-file-row${checked ? " is-marked" : ""}" data-upload-drawing-row="${escapeHtml(descriptor.id)}">
      <div class="upload-drawing-file-head">
        <div class="upload-drawing-file-name">
          <span class="upload-drawing-file-icon">${isPdf ? "PDF" : "DOC"}</span>
          <div>
            <strong title="${escapeHtml(descriptor.file?.name || "")}">${escapeHtml(descriptor.file?.name || text("未命名文件", "Untitled File"))}</strong>
            <small>${escapeHtml(pathLabel)} · ${escapeHtml(formatBytes(descriptor.file?.size || 0))}</small>
          </div>
        </div>
        <label class="upload-drawing-mark">
          <input type="checkbox" data-upload-drawing-mark ${checked ? "checked" : ""} ${isPdf ? "" : "disabled"} />
          <span>${escapeHtml(text("标记为图纸", "Mark as Drawing"))}</span>
        </label>
      </div>
      ${isPdf ? fields : `<p class="upload-drawing-disabled-hint">${escapeHtml(text("仅 PDF 上传时支持图纸属性声明。", "Only PDFs support drawing attribute declaration during upload."))}</p>`}
    </article>
  `;
}

function renderUploadDrawingMetadataFields(descriptor, draft) {
  const field = (name, label, value, required = true, extra = "") => `
    <label class="upload-drawing-field">
      <span>${escapeHtml(label)}${required ? '<em>*</em>' : ""}</span>
      <input class="text-input" data-upload-drawing-field="${escapeHtml(name)}" type="text" value="${escapeHtml(value || "")}" ${extra} />
    </label>
  `;
  const selectOptions = DRAWING_DISCIPLINE_OPTIONS
    .map((option) => `<option value="${escapeHtml(option)}" ${option === draft.discipline ? "selected" : ""}>${escapeHtml(option)}</option>`)
    .join("");
  const relatedOptions = existingDrawingRelationOptions();
  const relatedSelectOptions = [
    `<option value="">${escapeHtml(text("不关联", "No related drawing"))}</option>`,
    ...relatedOptions.map((option) => `
      <option value="${escapeHtml(option.id)}" ${option.id === draft.relatedDrawingId || option.number === draft.relatedDrawingNumber ? "selected" : ""}>
        ${escapeHtml([option.number, option.name, option.revision].filter(Boolean).join(" · "))}
      </option>
    `),
  ].join("");
  const relatedMatch = existingDrawingRelationById(draft.relatedDrawingId) || existingDrawingRelationByNumber(draft.relatedDrawingNumber);
  const relatedHint = relatedMatch
    ? text(
      `已关联：${relatedMatch.number} · ${relatedMatch.name || "未命名图纸"}`,
      `Linked: ${relatedMatch.number} · ${relatedMatch.name || "Untitled drawing"}`,
    )
    : draft.relatedDrawingNumber
      ? text("未匹配到已有图纸，将仅保存关联编号。", "No existing drawing matched; only the related number will be saved.")
      : text("可选。建议从已有图纸中选择，系统会同时保存编号和文件 ID。", "Optional. Select an existing drawing to save both drawing number and file ID.");
  return `
    <div class="upload-drawing-attributes">
      ${field("drawingNumber", text("图纸编号", "Drawing No."), draft.drawingNumber)}
      ${field("drawingName", text("图纸名称", "Drawing Name"), draft.drawingName)}
      <label class="upload-drawing-field">
        <span>${escapeHtml(text("专业", "Discipline"))}<em>*</em></span>
        <select class="text-input" data-upload-drawing-field="discipline">
          ${selectOptions}
        </select>
      </label>
      ${field("revision", text("版本号", "Revision"), draft.revision)}
      <label class="upload-drawing-field upload-drawing-field-wide">
        <span>${escapeHtml(text("选择已有图纸", "Select Existing Drawing"))}</span>
        <select class="text-input" data-upload-drawing-related-select>
          ${relatedSelectOptions}
        </select>
      </label>
      ${field("relatedDrawingNumber", text("关联图纸", "Related Drawing"), draft.relatedDrawingNumber, false, `list="uploadDrawingRelatedOptions" placeholder="${escapeHtml(text("搜索已有编号...", "Search existing number..."))}"`)}
      <p class="upload-drawing-related-hint">${escapeHtml(relatedHint)}</p>
    </div>
  `;
}

async function queueLibraryUploads(descriptors) {
  const normalizedDescriptors = descriptors.map(ensureUploadDescriptor).filter((descriptor) => descriptor?.file);
  if (!normalizedDescriptors.length) {
    return;
  }
  const targetPermissions = folderPermissionsMeta(currentFolder());
  if (!targetPermissions.upload) {
    notify(text("当前目录不允许上传文件。", "This folder does not allow file uploads."), "alert");
    return;
  }

  const preparedDescriptors = await requestUploadDrawingMetadata(normalizedDescriptors);
  if (!preparedDescriptors) {
    notify(text("已取消上传。", "Upload canceled."), "alert");
    return;
  }

  const tasks = preparedDescriptors.map(createUploadTask);
  state.uploadTasks = [...state.uploadTasks, ...tasks];
  renderUploadProgressPanel();
  clearTaskPanelAutoHideTimer();

  const job = async () => {
    let latestDocumentId = null;

    for (const task of tasks) {
      latestDocumentId = (await runUploadTask(task)) || latestDocumentId;
    }

    if (latestDocumentId) {
      state.selectedId = latestDocumentId;
      state.currentPage = 1;
      state.zoomFactor = 1;
      state.annotationMode = false;
      state.toolbarPreviewTool = null;
      state.draftAnnotation = null;
      state.selectedAnnotationId = null;
      state.pdfDoc = null;
      state.loadedPdfId = null;
      state.annotationEditor = createEmptyAnnotationEditor();
    }

    await refreshDocuments();
    scheduleTaskPanelAutoHide();
  };

  uploadPipeline = uploadPipeline.then(job, job);
  await uploadPipeline;
}

function createUploadTask(descriptor) {
  const split = splitUploadRelativePath(descriptor.relativePath, descriptor.file.name);
  const projectId = currentAccess().project?.id || "";
  return {
    id: crypto.randomUUID(),
    kind: "upload",
    projectId,
    name: split.fileName || descriptor.file.name,
    originalFileName: descriptor.file.name,
    size: descriptor.file.size,
    lastModified: Number(descriptor.file.lastModified || 0),
    relativePath: descriptor.relativePath,
    folderSegments: split.folderSegments,
    progress: 0,
    status: "queued",
    message: text("等待上传", "Waiting to Upload"),
    file: descriptor.file,
    drawingMetadata: descriptor.drawingMetadata || null,
    pathLabel: split.folderSegments.length ? split.folderSegments.join(" / ") : text("根目录", "Root"),
    parentId: null,
    docId: "",
    versionId: "",
    ownerUserId: String(state.currentUserId || currentUser()?.id || "").trim(),
    ownerName: String(currentUser()?.name || currentActorLabel() || "").trim(),
    uploadSessionId: "",
    fingerprint: "",
    targetName: "",
    chunkSize: RESUMABLE_UPLOAD_CHUNK_SIZE,
    receivedBytes: 0,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    _reader: null,
    _xhr: null,
    _aborted: false,
  };
}

function createUploadFingerprint(task, payload = {}) {
  const projectId = String(task?.projectId || currentAccess().project?.id || "").trim();
  const parentId = String(payload.parentId ?? task?.parentId ?? "").trim() || "root";
  const targetName = String(payload.name || task?.targetName || task?.name || task?.originalFileName || "").trim();
  const originalName = String(task?.originalFileName || task?.file?.name || task?.name || "").trim();
  const size = Number(task?.size || task?.file?.size || 0);
  const lastModified = Number(task?.lastModified || task?.file?.lastModified || 0);
  const relativePath = normalizeUploadRelativePath(task?.relativePath || task?.file?.webkitRelativePath || originalName);
  return ["cde-upload-v1", projectId, parentId, targetName, originalName, size, lastModified, relativePath]
    .map((part) => encodeURIComponent(String(part ?? "")))
    .join("|");
}

function readResumableUploadDrafts() {
  if (typeof window === "undefined") {
    return [];
  }
  try {
    const parsed = JSON.parse(window.localStorage.getItem(RESUMABLE_UPLOAD_DRAFTS_STORAGE_KEY) || "[]");
    return Array.isArray(parsed) ? parsed.filter((item) => item && typeof item === "object") : [];
  } catch {
    return [];
  }
}

function writeResumableUploadDrafts(drafts) {
  if (typeof window === "undefined") {
    return;
  }
  try {
    const normalized = Array.isArray(drafts) ? drafts.filter(Boolean) : [];
    if (!normalized.length) {
      window.localStorage.removeItem(RESUMABLE_UPLOAD_DRAFTS_STORAGE_KEY);
      return;
    }
    window.localStorage.setItem(RESUMABLE_UPLOAD_DRAFTS_STORAGE_KEY, JSON.stringify(normalized.slice(-80)));
  } catch {
    // Losing local draft metadata should not interrupt an in-flight upload.
  }
}

function currentResumableDraftScope() {
  return {
    projectId: String(currentAccess().project?.id || "").trim(),
    ownerUserId: String(state.currentUserId || currentUser()?.id || "").trim(),
  };
}

function resumableDraftMatchesScope(draft, scope = currentResumableDraftScope()) {
  const draftProjectId = String(draft?.projectId || "").trim();
  const draftOwnerUserId = String(draft?.ownerUserId || "").trim();
  return (!scope.projectId || !draftProjectId || draftProjectId === scope.projectId) &&
    (!scope.ownerUserId || !draftOwnerUserId || draftOwnerUserId === scope.ownerUserId);
}

function isResumableUploadDraftTask(task) {
  return Boolean(
    task &&
    task.kind === "upload" &&
    task.uploadSessionId &&
    !["done", "canceled", "skipped"].includes(task.status),
  );
}

function resumableDraftFromTask(task) {
  return {
    id: task.id,
    kind: "upload",
    projectId: task.projectId || currentAccess().project?.id || "",
    ownerUserId: task.ownerUserId || String(state.currentUserId || currentUser()?.id || "").trim(),
    ownerName: task.ownerName || String(currentUser()?.name || currentActorLabel() || "").trim(),
    uploadSessionId: task.uploadSessionId || "",
    fingerprint: task.fingerprint || "",
    name: task.name || task.originalFileName || "",
    targetName: task.targetName || task.name || "",
    originalFileName: task.originalFileName || task.name || "",
    size: Number(task.size || 0),
    lastModified: Number(task.lastModified || 0),
    relativePath: task.relativePath || "",
    folderSegments: Array.isArray(task.folderSegments) ? [...task.folderSegments] : [],
    parentId: task.parentId || null,
    pathLabel: task.pathLabel || "",
    drawingMetadata: task.drawingMetadata || null,
    chunkSize: Number(task.chunkSize || RESUMABLE_UPLOAD_CHUNK_SIZE),
    receivedBytes: Number(task.receivedBytes || 0),
    progress: Number(task.progress || 0),
    status: task.status || "queued",
    createdAt: task.createdAt || new Date().toISOString(),
    updatedAt: task.updatedAt || new Date().toISOString(),
  };
}

function persistResumableUploadDrafts() {
  const scope = currentResumableDraftScope();
  const preserved = readResumableUploadDrafts().filter((draft) => !resumableDraftMatchesScope(draft, scope));
  const active = state.uploadTasks
    .filter(isResumableUploadDraftTask)
    .map(resumableDraftFromTask);
  writeResumableUploadDrafts([...preserved, ...active]);
}

function removeResumableUploadDraft(taskOrSessionId) {
  const sessionId = typeof taskOrSessionId === "string" ? taskOrSessionId : taskOrSessionId?.uploadSessionId;
  const fingerprint = typeof taskOrSessionId === "string" ? "" : taskOrSessionId?.fingerprint;
  if (!sessionId && !fingerprint) {
    return;
  }
  writeResumableUploadDrafts(readResumableUploadDrafts().filter((draft) => {
    if (sessionId && draft.uploadSessionId === sessionId) {
      return false;
    }
    return !(fingerprint && draft.fingerprint === fingerprint);
  }));
}

function uploadTaskFromResumableSession(session, draft = null) {
  const size = Number(session?.size || draft?.size || 0);
  const receivedBytes = Number(session?.receivedBytes || draft?.receivedBytes || 0);
  const progress = size ? Math.max(2, Math.min(96, Math.round(4 + (receivedBytes / size) * 92))) : Number(draft?.progress || 0);
  const parentId = session?.parentId || draft?.parentId || null;
  return {
    id: draft?.id || crypto.randomUUID(),
    kind: "upload",
    projectId: session?.projectId || draft?.projectId || currentAccess().project?.id || "",
    name: session?.name || draft?.name || text("未命名文件", "Untitled File"),
    targetName: draft?.targetName || session?.name || draft?.name || "",
    originalFileName: draft?.originalFileName || session?.name || draft?.name || "",
    size,
    lastModified: Number(draft?.lastModified || 0),
    relativePath: draft?.relativePath || draft?.originalFileName || session?.name || "",
    folderSegments: Array.isArray(draft?.folderSegments) ? [...draft.folderSegments] : [],
    progress,
    status: "paused",
    message: text("选择原文件继续上传", "Select the original file to resume"),
    file: null,
    drawingMetadata: draft?.drawingMetadata || null,
    pathLabel: draft?.pathLabel || (parentId ? folderPathLabel(parentId) : text("根目录", "Root")),
    parentId,
    docId: "",
    versionId: "",
    ownerUserId: draft?.ownerUserId || String(state.currentUserId || currentUser()?.id || "").trim(),
    ownerName: draft?.ownerName || String(currentUser()?.name || currentActorLabel() || "").trim(),
    uploadSessionId: session?.id || draft?.uploadSessionId || "",
    fingerprint: session?.fingerprint || draft?.fingerprint || "",
    chunkSize: Number(session?.chunkSize || draft?.chunkSize || RESUMABLE_UPLOAD_CHUNK_SIZE),
    receivedBytes,
    createdAt: draft?.createdAt || session?.createdAt || new Date().toISOString(),
    updatedAt: session?.updatedAt || draft?.updatedAt || new Date().toISOString(),
    _reader: null,
    _xhr: null,
    _aborted: false,
  };
}

async function hydrateResumableUploadSessions() {
  if (!state.authenticated) {
    return;
  }
  try {
    const payload = await fetchJson("/api/uploads/resumable?status=active");
    const sessions = Array.isArray(payload.sessions) ? payload.sessions : [];
    const drafts = readResumableUploadDrafts().filter((draft) => resumableDraftMatchesScope(draft));
    const draftBySessionId = new Map(drafts.map((draft) => [draft.uploadSessionId, draft]));
    const draftByFingerprint = new Map(drafts.map((draft) => [draft.fingerprint, draft]));
    const existingSessionIds = new Set(state.uploadTasks.map((task) => task.uploadSessionId).filter(Boolean));
    const hydrated = sessions
      .filter((session) => !existingSessionIds.has(session.id))
      .map((session) => uploadTaskFromResumableSession(
        session,
        draftBySessionId.get(session.id) || draftByFingerprint.get(session.fingerprint) || null,
      ));

    if (hydrated.length) {
      state.uploadTasks = [...state.uploadTasks, ...hydrated];
      renderUploadProgressPanel();
    }
    persistResumableUploadDrafts();
  } catch {
    // Active uploads are recoverable convenience state; normal app bootstrap should not fail because of it.
  }
}

async function runUploadTask(task) {
  if (!task || task.status === "canceled") {
    return null;
  }

  const validationError = validateLibraryUploadFile(task.file);
  if (validationError) {
    updateUploadTask(task.id, {
      status: "error",
      message: validationError,
      progress: 100,
    });
    return null;
  }

  try {
    const parentId = task.uploadSessionId && task.parentId
      ? task.parentId
      : await ensureUploadTargetFolder(task.folderSegments);
    task.parentId = parentId;
    updateUploadTask(task.id, {
      pathLabel: parentId ? folderPathLabel(parentId) : "根目录",
      status: "queued",
      message: text("等待上传", "Waiting to Upload"),
    });

    let targetName = task.name;
    let conflictMode = task.forcedConflictMode || "replace";
    const duplicate = findDuplicateDocument(targetName, parentId);
    if (duplicate && !task.forcedConflictMode && !task.uploadSessionId) {
      updateUploadTask(task.id, {
        status: "waiting",
        message: text("等待同名文件处理", "Waiting for duplicate handling"),
      });
      const decision = await requestUploadConflict(task, parentId);
      if (task.status === "canceled") {
        return null;
      }
      if (decision === "skip") {
        updateUploadTask(task.id, {
          status: "skipped",
          message: text("检测到同名文件，已跳过", "Duplicate file detected and skipped"),
          progress: 100,
        });
        return null;
      }
      if (decision === "rename") {
        targetName = nextAvailableLibraryDocumentName(targetName, parentId);
        conflictMode = "rename";
      }
    }

    task.targetName = targetName;
    task.fingerprint = task.fingerprint || createUploadFingerprint(task, { name: targetName, parentId });
    updateUploadTask(task.id, {
      status: "uploading",
      message: task.uploadSessionId ? text("正在续传", "Resuming upload") : text("正在创建上传会话", "Creating upload session"),
      progress: Math.max(task.progress || 0, 2),
    });
    const response = await uploadFileWithResume(task, {
      name: targetName,
      parentId,
      conflictMode,
    });

    syncDocumentFromUpload(response.document);
    updateUploadTask(task.id, {
      docId: response.document?.id || task.docId || "",
      versionId: response.document?.currentVersionId || task.versionId || "",
      projectId: response.document?.projectId || task.projectId || "",
      ownerUserId: response.document?.uploaderId || task.ownerUserId || "",
      ownerName: response.document?.uploader || task.ownerName || "",
      status: "done",
      message:
        conflictMode === "rename"
          ? text(`已保留两者，新文件为 ${response.document.name}`, `Kept both. New file: ${response.document.name}`)
          : duplicate
            ? text(`已生成 ${response.document.version || "新版本"}`, `Created ${response.document.version || "new version"}`)
            : text("上传完成", "Upload complete"),
      progress: 100,
    });
    return response.document?.id || null;
  } catch (error) {
    if (error?.name === "AbortError") {
      updateUploadTask(task.id, {
        status: "canceled",
        message: text("已取消上传", "Upload canceled"),
        progress: task.progress || 0,
      });
      return null;
    }

    updateUploadTask(task.id, {
      status: "error",
      message: error.message || text("上传失败，请稍后重试。", "Upload failed. Please try again later."),
      progress: 100,
    });
    return null;
  } finally {
    task._reader = null;
    task._xhr = null;
  }
}

function uploadChunkWithProgress(sessionId, index, chunk, { task, onProgress = null } = {}) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    if (task) {
      task._xhr = xhr;
    }
    xhr.open("PUT", `/api/uploads/resumable/${encodeURIComponent(sessionId)}/chunks/${index}`);
    xhr.setRequestHeader("Content-Type", "application/octet-stream");
    xhr.withCredentials = true;
    xhr.upload.onprogress = (event) => {
      if (event.lengthComputable && typeof onProgress === "function") {
        onProgress(event.loaded, event.total);
      }
    };
    xhr.onload = () => {
      let payload = {};
      try {
        payload = xhr.responseText ? JSON.parse(xhr.responseText) : {};
      } catch {
        payload = {};
      }
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve(payload);
        return;
      }
      if (xhr.status === 401 && state.authenticated) {
        applyLoggedOutState(text("登录已失效，请重新登录。", "Your session has expired. Please sign in again."));
        render();
      }
      reject(new Error(localizeUserMessage(payload.error, text("请求失败，请稍后重试。", "Request failed. Please try again."))));
    };
    xhr.onerror = () => reject(new Error(text("网络异常，请稍后重试。", "Network error. Please try again later.")));
    xhr.onabort = () => {
      const error = new Error("Upload canceled");
      error.name = "AbortError";
      reject(error);
    };
    xhr.send(chunk);
  });
}

async function ensureResumableUploadSession(task, payload) {
  task.targetName = payload.name || task.targetName || task.name;
  if (task.uploadSessionId) {
    try {
      const existing = await fetchJson(`/api/uploads/resumable/${encodeURIComponent(task.uploadSessionId)}`);
      task.fingerprint = existing.session?.fingerprint || task.fingerprint || createUploadFingerprint(task, payload);
      task.receivedBytes = Number(existing.session?.receivedBytes || task.receivedBytes || 0);
      task.chunkSize = Number(existing.session?.chunkSize || task.chunkSize || RESUMABLE_UPLOAD_CHUNK_SIZE);
      persistResumableUploadDrafts();
      return existing.session;
    } catch (error) {
      if (!/not found|未找到/i.test(error?.message || "")) {
        throw error;
      }
      task.uploadSessionId = "";
      task.receivedBytes = 0;
      task.chunkSize = RESUMABLE_UPLOAD_CHUNK_SIZE;
    }
  }

  task.fingerprint = task.fingerprint || createUploadFingerprint(task, payload);
  const created = await postJson("/api/uploads/resumable", {
    name: payload.name,
    size: task.file.size,
    parentId: payload.parentId,
    actor: currentActorLabel(),
    mimeType: task.file.type || inferMimeType(task.file.name, "document"),
    conflictMode: payload.conflictMode,
    note: payload.note || "",
    chunkSize: task.chunkSize || RESUMABLE_UPLOAD_CHUNK_SIZE,
    fingerprint: task.fingerprint,
    ...(task.drawingMetadata?.markedAsDrawing ? { drawingMetadata: task.drawingMetadata } : {}),
  });
  task.uploadSessionId = created.session?.id || "";
  task.fingerprint = created.session?.fingerprint || task.fingerprint;
  task.chunkSize = Number(created.session?.chunkSize || task.chunkSize || RESUMABLE_UPLOAD_CHUNK_SIZE);
  task.receivedBytes = Number(created.session?.receivedBytes || 0);
  persistResumableUploadDrafts();
  return created.session;
}

async function uploadFileWithResume(task, payload) {
  task._aborted = false;
  const session = await ensureResumableUploadSession(task, payload);
  const sessionId = session?.id || task.uploadSessionId;
  if (!sessionId) {
    throw new Error(text("上传会话创建失败，请稍后重试。", "Upload session creation failed. Please try again later."));
  }

  const chunkSize = Math.max(1, Number(session?.chunkSize || task.chunkSize || RESUMABLE_UPLOAD_CHUNK_SIZE));
  const chunkCount = Math.max(0, Number(session?.chunkCount ?? Math.ceil(task.file.size / chunkSize)));
  const receivedChunks = new Set((session?.receivedChunks || []).map((index) => Number(index)));
  let confirmedBytes = Number(session?.receivedBytes || 0);
  task.chunkSize = chunkSize;
  task.receivedBytes = confirmedBytes;

  const updateProgress = (bytes, message = text("正在上传", "Uploading")) => {
    const ratio = task.file.size ? bytes / task.file.size : 1;
    updateUploadTask(task.id, {
      status: "uploading",
      message,
      receivedBytes: bytes,
      progress: Math.max(4, Math.min(96, Math.round(4 + ratio * 92))),
    });
  };

  updateProgress(confirmedBytes, receivedChunks.size ? text("正在续传", "Resuming upload") : text("正在上传", "Uploading"));

  for (let index = 0; index < chunkCount; index += 1) {
    if (task.status === "canceled" || task._aborted) {
      const error = new Error("Upload canceled");
      error.name = "AbortError";
      throw error;
    }
    const start = index * chunkSize;
    const end = Math.min(task.file.size, start + chunkSize);
    if (receivedChunks.has(index)) {
      continue;
    }
    const chunk = task.file.slice(start, end);
    await uploadChunkWithProgress(sessionId, index, chunk, {
      task,
      onProgress: (loaded) => {
        updateProgress(confirmedBytes + loaded, text(`正在上传分片 ${index + 1}/${chunkCount}`, `Uploading chunk ${index + 1}/${chunkCount}`));
      },
    });
    confirmedBytes += chunk.size;
    receivedChunks.add(index);
    updateProgress(confirmedBytes, text(`已上传 ${receivedChunks.size}/${chunkCount} 个分片`, `${receivedChunks.size}/${chunkCount} chunks uploaded`));
  }

  updateUploadTask(task.id, {
    status: "finalizing",
    message: text("正在合并分片", "Finalizing upload"),
    progress: 98,
  });
  const completed = await postJson(`/api/uploads/resumable/${encodeURIComponent(sessionId)}/complete`, {});
  removeResumableUploadDraft(task);
  task.uploadSessionId = "";
  task.receivedBytes = task.file.size;
  persistResumableUploadDrafts();
  return completed;
}

function updateUploadTask(taskId, patch) {
  const task = state.uploadTasks.find((item) => item.id === taskId);
  if (!task) {
    return;
  }
  Object.assign(task, patch, {
    updatedAt: new Date().toISOString(),
  });
  persistResumableUploadDrafts();
  renderUploadProgressPanel();
}

function uploadTaskById(taskId) {
  return state.uploadTasks.find((item) => item.id === taskId) || null;
}

async function retryUploadTask(taskId) {
  const task = uploadTaskById(taskId);
  if (!task || task.kind !== "upload" || task.status !== "error" || !task.file) {
    return;
  }

  clearTaskPanelAutoHideTimer();
  Object.assign(task, {
    progress: 0,
    status: "queued",
    message: text("准备重试", "Preparing retry"),
    docId: "",
    versionId: "",
    _reader: null,
    _xhr: null,
    _aborted: false,
  });
  renderUploadProgressPanel();
  const documentId = await runUploadTask(task);
  if (documentId) {
    state.selectedId = documentId;
    await refreshDocuments();
    notify(text("上传重试成功。", "Upload retry succeeded."), "success");
  }
  scheduleTaskPanelAutoHide();
}

function pickFileForResumableTask(task) {
  return new Promise((resolve) => {
    const input = document.createElement("input");
    input.type = "file";
    input.style.position = "fixed";
    input.style.left = "-9999px";
    input.setAttribute("aria-hidden", "true");
    input.addEventListener("change", () => {
      const file = input.files?.[0] || null;
      input.remove();
      resolve(file);
    }, { once: true });
    document.body.appendChild(input);
    input.click();
  });
}

function validateResumableResumeFile(task, file) {
  if (!file) {
    return text("未选择文件。", "No file selected.");
  }
  if (Number(file.size || 0) !== Number(task.size || 0)) {
    return text("选择的文件大小与续传任务不一致，请选择原始文件。", "The selected file size does not match this resumable task. Select the original file.");
  }
  const expectedName = String(task.originalFileName || task.name || "").trim();
  const expectedLastModified = Number(task.lastModified || 0);
  if (expectedName && expectedLastModified && file.name !== expectedName) {
    return text(`请选择原文件“${expectedName}”。`, `Select the original file "${expectedName}".`);
  }
  if (expectedLastModified && Math.abs(Number(file.lastModified || 0) - expectedLastModified) > 1000) {
    return text("选择的文件修改时间与原上传文件不一致，请确认选择的是同一个本地文件。", "The selected file modified time does not match the original upload.");
  }
  return "";
}

async function resumeUploadTaskWithFile(taskId) {
  const task = uploadTaskById(taskId);
  if (!task || task.kind !== "upload" || !task.uploadSessionId) {
    return;
  }

  const file = await pickFileForResumableTask(task);
  if (!file) {
    return;
  }
  const validationError = validateResumableResumeFile(task, file);
  if (validationError) {
    notify(validationError, "alert");
    return;
  }

  clearTaskPanelAutoHideTimer();
  Object.assign(task, {
    file,
    size: file.size,
    lastModified: Number(file.lastModified || task.lastModified || 0),
    status: "queued",
    message: text("准备续传", "Preparing resume"),
    _reader: null,
    _xhr: null,
    _aborted: false,
  });
  persistResumableUploadDrafts();
  renderUploadProgressPanel();

  const documentId = await runUploadTask(task);
  if (documentId) {
    state.selectedId = documentId;
    await refreshDocuments();
    notify(text("续传完成。", "Upload resumed and completed."), "success");
  }
  scheduleTaskPanelAutoHide();
}

async function locateUploadTask(taskId) {
  const task = uploadTaskById(taskId);
  const doc = documentById(task?.docId || "");
  if (!doc) {
    notify(text("未找到该上传文件，可能已被移动或删除。", "The uploaded file was not found. It may have been moved or deleted."), "alert");
    return;
  }

  state.currentView = "files";
  openFolder(doc.parentId || null, { clearSearch: true });
  await selectDocument(doc.id);
  notify(text("已定位到上传文件。", "Located the uploaded file."), "success");
}

function cancelUploadTask(taskId) {
  const task = uploadTaskById(taskId);
  if (!task || isUploadTaskTerminal(task.status)) {
    scheduleTaskPanelAutoHide();
    return;
  }

  if (state.uploadConflictModalOpen && state.uploadConflictTaskId === taskId) {
    resolveUploadConflict("skip");
  }

  task.status = "canceled";
  task.message = text("已取消上传", "Upload canceled");
  task._aborted = true;
  task._reader?.abort();
  task._xhr?.abort();
  if (task.uploadSessionId) {
    removeResumableUploadDraft(task);
    void deleteJson(`/api/uploads/resumable/${encodeURIComponent(task.uploadSessionId)}`).catch(() => {});
    task.uploadSessionId = "";
  }
  persistResumableUploadDrafts();

  if (!task._reader && !task._xhr) {
    renderUploadProgressPanel();
    scheduleTaskPanelAutoHide();
  }
}

function clearTaskPanelAutoHideTimer() {
  window.clearTimeout(taskPanelAutoHideTimer);
  taskPanelAutoHideTimer = 0;
}

function scheduleTaskPanelAutoHide() {
  clearTaskPanelAutoHideTimer();
  renderUploadProgressPanel();
}

function validateLibraryUploadFile(file) {
  if (!file || !file.name) {
    return "存在无法识别的文件，当前任务已跳过。";
  }

  if (file.size > EFFECTIVE_LIBRARY_UPLOAD_LIMIT_BYTES) {
    return `文件“${file.name}”超过当前上传通道上限 ${formatBytes(EFFECTIVE_LIBRARY_UPLOAD_LIMIT_BYTES)}。产品配置目标为 2 GB，当前浏览器直传通道限制为 ${formatBytes(DEMO_TRANSPORT_UPLOAD_LIMIT_BYTES)}。`;
  }

  return "";
}

function findDuplicateDocument(name, parentId) {
  return state.documents.find(
    (doc) =>
      (doc.parentId || null) === (parentId || null) &&
      String(doc.name || "").toLowerCase() === String(name || "").toLowerCase(),
  ) || null;
}

function nextAvailableLibraryDocumentName(name, parentId) {
  const extension = (() => {
    const ext = fileExtension(name || "");
    return ext ? `.${ext}` : "";
  })();
  const baseName = extension ? name.slice(0, -extension.length) : name;
  let candidate = name;
  let index = 1;

  while (findDuplicateDocument(candidate, parentId)) {
    candidate = `${baseName} (${index})${extension}`;
    index += 1;
  }

  return candidate;
}

async function requestUploadConflict(task, parentId) {
  const duplicate = findDuplicateDocument(task.name, parentId);
  if (!duplicate) {
    return "replace";
  }

  return new Promise((resolve) => {
    uploadConflictResolver = resolve;
    state.uploadConflictModalOpen = true;
    state.uploadConflictTaskId = task.id;
    state.uploadConflictFileName = task.name;
    state.uploadConflictTargetLabel = parentId ? folderPathLabel(parentId) : "根目录";
    renderUploadConflictModal();
  });
}

function resolveUploadConflict(choice = "skip") {
  if (!uploadConflictResolver) {
    return;
  }

  const resolver = uploadConflictResolver;
  uploadConflictResolver = null;
  state.uploadConflictModalOpen = false;
  state.uploadConflictTaskId = null;
  state.uploadConflictFileName = "";
  state.uploadConflictTargetLabel = "";
  renderUploadConflictModal();
  resolver(choice);
}

async function ensureUploadTargetFolder(folderSegments) {
  let parentId = state.currentFolderId || null;

  for (const segment of folderSegments) {
    const existing = state.folders.find(
      (folder) =>
        (folder.parentId || null) === (parentId || null) &&
        folder.name.toLowerCase() === segment.toLowerCase(),
    );
    if (existing) {
      parentId = existing.id;
      continue;
    }

    try {
      const parentFolder = parentId ? folderById(parentId) : null;
      if (!folderPermissionsMeta(parentFolder).createFolder) {
        throw new Error(text("当前目录不允许创建子文件夹。", "This folder does not allow creating subfolders."));
      }
      const response = await postJson("/api/folders", {
        name: segment,
        parentId,
      });
      state.folders.push(response.folder);
      parentId = response.folder.id;
    } catch (error) {
      const fallback = state.folders.find(
        (folder) =>
          (folder.parentId || null) === (parentId || null) &&
          folder.name.toLowerCase() === segment.toLowerCase(),
      );
      if (!fallback) {
        throw error;
      }
      parentId = fallback.id;
    }
  }

  return parentId;
}

function syncDocumentFromUpload(document) {
  if (!document?.id) {
    return;
  }

  const existingIndex = state.documents.findIndex((item) => item.id === document.id);
  if (existingIndex >= 0) {
    state.documents.splice(existingIndex, 1, document);
  } else {
    state.documents.unshift(document);
  }

  syncBackgroundTasksFromDocuments();
  renderUploadProgressPanel();
}

function readFileAsBase64WithProgress(file, { onProgress = null, task = null } = {}) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    if (task) {
      task._reader = reader;
    }

    reader.onprogress = (event) => {
      if (event.lengthComputable && typeof onProgress === "function") {
        onProgress(event.loaded / event.total);
      }
    };
    reader.onload = () => {
      const result = String(reader.result || "");
      resolve(result.split(",")[1]);
    };
    reader.onerror = () => {
      reject(reader.error || new Error(text("读取文件失败", "Failed to read file")));
    };
    reader.onabort = () => {
      const error = new Error("Upload canceled");
      error.name = "AbortError";
      reject(error);
    };
    reader.readAsDataURL(file);
  });
}

async function handleLibraryDrop(event) {
  if (!isLibraryUploadDragEvent(event) || state.currentView !== "files") {
    return;
  }

  event.preventDefault();
  resetLibraryDragState();

  const descriptors = await collectDroppedUploadDescriptors(event.dataTransfer);
  await queueLibraryUploads(descriptors);
}

function handleLibraryDragEnter(event) {
  if (!isLibraryUploadDragEvent(event) || state.currentView !== "files") {
    return;
  }

  event.preventDefault();
  state.libraryDragDepth += 1;
  if (!state.libraryDropActive) {
    state.libraryDropActive = true;
    renderLibraryDropOverlay();
  }
}

function handleLibraryDragOver(event) {
  if (!isLibraryUploadDragEvent(event) || state.currentView !== "files") {
    return;
  }

  event.preventDefault();
  if (!state.libraryDropActive) {
    state.libraryDropActive = true;
    renderLibraryDropOverlay();
  }
}

function handleLibraryDragLeave(event) {
  if (!isLibraryUploadDragEvent(event) || state.currentView !== "files") {
    return;
  }

  state.libraryDragDepth = Math.max(0, state.libraryDragDepth - 1);
  if (state.libraryDragDepth === 0) {
    resetLibraryDragState();
  }
}

function resetLibraryDragState() {
  state.libraryDragDepth = 0;
  state.libraryDropActive = false;
  renderLibraryDropOverlay();
}

function isLibraryUploadDragEvent(event) {
  const types = Array.from(event.dataTransfer?.types || []);
  return types.includes("Files");
}

async function collectDroppedUploadDescriptors(dataTransfer) {
  const items = Array.from(dataTransfer?.items || []);
  if (!items.length) {
    return buildUploadDescriptors(Array.from(dataTransfer?.files || []));
  }

  const descriptors = [];
  for (const item of items) {
    const entry = typeof item.webkitGetAsEntry === "function" ? item.webkitGetAsEntry() : null;
    if (entry) {
      descriptors.push(...(await walkDroppedEntry(entry)));
      continue;
    }

    const file = item.kind === "file" ? item.getAsFile() : null;
    if (file) {
      descriptors.push(createUploadDescriptor(file, file.name));
    }
  }

  return descriptors;
}

async function walkDroppedEntry(entry, prefix = "") {
  if (entry.isFile) {
    const file = await getFileFromEntry(entry);
    return file && file.name !== ".DS_Store"
      ? [createUploadDescriptor(file, `${prefix}${file.name}`)]
      : [];
  }

  if (!entry.isDirectory) {
    return [];
  }

  const results = [];
  const children = await readAllDirectoryEntries(entry.createReader());
  for (const child of children) {
    results.push(...(await walkDroppedEntry(child, `${prefix}${entry.name}/`)));
  }
  return results;
}

function readAllDirectoryEntries(reader) {
  return new Promise((resolve, reject) => {
    const entries = [];

    const readNext = () => {
      reader.readEntries(
        (chunk) => {
          if (!chunk.length) {
            resolve(entries);
            return;
          }
          entries.push(...chunk);
          readNext();
        },
        reject,
      );
    };

    readNext();
  });
}

function getFileFromEntry(entry) {
  return new Promise((resolve, reject) => {
    entry.file(resolve, reject);
  });
}

async function createFolderFromPrompt(parentId = state.currentFolderId) {
  const targetFolder = parentId ? folderById(parentId) : null;
  const permissions = folderPermissionsMeta(targetFolder);
  if (!permissions.createFolder) {
    notify(text("当前目录不允许新建文件夹。", "This folder does not allow creating folders."), "alert");
    return;
  }
  const defaultFolderNames = new Set(["新建文件夹", "New Folder"]);
  const suggestedName = state.folders.some(
    (folder) => folder.parentId === parentId && defaultFolderNames.has(folder.name),
  )
    ? ""
    : text("新建文件夹", "New Folder");
  const name = await promptAction(text("请输入文件夹名称", "Enter folder name"), suggestedName, { label: text("文件夹名称", "Folder name") });
  if (name === null) {
    return;
  }

  const trimmed = name.trim();
  if (!trimmed) {
    notify(text("文件夹名称不能为空。", "Folder name cannot be empty."), "alert");
    return;
  }

  try {
    const response = await postJson("/api/folders", {
      name: trimmed,
      parentId,
    });
    state.currentFolderId = response.folder.id;
    state.fileSearchQuery = "";
    await refreshDocuments();
  } catch (error) {
    notifyError(error, text("创建文件夹失败，请稍后重试。", "Failed to create folder. Please try again later."));
  }
}

async function saveCurrentFolderConfig() {
  const folder = managedFolder();
  if (!folder || (!folderPermissionsMeta(folder).rename && !folderPermissionsMeta(folder).move)) {
    return;
  }

  const name = elements.folderNameInput.value.trim();
  if (!name) {
    notify(text("文件夹名称不能为空。", "Folder name cannot be empty."), "alert");
    return;
  }

  return runPendingAction("folder:save", async () => {
    try {
      await patchJson(`/api/folders/${folder.id}`, {
        name,
        parentId: elements.folderParentSelect.value || null,
        accessLevel: elements.folderAccessSelect.value,
      });
      await refreshDocuments();
    } catch (error) {
      notifyError(error, text("保存目录失败，请稍后重试。", "Failed to save folder. Please try again later."));
    }
  });
}

async function deleteCurrentFolder() {
  const folder = managedFolder();
  if (!folder || !folderPermissionsMeta(folder).delete) {
    return;
  }

  if (!await confirmAction(text(`确认删除文件夹“${folder.name}”吗？为空目录时才允许删除。`, `Delete folder "${folder.name}"? Only empty folders can be deleted.`))) {
    return;
  }

  return runPendingAction("folder:delete", async () => {
    try {
      if (state.currentFolderId === folder.id) {
        state.currentFolderId = folder.parentId || null;
      }
      state.fileSearchQuery = "";
      closeFileManagerModal({ render: false });
      await deleteJson(`/api/folders/${folder.id}`);
      await refreshDocuments();
    } catch (error) {
      notifyError(error, text("删除目录失败，请稍后重试。", "Failed to delete folder. Please try again later."));
    }
  });
}

async function saveCurrentDocumentConfig() {
  const doc = managedDocument();
  if (!doc || (!canRenameDocument(doc) && !canToggleDocumentCheckout(doc))) {
    return;
  }

  const name = elements.libraryNameInput.value.trim();
  if (canRenameDocument(doc) && !name) {
    notify(text("文件名称不能为空。", "File name cannot be empty."), "alert");
    return;
  }
  const shouldSaveDrawingMetadata = canRenameDocument(doc) && Boolean(doc.drawingMetadata?.markedAsDrawing);
  const nextDrawingMetadata = shouldSaveDrawingMetadata
    ? normalizeDrawingRegisterMetadataDraft({
        drawingNumber: elements.libraryDrawingNumberInput.value,
        drawingName: elements.libraryDrawingNameInput.value,
        discipline: elements.libraryDrawingDisciplineSelect.value,
        revision: elements.libraryDrawingRevisionInput.value,
        relatedDrawingNumber: elements.libraryRelatedDrawingInput.value,
      })
    : null;
  if (shouldSaveDrawingMetadata) {
    const missing = [];
    if (!nextDrawingMetadata.drawingNumber) missing.push(text("图纸编号", "Drawing No."));
    if (!nextDrawingMetadata.drawingName) missing.push(text("图纸名称", "Drawing Name"));
    if (!nextDrawingMetadata.discipline) missing.push(text("专业", "Discipline"));
    if (!nextDrawingMetadata.revision) missing.push(text("版本号", "Revision"));
    if (missing.length) {
      notify(text(`请补全图纸属性：${missing.join("、")}`, `Complete drawing attributes: ${missing.join(", ")}`), "alert");
      return;
    }
  }

  return runPendingAction("document:save", async () => {
    try {
      const actor = currentActorLabel();
      const payload = { actor };
      if (canRenameDocument(doc)) {
        payload.name = name;
        payload.accessLevel = elements.libraryAccessSelect.value;
        payload.downloadScope = elements.libraryDownloadSelect.value;
        payload.watermarkEnabled = elements.libraryWatermarkToggle.checked;
        if (nextDrawingMetadata) {
          payload.drawingMetadata = nextDrawingMetadata;
        }
      }
      if (canToggleDocumentCheckout(doc)) {
        payload.checkedOut = elements.libraryCheckoutToggle.checked;
      }
      await patchJson(`/api/documents/${doc.id}`, payload);
      if (canRenameDocument(doc) && isApsModelDocument(doc)) {
        const enteredUrn = elements.libraryApsUrnInput.value.trim();
        await patchJson(`/api/documents/${doc.id}/aps`, {
          actor,
          aps: {
            urn: enteredUrn,
            defaultView: elements.libraryApsDefaultViewSelect.value,
            viewable2dGuid: elements.libraryAps2dGuidInput.value.trim(),
            viewable3dGuid: elements.libraryAps3dGuidInput.value.trim(),
          },
        });
        if (!enteredUrn) {
          await postJson(`/api/documents/${doc.id}/aps/translate`, {
            actor,
            reason: text("从属性面板重新触发 APS 自动转换", "Retrigger APS auto-translation from the properties panel"),
          });
        }
      }
      await refreshDocuments();
    } catch (error) {
      notifyError(error, text("保存文件配置失败，请稍后重试。", "Failed to save file settings. Please try again later."));
    }
  });
}

async function moveCurrentDocument() {
  const doc = managedDocument();
  if (!doc || !canMoveDocument(doc)) {
    return;
  }

  const targetParentId = elements.libraryMoveSelect.value || null;
  if ((doc.parentId || null) === targetParentId) {
    notify(text("当前文件已经在所选目录中。", "This file is already in the selected folder."), "alert");
    return;
  }

  return runPendingAction("document:move", async () => {
    try {
      await patchJson(`/api/documents/${doc.id}`, {
        actor: currentActorLabel(),
        parentId: targetParentId,
      });
      state.currentFolderId = targetParentId;
      state.fileSearchQuery = "";
      await refreshDocuments();
    } catch (error) {
      notifyError(error, text("移动文件失败，请稍后重试。", "Failed to move file. Please try again later."));
    }
  });
}

async function generateDocumentShareLink() {
  const doc = managedDocument();
  if (!doc || !canShareDocument(doc)) {
    return;
  }

  const expiresAt = elements.libraryShareExpiresInput.value || defaultShareExpiryInputValue();
  if (!expiresAt) {
    notify(text("请先选择分享失效日期。", "Select a share expiry date first."), "alert");
    return;
  }

  return runPendingAction("document:share:create", async () => {
    try {
      await patchJson(`/api/documents/${doc.id}`, {
        actor: currentActorLabel(),
        share: {
          enabled: true,
          permission: elements.librarySharePermissionSelect.value,
          expiresAt,
          token: crypto.randomUUID().replaceAll("-", ""),
        },
      });
      await refreshDocuments();
    } catch (error) {
      notifyError(error, text("生成分享链接失败，请稍后重试。", "Failed to generate share link. Please try again later."));
    }
  });
}

async function copyDocumentShareLink() {
  const url = documentShareUrl(managedDocument());
  if (!url) {
    notify(text("当前还没有可复制的分享链接。", "No share link is available to copy yet."), "alert");
    return;
  }

  return runPendingAction("document:share:copy", async () => {
    try {
      await copyTextToClipboard(url);
      notify(text("分享链接已复制。", "Share link copied."), "success");
    } catch (error) {
      notifyError(error, text("复制分享链接失败，请稍后重试。", "Failed to copy share link. Please try again later."));
    }
  });
}

async function disableDocumentShareLink() {
  const doc = managedDocument();
  if (!doc?.share?.enabled || !canShareDocument(doc)) {
    return;
  }

  return runPendingAction("document:share:disable", async () => {
    try {
      await patchJson(`/api/documents/${doc.id}`, {
        actor: currentActorLabel(),
        share: {
          enabled: false,
          token: "",
        },
      });
      await refreshDocuments();
    } catch (error) {
      notifyError(error, text("关闭分享失败，请稍后重试。", "Failed to disable sharing. Please try again later."));
    }
  });
}

async function restoreDocumentVersionById(docId, versionId) {
  const doc = documentById(docId);
  if (!doc || !versionId) {
    return;
  }

  if (!canUploadNewVersion(doc)) {
    notify(documentUploadBlockMessage(doc), "alert");
    return;
  }

  const entry = doc.versionHistory?.find((item) => item.id === versionId);
  if (!entry) {
    notify(text("未找到要还原的历史版本。", "The historical version to restore was not found."), "alert");
    return;
  }

  if (!await confirmAction(text(`确认将 ${doc.name} 还原为 ${entry.version} 吗？系统会生成一个新的当前版本。`, `Restore ${doc.name} to ${entry.version}? The system will create a new current version.`))) {
    return;
  }

  return runPendingAction("version:mutate", async () => {
    try {
      await postJson(`/api/documents/${doc.id}/version/${versionId}/restore`, {
        actor: currentActorLabel(),
      });
      await refreshDocuments();
    } catch (error) {
      notifyError(error, text("还原历史版本失败，请稍后重试。", "Failed to restore historical version. Please try again later."));
    }
  });
}

