async function previewDocumentVersion(docId, versionId) {
  const doc = documentById(docId);
  const entry = doc?.versionHistory?.find((item) => item.id === versionId);
  if (!doc || !entry || !canPreviewDocument(doc)) {
    return;
  }

  if (isModelWorkspaceDocument(doc)) {
    showAlert(text("当前 APS 模型工作台默认基于文件当前配置的模型 URN 打开，历史版本联动后续补充。", "The APS model workspace currently opens from the file's current model URN. Historical version linkage will be added later."));
    return;
  }

  if (isOnlyOfficeDocument(doc)) {
    openOnlyOfficeDocument(doc.id, {
      versionId: entry.id,
      mode: "view",
    });
    return;
  }

  if (isDrawingWorkspaceDocument(doc)) {
    openDrawingDocument(doc.id, {
      versionId: entry.id,
      mode: "view",
    });
    return;
  }

  if (isReviewableDocument(doc)) {
    openPdfDocument(doc.id, {
      versionId: entry.id,
      mode: "view",
    });
    return;
  }

  const previewUrl = entry.previewUrl || entry.fileUrl;
  const wrapperWindow = window.open("about:blank", "_blank");
  if (!wrapperWindow) {
    notify(text("浏览器拦截了新窗口，请允许弹窗后重试。", "The browser blocked the popup. Allow popups and try again."), "alert");
    return;
  }

  const headerLabel = entry.isCurrent || entry.id === doc.currentVersionId ? text(`${entry.version} · 当前版本`, `${entry.version} · Current Version`) : text(`${entry.version} · 历史版本`, `${entry.version} · Historical Version`);
  wrapperWindow.document.write(`
    <!DOCTYPE html>
    <html lang="${escapeHtml(currentLanguageMeta().htmlLang)}">
      <head>
        <meta charset="UTF-8" />
        <title>${escapeHtml(doc.name)} - ${escapeHtml(headerLabel)}</title>
        <style>
          html, body { margin: 0; height: 100%; background: #eff3f8; font-family: "SF Pro Display", "PingFang SC", sans-serif; color: #17304d; }
          body { display: grid; grid-template-rows: auto 1fr; }
          .preview-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 20px; background: rgba(255,255,255,0.96); border-bottom: 1px solid rgba(23,48,77,0.1); }
          .preview-head strong { font-size: 14px; }
          .preview-head span { color: #6e8099; font-size: 12px; }
          iframe { width: 100%; height: 100%; border: 0; background: #f7f9fc; }
        </style>
      </head>
      <body>
        <div class="preview-head">
          <strong>${escapeHtml(doc.name)}</strong>
          <span>${escapeHtml(headerLabel)}${entry.isCurrent || entry.id === doc.currentVersionId ? "" : escapeHtml(text("，仅供只读预览", ", read-only preview"))}</span>
        </div>
        <iframe src="${escapeHtml(new URL(`${previewUrl}?t=${encodeURIComponent(entry.uploadedAt || doc.updatedAt || "")}`, window.location.origin).toString())}"></iframe>
      </body>
    </html>
  `);
  wrapperWindow.document.close();
}

function downloadDocumentVersion(docId, versionId) {
  const doc = documentById(docId);
  const entry = doc?.versionHistory?.find((item) => item.id === versionId);
  if (!doc || !entry || !canDownloadDocument(doc)) {
    return;
  }

  const extension = pathExtension(doc.name || entry.name || "");
  const baseName = pathBaseName(doc.name || entry.name || `document-${docId}`, extension);
  const downloadName = `${baseName}_${entry.version}${extension}`;
  const anchor = document.createElement("a");
  anchor.href = new URL(`${entry.fileUrl}?download=${encodeURIComponent(downloadName)}&t=${encodeURIComponent(entry.uploadedAt || "")}`, window.location.origin).toString();
  anchor.download = downloadName;
  anchor.rel = "noreferrer";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
}

async function copyOrCreateVersionShareLink(docId, versionId) {
  const doc = documentById(docId);
  const entry = doc?.versionHistory?.find((item) => item.id === versionId);
  if (!doc || !entry || !canShareDocument(doc)) {
    return;
  }

  return runPendingAction("version:mutate", async () => {
    try {
      if (!entry.shareUrl) {
        await patchJson(`/api/documents/${doc.id}/version/${versionId}`, {
          actor: currentActorLabel(),
          share: {
            enabled: true,
            permission: entry.share?.permission || "view",
            expiresAt: entry.share?.expiresAt || defaultShareExpiryInputValue(),
            token: crypto.randomUUID().replaceAll("-", ""),
          },
        });
        await refreshDocuments();
      }

      const latestDoc = documentById(doc.id);
      const latestEntry = latestDoc?.versionHistory?.find((item) => item.id === versionId);
      if (!latestEntry?.shareUrl) {
        throw new Error(text("版本分享链接生成失败，请稍后重试。", "Failed to generate version share link. Please try again later."));
      }

      await copyTextToClipboard(new URL(latestEntry.shareUrl, window.location.origin).toString());
      notify(text(`${latestEntry.version} 的锁定分享链接已复制。`, `${latestEntry.version} locked share link copied.`), "success");
    } catch (error) {
      notifyError(error, text("生成版本分享链接失败，请稍后重试。", "Failed to generate version share link. Please try again later."));
    }
  });
}

async function uploadVersionForDocument(doc, file, note = "") {
  if (!doc || !file) {
    return;
  }

  if (!canUploadNewVersion(doc)) {
    notify(documentUploadBlockMessage(doc), "alert");
    return;
  }

  const validationError = validateLibraryUploadFile(file);
  if (validationError) {
    notify(validationError, "alert");
    return;
  }

  const currentExtension = fileExtension(doc.name || "");
  const nextExtension = fileExtension(file.name || "");
  if (currentExtension && nextExtension && currentExtension !== nextExtension) {
    const allowMismatch = await confirmAction(text(`当前文件扩展名为 .${currentExtension}，你选择的是 .${nextExtension}。系统会给出警告但仍允许继续创建新版本，是否继续？`, `The current file extension is .${currentExtension}, but you selected .${nextExtension}. The system will warn but still allow creating a new version. Continue?`));
    if (!allowMismatch) {
      return;
    }
  }

  const task = createUploadTask({
    file,
    relativePath: doc.name,
    drawingMetadata: doc.drawingMetadata?.markedAsDrawing ? doc.drawingMetadata : null,
  });
  Object.assign(task, {
    name: doc.name,
    parentId: doc.parentId || null,
    pathLabel: folderPathLabel(doc.parentId) || text("根目录", "Root"),
    docId: doc.id,
    forcedConflictMode: "replace",
    status: "queued",
    message: text("等待上传新版本", "Waiting to upload new version"),
  });
  state.uploadTasks = [...state.uploadTasks, task];
  renderUploadProgressPanel();
  clearTaskPanelAutoHideTimer();

  try {
    const response = await uploadFileWithResume(task, {
      name: doc.name,
      parentId: doc.parentId || null,
      conflictMode: "replace",
      note: note.trim(),
    });
    syncDocumentFromUpload(response.document);
    updateUploadTask(task.id, {
      docId: response.document?.id || doc.id,
      versionId: response.document?.currentVersionId || "",
      projectId: response.document?.projectId || task.projectId || "",
      ownerUserId: response.document?.uploaderId || task.ownerUserId || "",
      ownerName: response.document?.uploader || task.ownerName || "",
      status: "done",
      message: text(`已生成 ${response.document?.version || "新版本"}`, `Created ${response.document?.version || "new version"}`),
      progress: 100,
    });
    scheduleTaskPanelAutoHide();
  } catch (error) {
    updateUploadTask(task.id, {
      status: error?.name === "AbortError" ? "canceled" : "error",
      message: error?.name === "AbortError" ? text("已取消上传", "Upload canceled") : error.message || text("上传新版本失败，请稍后重试。", "Failed to upload new version. Please try again later."),
      progress: error?.name === "AbortError" ? task.progress || 0 : 100,
    });
    scheduleTaskPanelAutoHide();
    throw error;
  }
}

async function handleNewVersionUpload(event) {
  const [file] = event.target.files || [];
  const doc = managedDocument();

  try {
    if (!file || !doc) {
      return;
    }
    await runPendingAction("document:version:upload", async () => {
      await uploadVersionForDocument(doc, file, elements.versionNoteInput.value.trim());
      elements.versionNoteInput.value = "";
      await refreshDocuments();
    });
  } catch (error) {
    notifyError(error, text("上传新版本失败，请稍后重试。", "Failed to upload new version. Please try again later."));
  } finally {
    event.target.value = "";
  }
}

